fn m3_micro_metal_parity_policy_identity_v1() -> String {
    stable_hash_string(
        "m3-micro-metal-parity-policy-v1:output-abs=0.00002:output-rel=0.0002:state-abs=0.00003:state-rel=0.0003:exact-shape=true:finite=true:no-fallback=true",
    )
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct M3MicroParameters {
    values: Vec<f32>,
}

impl M3MicroParameters {
    fn seeded(config: &M3MicroConfig, seed: u64) -> Result<Self, M3MicroError> {
        Self::seeded_with_initialization(config, seed, REDUCED_CORE_INITIALIZATION_POLICY_V2)
    }

    fn seeded_with_initialization(
        config: &M3MicroConfig,
        seed: u64,
        initialization: M3MicroInitializationPolicyV2,
    ) -> Result<Self, M3MicroError> {
        let layout = M3MicroLayout::new(config)?;
        let mut rng = DeterministicRng::new(seed);
        let mut values = (0..layout.parameter_count)
            .map(|_| rng.symmetric(0.02))
            .collect::<Vec<_>>();
        if initialization == M3MicroInitializationPolicyV2::ReinforcedCandidate {
            values[layout.b_embed.clone()].fill(0.0);
            values[layout.b_head.clone()].fill(0.0);
            for feature in 0..config.input_dim.min(config.d_model) {
                values[layout.w_embed.start + feature * config.input_dim + feature] +=
                    INITIAL_INPUT_IDENTITY_SCALE_V2;
            }
            for block in &layout.blocks {
                values[block.b_in.clone()].fill(0.0);
                values[block.b_out.clone()].fill(0.0);
                for value in &mut values[block.w_decay.clone()] {
                    *value *= INITIAL_RETENTION_RESPONSE_SCALE_V2;
                }
                for row in 0..config.inner_dim() {
                    let column = row % config.d_model;
                    values[block.w_in.start + row * config.d_model + column] +=
                        INITIAL_INPUT_IDENTITY_SCALE_V2;
                }
                values[block.b_decay.clone()].fill(0.0);
                values[block.decay_state_bias.clone()].fill(INITIAL_LONG_RETENTION_LOGIT_V2);
                values[block.prev_scale.clone()].fill(INITIAL_STATE_PATH_SCALE_V2);
                values[block.curr_scale.clone()].fill(INITIAL_STATE_PATH_SCALE_V2);
                values[block.readout_scale.clone()].fill(INITIAL_STATE_PATH_SCALE_V2);
                values[block.skip.clone()].fill(0.0);
                for row in 0..config.d_model {
                    for half in 0..config.expansion {
                        let column = half * config.d_model + row;
                        values[block.w_out.start + row * config.inner_dim() + column] +=
                            INITIAL_STATE_OUTPUT_IDENTITY_SCALE_V2 / config.expansion as f32;
                    }
                }
            }
        } else {
            for block in &layout.blocks {
                values[block.b_decay.clone()].fill(1.25);
                values[block.decay_state_bias.clone()].fill(0.0);
                values[block.prev_scale.clone()].fill(0.05);
                values[block.curr_scale.clone()].fill(0.05);
                values[block.readout_scale.clone()].fill(0.05);
                values[block.skip.clone()].fill(0.0);
            }
        }
        let parameters = Self { values };
        parameters.validate(config)?;
        Ok(parameters)
    }

    fn validate(&self, config: &M3MicroConfig) -> Result<(), M3MicroError> {
        let expected = M3MicroLayout::new(config)?.parameter_count;
        if self.values.len() != expected {
            return Err(M3MicroError::InvalidShape);
        }
        if self
            .values
            .iter()
            .any(|value| !value.is_finite() || value.abs() > PARAMETER_ABS_LIMIT)
        {
            return Err(M3MicroError::NonFiniteParameter);
        }
        Ok(())
    }

    pub fn len(&self) -> usize {
        self.values.len()
    }

    pub fn is_empty(&self) -> bool {
        self.values.is_empty()
    }

    pub fn storage_identity(&self) -> usize {
        self.values.as_ptr() as usize
    }

    pub fn digest(&self) -> String {
        stable_hash_string(&format!("{:?}", self.values))
    }
}

struct DeterministicRng(u64);

impl DeterministicRng {
    fn new(seed: u64) -> Self {
        Self(seed ^ 0x9e3779b97f4a7c15)
    }

    fn next(&mut self) -> u32 {
        let mut value = self.0;
        value ^= value << 13;
        value ^= value >> 7;
        value ^= value << 17;
        self.0 = value;
        (value >> 16) as u32
    }

    fn symmetric(&mut self, scale: f32) -> f32 {
        (self.next() as f32 / u32::MAX as f32 * 2.0 - 1.0) * scale
    }
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct M3MicroBlockState {
    values: Vec<f32>,
    previous_u: Vec<f32>,
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct M3MicroState {
    pub blocks: Vec<M3MicroBlockState>,
    pub step_index: usize,
}

impl M3MicroState {
    pub fn zero(config: &M3MicroConfig) -> Result<Self, M3MicroError> {
        config.validate()?;
        let inner = config.inner_dim();
        Ok(Self {
            blocks: (0..config.block_count)
                .map(|_| M3MicroBlockState {
                    values: vec![0.0; inner * config.d_state],
                    previous_u: vec![0.0; inner],
                })
                .collect(),
            step_index: 0,
        })
    }

    pub fn validate(&self, config: &M3MicroConfig) -> Result<(), M3MicroError> {
        let inner = config.inner_dim();
        if self.blocks.len() != config.block_count
            || self.blocks.iter().any(|block| {
                block.values.len() != inner * config.d_state || block.previous_u.len() != inner
            })
        {
            return Err(M3MicroError::InvalidShape);
        }
        if self
            .blocks
            .iter()
            .flat_map(|block| block.values.iter().chain(&block.previous_u))
            .any(|value| !value.is_finite())
        {
            return Err(M3MicroError::NonFiniteOutput);
        }
        if self
            .blocks
            .iter()
            .flat_map(|block| &block.values)
            .any(|value| value.abs() > STATE_LIMIT)
        {
            return Err(M3MicroError::StateExplosion);
        }
        Ok(())
    }

    pub fn digest(&self) -> String {
        stable_hash_string(&format!("{self:?}"))
    }

    pub fn byte_size(&self) -> usize {
        self.blocks
            .iter()
            .map(|block| (block.values.len() + block.previous_u.len()) * std::mem::size_of::<f32>())
            .sum::<usize>()
            + std::mem::size_of::<usize>()
    }

    pub fn storage_identities(&self) -> Vec<usize> {
        self.blocks
            .iter()
            .flat_map(|block| {
                [
                    block.values.as_ptr() as usize,
                    block.previous_u.as_ptr() as usize,
                ]
            })
            .collect()
    }
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct M3MicroModel {
    pub config: M3MicroConfig,
    pub parameters: M3MicroParameters,
    pub model_identity: String,
}

#[derive(Clone, Debug)]
struct BlockTape {
    h_input: Vec<f32>,
    u: Vec<f32>,
    decay: Vec<f32>,
    retention_base_response: Vec<f32>,
    retention_response: Vec<f32>,
    prev_gate: Vec<f32>,
    curr_gate: Vec<f32>,
    previous_state: Vec<f32>,
    previous_u: Vec<f32>,
    next_state: Vec<f32>,
    z: Vec<f32>,
    h_output: Vec<f32>,
}

#[derive(Clone, Debug)]
struct StepTape {
    input: Vec<f32>,
    input_activity: f32,
    embedded: Vec<f32>,
    blocks: Vec<BlockTape>,
}

#[derive(Clone, Debug)]
struct ForwardTape {
    steps: Vec<StepTape>,
    raw_output: Vec<f32>,
}

impl ForwardTape {
    fn byte_size(&self) -> usize {
        let values = self.raw_output.len()
            + self
                .steps
                .iter()
                .map(|step| {
                    step.input.len()
                        + 1
                        + step.embedded.len()
                        + step
                            .blocks
                            .iter()
                            .map(|block| {
                                block.h_input.len()
                                    + block.u.len()
                                    + block.decay.len()
                                    + block.retention_base_response.len()
                                    + block.retention_response.len()
                                    + block.prev_gate.len()
                                    + block.curr_gate.len()
                                    + block.previous_state.len()
                                    + block.previous_u.len()
                                    + block.next_state.len()
                                    + block.z.len()
                                    + block.h_output.len()
                            })
                            .sum::<usize>()
                })
                .sum::<usize>();
        values * std::mem::size_of::<f32>()
    }
}

impl M3MicroModel {
    pub fn seeded(config: M3MicroConfig, seed: u64) -> Result<Self, M3MicroError> {
        config.validate()?;
        let parameters = M3MicroParameters::seeded(&config, seed)?;
        let mut model = Self {
            config,
            parameters,
            model_identity: String::new(),
        };
        model.refresh_identity();
        Ok(model)
    }

    pub fn validate(&self) -> Result<(), M3MicroError> {
        self.config.validate()?;
        self.parameters.validate(&self.config)?;
        if self.model_identity != self.computed_identity() {
            return Err(M3MicroError::CorruptArtifact);
        }
        Ok(())
    }

    pub fn parameter_count(&self) -> usize {
        self.parameters.len()
    }

    pub fn revision(&self) -> M3MicroCoreRevisionV2 {
        M3MicroCoreRevisionV2::V1Reduced
    }

    pub fn parameter_digest(&self) -> String {
        self.parameters.digest()
    }

    fn computed_identity(&self) -> String {
        stable_hash_string(&format!(
            "{M3_MICRO_CORE_SCHEMA_V3}:{:?}:{}",
            self.config,
            self.parameters.digest()
        ))
    }

    fn refresh_identity(&mut self) {
        self.model_identity = self.computed_identity();
    }

    pub fn forward(
        &self,
        sequence: &[Vec<f32>],
        state: &mut M3MicroState,
    ) -> Result<Vec<f32>, M3MicroError> {
        self.forward_with_work_counters(sequence, state)
            .map(|(output, _)| output)
    }

    pub fn forward_with_work_counters(
        &self,
        sequence: &[Vec<f32>],
        state: &mut M3MicroState,
    ) -> Result<(Vec<f32>, M3MicroWorkCountersV1), M3MicroError> {
        let mut counters = M3MicroWorkCountersV1::default();
        let output = self
            .forward_internal(sequence, state, false, &mut counters)?
            .raw_output;
        Ok((output, counters))
    }

    pub fn stream_step(
        &self,
        input: &[f32],
        state: &mut M3MicroState,
    ) -> Result<(Vec<f32>, M3MicroWorkCountersV1), M3MicroError> {
        self.forward_with_work_counters(&[input.to_vec()], state)
    }

    pub fn forward_from_zero_with_work_counters(
        &self,
        sequence: &[Vec<f32>],
    ) -> Result<(Vec<f32>, M3MicroState, M3MicroWorkCountersV1), M3MicroError> {
        let mut state = M3MicroState::zero(&self.config)?;
        let (output, mut counters) = self.forward_with_work_counters(sequence, &mut state)?;
        counters.state_allocation_count = 1;
        Ok((output, state, counters))
    }

    fn forward_for_training(&self, sequence: &[Vec<f32>]) -> Result<ForwardTape, M3MicroError> {
        let state = M3MicroState::zero(&self.config)?;
        self.forward_for_training_from_state_with_math(
            sequence,
            &state,
            REDUCED_CORE_MATH_PROFILE_V1,
        )
    }

    fn forward_for_training_from_state_with_math(
        &self,
        sequence: &[Vec<f32>],
        initial_state: &M3MicroState,
        core_profile: CoreMathProfileV1,
    ) -> Result<ForwardTape, M3MicroError> {
        let mut state = initial_state.clone();
        let mut counters = M3MicroWorkCountersV1::default();
        self.forward_internal_with_profile(sequence, &mut state, true, &mut counters, core_profile)
    }

    fn forward_internal(
        &self,
        sequence: &[Vec<f32>],
        state: &mut M3MicroState,
        record_tape: bool,
        counters: &mut M3MicroWorkCountersV1,
    ) -> Result<ForwardTape, M3MicroError> {
        self.forward_internal_with_profile(
            sequence,
            state,
            record_tape,
            counters,
            REDUCED_CORE_MATH_PROFILE_V1,
        )
    }

    fn forward_internal_with_profile(
        &self,
        sequence: &[Vec<f32>],
        state: &mut M3MicroState,
        record_tape: bool,
        counters: &mut M3MicroWorkCountersV1,
        core_profile: CoreMathProfileV1,
    ) -> Result<ForwardTape, M3MicroError> {
        self.validate()?;
        state.validate(&self.config)?;
        if sequence.is_empty()
            || sequence.iter().any(|row| {
                row.len() != self.config.input_dim || row.iter().any(|value| !value.is_finite())
            })
        {
            return Err(M3MicroError::NonFiniteInput);
        }
        let layout = M3MicroLayout::new(&self.config)?;
        let params = &self.parameters.values;
        let inner = self.config.inner_dim();
        let mut tapes = Vec::with_capacity(sequence.len());
        let mut final_hidden = vec![0.0; self.config.d_model];
        for input in sequence {
            counters.sequence_step_count = counters
                .sequence_step_count
                .checked_add(1)
                .ok_or(M3MicroError::StateExplosion)?;
            let input_activity = input.iter().map(|value| value.tanh().powi(2)).sum::<f32>()
                / self.config.input_dim as f32;
            let embedded = affine_tanh(
                params,
                &layout.w_embed,
                &layout.b_embed,
                self.config.d_model,
                self.config.input_dim,
                input,
            )?;
            counters.projection_operation_count = counters
                .projection_operation_count
                .checked_add(1)
                .ok_or(M3MicroError::StateExplosion)?;
            let mut hidden = embedded.clone();
            let mut block_tapes = Vec::with_capacity(self.config.block_count);
            for (block_index, block_layout) in layout.blocks.iter().enumerate() {
                let block_state = &mut state.blocks[block_index];
                let previous_state = block_state.values.clone();
                let previous_u = block_state.previous_u.clone();
                let u = affine_tanh(
                    params,
                    &block_layout.w_in,
                    &block_layout.b_in,
                    inner,
                    self.config.d_model,
                    &hidden,
                )?;
                let decay_channel = affine(
                    params,
                    &block_layout.w_decay,
                    &block_layout.b_decay,
                    inner,
                    inner,
                    &u,
                )?;
                let prev_gate_pre = affine(
                    params,
                    &block_layout.w_prev_gate,
                    &block_layout.b_prev_gate,
                    inner,
                    inner,
                    &u,
                )?;
                let curr_gate_pre = affine(
                    params,
                    &block_layout.w_curr_gate,
                    &block_layout.b_curr_gate,
                    inner,
                    inner,
                    &u,
                )?;
                let prev_gate = prev_gate_pre
                    .iter()
                    .map(|value| sigmoid(*value))
                    .collect::<Vec<_>>();
                let curr_gate = curr_gate_pre
                    .iter()
                    .map(|value| sigmoid(*value))
                    .collect::<Vec<_>>();
                let retention_base_response = if core_profile.reinforced_retention {
                    decay_channel
                        .iter()
                        .map(|value| softsign(*value * RETENTION_RESPONSE_GAIN_V2))
                        .collect::<Vec<_>>()
                } else {
                    decay_channel.clone()
                };
                let retention_response = if core_profile.reinforced_retention {
                    retention_base_response
                        .iter()
                        .zip(&curr_gate)
                        .map(|(response, gate)| response * input_activity * gate * gate)
                        .collect::<Vec<_>>()
                } else {
                    vec![0.0; inner]
                };
                let mut decay = vec![0.0; inner * self.config.d_state];
                let mut next_state = vec![0.0; decay.len()];
                let mut readout = vec![0.0; inner];
                for channel in 0..inner {
                    for state_index in 0..self.config.d_state {
                        let index = channel * self.config.d_state + state_index;
                        let state_bias = params[block_layout.decay_state_bias.start + index];
                        let bounded = if core_profile.reinforced_retention {
                            let baseline_response = decay_channel[channel].signum()
                                * (decay_channel[channel].abs()
                                    - RETENTION_BASE_LOGIT_DEAD_ZONE_V2)
                                    .max(0.0)
                                * RETENTION_BASE_LOGIT_RESPONSE_SCALE_V2;
                            let baseline = sigmoid(state_bias + baseline_response);
                            let response = retention_response[channel];
                            if response < 0.0 {
                                baseline * (1.0 + response)
                            } else {
                                baseline + (1.0 - baseline) * response
                            }
                        } else {
                            sigmoid(state_bias + decay_channel[channel])
                        };
                        decay[index] = self.config.decay_min
                            + (self.config.decay_max - self.config.decay_min) * bounded;
                        let prev_scale = params[block_layout.prev_scale.start + index].tanh();
                        let curr_scale = params[block_layout.curr_scale.start + index].tanh();
                        let next = decay[index] * previous_state[index]
                            + prev_gate[channel] * previous_u[channel] * prev_scale
                            + curr_gate[channel] * u[channel] * curr_scale;
                        if !next.is_finite() {
                            return Err(M3MicroError::NonFiniteOutput);
                        }
                        if next.abs() > STATE_LIMIT {
                            return Err(M3MicroError::StateExplosion);
                        }
                        next_state[index] = next;
                        readout[channel] += next
                            * params[block_layout.readout_scale.start + index].tanh()
                            * core_profile.readout_gain
                            / self.config.d_state as f32;
                    }
                }
                let z = (0..inner)
                    .map(|channel| {
                        let value = readout[channel]
                            + sigmoid(params[block_layout.skip.start + channel]) * u[channel];
                        if core_profile.softsign_activations {
                            softsign(value)
                        } else {
                            value.tanh()
                        }
                    })
                    .collect::<Vec<_>>();
                let h_output = if core_profile.softsign_activations {
                    affine_softsign(
                        params,
                        &block_layout.w_out,
                        &block_layout.b_out,
                        self.config.d_model,
                        inner,
                        &z,
                    )?
                } else {
                    affine_tanh(
                        params,
                        &block_layout.w_out,
                        &block_layout.b_out,
                        self.config.d_model,
                        inner,
                        &z,
                    )?
                };
                counters.projection_operation_count = counters
                    .projection_operation_count
                    .checked_add(5)
                    .ok_or(M3MicroError::StateExplosion)?;
                counters.state_transition_count = counters
                    .state_transition_count
                    .checked_add(inner * self.config.d_state)
                    .ok_or(M3MicroError::StateExplosion)?;
                block_state.values.clone_from(&next_state);
                block_state.previous_u.clone_from(&u);
                if record_tape {
                    block_tapes.push(BlockTape {
                        h_input: hidden,
                        u,
                        decay,
                        retention_base_response,
                        retention_response,
                        prev_gate,
                        curr_gate,
                        previous_state,
                        previous_u,
                        next_state,
                        z,
                        h_output: h_output.clone(),
                    });
                }
                hidden = h_output;
            }
            final_hidden = hidden;
            if record_tape {
                tapes.push(StepTape {
                    input: input.clone(),
                    input_activity,
                    embedded,
                    blocks: block_tapes,
                });
            }
            state.step_index = state
                .step_index
                .checked_add(1)
                .ok_or(M3MicroError::StateExplosion)?;
            state.validate(&self.config)?;
        }
        let raw_output = affine(
            params,
            &layout.w_head,
            &layout.b_head,
            self.config.output_dim,
            self.config.d_model,
            &final_hidden,
        )?;
        counters.projection_operation_count = counters
            .projection_operation_count
            .checked_add(1)
            .ok_or(M3MicroError::StateExplosion)?;
        if raw_output.iter().any(|value| !value.is_finite()) {
            return Err(M3MicroError::NonFiniteOutput);
        }
        Ok(ForwardTape {
            steps: tapes,
            raw_output,
        })
    }

    pub fn capability_probe_step(
        &self,
        input: &[f32],
        initial_state: &M3MicroState,
    ) -> Result<M3MicroStepCapabilityProbeV1, M3MicroError> {
        let mut state = initial_state.clone();
        let mut counters = M3MicroWorkCountersV1::default();
        let tape = self.forward_internal(&[input.to_vec()], &mut state, true, &mut counters)?;
        let layout = M3MicroLayout::new(&self.config)?;
        let params = &self.parameters.values;
        let blocks = &tape.steps[0].blocks;
        let retention_count = blocks.iter().map(|block| block.decay.len()).sum::<usize>();
        let gate_count = blocks
            .iter()
            .map(|block| block.prev_gate.len())
            .sum::<usize>();
        if retention_count == 0 || gate_count == 0 {
            return Err(M3MicroError::InvalidShape);
        }
        let mean_retention =
            blocks.iter().flat_map(|block| &block.decay).sum::<f32>() / retention_count as f32;
        let mean_previous_gate = blocks
            .iter()
            .flat_map(|block| &block.prev_gate)
            .sum::<f32>()
            / gate_count as f32;
        let mean_current_gate = blocks
            .iter()
            .flat_map(|block| &block.curr_gate)
            .sum::<f32>()
            / gate_count as f32;
        let mut previous_input_contribution_l1 = 0.0;
        let mut current_input_contribution_l1 = 0.0;
        for (block, block_layout) in blocks.iter().zip(&layout.blocks) {
            for channel in 0..self.config.inner_dim() {
                for state_index in 0..self.config.d_state {
                    let index = channel * self.config.d_state + state_index;
                    previous_input_contribution_l1 += (block.prev_gate[channel]
                        * block.previous_u[channel]
                        * params[block_layout.prev_scale.start + index].tanh())
                    .abs();
                    current_input_contribution_l1 += (block.curr_gate[channel]
                        * block.u[channel]
                        * params[block_layout.curr_scale.start + index].tanh())
                    .abs();
                }
            }
        }
        Ok(M3MicroStepCapabilityProbeV1 {
            mean_retention,
            mean_previous_gate,
            mean_current_gate,
            previous_input_contribution_l1,
            current_input_contribution_l1,
            updated_state_digest: state.digest(),
            raw_output: tape.raw_output,
        })
    }

    pub fn with_ablation(&self, ablation: M3MicroAblationV1) -> Result<Self, M3MicroError> {
        let mut model = self.clone();
        let layout = M3MicroLayout::new(&model.config)?;
        for block in &layout.blocks {
            match ablation {
                M3MicroAblationV1::FixedRetention => {
                    model.parameters.values[block.w_decay.clone()].fill(0.0);
                    model.parameters.values[block.b_decay.clone()].fill(0.0);
                    model.parameters.values[block.decay_state_bias.clone()].fill(0.0);
                }
                M3MicroAblationV1::NoPreviousInputContribution => {
                    model.parameters.values[block.prev_scale.clone()].fill(0.0);
                }
                M3MicroAblationV1::NoCurrentInputGate => {
                    model.parameters.values[block.w_curr_gate.clone()].fill(0.0);
                    model.parameters.values[block.b_curr_gate.clone()].fill(PARAMETER_ABS_LIMIT);
                }
                M3MicroAblationV1::NoRecurrentState => {
                    model.parameters.values[block.prev_scale.clone()].fill(0.0);
                    model.parameters.values[block.curr_scale.clone()].fill(0.0);
                    model.parameters.values[block.readout_scale.clone()].fill(0.0);
                }
                M3MicroAblationV1::NoSelectiveForgetting => {
                    model.parameters.values[block.w_decay.clone()].fill(0.0);
                    model.parameters.values[block.b_decay.clone()].fill(0.0);
                    model.parameters.values[block.decay_state_bias.clone()]
                        .fill(PARAMETER_ABS_LIMIT);
                }
            }
        }
        model.refresh_identity();
        model.validate()?;
        Ok(model)
    }

    pub fn gradient_audit(
        &self,
        agent_id: AgentId,
        sequence: &[Vec<f32>],
        target: &M3MicroTarget,
    ) -> Result<M3MicroGradientAuditV1, M3MicroError> {
        let training_cache_bytes = self.forward_for_training(sequence)?.byte_size();
        let (loss, gradients, input_gradients) =
            model_loss_gradients_internal(self, agent_id, sequence, target, true)?;
        let layout = M3MicroLayout::new(&self.config)?;
        let mut ranges = BTreeMap::<M3MicroGradientGroupV1, Vec<Range<usize>>>::new();
        ranges
            .entry(M3MicroGradientGroupV1::InputProjection)
            .or_default()
            .extend([layout.w_embed.clone(), layout.b_embed.clone()]);
        ranges
            .entry(M3MicroGradientGroupV1::PredictionHead)
            .or_default()
            .extend([layout.w_head.clone(), layout.b_head.clone()]);
        for block in &layout.blocks {
            ranges
                .entry(M3MicroGradientGroupV1::InputProjection)
                .or_default()
                .extend([block.w_in.clone(), block.b_in.clone()]);
            ranges
                .entry(M3MicroGradientGroupV1::RetentionDecay)
                .or_default()
                .extend([
                    block.w_decay.clone(),
                    block.b_decay.clone(),
                    block.decay_state_bias.clone(),
                ]);
            ranges
                .entry(M3MicroGradientGroupV1::PreviousInputGate)
                .or_default()
                .extend([block.w_prev_gate.clone(), block.b_prev_gate.clone()]);
            ranges
                .entry(M3MicroGradientGroupV1::CurrentInputGate)
                .or_default()
                .extend([block.w_curr_gate.clone(), block.b_curr_gate.clone()]);
            ranges
                .entry(M3MicroGradientGroupV1::StateInjectionScale)
                .or_default()
                .extend([block.prev_scale.clone(), block.curr_scale.clone()]);
            ranges
                .entry(M3MicroGradientGroupV1::StateReadout)
                .or_default()
                .push(block.readout_scale.clone());
            ranges
                .entry(M3MicroGradientGroupV1::SkipPath)
                .or_default()
                .push(block.skip.clone());
            ranges
                .entry(M3MicroGradientGroupV1::OutputProjection)
                .or_default()
                .extend([block.w_out.clone(), block.b_out.clone()]);
        }
        let groups = ranges
            .into_iter()
            .map(|(group, ranges)| {
                let values = ranges
                    .iter()
                    .flat_map(|range| gradients[range.clone()].iter().copied())
                    .collect::<Vec<_>>();
                M3MicroGradientGroupEvidenceV1 {
                    group,
                    parameter_count: values.len(),
                    nonzero_gradient_count: values.iter().filter(|value| **value != 0.0).count(),
                    gradient_l1_norm: values.iter().map(|value| value.abs()).sum(),
                    all_finite: values.iter().all(|value| value.is_finite()),
                }
            })
            .collect();
        Ok(M3MicroGradientAuditV1 {
            loss,
            training_cache_bytes,
            earliest_input_gradient_l1: input_gradients
                .first()
                .into_iter()
                .flatten()
                .map(|value| value.abs())
                .sum(),
            groups,
        })
    }
}

fn affine(
    params: &[f32],
    weights: &Range<usize>,
    bias: &Range<usize>,
    rows: usize,
    cols: usize,
    input: &[f32],
) -> Result<Vec<f32>, M3MicroError> {
    if input.len() != cols
        || weights.len() != rows * cols
        || bias.len() != rows
        || input.iter().any(|value| !value.is_finite())
    {
        return Err(M3MicroError::InvalidShape);
    }
    let mut output = vec![0.0; rows];
    for row in 0..rows {
        let mut value = params[bias.start + row];
        for col in 0..cols {
            value += params[weights.start + row * cols + col] * input[col];
        }
        if !value.is_finite() {
            return Err(M3MicroError::NonFiniteOutput);
        }
        output[row] = value;
    }
    Ok(output)
}

fn affine_tanh(
    params: &[f32],
    weights: &Range<usize>,
    bias: &Range<usize>,
    rows: usize,
    cols: usize,
    input: &[f32],
) -> Result<Vec<f32>, M3MicroError> {
    Ok(affine(params, weights, bias, rows, cols, input)?
        .into_iter()
        .map(f32::tanh)
        .collect())
}

fn affine_softsign(
    params: &[f32],
    weights: &Range<usize>,
    bias: &Range<usize>,
    rows: usize,
    cols: usize,
    input: &[f32],
) -> Result<Vec<f32>, M3MicroError> {
    Ok(affine(params, weights, bias, rows, cols, input)?
        .into_iter()
        .map(softsign)
        .collect())
}

fn softsign(value: f32) -> f32 {
    value / (1.0 + value.abs())
}

fn softsign_derivative_from_output(output: f32) -> f32 {
    (1.0 - output.abs()).powi(2)
}

fn core_activation_derivative_from_output(output: f32, softsign_activation: bool) -> f32 {
    if softsign_activation {
        softsign_derivative_from_output(output)
    } else {
        1.0 - output * output
    }
}

pub(crate) fn sigmoid(value: f32) -> f32 {
    if value >= 0.0 {
        1.0 / (1.0 + (-value).exp())
    } else {
        let exponential = value.exp();
        exponential / (1.0 + exponential)
    }
}

pub(crate) fn softplus(value: f32) -> f32 {
    if value > 20.0 {
        value
    } else if value < -20.0 {
        value.exp()
    } else {
        (1.0 + value.exp()).ln()
    }
}

pub(crate) fn softmax(values: &[f32]) -> Result<Vec<f32>, M3MicroError> {
    if values.is_empty() || values.iter().any(|value| !value.is_finite()) {
        return Err(M3MicroError::NonFiniteOutput);
    }
    let maximum = values.iter().copied().reduce(f32::max).unwrap();
    let exponentials = values
        .iter()
        .map(|value| (value - maximum).exp())
        .collect::<Vec<_>>();
    let total = exponentials.iter().sum::<f32>();
    if !total.is_finite() || total <= 0.0 {
        return Err(M3MicroError::NonFiniteOutput);
    }
    Ok(exponentials
        .into_iter()
        .map(|value| value / total)
        .collect())
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct M3MicroTarget {
    pub agent_id: AgentId,
    pub direction_distribution: Option<[f32; 3]>,
    pub future_return: Option<f32>,
    pub continuation: Option<f32>,
    pub future_variance: Option<f32>,
    pub volatility_regime: Option<[f32; 3]>,
    pub risk_abstention: Option<f32>,
    pub reversal: Option<f32>,
    pub failed_breakout: Option<f32>,
}

impl M3MicroTarget {
    pub fn validate(&self) -> Result<(), M3MicroError> {
        if role_policy_v1(self.agent_id).validate_target(self) {
            Ok(())
        } else {
            Err(M3MicroError::InvalidConfiguration)
        }
    }
}

pub(crate) fn valid_probability(value: Option<f32>) -> bool {
    value.is_some_and(|value| value.is_finite() && (0.0..=1.0).contains(&value))
}

pub(crate) fn valid_distribution(value: Option<[f32; 3]>) -> bool {
    value.is_some_and(|value| {
        value
            .iter()
            .all(|item| item.is_finite() && (0.0..=1.0).contains(item))
            && (value.iter().sum::<f32>() - 1.0).abs() <= 1e-4
    })
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct M3MicroPrediction {
    pub agent_id: AgentId,
    pub direction_distribution: Option<[f32; 3]>,
    pub expected_return: Option<f32>,
    pub continuation_probability: Option<f32>,
    pub predicted_variance: Option<f32>,
    pub volatility_regime: Option<[f32; 3]>,
    pub risk_abstention_probability: Option<f32>,
    pub reversal_probability: Option<f32>,
    pub failed_breakout_probability: Option<f32>,
    pub confidence: f32,
    pub abstain: bool,
}

impl M3MicroPrediction {
    fn from_raw(agent_id: AgentId, raw: &[f32]) -> Result<Self, M3MicroError> {
        if raw.iter().any(|value| !value.is_finite()) {
            return Err(M3MicroError::NonFiniteOutput);
        }
        let prediction = role_policy_v1(agent_id).prediction_from_raw(raw)?;
        if !prediction.confidence.is_finite() || !(0.0..=1.0).contains(&prediction.confidence) {
            return Err(M3MicroError::NonFiniteOutput);
        }
        Ok(prediction)
    }
}

pub(crate) fn empty_prediction(agent_id: AgentId) -> M3MicroPrediction {
    M3MicroPrediction {
        agent_id,
        direction_distribution: None,
        expected_return: None,
        continuation_probability: None,
        predicted_variance: None,
        volatility_regime: None,
        risk_abstention_probability: None,
        reversal_probability: None,
        failed_breakout_probability: None,
        confidence: 0.0,
        abstain: false,
    }
}

pub(crate) fn bce_loss_and_gradient(logit: f32, target: f32, calibration: f32) -> (f32, f32) {
    let probability = sigmoid(logit).clamp(PROBABILITY_EPSILON, 1.0 - PROBABILITY_EPSILON);
    let bce = -(target * probability.ln() + (1.0 - target) * (1.0 - probability).ln());
    let residual = probability - target;
    (
        bce + calibration * residual * residual,
        residual + calibration * 2.0 * residual * probability * (1.0 - probability),
    )
}

pub(crate) fn distribution_loss_and_gradient(
    logits: &[f32],
    target: &[f32; 3],
    calibration: f32,
) -> Result<(f32, Vec<f32>), M3MicroError> {
    let probabilities = softmax(logits)?;
    let cross_entropy = probabilities
        .iter()
        .zip(target)
        .map(|(probability, target)| -target * probability.clamp(PROBABILITY_EPSILON, 1.0).ln())
        .sum::<f32>();
    let mut gradient = probabilities
        .iter()
        .zip(target)
        .map(|(probability, target)| probability - target)
        .collect::<Vec<_>>();
    let probability_gradient = probabilities
        .iter()
        .zip(target)
        .map(|(probability, target)| calibration * 2.0 * (probability - target) / 3.0)
        .collect::<Vec<_>>();
    let projection = probability_gradient
        .iter()
        .zip(&probabilities)
        .map(|(gradient, probability)| gradient * probability)
        .sum::<f32>();
    for index in 0..3 {
        gradient[index] += probabilities[index] * (probability_gradient[index] - projection);
    }
    let brier = probabilities
        .iter()
        .zip(target)
        .map(|(probability, target)| (probability - target).powi(2))
        .sum::<f32>()
        / 3.0;
    Ok((cross_entropy + calibration * brier, gradient))
}

fn loss_and_output_gradient(
    agent_id: AgentId,
    raw: &[f32],
    target: &M3MicroTarget,
) -> Result<(f32, Vec<f32>), M3MicroError> {
    target.validate()?;
    if target.agent_id != agent_id {
        return Err(M3MicroError::WrongAgent);
    }
    let (loss, gradient) = role_policy_v1(agent_id).loss_and_output_gradient(raw, target)?;
    if !loss.is_finite() || gradient.iter().any(|value| !value.is_finite()) {
        return Err(M3MicroError::NonFiniteGradient);
    }
    Ok((loss, gradient))
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct M3MicroOptimizerConfig {
    pub learning_rate: f32,
    pub beta1: f32,
    pub beta2: f32,
    pub epsilon: f32,
    pub weight_decay: f32,
    pub gradient_clip_norm: f32,
}

impl Default for M3MicroOptimizerConfig {
    fn default() -> Self {
        Self {
            learning_rate: 0.001,
            beta1: 0.9,
            beta2: 0.999,
            epsilon: 1e-8,
            weight_decay: 1e-5,
            gradient_clip_norm: 1.0,
        }
    }
}

impl M3MicroOptimizerConfig {
    fn validate(&self) -> Result<(), M3MicroError> {
        if !self.learning_rate.is_finite()
            || self.learning_rate <= 0.0
            || !self.beta1.is_finite()
            || !(0.0..1.0).contains(&self.beta1)
            || !self.beta2.is_finite()
            || !(0.0..1.0).contains(&self.beta2)
            || !self.epsilon.is_finite()
            || self.epsilon <= 0.0
            || !self.weight_decay.is_finite()
            || self.weight_decay < 0.0
            || !self.gradient_clip_norm.is_finite()
            || self.gradient_clip_norm <= 0.0
        {
            return Err(M3MicroError::InvalidConfiguration);
        }
        Ok(())
    }
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct M3MicroOptimizerState {
    pub config: M3MicroOptimizerConfig,
    pub step: u64,
    first_moment: Vec<f32>,
    second_moment: Vec<f32>,
}

impl M3MicroOptimizerState {
    pub fn new(
        parameter_count: usize,
        config: M3MicroOptimizerConfig,
    ) -> Result<Self, M3MicroError> {
        config.validate()?;
        if parameter_count == 0 || parameter_count > PARAMETER_LIMIT {
            return Err(M3MicroError::InvalidConfiguration);
        }
        Ok(Self {
            config,
            step: 0,
            first_moment: vec![0.0; parameter_count],
            second_moment: vec![0.0; parameter_count],
        })
    }

    fn validate(&self, parameter_count: usize) -> Result<(), M3MicroError> {
        self.config.validate()?;
        if self.first_moment.len() != parameter_count || self.second_moment.len() != parameter_count
        {
            return Err(M3MicroError::InvalidShape);
        }
        if self
            .first_moment
            .iter()
            .chain(&self.second_moment)
            .any(|value| !value.is_finite())
        {
            return Err(M3MicroError::NonFiniteParameter);
        }
        Ok(())
    }

    pub fn digest(&self) -> String {
        stable_hash_string(&format!(
            "{:?}:{}:{:?}:{:?}",
            self.config, self.step, self.first_moment, self.second_moment
        ))
    }

    pub fn storage_identities(&self) -> [usize; 2] {
        [
            self.first_moment.as_ptr() as usize,
            self.second_moment.as_ptr() as usize,
        ]
    }

    pub fn byte_size(&self) -> usize {
        (self.first_moment.len() + self.second_moment.len()) * std::mem::size_of::<f32>()
            + std::mem::size_of::<u64>()
            + std::mem::size_of::<M3MicroOptimizerConfig>()
    }

    fn apply_values(&mut self, values: &mut [f32], gradients: &[f32]) -> Result<(), M3MicroError> {
        self.validate(values.len())?;
        if gradients.len() != values.len() {
            return Err(M3MicroError::InvalidShape);
        }
        if gradients.iter().any(|value| !value.is_finite()) {
            return Err(M3MicroError::NonFiniteGradient);
        }
        let norm = gradients
            .iter()
            .map(|value| value * value)
            .sum::<f32>()
            .sqrt();
        if !norm.is_finite() {
            return Err(M3MicroError::NonFiniteGradient);
        }
        let scale = if norm > self.config.gradient_clip_norm {
            self.config.gradient_clip_norm / norm
        } else {
            1.0
        };
        self.step = self
            .step
            .checked_add(1)
            .ok_or(M3MicroError::NonFiniteGradient)?;
        let correction1 = 1.0 - self.config.beta1.powf(self.step as f32);
        let correction2 = 1.0 - self.config.beta2.powf(self.step as f32);
        for index in 0..gradients.len() {
            let gradient = gradients[index] * scale + self.config.weight_decay * values[index];
            self.first_moment[index] =
                self.config.beta1 * self.first_moment[index] + (1.0 - self.config.beta1) * gradient;
            self.second_moment[index] = self.config.beta2 * self.second_moment[index]
                + (1.0 - self.config.beta2) * gradient * gradient;
            let first = self.first_moment[index] / correction1;
            let second = self.second_moment[index] / correction2;
            let update = self.config.learning_rate * first / (second.sqrt() + self.config.epsilon);
            if !update.is_finite() {
                return Err(M3MicroError::NonFiniteGradient);
            }
            values[index] =
                (values[index] - update).clamp(-PARAMETER_ABS_LIMIT, PARAMETER_ABS_LIMIT);
        }
        self.validate(values.len())?;
        Ok(())
    }

    fn apply(&mut self, model: &mut M3MicroModel, gradients: &[f32]) -> Result<(), M3MicroError> {
        self.apply_values(&mut model.parameters.values, gradients)?;
        model.parameters.validate(&model.config)?;
        model.refresh_identity();
        Ok(())
    }
}

fn add_affine_backward(
    params: &[f32],
    weights: &Range<usize>,
    bias: &Range<usize>,
    rows: usize,
    cols: usize,
    input: &[f32],
    output_gradient: &[f32],
    parameter_gradient: &mut [f32],
) -> Result<Vec<f32>, M3MicroError> {
    if input.len() != cols
        || output_gradient.len() != rows
        || weights.len() != rows * cols
        || bias.len() != rows
        || parameter_gradient.len() != params.len()
    {
        return Err(M3MicroError::InvalidShape);
    }
    let mut input_gradient = vec![0.0; cols];
    for row in 0..rows {
        parameter_gradient[bias.start + row] += output_gradient[row];
        for col in 0..cols {
            let index = weights.start + row * cols + col;
            parameter_gradient[index] += output_gradient[row] * input[col];
            input_gradient[col] += params[index] * output_gradient[row];
        }
    }
    Ok(input_gradient)
}

fn add_assign(destination: &mut [f32], source: &[f32]) -> Result<(), M3MicroError> {
    if destination.len() != source.len() {
        return Err(M3MicroError::InvalidShape);
    }
    for (destination, source) in destination.iter_mut().zip(source) {
        *destination += source;
    }
    Ok(())
}

#[derive(Clone, Debug, PartialEq)]
struct ModelGradientResult {
    loss: f32,
    parameter_gradients: Vec<f32>,
    input_gradients: Vec<Vec<f32>>,
    initial_state_gradients: Vec<Vec<f32>>,
    initial_previous_u_gradients: Vec<Vec<f32>>,
}

fn model_loss_gradients_internal_with_math(
    model: &M3MicroModel,
    agent_id: AgentId,
    sequence: &[Vec<f32>],
    target: &M3MicroTarget,
    capture_input_gradients: bool,
    initial_state: &M3MicroState,
    core_profile: CoreMathProfileV1,
) -> Result<ModelGradientResult, M3MicroError> {
    let tape =
        model.forward_for_training_from_state_with_math(sequence, initial_state, core_profile)?;
    let (loss, output_gradient) = loss_and_output_gradient(agent_id, &tape.raw_output, target)?;
    let config = &model.config;
    let layout = M3MicroLayout::new(config)?;
    let params = &model.parameters.values;
    let mut gradients = vec![0.0; params.len()];
    let mut input_gradients = if capture_input_gradients {
        vec![vec![0.0; config.input_dim]; tape.steps.len()]
    } else {
        Vec::new()
    };
    let final_hidden = tape
        .steps
        .last()
        .and_then(|step| step.blocks.last())
        .map(|block| &block.h_output)
        .ok_or(M3MicroError::InvalidShape)?;
    let head_hidden_gradient = add_affine_backward(
        params,
        &layout.w_head,
        &layout.b_head,
        config.output_dim,
        config.d_model,
        final_hidden,
        &output_gradient,
        &mut gradients,
    )?;
    let inner = config.inner_dim();
    let state_len = inner * config.d_state;
    let mut future_state_gradients = vec![vec![0.0; state_len]; config.block_count];
    let mut future_previous_u_gradients = vec![vec![0.0; inner]; config.block_count];
    let last_step = tape.steps.len() - 1;
    for (step_index, step) in tape.steps.iter().enumerate().rev() {
        let mut input_activity_gradient = 0.0;
        let mut hidden_gradient = if step_index == last_step {
            head_hidden_gradient.clone()
        } else {
            vec![0.0; config.d_model]
        };
        for block_index in (0..config.block_count).rev() {
            let block = &step.blocks[block_index];
            let block_layout = &layout.blocks[block_index];
            let output_pre_gradient = hidden_gradient
                .iter()
                .zip(&block.h_output)
                .map(|(gradient, output)| {
                    gradient
                        * core_activation_derivative_from_output(
                            *output,
                            core_profile.softsign_activations,
                        )
                })
                .collect::<Vec<_>>();
            let z_gradient = add_affine_backward(
                params,
                &block_layout.w_out,
                &block_layout.b_out,
                config.d_model,
                inner,
                &block.z,
                &output_pre_gradient,
                &mut gradients,
            )?;
            let readout_gradient = z_gradient
                .iter()
                .zip(&block.z)
                .map(|(gradient, z)| {
                    gradient
                        * core_activation_derivative_from_output(
                            *z,
                            core_profile.softsign_activations,
                        )
                })
                .collect::<Vec<_>>();
            let mut u_gradient = vec![0.0; inner];
            let mut state_gradient = future_state_gradients[block_index].clone();
            for channel in 0..inner {
                let skip = sigmoid(params[block_layout.skip.start + channel]);
                u_gradient[channel] += readout_gradient[channel] * skip;
                gradients[block_layout.skip.start + channel] +=
                    readout_gradient[channel] * block.u[channel] * skip * (1.0 - skip);
                for state_index in 0..config.d_state {
                    let index = channel * config.d_state + state_index;
                    let raw = params[block_layout.readout_scale.start + index];
                    let scale = raw.tanh();
                    state_gradient[index] +=
                        readout_gradient[channel] * scale * core_profile.readout_gain
                            / config.d_state as f32;
                    gradients[block_layout.readout_scale.start + index] += readout_gradient
                        [channel]
                        * block.next_state[index]
                        * core_profile.readout_gain
                        / config.d_state as f32
                        * (1.0 - scale * scale);
                }
            }
            let mut previous_state_gradient = vec![0.0; state_len];
            let mut previous_u_gradient = vec![0.0; inner];
            let mut decay_channel_gradient = vec![0.0; inner];
            let mut prev_gate_gradient = vec![0.0; inner];
            let mut curr_gate_gradient = vec![0.0; inner];
            let decay_range = config.decay_max - config.decay_min;
            for channel in 0..inner {
                for state_index in 0..config.d_state {
                    let index = channel * config.d_state + state_index;
                    let state_derivative = state_gradient[index];
                    previous_state_gradient[index] = state_derivative * block.decay[index];
                    let state_bias = params[block_layout.decay_state_bias.start + index];
                    let bounded_gradient =
                        state_derivative * block.previous_state[index] * decay_range;
                    if core_profile.reinforced_retention {
                        let base_response = block.retention_base_response[channel];
                        let decay_channel = if base_response.abs() < 1.0 {
                            base_response
                                / (RETENTION_RESPONSE_GAIN_V2 * (1.0 - base_response.abs()))
                        } else {
                            0.0
                        };
                        let baseline_response = decay_channel.signum()
                            * (decay_channel.abs() - RETENTION_BASE_LOGIT_DEAD_ZONE_V2).max(0.0)
                            * RETENTION_BASE_LOGIT_RESPONSE_SCALE_V2;
                        let baseline = sigmoid(state_bias + baseline_response);
                        let response = block.retention_response[channel];
                        let response_gradient = if response < 0.0 {
                            bounded_gradient * baseline
                        } else {
                            bounded_gradient * (1.0 - baseline)
                        };
                        decay_channel_gradient[channel] += response_gradient
                            * step.input_activity
                            * block.curr_gate[channel]
                            * block.curr_gate[channel]
                            * softsign_derivative_from_output(base_response)
                            * RETENTION_RESPONSE_GAIN_V2;
                        input_activity_gradient += response_gradient
                            * base_response
                            * block.curr_gate[channel]
                            * block.curr_gate[channel];
                        curr_gate_gradient[channel] += response_gradient
                            * base_response
                            * step.input_activity
                            * 2.0
                            * block.curr_gate[channel];
                        let baseline_gradient = if response < 0.0 {
                            bounded_gradient * (1.0 + response)
                        } else {
                            bounded_gradient * (1.0 - response)
                        };
                        gradients[block_layout.decay_state_bias.start + index] +=
                            baseline_gradient * baseline * (1.0 - baseline);
                        if decay_channel.abs() > RETENTION_BASE_LOGIT_DEAD_ZONE_V2 {
                            decay_channel_gradient[channel] += baseline_gradient
                                * baseline
                                * (1.0 - baseline)
                                * RETENTION_BASE_LOGIT_RESPONSE_SCALE_V2;
                        }
                    } else {
                        let decay_channel = block.retention_base_response[channel];
                        let retention = sigmoid(state_bias + decay_channel);
                        let retention_gradient = bounded_gradient * retention * (1.0 - retention);
                        decay_channel_gradient[channel] += retention_gradient;
                        gradients[block_layout.decay_state_bias.start + index] +=
                            retention_gradient;
                    }
                    let prev_raw = params[block_layout.prev_scale.start + index];
                    let prev_scale = prev_raw.tanh();
                    prev_gate_gradient[channel] +=
                        state_derivative * block.previous_u[channel] * prev_scale;
                    previous_u_gradient[channel] +=
                        state_derivative * block.prev_gate[channel] * prev_scale;
                    gradients[block_layout.prev_scale.start + index] += state_derivative
                        * block.prev_gate[channel]
                        * block.previous_u[channel]
                        * (1.0 - prev_scale * prev_scale);
                    let curr_raw = params[block_layout.curr_scale.start + index];
                    let curr_scale = curr_raw.tanh();
                    curr_gate_gradient[channel] += state_derivative * block.u[channel] * curr_scale;
                    u_gradient[channel] += state_derivative * block.curr_gate[channel] * curr_scale;
                    gradients[block_layout.curr_scale.start + index] += state_derivative
                        * block.curr_gate[channel]
                        * block.u[channel]
                        * (1.0 - curr_scale * curr_scale);
                }
            }
            let decay_pre_gradient = decay_channel_gradient;
            let prev_gate_pre_gradient = prev_gate_gradient
                .iter()
                .zip(&block.prev_gate)
                .map(|(gradient, gate)| gradient * gate * (1.0 - gate))
                .collect::<Vec<_>>();
            let curr_gate_pre_gradient = curr_gate_gradient
                .iter()
                .zip(&block.curr_gate)
                .map(|(gradient, gate)| gradient * gate * (1.0 - gate))
                .collect::<Vec<_>>();
            let decay_u_gradient = add_affine_backward(
                params,
                &block_layout.w_decay,
                &block_layout.b_decay,
                inner,
                inner,
                &block.u,
                &decay_pre_gradient,
                &mut gradients,
            )?;
            let prev_u_gate_gradient = add_affine_backward(
                params,
                &block_layout.w_prev_gate,
                &block_layout.b_prev_gate,
                inner,
                inner,
                &block.u,
                &prev_gate_pre_gradient,
                &mut gradients,
            )?;
            let curr_u_gate_gradient = add_affine_backward(
                params,
                &block_layout.w_curr_gate,
                &block_layout.b_curr_gate,
                inner,
                inner,
                &block.u,
                &curr_gate_pre_gradient,
                &mut gradients,
            )?;
            add_assign(&mut u_gradient, &decay_u_gradient)?;
            add_assign(&mut u_gradient, &prev_u_gate_gradient)?;
            add_assign(&mut u_gradient, &curr_u_gate_gradient)?;
            add_assign(&mut u_gradient, &future_previous_u_gradients[block_index])?;
            let u_pre_gradient = u_gradient
                .iter()
                .zip(&block.u)
                .map(|(gradient, u)| gradient * (1.0 - u * u))
                .collect::<Vec<_>>();
            hidden_gradient = add_affine_backward(
                params,
                &block_layout.w_in,
                &block_layout.b_in,
                inner,
                config.d_model,
                &block.h_input,
                &u_pre_gradient,
                &mut gradients,
            )?;
            future_state_gradients[block_index] = previous_state_gradient;
            future_previous_u_gradients[block_index] = previous_u_gradient;
        }
        let embed_pre_gradient = hidden_gradient
            .iter()
            .zip(&step.embedded)
            .map(|(gradient, embedded)| gradient * (1.0 - embedded * embedded))
            .collect::<Vec<_>>();
        let mut input_gradient = add_affine_backward(
            params,
            &layout.w_embed,
            &layout.b_embed,
            config.d_model,
            config.input_dim,
            &step.input,
            &embed_pre_gradient,
            &mut gradients,
        )?;
        for (gradient, input) in input_gradient.iter_mut().zip(&step.input) {
            let bounded_input = input.tanh();
            *gradient += input_activity_gradient
                * 2.0
                * bounded_input
                * (1.0 - bounded_input * bounded_input)
                / config.input_dim as f32;
        }
        if capture_input_gradients {
            input_gradients[step_index] = input_gradient;
        }
    }
    if gradients.iter().any(|value| !value.is_finite()) {
        return Err(M3MicroError::NonFiniteGradient);
    }
    Ok(ModelGradientResult {
        loss,
        parameter_gradients: gradients,
        input_gradients,
        initial_state_gradients: future_state_gradients,
        initial_previous_u_gradients: future_previous_u_gradients,
    })
}

fn model_loss_gradients_internal(
    model: &M3MicroModel,
    agent_id: AgentId,
    sequence: &[Vec<f32>],
    target: &M3MicroTarget,
    capture_input_gradients: bool,
) -> Result<(f32, Vec<f32>, Vec<Vec<f32>>), M3MicroError> {
    let initial_state = M3MicroState::zero(&model.config)?;
    let result = model_loss_gradients_internal_with_math(
        model,
        agent_id,
        sequence,
        target,
        capture_input_gradients,
        &initial_state,
        REDUCED_CORE_MATH_PROFILE_V1,
    )?;
    Ok((
        result.loss,
        result.parameter_gradients,
        result.input_gradients,
    ))
}

fn model_loss_and_gradients(
    model: &M3MicroModel,
    agent_id: AgentId,
    sequence: &[Vec<f32>],
    target: &M3MicroTarget,
) -> Result<(f32, Vec<f32>), M3MicroError> {
    model_loss_gradients_internal(model, agent_id, sequence, target, false)
        .map(|(loss, gradients, _)| (loss, gradients))
}

#[derive(Clone, Debug)]
struct M3MicroV2BlockLayout {
    w_local: Range<usize>,
    b_local: Range<usize>,
    gate_state_scale: Range<usize>,
    gate_input_scale: Range<usize>,
    gate_bias: Range<usize>,
    candidate_state_scale: Range<usize>,
    candidate_input_scale: Range<usize>,
    candidate_bias: Range<usize>,
    memory_read_scale: Range<usize>,
}

#[derive(Clone, Debug)]
struct M3MicroV2Layout {
    w_embed: Range<usize>,
    b_embed: Range<usize>,
    blocks: Vec<M3MicroV2BlockLayout>,
    w_head: Range<usize>,
    b_head: Range<usize>,
    parameter_count: usize,
}

impl M3MicroV2Layout {
    fn new(config: &M3MicroConfig) -> Result<Self, M3MicroError> {
        let state_len = config
            .d_model
            .checked_mul(config.d_state)
            .ok_or(M3MicroError::InvalidConfiguration)?;
        let mut builder = LayoutBuilder::default();
        let w_embed = builder.take(config.d_model * config.input_dim);
        let b_embed = builder.take(config.d_model);
        let mut blocks = Vec::with_capacity(config.block_count);
        for _ in 0..config.block_count {
            blocks.push(M3MicroV2BlockLayout {
                w_local: builder.take(config.d_model * config.d_model),
                b_local: builder.take(config.d_model),
                gate_state_scale: builder.take(state_len),
                gate_input_scale: builder.take(state_len),
                gate_bias: builder.take(state_len),
                candidate_state_scale: builder.take(state_len),
                candidate_input_scale: builder.take(state_len),
                candidate_bias: builder.take(state_len),
                memory_read_scale: builder.take(state_len),
            });
        }
        let w_head = builder.take(config.output_dim * config.d_model);
        let b_head = builder.take(config.output_dim);
        if builder.next > PARAMETER_LIMIT {
            return Err(M3MicroError::InvalidConfiguration);
        }
        Ok(Self {
            w_embed,
            b_embed,
            blocks,
            w_head,
            b_head,
            parameter_count: builder.next,
        })
    }
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct M3MicroV2Parameters {
    values: Vec<f32>,
}

impl M3MicroV2Parameters {
    fn seeded(config: &M3MicroConfig, seed: u64) -> Result<Self, M3MicroError> {
        let layout = M3MicroV2Layout::new(config)?;
        let mut rng = DeterministicRng::new(seed);
        let mut values = (0..layout.parameter_count)
            .map(|_| rng.symmetric(0.02))
            .collect::<Vec<_>>();
        values[layout.b_embed.clone()].fill(0.0);
        values[layout.b_head.clone()].fill(0.0);
        for feature in 0..config.input_dim.min(config.d_model) {
            values[layout.w_embed.start + feature * config.input_dim + feature] +=
                INITIAL_INPUT_IDENTITY_SCALE_V2;
        }
        for block in &layout.blocks {
            values[block.b_local.clone()].fill(0.0);
            for feature in 0..config.d_model {
                values[block.w_local.start + feature * config.d_model + feature] +=
                    INITIAL_INPUT_IDENTITY_SCALE_V2;
            }
            values[block.gate_state_scale.clone()].fill(0.25);
            values[block.gate_input_scale.clone()].fill(0.25);
            values[block.gate_bias.clone()].fill(0.0);
            values[block.candidate_state_scale.clone()].fill(0.5);
            values[block.candidate_input_scale.clone()].fill(1.0);
            values[block.candidate_bias.clone()].fill(0.0);
            values[block.memory_read_scale.clone()].fill(1.0);
        }
        let parameters = Self { values };
        parameters.validate(config)?;
        Ok(parameters)
    }

    fn validate(&self, config: &M3MicroConfig) -> Result<(), M3MicroError> {
        let expected = M3MicroV2Layout::new(config)?.parameter_count;
        if self.values.len() != expected {
            return Err(M3MicroError::InvalidShape);
        }
        if self
            .values
            .iter()
            .any(|value| !value.is_finite() || value.abs() > PARAMETER_ABS_LIMIT)
        {
            return Err(M3MicroError::NonFiniteParameter);
        }
        Ok(())
    }

    pub fn len(&self) -> usize {
        self.values.len()
    }

    pub fn is_empty(&self) -> bool {
        self.values.is_empty()
    }

    pub fn digest(&self) -> String {
        stable_hash_string(&format!("{:?}", self.values))
    }
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct M3MicroV2BlockState {
    values: Vec<f32>,
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct M3MicroV2State {
    pub blocks: Vec<M3MicroV2BlockState>,
    pub step_index: usize,
}

impl M3MicroV2State {
    pub fn zero(config: &M3MicroConfig) -> Result<Self, M3MicroError> {
        config.validate()?;
        let state_len = config
            .d_model
            .checked_mul(config.d_state)
            .ok_or(M3MicroError::InvalidConfiguration)?;
        Ok(Self {
            blocks: (0..config.block_count)
                .map(|_| M3MicroV2BlockState {
                    values: vec![0.0; state_len],
                })
                .collect(),
            step_index: 0,
        })
    }

    pub fn validate(&self, config: &M3MicroConfig) -> Result<(), M3MicroError> {
        let state_len = config
            .d_model
            .checked_mul(config.d_state)
            .ok_or(M3MicroError::InvalidConfiguration)?;
        if self.blocks.len() != config.block_count
            || self
                .blocks
                .iter()
                .any(|block| block.values.len() != state_len)
        {
            return Err(M3MicroError::InvalidShape);
        }
        if self
            .blocks
            .iter()
            .flat_map(|block| &block.values)
            .any(|value| !value.is_finite())
        {
            return Err(M3MicroError::NonFiniteOutput);
        }
        if self
            .blocks
            .iter()
            .flat_map(|block| &block.values)
            .any(|value| value.abs() > 1.0 + 1.0e-5)
        {
            return Err(M3MicroError::StateExplosion);
        }
        Ok(())
    }

    pub fn byte_size(&self) -> usize {
        self.blocks
            .iter()
            .map(|block| block.values.len() * std::mem::size_of::<f32>())
            .sum::<usize>()
            + std::mem::size_of::<usize>()
    }

    pub fn value_count(&self) -> usize {
        self.blocks.iter().map(|block| block.values.len()).sum()
    }

    pub fn digest(&self) -> String {
        stable_hash_string(&format!("{self:?}"))
    }
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct M3MicroV2Candidate {
    pub config: M3MicroConfig,
    pub parameters: M3MicroV2Parameters,
    pub model_identity: String,
}

#[derive(Clone, Debug)]
struct M3MicroV2BlockTape {
    h_input: Vec<f32>,
    u: Vec<f32>,
    previous_state: Vec<f32>,
    gate: Vec<f32>,
    candidate: Vec<f32>,
    next_state: Vec<f32>,
    h_output: Vec<f32>,
}

#[derive(Clone, Debug)]
struct M3MicroV2StepTape {
    input: Vec<f32>,
    embedded: Vec<f32>,
    blocks: Vec<M3MicroV2BlockTape>,
}

#[derive(Clone, Debug)]
struct M3MicroV2ForwardTape {
    steps: Vec<M3MicroV2StepTape>,
    raw_output: Vec<f32>,
}

impl M3MicroV2Candidate {
    pub fn seeded(config: M3MicroConfig, seed: u64) -> Result<Self, M3MicroError> {
        config.validate()?;
        let parameters = M3MicroV2Parameters::seeded(&config, seed)?;
        let mut model = Self {
            config,
            parameters,
            model_identity: String::new(),
        };
        model.refresh_identity();
        Ok(model)
    }

    pub fn revision(&self) -> M3MicroCoreRevisionV2 {
        M3MicroCoreRevisionV2::V2Candidate
    }

    pub fn validate(&self) -> Result<(), M3MicroError> {
        self.config.validate()?;
        self.parameters.validate(&self.config)?;
        if self.model_identity != self.computed_identity() {
            return Err(M3MicroError::CorruptArtifact);
        }
        Ok(())
    }

    pub fn parameter_count(&self) -> usize {
        self.parameters.len()
    }

    pub fn parameter_digest(&self) -> String {
        self.parameters.digest()
    }

    pub fn zero_state(&self) -> Result<M3MicroV2State, M3MicroError> {
        M3MicroV2State::zero(&self.config)
    }

    fn computed_identity(&self) -> String {
        stable_hash_string(&format!(
            "{M3_MICRO_V2_CANDIDATE_SCHEMA_V1}:{:?}:{}",
            self.config,
            self.parameters.digest()
        ))
    }

    fn refresh_identity(&mut self) {
        self.model_identity = self.computed_identity();
    }

    pub fn forward(
        &self,
        sequence: &[Vec<f32>],
        state: &mut M3MicroV2State,
    ) -> Result<Vec<f32>, M3MicroError> {
        self.forward_with_work_counters(sequence, state)
            .map(|(output, _)| output)
    }

    pub fn forward_with_work_counters(
        &self,
        sequence: &[Vec<f32>],
        state: &mut M3MicroV2State,
    ) -> Result<(Vec<f32>, M3MicroWorkCountersV1), M3MicroError> {
        let mut counters = M3MicroWorkCountersV1::default();
        let output = self
            .forward_internal(sequence, state, false, true, &mut counters)?
            .raw_output;
        Ok((output, counters))
    }

    pub fn stream_step(
        &self,
        input: &[f32],
        state: &mut M3MicroV2State,
    ) -> Result<(Vec<f32>, M3MicroWorkCountersV1), M3MicroError> {
        self.forward_with_work_counters(&[input.to_vec()], state)
    }

    pub fn forward_from_zero_with_work_counters(
        &self,
        sequence: &[Vec<f32>],
    ) -> Result<(Vec<f32>, M3MicroV2State, M3MicroWorkCountersV1), M3MicroError> {
        let mut state = self.zero_state()?;
        let (output, mut counters) = self.forward_with_work_counters(sequence, &mut state)?;
        counters.state_allocation_count = 1;
        Ok((output, state, counters))
    }

    pub fn forward_with_backend(
        &self,
        backend: M3MicroBackendKind,
        sequence: &[Vec<f32>],
        state: &mut M3MicroV2State,
    ) -> Result<Vec<f32>, M3MicroError> {
        if backend != M3MicroBackendKind::DefaultCpu {
            return Err(M3MicroError::UnsupportedCandidateBackend);
        }
        self.forward(sequence, state)
    }

    fn forward_internal(
        &self,
        sequence: &[Vec<f32>],
        state: &mut M3MicroV2State,
        record_tape: bool,
        state_enabled: bool,
        counters: &mut M3MicroWorkCountersV1,
    ) -> Result<M3MicroV2ForwardTape, M3MicroError> {
        self.validate()?;
        state.validate(&self.config)?;
        if sequence.is_empty()
            || sequence.iter().any(|row| {
                row.len() != self.config.input_dim || row.iter().any(|value| !value.is_finite())
            })
        {
            return Err(M3MicroError::NonFiniteInput);
        }
        let layout = M3MicroV2Layout::new(&self.config)?;
        let params = &self.parameters.values;
        let state_len = self.config.d_model * self.config.d_state;
        let mut tapes = Vec::with_capacity(sequence.len());
        let mut final_hidden = vec![0.0; self.config.d_model];
        for input in sequence {
            counters.sequence_step_count = counters
                .sequence_step_count
                .checked_add(1)
                .ok_or(M3MicroError::StateExplosion)?;
            let embedded = affine_tanh(
                params,
                &layout.w_embed,
                &layout.b_embed,
                self.config.d_model,
                self.config.input_dim,
                input,
            )?;
            counters.projection_operation_count = counters
                .projection_operation_count
                .checked_add(1)
                .ok_or(M3MicroError::StateExplosion)?;
            let mut hidden = embedded.clone();
            let mut block_tapes = Vec::with_capacity(self.config.block_count);
            for (block_index, block_layout) in layout.blocks.iter().enumerate() {
                let block_state = &mut state.blocks[block_index];
                let previous_state = block_state.values.clone();
                let u = affine_tanh(
                    params,
                    &block_layout.w_local,
                    &block_layout.b_local,
                    self.config.d_model,
                    self.config.d_model,
                    &hidden,
                )?;
                let mut gate = vec![0.0; state_len];
                let mut candidate = vec![0.0; state_len];
                let mut next_state = vec![0.0; state_len];
                for index in 0..state_len {
                    let channel = index / self.config.d_state;
                    let projected_input = u[channel];
                    gate[index] = sigmoid(
                        params[block_layout.gate_state_scale.start + index] * previous_state[index]
                            + params[block_layout.gate_input_scale.start + index] * projected_input
                            + params[block_layout.gate_bias.start + index],
                    );
                    candidate[index] = (params[block_layout.candidate_state_scale.start + index]
                        * previous_state[index]
                        + params[block_layout.candidate_input_scale.start + index]
                            * projected_input
                        + params[block_layout.candidate_bias.start + index])
                        .tanh();
                    let value = previous_state[index]
                        + gate[index] * (candidate[index] - previous_state[index]);
                    if !value.is_finite() {
                        return Err(M3MicroError::NonFiniteOutput);
                    }
                    next_state[index] = value;
                }
                let mut memory = vec![0.0; self.config.d_model];
                for channel in 0..self.config.d_model {
                    for state_index in 0..self.config.d_state {
                        let index = channel * self.config.d_state + state_index;
                        memory[channel] += next_state[index]
                            * params[block_layout.memory_read_scale.start + index]
                            / self.config.d_state as f32;
                    }
                }
                let h_output = u
                    .iter()
                    .zip(&memory)
                    .map(|(local, memory)| local + if state_enabled { *memory } else { 0.0 })
                    .collect::<Vec<_>>();
                if h_output.iter().any(|value| !value.is_finite()) {
                    return Err(M3MicroError::NonFiniteOutput);
                }
                counters.projection_operation_count = counters
                    .projection_operation_count
                    .checked_add(1)
                    .ok_or(M3MicroError::StateExplosion)?;
                counters.state_transition_count = counters
                    .state_transition_count
                    .checked_add(state_len)
                    .ok_or(M3MicroError::StateExplosion)?;
                block_state.values.clone_from(&next_state);
                if record_tape {
                    block_tapes.push(M3MicroV2BlockTape {
                        h_input: hidden,
                        u,
                        previous_state,
                        gate,
                        candidate,
                        next_state,
                        h_output: h_output.clone(),
                    });
                }
                hidden = h_output;
            }
            final_hidden = hidden;
            if record_tape {
                tapes.push(M3MicroV2StepTape {
                    input: input.clone(),
                    embedded,
                    blocks: block_tapes,
                });
            }
            state.step_index = state
                .step_index
                .checked_add(1)
                .ok_or(M3MicroError::StateExplosion)?;
            state.validate(&self.config)?;
        }
        let raw_output = affine(
            params,
            &layout.w_head,
            &layout.b_head,
            self.config.output_dim,
            self.config.d_model,
            &final_hidden,
        )?;
        counters.projection_operation_count = counters
            .projection_operation_count
            .checked_add(1)
            .ok_or(M3MicroError::StateExplosion)?;
        if raw_output.iter().any(|value| !value.is_finite()) {
            return Err(M3MicroError::NonFiniteOutput);
        }
        Ok(M3MicroV2ForwardTape {
            steps: tapes,
            raw_output,
        })
    }
}

#[derive(Clone, Debug, PartialEq)]
struct M3MicroV2GradientResult {
    loss: f32,
    parameter_gradients: Vec<f32>,
    input_gradients: Vec<Vec<f32>>,
}

impl M3MicroV2Candidate {
    fn loss_gradients_internal(
        &self,
        agent_id: AgentId,
        sequence: &[Vec<f32>],
        target: &M3MicroTarget,
        capture_input_gradients: bool,
        state_enabled: bool,
    ) -> Result<M3MicroV2GradientResult, M3MicroError> {
        let mut state = self.zero_state()?;
        let mut counters = M3MicroWorkCountersV1::default();
        let tape =
            self.forward_internal(sequence, &mut state, true, state_enabled, &mut counters)?;
        let (loss, output_gradient) = loss_and_output_gradient(agent_id, &tape.raw_output, target)?;
        let layout = M3MicroV2Layout::new(&self.config)?;
        let params = &self.parameters.values;
        let state_len = self.config.d_model * self.config.d_state;
        let mut gradients = vec![0.0; params.len()];
        let mut input_gradients = if capture_input_gradients {
            vec![vec![0.0; self.config.input_dim]; tape.steps.len()]
        } else {
            Vec::new()
        };
        let final_hidden = tape
            .steps
            .last()
            .and_then(|step| step.blocks.last())
            .map(|block| &block.h_output)
            .ok_or(M3MicroError::InvalidShape)?;
        let head_hidden_gradient = add_affine_backward(
            params,
            &layout.w_head,
            &layout.b_head,
            self.config.output_dim,
            self.config.d_model,
            final_hidden,
            &output_gradient,
            &mut gradients,
        )?;
        let mut future_state_gradients = vec![vec![0.0; state_len]; self.config.block_count];
        let last_step = tape.steps.len() - 1;
        for (step_index, step) in tape.steps.iter().enumerate().rev() {
            let mut hidden_gradient = if step_index == last_step {
                head_hidden_gradient.clone()
            } else {
                vec![0.0; self.config.d_model]
            };
            for block_index in (0..self.config.block_count).rev() {
                let block = &step.blocks[block_index];
                let block_layout = &layout.blocks[block_index];
                let mut u_gradient = hidden_gradient.clone();
                let mut state_gradient = future_state_gradients[block_index].clone();
                if state_enabled {
                    for channel in 0..self.config.d_model {
                        for state_index in 0..self.config.d_state {
                            let index = channel * self.config.d_state + state_index;
                            let read_scale = params[block_layout.memory_read_scale.start + index];
                            state_gradient[index] +=
                                hidden_gradient[channel] * read_scale / self.config.d_state as f32;
                            gradients[block_layout.memory_read_scale.start + index] +=
                                hidden_gradient[channel] * block.next_state[index]
                                    / self.config.d_state as f32;
                        }
                    }
                }
                let mut previous_state_gradient = vec![0.0; state_len];
                for index in 0..state_len {
                    let channel = index / self.config.d_state;
                    let state_derivative = state_gradient[index];
                    let gate_gradient =
                        state_derivative * (block.candidate[index] - block.previous_state[index]);
                    let candidate_gradient = state_derivative * block.gate[index];
                    let gate_pre_gradient =
                        gate_gradient * block.gate[index] * (1.0 - block.gate[index]);
                    let candidate_pre_gradient = candidate_gradient
                        * (1.0 - block.candidate[index] * block.candidate[index]);
                    let projected_input = block.u[channel];
                    gradients[block_layout.gate_state_scale.start + index] +=
                        gate_pre_gradient * block.previous_state[index];
                    gradients[block_layout.gate_input_scale.start + index] +=
                        gate_pre_gradient * projected_input;
                    gradients[block_layout.gate_bias.start + index] += gate_pre_gradient;
                    gradients[block_layout.candidate_state_scale.start + index] +=
                        candidate_pre_gradient * block.previous_state[index];
                    gradients[block_layout.candidate_input_scale.start + index] +=
                        candidate_pre_gradient * projected_input;
                    gradients[block_layout.candidate_bias.start + index] += candidate_pre_gradient;
                    previous_state_gradient[index] = state_derivative * (1.0 - block.gate[index])
                        + gate_pre_gradient * params[block_layout.gate_state_scale.start + index]
                        + candidate_pre_gradient
                            * params[block_layout.candidate_state_scale.start + index];
                    u_gradient[channel] += gate_pre_gradient
                        * params[block_layout.gate_input_scale.start + index]
                        + candidate_pre_gradient
                            * params[block_layout.candidate_input_scale.start + index];
                }
                let u_pre_gradient = u_gradient
                    .iter()
                    .zip(&block.u)
                    .map(|(gradient, value)| gradient * (1.0 - value * value))
                    .collect::<Vec<_>>();
                hidden_gradient = add_affine_backward(
                    params,
                    &block_layout.w_local,
                    &block_layout.b_local,
                    self.config.d_model,
                    self.config.d_model,
                    &block.h_input,
                    &u_pre_gradient,
                    &mut gradients,
                )?;
                future_state_gradients[block_index] = previous_state_gradient;
            }
            let embed_pre_gradient = hidden_gradient
                .iter()
                .zip(&step.embedded)
                .map(|(gradient, value)| gradient * (1.0 - value * value))
                .collect::<Vec<_>>();
            let input_gradient = add_affine_backward(
                params,
                &layout.w_embed,
                &layout.b_embed,
                self.config.d_model,
                self.config.input_dim,
                &step.input,
                &embed_pre_gradient,
                &mut gradients,
            )?;
            if capture_input_gradients {
                input_gradients[step_index] = input_gradient;
            }
        }
        if gradients.iter().any(|value| !value.is_finite()) {
            return Err(M3MicroError::NonFiniteGradient);
        }
        Ok(M3MicroV2GradientResult {
            loss,
            parameter_gradients: gradients,
            input_gradients,
        })
    }

    fn apply_gradients(
        &mut self,
        optimizer: &mut M3MicroOptimizerState,
        gradients: &[f32],
    ) -> Result<(), M3MicroError> {
        optimizer.apply_values(&mut self.parameters.values, gradients)?;
        self.parameters.validate(&self.config)?;
        self.refresh_identity();
        Ok(())
    }

    fn train_step_with_state(
        &mut self,
        optimizer: &mut M3MicroOptimizerState,
        agent_id: AgentId,
        sequence: &[Vec<f32>],
        target: &M3MicroTarget,
        state_enabled: bool,
    ) -> Result<f32, M3MicroError> {
        let result =
            self.loss_gradients_internal(agent_id, sequence, target, false, state_enabled)?;
        self.apply_gradients(optimizer, &result.parameter_gradients)?;
        Ok(result.loss)
    }

    pub fn train_development_step(
        &mut self,
        optimizer: &mut M3MicroOptimizerState,
        agent_id: AgentId,
        sequence: &[Vec<f32>],
        target: &M3MicroTarget,
    ) -> Result<f32, M3MicroError> {
        self.train_step_with_state(optimizer, agent_id, sequence, target, true)
    }
}

