    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    enum GradientVariableV1 {
        Parameter(usize),
        Input { step: usize, index: usize },
        InitialState { block: usize, index: usize },
        InitialPreviousU { block: usize, index: usize },
    }

    #[derive(Clone, Debug, PartialEq)]
    struct GradientPathEvidenceV1 {
        path: String,
        analytical: f32,
        numerical_by_step: [f32; 3],
        numerical: f32,
        absolute_error: f32,
        relative_error: f32,
        sign_matches: bool,
        stable_step_count: usize,
    }

    #[derive(Clone, Debug, PartialEq)]
    struct GradientConformanceEvidenceV1 {
        policy: NumericalGradientConformancePolicyV1,
        initial_parameter_digest: String,
        single_step: Vec<GradientPathEvidenceV1>,
        multi_step: Vec<GradientPathEvidenceV1>,
        positive_branch: GradientPathEvidenceV1,
        negative_branch: GradientPathEvidenceV1,
        dead_zone: GradientPathEvidenceV1,
        dead_zone_state_bias_gradient: f32,
        boundary_loss_spans: [f32; 2],
    }

    fn gradient_fixture_v1(
        decay_channel: f32,
        sequence_length: usize,
    ) -> Result<(M3MicroModel, M3MicroState, Vec<Vec<f32>>, M3MicroTarget), M3MicroError> {
        let mut model = M3MicroModel::seeded(
            M3MicroConfig::for_agent(AgentId::TrendContinuation, 8),
            V2_EVIDENCE_SEED,
        )?;
        let layout = M3MicroLayout::new(&model.config)?;
        for block in &layout.blocks {
            model.parameters.values[block.w_decay.clone()].fill(0.0);
            model.parameters.values[block.b_decay.clone()].fill(decay_channel);
            model.parameters.values[block.decay_state_bias.clone()].fill(0.25);
            model.parameters.values[block.b_curr_gate.clone()].fill(0.2);
        }
        model.refresh_identity();
        let mut state = M3MicroState::zero(&model.config)?;
        for block in &mut state.blocks {
            for (index, value) in block.values.iter_mut().enumerate() {
                *value = 0.08 + (index % 7) as f32 * 0.01;
            }
            for (index, value) in block.previous_u.iter_mut().enumerate() {
                *value = if index % 2 == 0 { 0.06 } else { -0.04 };
            }
        }
        let sequence = (0..sequence_length)
            .map(|step| {
                let phase = step as f32 * 0.37;
                let mut input = row(model.config.input_dim, 0.65 - phase * 0.04, -0.3);
                input[2] = phase.sin() * 0.12;
                input[3] = phase.cos() * 0.08;
                input
            })
            .collect();
        Ok((model, state, sequence, trend_target()))
    }

    fn maximum_gradient_index(gradients: &[f32], range: &Range<usize>) -> usize {
        range
            .clone()
            .max_by(|left, right| gradients[*left].abs().total_cmp(&gradients[*right].abs()))
            .unwrap()
    }

    fn maximum_value_index(values: &[f32]) -> usize {
        values
            .iter()
            .enumerate()
            .max_by(|(_, left), (_, right)| left.abs().total_cmp(&right.abs()))
            .map(|(index, _)| index)
            .unwrap()
    }

    fn gradient_variable_value_v1(
        model: &M3MicroModel,
        state: &M3MicroState,
        sequence: &[Vec<f32>],
        variable: GradientVariableV1,
    ) -> f32 {
        match variable {
            GradientVariableV1::Parameter(index) => model.parameters.values[index],
            GradientVariableV1::Input { step, index } => sequence[step][index],
            GradientVariableV1::InitialState { block, index } => state.blocks[block].values[index],
            GradientVariableV1::InitialPreviousU { block, index } => {
                state.blocks[block].previous_u[index]
            }
        }
    }

    fn snapshot_loss_with_math_v1(
        model: &M3MicroModel,
        state: &M3MicroState,
        sequence: &[Vec<f32>],
        target: &M3MicroTarget,
        variable: GradientVariableV1,
        delta: f32,
        core_profile: CoreMathProfileV1,
    ) -> Result<f32, M3MicroError> {
        let mut perturbed_model = model.clone();
        let mut perturbed_state = state.clone();
        let mut perturbed_sequence = sequence.to_vec();
        match variable {
            GradientVariableV1::Parameter(index) => {
                perturbed_model.parameters.values[index] += delta;
                perturbed_model.refresh_identity();
            }
            GradientVariableV1::Input { step, index } => {
                perturbed_sequence[step][index] += delta;
            }
            GradientVariableV1::InitialState { block, index } => {
                perturbed_state.blocks[block].values[index] += delta;
            }
            GradientVariableV1::InitialPreviousU { block, index } => {
                perturbed_state.blocks[block].previous_u[index] += delta;
            }
        }
        let mut counters = M3MicroWorkCountersV1::default();
        let tape = perturbed_model.forward_internal_with_profile(
            &perturbed_sequence,
            &mut perturbed_state,
            false,
            &mut counters,
            core_profile,
        )?;
        perturbed_state.validate(&perturbed_model.config)?;
        loss_and_output_gradient(AgentId::TrendContinuation, &tape.raw_output, target)
            .map(|(loss, _)| loss)
    }

    fn snapshot_loss_v1(
        model: &M3MicroModel,
        state: &M3MicroState,
        sequence: &[Vec<f32>],
        target: &M3MicroTarget,
        variable: GradientVariableV1,
        delta: f32,
        core_profile: CoreMathProfileV1,
    ) -> Result<f32, M3MicroError> {
        snapshot_loss_with_math_v1(
            model,
            state,
            sequence,
            target,
            variable,
            delta,
            core_profile,
        )
    }

    fn compare_gradient_v1(
        path: &str,
        analytical: f32,
        model: &M3MicroModel,
        state: &M3MicroState,
        sequence: &[Vec<f32>],
        target: &M3MicroTarget,
        variable: GradientVariableV1,
        policy: NumericalGradientConformancePolicyV1,
        core_profile: CoreMathProfileV1,
    ) -> Result<GradientPathEvidenceV1, M3MicroError> {
        let value = gradient_variable_value_v1(model, state, sequence, variable);
        let mut numerical_by_step = [0.0; 3];
        let mut stable_step_count = 0;
        for (index, relative_scale) in policy.relative_step_scales.iter().enumerate() {
            let step = relative_scale * value.abs().max(1.0);
            let plus =
                snapshot_loss_v1(model, state, sequence, target, variable, step, core_profile)?;
            let minus = snapshot_loss_v1(
                model,
                state,
                sequence,
                target,
                variable,
                -step,
                core_profile,
            )?;
            let numerical = (plus - minus) / (2.0 * step);
            numerical_by_step[index] = numerical;
            let absolute_error = (analytical - numerical).abs();
            let tolerance = policy.absolute_tolerance
                + policy.relative_tolerance * analytical.abs().max(numerical.abs());
            let sign_matches = analytical.abs() <= policy.sign_check_floor
                || numerical.abs() <= policy.sign_check_floor
                || analytical.signum() == numerical.signum();
            stable_step_count += usize::from(absolute_error <= tolerance && sign_matches);
        }
        let numerical = numerical_by_step[2];
        let absolute_error = (analytical - numerical).abs();
        let relative_error = absolute_error / analytical.abs().max(numerical.abs()).max(1.0e-12);
        let sign_matches = analytical.abs() <= policy.sign_check_floor
            || numerical.abs() <= policy.sign_check_floor
            || analytical.signum() == numerical.signum();
        Ok(GradientPathEvidenceV1 {
            path: path.to_string(),
            analytical,
            numerical_by_step,
            numerical,
            absolute_error,
            relative_error,
            sign_matches,
            stable_step_count,
        })
    }

    fn parameter_comparison_v1(
        path: &str,
        range: &Range<usize>,
        result: &ModelGradientResult,
        model: &M3MicroModel,
        state: &M3MicroState,
        sequence: &[Vec<f32>],
        target: &M3MicroTarget,
        policy: NumericalGradientConformancePolicyV1,
        core_profile: CoreMathProfileV1,
    ) -> Result<GradientPathEvidenceV1, M3MicroError> {
        let index = maximum_gradient_index(&result.parameter_gradients, range);
        compare_gradient_v1(
            path,
            result.parameter_gradients[index],
            model,
            state,
            sequence,
            target,
            GradientVariableV1::Parameter(index),
            policy,
            core_profile,
        )
    }

    fn run_gradient_conformance_with_math_v1(
        core_profile: CoreMathProfileV1,
    ) -> Result<GradientConformanceEvidenceV1, M3MicroError> {
        let policy = numerical_gradient_conformance_policy_v1();
        let (single_model, single_state, single_sequence, single_target) =
            gradient_fixture_v1(1.6, policy.single_step_sequence_length)?;
        let single_result = model_loss_gradients_internal_with_math(
            &single_model,
            AgentId::TrendContinuation,
            &single_sequence,
            &single_target,
            true,
            &single_state,
            core_profile,
        )?;
        let single_layout = M3MicroLayout::new(&single_model.config)?;
        let first_block = &single_layout.blocks[0];
        let last_block = single_layout.blocks.last().unwrap();
        let input_index = maximum_value_index(&single_result.input_gradients[0]);
        let initial_state_index = maximum_value_index(&single_result.initial_state_gradients[0]);
        let previous_u_index = maximum_value_index(&single_result.initial_previous_u_gradients[0]);
        let single_step = vec![
            parameter_comparison_v1(
                "w_decay representative",
                &first_block.w_decay,
                &single_result,
                &single_model,
                &single_state,
                &single_sequence,
                &single_target,
                policy,
                core_profile,
            )?,
            parameter_comparison_v1(
                "b_decay representative",
                &first_block.b_decay,
                &single_result,
                &single_model,
                &single_state,
                &single_sequence,
                &single_target,
                policy,
                core_profile,
            )?,
            parameter_comparison_v1(
                "decay_state_bias representative",
                &first_block.decay_state_bias,
                &single_result,
                &single_model,
                &single_state,
                &single_sequence,
                &single_target,
                policy,
                core_profile,
            )?,
            parameter_comparison_v1(
                "current gate retention path",
                &first_block.b_curr_gate,
                &single_result,
                &single_model,
                &single_state,
                &single_sequence,
                &single_target,
                policy,
                core_profile,
            )?,
            parameter_comparison_v1(
                "readout representative",
                &last_block.readout_scale,
                &single_result,
                &single_model,
                &single_state,
                &single_sequence,
                &single_target,
                policy,
                core_profile,
            )?,
            parameter_comparison_v1(
                "output activation path",
                &last_block.w_out,
                &single_result,
                &single_model,
                &single_state,
                &single_sequence,
                &single_target,
                policy,
                core_profile,
            )?,
            compare_gradient_v1(
                "input activity path",
                single_result.input_gradients[0][input_index],
                &single_model,
                &single_state,
                &single_sequence,
                &single_target,
                GradientVariableV1::Input {
                    step: 0,
                    index: input_index,
                },
                policy,
                core_profile,
            )?,
            compare_gradient_v1(
                "initial recurrent state",
                single_result.initial_state_gradients[0][initial_state_index],
                &single_model,
                &single_state,
                &single_sequence,
                &single_target,
                GradientVariableV1::InitialState {
                    block: 0,
                    index: initial_state_index,
                },
                policy,
                core_profile,
            )?,
            compare_gradient_v1(
                "previous projected input",
                single_result.initial_previous_u_gradients[0][previous_u_index],
                &single_model,
                &single_state,
                &single_sequence,
                &single_target,
                GradientVariableV1::InitialPreviousU {
                    block: 0,
                    index: previous_u_index,
                },
                policy,
                core_profile,
            )?,
        ];

        let (multi_model, multi_state, multi_sequence, multi_target) =
            gradient_fixture_v1(-1.6, policy.multi_step_sequence_length)?;
        let multi_result = model_loss_gradients_internal_with_math(
            &multi_model,
            AgentId::TrendContinuation,
            &multi_sequence,
            &multi_target,
            true,
            &multi_state,
            core_profile,
        )?;
        let multi_layout = M3MicroLayout::new(&multi_model.config)?;
        let first_input_index = maximum_value_index(&multi_result.input_gradients[0]);
        let multi_step = vec![
            compare_gradient_v1(
                "first input to final loss",
                multi_result.input_gradients[0][first_input_index],
                &multi_model,
                &multi_state,
                &multi_sequence,
                &multi_target,
                GradientVariableV1::Input {
                    step: 0,
                    index: first_input_index,
                },
                policy,
                core_profile,
            )?,
            parameter_comparison_v1(
                "shared retention parameter through four steps",
                &multi_layout.blocks[0].w_decay,
                &multi_result,
                &multi_model,
                &multi_state,
                &multi_sequence,
                &multi_target,
                policy,
                core_profile,
            )?,
            parameter_comparison_v1(
                "final readout path",
                &multi_layout.blocks.last().unwrap().readout_scale,
                &multi_result,
                &multi_model,
                &multi_state,
                &multi_sequence,
                &multi_target,
                policy,
                core_profile,
            )?,
            parameter_comparison_v1(
                "final output path",
                &multi_layout.blocks.last().unwrap().w_out,
                &multi_result,
                &multi_model,
                &multi_state,
                &multi_sequence,
                &multi_target,
                policy,
                core_profile,
            )?,
        ];

        let mut branch_evidence = Vec::new();
        for (name, decay_channel) in [
            ("positive retention branch", 1.6),
            ("negative retention branch", -1.6),
        ] {
            let (model, state, sequence, target) = gradient_fixture_v1(decay_channel, 1)?;
            let result = model_loss_gradients_internal_with_math(
                &model,
                AgentId::TrendContinuation,
                &sequence,
                &target,
                true,
                &state,
                core_profile,
            )?;
            let layout = M3MicroLayout::new(&model.config)?;
            branch_evidence.push(parameter_comparison_v1(
                name,
                &layout.blocks[0].b_decay,
                &result,
                &model,
                &state,
                &sequence,
                &target,
                policy,
                core_profile,
            )?);
        }

        let (dead_model, dead_state, mut dead_sequence, dead_target) = gradient_fixture_v1(0.5, 1)?;
        dead_sequence[0].fill(0.0);
        let dead_result = model_loss_gradients_internal_with_math(
            &dead_model,
            AgentId::TrendContinuation,
            &dead_sequence,
            &dead_target,
            true,
            &dead_state,
            core_profile,
        )?;
        let dead_layout = M3MicroLayout::new(&dead_model.config)?;
        let dead_index = dead_layout.blocks[0].b_decay.start;
        let dead_zone = compare_gradient_v1(
            "dead-zone baseline response",
            dead_result.parameter_gradients[dead_index],
            &dead_model,
            &dead_state,
            &dead_sequence,
            &dead_target,
            GradientVariableV1::Parameter(dead_index),
            policy,
            core_profile,
        )?;
        let dead_zone_state_bias_gradient = dead_result.parameter_gradients[maximum_gradient_index(
            &dead_result.parameter_gradients,
            &dead_layout.blocks[0].decay_state_bias,
        )];

        let mut boundary_loss_spans = [0.0; 2];
        for (index, boundary) in [1.0, -1.0].into_iter().enumerate() {
            let (model, state, sequence, target) = gradient_fixture_v1(boundary, 1)?;
            let layout = M3MicroLayout::new(&model.config)?;
            let variable = GradientVariableV1::Parameter(layout.blocks[0].b_decay.start);
            let step = policy.relative_step_scales[2];
            let plus = snapshot_loss_v1(
                &model,
                &state,
                &sequence,
                &target,
                variable,
                step,
                core_profile,
            )?;
            let minus = snapshot_loss_v1(
                &model,
                &state,
                &sequence,
                &target,
                variable,
                -step,
                core_profile,
            )?;
            boundary_loss_spans[index] = (plus - minus).abs();
        }

        Ok(GradientConformanceEvidenceV1 {
            policy,
            initial_parameter_digest: single_model.parameter_digest(),
            single_step,
            multi_step,
            positive_branch: branch_evidence.remove(0),
            negative_branch: branch_evidence.remove(0),
            dead_zone,
            dead_zone_state_bias_gradient,
            boundary_loss_spans,
        })
    }

    fn gradient_conformance_evidence_v1() -> &'static GradientConformanceEvidenceV1 {
        static EVIDENCE: OnceLock<GradientConformanceEvidenceV1> = OnceLock::new();
        EVIDENCE.get_or_init(|| {
            let first =
                run_gradient_conformance_with_math_v1(REDUCED_CORE_MATH_PROFILE_V1).unwrap();
            let second =
                run_gradient_conformance_with_math_v1(REDUCED_CORE_MATH_PROFILE_V1).unwrap();
            assert_eq!(first, second);
            first
        })
    }

    fn reinforced_retention_gradient_evidence_v1() -> &'static GradientConformanceEvidenceV1 {
        static EVIDENCE: OnceLock<GradientConformanceEvidenceV1> = OnceLock::new();
        EVIDENCE.get_or_init(|| {
            let first =
                run_gradient_conformance_with_math_v1(FULL_CANDIDATE_MATH_PROFILE_V2).unwrap();
            let second =
                run_gradient_conformance_with_math_v1(FULL_CANDIDATE_MATH_PROFILE_V2).unwrap();
            assert_eq!(first, second);
            first
        })
    }

    fn assert_gradient_path_v1(evidence: &GradientPathEvidenceV1) {
        let policy = numerical_gradient_conformance_policy_v1();
        assert!(evidence.analytical.is_finite());
        assert!(
            evidence
                .numerical_by_step
                .iter()
                .all(|value| value.is_finite())
        );
        assert!(evidence.sign_matches, "{}", evidence.path);
        assert!(
            evidence.stable_step_count >= policy.minimum_stable_step_pair,
            "{}: {evidence:?}",
            evidence.path
        );
    }

