    #[test]
    fn m3_micro_dead_zone_contract_applies_only_to_reinforced_retention() {
        let reinforced = reinforced_retention_gradient_evidence_v1();
        assert!(reinforced.dead_zone.analytical.abs() <= 1.0e-7);
        assert!(reinforced.dead_zone.numerical.abs() <= 1.0e-5);
        let final_core = gradient_conformance_evidence_v1();
        assert_gradient_path_v1(&final_core.dead_zone);
        if REDUCED_CORE_MATH_PROFILE_V1.reinforced_retention {
            assert!(final_core.dead_zone.analytical.abs() <= 1.0e-7);
            assert!(final_core.dead_zone.numerical.abs() <= 1.0e-5);
            println!("SPRINT104_R4_FINAL_DEAD_ZONE=APPLICABLE_TO_FINAL_CORE");
        } else {
            println!("SPRINT104_R4_FINAL_DEAD_ZONE=NOT_APPLICABLE_TO_FINAL_CORE");
        }
    }

