    fn classification_target_v2(positive: bool) -> M3MicroTarget {
        M3MicroTarget {
            agent_id: AgentId::TrendContinuation,
            direction_distribution: Some(if positive {
                [0.0, 0.0, 1.0]
            } else {
                [1.0, 0.0, 0.0]
            }),
            future_return: Some(if positive { 0.5 } else { -0.5 }),
            continuation: Some(1.0),
            future_variance: None,
            volatility_regime: None,
            risk_abstention: None,
            reversal: None,
            failed_breakout: None,
        }
    }

    fn model_loss_and_gradients_with_profile_v1(
        model: &M3MicroModel,
        profile: CoreAttributionProfileV2,
        sequence: &[Vec<f32>],
        target: &M3MicroTarget,
    ) -> Result<(f32, Vec<f32>), M3MicroError> {
        let initial_state = M3MicroState::zero(&model.config)?;
        let result = model_loss_gradients_internal_with_math(
            model,
            AgentId::TrendContinuation,
            sequence,
            target,
            false,
            &initial_state,
            profile.math(),
        )?;
        Ok((result.loss, result.parameter_gradients))
    }

    fn average_profile_loss_and_gradients_v1(
        model: &M3MicroModel,
        profile: CoreAttributionProfileV2,
        examples: &[EvidenceExampleV2],
    ) -> Result<(f32, Vec<f32>), M3MicroError> {
        if examples.is_empty() {
            return Err(M3MicroError::InvalidShape);
        }
        let mut loss = 0.0;
        let mut gradients = vec![0.0; model.parameter_count()];
        for example in examples {
            let (example_loss, example_gradients) = model_loss_and_gradients_with_profile_v1(
                model,
                profile,
                &example.sequence,
                &example.target,
            )?;
            loss += example_loss / examples.len() as f32;
            for (mean, gradient) in gradients.iter_mut().zip(example_gradients) {
                *mean += gradient / examples.len() as f32;
            }
        }
        Ok((loss, gradients))
    }

    fn profile_raw_output_v1(
        model: &M3MicroModel,
        profile: CoreAttributionProfileV2,
        sequence: &[Vec<f32>],
    ) -> Result<(Vec<f32>, M3MicroState), M3MicroError> {
        let mut state = M3MicroState::zero(&model.config)?;
        let mut counters = M3MicroWorkCountersV1::default();
        let tape = model.forward_internal_with_profile(
            sequence,
            &mut state,
            false,
            &mut counters,
            profile.math(),
        )?;
        Ok((tape.raw_output, state))
    }

    #[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
    enum ForgettingCaseV3 {
        Preserve,
        Noise,
        Invalidation,
    }

    impl ForgettingCaseV3 {
        const ORDERED: [Self; 3] = [Self::Preserve, Self::Noise, Self::Invalidation];
    }

    #[derive(Clone, Debug, PartialEq)]
    struct EvidenceExampleV3 {
        case: ForgettingCaseV3,
        sequence_length: usize,
        position: InvalidationPositionV3,
        seed_index: usize,
        variant_index: usize,
        sequence: Vec<Vec<f32>>,
        target: M3MicroTarget,
        positive: bool,
        initial_positive: bool,
    }

    #[derive(Clone, Debug, PartialEq)]
    struct PairedEventEvidenceV3 {
        case: ForgettingCaseV3,
        sequence_length: usize,
        position: InvalidationPositionV3,
        seed_index: usize,
        variant_index: usize,
        positive: bool,
        base_correct: bool,
        no_forgetting_correct: bool,
        base_nll: f32,
        no_forgetting_nll: f32,
        base_target_margin: f32,
        no_forgetting_target_margin: f32,
    }

    #[derive(Clone, Debug, PartialEq)]
    struct SelectiveForgettingEvidenceV3 {
        policy_identity: String,
        initial_parameter_digests: Vec<String>,
        final_parameter_digests: Vec<String>,
        optimizer_digests: Vec<String>,
        event_order: Vec<String>,
        base_predictions: Vec<f32>,
        no_forgetting_predictions: Vec<f32>,
        events: Vec<PairedEventEvidenceV3>,
    }

    #[derive(Clone, Copy, Debug, PartialEq)]
    struct AggregateMetricsV3 {
        count: usize,
        base_accuracy: f32,
        no_forgetting_accuracy: f32,
        base_mean_nll: f32,
        no_forgetting_mean_nll: f32,
        base_median_nll: f32,
        no_forgetting_median_nll: f32,
        base_mean_target_margin: f32,
        no_forgetting_mean_target_margin: f32,
        base_only_correct: usize,
        no_forgetting_only_correct: usize,
        paired_win_rate: f32,
    }

    fn seed_from_identity_v3(identity: &str) -> u64 {
        let digest = stable_hash_string(&format!("m3-micro-selective-v3-seed:{identity}"));
        u64::from_str_radix(&digest[..16], 16).unwrap()
    }

    fn invalidation_index_v3(length: usize, position: InvalidationPositionV3) -> usize {
        match position {
            InvalidationPositionV3::Early => length / 4,
            InvalidationPositionV3::Middle => length / 2,
            InvalidationPositionV3::Late => length - 5,
        }
    }

    fn forgetting_sequence_v3(
        width: usize,
        case: ForgettingCaseV3,
        length: usize,
        position: InvalidationPositionV3,
        seed_index: usize,
        positive: bool,
        nuisance_variant: usize,
    ) -> (Vec<Vec<f32>>, bool) {
        let event_index = invalidation_index_v3(length, position);
        assert!(width >= 8 && event_index >= 3 && event_index + 2 < length - 1);
        let mut sequence = vec![vec![0.0; width]; length];
        let target_sign = if positive { 1.0 } else { -1.0 };
        let initial_positive = if case == ForgettingCaseV3::Invalidation {
            (nuisance_variant + seed_index + event_index) % 2 == 0
        } else {
            positive
        };
        let initial_sign = if initial_positive { 1.0 } else { -1.0 };
        for (step, input) in sequence.iter_mut().enumerate().take(length - 2) {
            let phase = step as f32 * 0.19
                + nuisance_variant as f32 * 0.071
                + seed_index as f32 * 0.13
                + event_index as f32 * 0.017;
            input[4] = phase.sin() * 0.02;
            input[5] = phase.cos() * 0.02;
            input[7] = ((nuisance_variant + step + seed_index) % 5) as f32 * 0.004 - 0.008;
        }
        let initial_scale = if case == ForgettingCaseV3::Invalidation {
            3.0
        } else {
            1.25
        };
        for input in sequence.iter_mut().take(3) {
            input[0] = initial_sign * initial_scale;
            input[1] = -0.5 * initial_sign * initial_scale;
        }
        match case {
            ForgettingCaseV3::Preserve => {}
            ForgettingCaseV3::Noise => {
                let noise_sign = if (nuisance_variant + seed_index) % 2 == 0 {
                    1.0
                } else {
                    -1.0
                };
                sequence[event_index] = row(width, 5.0 * noise_sign, -2.5 * noise_sign);
                sequence[event_index][6] = 2.0;
            }
            ForgettingCaseV3::Invalidation => {
                for input in sequence.iter_mut().skip(event_index).take(3) {
                    *input = row(width, 2.0 * target_sign, -target_sign);
                }
                sequence[event_index][2] = 4.0;
                sequence[event_index][3] = -4.0;
            }
        }
        (sequence, initial_positive)
    }

    fn forgetting_panel_v3(seed_index: usize, frozen: bool) -> Vec<EvidenceExampleV3> {
        let policy = selective_forgetting_evidence_policy_v3();
        let count = if frozen {
            policy.frozen_examples_per_class
        } else {
            policy.development_examples_per_class
        };
        let nuisance_offset = if frozen { 10_000 } else { 1_000 };
        let mut examples = Vec::with_capacity(
            ForgettingCaseV3::ORDERED.len()
                * policy.sequence_lengths.len()
                * policy.invalidation_positions.len()
                * count
                * 2,
        );
        for case in ForgettingCaseV3::ORDERED {
            for length in policy.sequence_lengths {
                for position in policy.invalidation_positions {
                    for positive in [false, true] {
                        for variant_index in 0..count {
                            let nuisance_variant = nuisance_offset + variant_index;
                            let (sequence, initial_positive) = forgetting_sequence_v3(
                                8,
                                case,
                                length,
                                position,
                                seed_index,
                                positive,
                                nuisance_variant,
                            );
                            examples.push(EvidenceExampleV3 {
                                case,
                                sequence_length: length,
                                position,
                                seed_index,
                                variant_index,
                                sequence,
                                target: classification_target_v2(positive),
                                positive,
                                initial_positive,
                            });
                        }
                    }
                }
            }
        }
        examples
    }

    fn validate_forgetting_panel_v3(examples: &[EvidenceExampleV3], frozen: bool) {
        let policy = selective_forgetting_evidence_policy_v3();
        let per_class = if frozen {
            policy.frozen_examples_per_class
        } else {
            policy.development_examples_per_class
        };
        for case in ForgettingCaseV3::ORDERED {
            for length in policy.sequence_lengths {
                for position in policy.invalidation_positions {
                    for positive in [false, true] {
                        let group = examples
                            .iter()
                            .filter(|example| {
                                example.case == case
                                    && example.sequence_length == length
                                    && example.position == position
                                    && example.positive == positive
                            })
                            .collect::<Vec<_>>();
                        assert_eq!(group.len(), per_class);
                        assert!(group.iter().all(|example| {
                            example.sequence.len() == length
                                && example.sequence[length - 2..]
                                    == vec![vec![0.0; 8], vec![0.0; 8]]
                        }));
                        if case == ForgettingCaseV3::Invalidation {
                            assert!(group.iter().any(|example| example.initial_positive));
                            assert!(group.iter().any(|example| !example.initial_positive));
                        }
                    }
                }
            }
        }
    }

    fn train_selective_model_v3(
        initial_model: &M3MicroModel,
        development: &[EvidenceExampleV3],
        ablation: Option<M3MicroAblationV1>,
    ) -> Result<(M3MicroModel, String), M3MicroError> {
        let policy = selective_forgetting_evidence_policy_v3();
        let mut model = match ablation {
            Some(ablation) => initial_model.with_ablation(ablation)?,
            None => initial_model.clone(),
        };
        let mut optimizer_config = M3MicroOptimizerConfig::default();
        optimizer_config.learning_rate = V2_EVIDENCE_LEARNING_RATE;
        let mut optimizer = M3MicroOptimizerState::new(model.parameter_count(), optimizer_config)?;
        for update in 0..policy.fixed_training_budget {
            let batch = development
                .iter()
                .filter(|example| example.variant_index % policy.fixed_training_budget == update)
                .map(|example| EvidenceExampleV2 {
                    sequence: example.sequence.clone(),
                    target: example.target.clone(),
                    positive: example.positive,
                })
                .collect::<Vec<_>>();
            let (_, gradients) = average_loss_and_gradients_v2(&model, &batch)?;
            optimizer.apply(&mut model, &gradients)?;
            if let Some(ablation) = ablation {
                model = model.with_ablation(ablation)?;
            }
        }
        Ok((model, optimizer.digest()))
    }

    fn direction_metrics_v3(
        raw_output: &[f32],
        positive: bool,
    ) -> Result<(bool, f32, f32), M3MicroError> {
        let prediction = M3MicroPrediction::from_raw(AgentId::TrendContinuation, raw_output)?;
        let probabilities = prediction
            .direction_distribution
            .ok_or(M3MicroError::InvalidShape)?;
        let target_probability = if positive {
            probabilities[2]
        } else {
            probabilities[0]
        };
        let margin = if positive {
            probabilities[2] - probabilities[0]
        } else {
            probabilities[0] - probabilities[2]
        };
        Ok((
            margin > 0.0,
            -target_probability.max(PROBABILITY_EPSILON).ln(),
            margin,
        ))
    }

    fn run_selective_forgetting_v3() -> Result<SelectiveForgettingEvidenceV3, M3MicroError> {
        let policy = selective_forgetting_evidence_policy_v3();
        let policy_identity = stable_hash_string(&format!("m3-micro-selective-v3:{policy:?}"));
        let mut initial_parameter_digests = Vec::new();
        let mut final_parameter_digests = Vec::new();
        let mut optimizer_digests = Vec::new();
        let mut event_order = Vec::new();
        let mut base_predictions = Vec::new();
        let mut no_forgetting_predictions = Vec::new();
        let mut events = Vec::new();
        for (seed_index, seed_identity) in policy.seed_identities.iter().enumerate() {
            let seed = seed_from_identity_v3(seed_identity);
            let initial_model = M3MicroModel::seeded(
                M3MicroConfig::for_agent(AgentId::TrendContinuation, 8),
                seed,
            )?;
            initial_parameter_digests.push(initial_model.parameter_digest());
            let development = forgetting_panel_v3(seed_index, false);
            let frozen = forgetting_panel_v3(seed_index, true);
            validate_forgetting_panel_v3(&development, false);
            validate_forgetting_panel_v3(&frozen, true);
            let (base, base_optimizer) =
                train_selective_model_v3(&initial_model, &development, None)?;
            let (no_forgetting, no_forgetting_optimizer) = train_selective_model_v3(
                &initial_model,
                &development,
                Some(M3MicroAblationV1::NoSelectiveForgetting),
            )?;
            final_parameter_digests
                .extend([base.parameter_digest(), no_forgetting.parameter_digest()]);
            optimizer_digests.extend([base_optimizer, no_forgetting_optimizer]);
            for example in frozen {
                let (base_raw, base_state, _) =
                    base.forward_from_zero_with_work_counters(&example.sequence)?;
                let (no_forgetting_raw, no_forgetting_state, _) =
                    no_forgetting.forward_from_zero_with_work_counters(&example.sequence)?;
                base_state.validate(&base.config)?;
                no_forgetting_state.validate(&no_forgetting.config)?;
                let (base_correct, base_nll, base_target_margin) =
                    direction_metrics_v3(&base_raw, example.positive)?;
                let (no_forgetting_correct, no_forgetting_nll, no_forgetting_target_margin) =
                    direction_metrics_v3(&no_forgetting_raw, example.positive)?;
                event_order.push(format!(
                    "{:?}:{}:{:?}:{}:{}:{}",
                    example.case,
                    example.sequence_length,
                    example.position,
                    example.seed_index,
                    example.positive,
                    example.variant_index
                ));
                base_predictions.push(base_target_margin);
                no_forgetting_predictions.push(no_forgetting_target_margin);
                events.push(PairedEventEvidenceV3 {
                    case: example.case,
                    sequence_length: example.sequence_length,
                    position: example.position,
                    seed_index: example.seed_index,
                    variant_index: example.variant_index,
                    positive: example.positive,
                    base_correct,
                    no_forgetting_correct,
                    base_nll,
                    no_forgetting_nll,
                    base_target_margin,
                    no_forgetting_target_margin,
                });
            }
        }
        Ok(SelectiveForgettingEvidenceV3 {
            policy_identity,
            initial_parameter_digests,
            final_parameter_digests,
            optimizer_digests,
            event_order,
            base_predictions,
            no_forgetting_predictions,
            events,
        })
    }

    fn aggregate_v3<'a>(
        events: impl Iterator<Item = &'a PairedEventEvidenceV3>,
    ) -> AggregateMetricsV3 {
        let events = events.collect::<Vec<_>>();
        assert!(!events.is_empty());
        let count = events.len();
        let base_accuracy =
            events.iter().filter(|event| event.base_correct).count() as f32 / count as f32;
        let no_forgetting_accuracy = events
            .iter()
            .filter(|event| event.no_forgetting_correct)
            .count() as f32
            / count as f32;
        let base_mean_nll = events.iter().map(|event| event.base_nll).sum::<f32>() / count as f32;
        let no_forgetting_mean_nll = events
            .iter()
            .map(|event| event.no_forgetting_nll)
            .sum::<f32>()
            / count as f32;
        let mut base_nll = events
            .iter()
            .map(|event| event.base_nll)
            .collect::<Vec<_>>();
        let mut no_forgetting_nll = events
            .iter()
            .map(|event| event.no_forgetting_nll)
            .collect::<Vec<_>>();
        base_nll.sort_by(f32::total_cmp);
        no_forgetting_nll.sort_by(f32::total_cmp);
        let median = |values: &[f32]| {
            if values.len() % 2 == 0 {
                (values[values.len() / 2 - 1] + values[values.len() / 2]) * 0.5
            } else {
                values[values.len() / 2]
            }
        };
        AggregateMetricsV3 {
            count,
            base_accuracy,
            no_forgetting_accuracy,
            base_mean_nll,
            no_forgetting_mean_nll,
            base_median_nll: median(&base_nll),
            no_forgetting_median_nll: median(&no_forgetting_nll),
            base_mean_target_margin: events
                .iter()
                .map(|event| event.base_target_margin)
                .sum::<f32>()
                / count as f32,
            no_forgetting_mean_target_margin: events
                .iter()
                .map(|event| event.no_forgetting_target_margin)
                .sum::<f32>()
                / count as f32,
            base_only_correct: events
                .iter()
                .filter(|event| event.base_correct && !event.no_forgetting_correct)
                .count(),
            no_forgetting_only_correct: events
                .iter()
                .filter(|event| !event.base_correct && event.no_forgetting_correct)
                .count(),
            paired_win_rate: events
                .iter()
                .filter(|event| event.base_target_margin > event.no_forgetting_target_margin)
                .count() as f32
                / count as f32,
        }
    }

    fn selective_forgetting_evidence_v3() -> &'static SelectiveForgettingEvidenceV3 {
        static EVIDENCE: OnceLock<SelectiveForgettingEvidenceV3> = OnceLock::new();
        EVIDENCE.get_or_init(|| {
            R10_FROZEN_V3_EVALUATIONS.fetch_add(1, Ordering::SeqCst);
            let first = run_selective_forgetting_v3().unwrap();
            let second = run_selective_forgetting_v3().unwrap();
            assert_eq!(first, second);
            first
        })
    }

    #[test]
    #[ignore = "explicit capability evidence"]
    fn m3_micro_selective_forgetting_v3_preserve() {
        let evidence = selective_forgetting_evidence_v3();
        let policy = selective_forgetting_evidence_policy_v3();
        println!(
            "SPRINT104_R3_V3_POLICY_IDENTITY={}",
            evidence.policy_identity
        );
        let aggregate = aggregate_v3(
            evidence
                .events
                .iter()
                .filter(|event| event.case == ForgettingCaseV3::Preserve),
        );
        println!("SPRINT104_R2_V3_PRESERVE_AGGREGATE={aggregate:?}");
        for length in policy.sequence_lengths {
            let metrics = aggregate_v3(evidence.events.iter().filter(|event| {
                event.case == ForgettingCaseV3::Preserve && event.sequence_length == length
            }));
            println!("SPRINT104_R2_V3_PRESERVE_{length}={metrics:?}");
            assert!(metrics.base_accuracy >= policy.minimum_preserve_accuracy);
        }
        for seed_index in 0..policy.seed_identities.len() {
            let metrics = aggregate_v3(evidence.events.iter().filter(|event| {
                event.case == ForgettingCaseV3::Preserve && event.seed_index == seed_index
            }));
            println!(
                "SPRINT104_R2_V3_PRESERVE_SEED_{}={metrics:?}",
                policy.seed_identities[seed_index]
            );
        }
    }

    #[test]
    #[ignore = "explicit capability evidence"]
    fn m3_micro_selective_forgetting_v3_noise() {
        let evidence = selective_forgetting_evidence_v3();
        let policy = selective_forgetting_evidence_policy_v3();
        let aggregate = aggregate_v3(
            evidence
                .events
                .iter()
                .filter(|event| event.case == ForgettingCaseV3::Noise),
        );
        println!("SPRINT104_R2_V3_NOISE_AGGREGATE={aggregate:?}");
        for length in policy.sequence_lengths {
            let metrics = aggregate_v3(evidence.events.iter().filter(|event| {
                event.case == ForgettingCaseV3::Noise && event.sequence_length == length
            }));
            println!("SPRINT104_R2_V3_NOISE_{length}={metrics:?}");
        }
        for seed_index in 0..policy.seed_identities.len() {
            let metrics = aggregate_v3(evidence.events.iter().filter(|event| {
                event.case == ForgettingCaseV3::Noise && event.seed_index == seed_index
            }));
            println!(
                "SPRINT104_R2_V3_NOISE_SEED_{}={metrics:?}",
                policy.seed_identities[seed_index]
            );
        }
        assert!(policy.sequence_lengths.into_iter().all(|length| {
            aggregate_v3(evidence.events.iter().filter(|event| {
                event.case == ForgettingCaseV3::Noise && event.sequence_length == length
            }))
            .base_accuracy
                >= policy.minimum_noise_accuracy
        }));
    }

    #[test]
    #[ignore = "explicit capability evidence"]
    fn m3_micro_selective_forgetting_v3_invalidation() {
        let evidence = selective_forgetting_evidence_v3();
        let policy = selective_forgetting_evidence_policy_v3();
        let aggregate = aggregate_v3(
            evidence
                .events
                .iter()
                .filter(|event| event.case == ForgettingCaseV3::Invalidation),
        );
        println!("SPRINT104_R2_V3_INVALIDATION={aggregate:?}");
        for length in policy.sequence_lengths {
            let metrics = aggregate_v3(evidence.events.iter().filter(|event| {
                event.case == ForgettingCaseV3::Invalidation && event.sequence_length == length
            }));
            println!("SPRINT104_R2_V3_INVALIDATION_LENGTH_{length}={metrics:?}");
        }
        for position in policy.invalidation_positions {
            let metrics = aggregate_v3(evidence.events.iter().filter(|event| {
                event.case == ForgettingCaseV3::Invalidation && event.position == position
            }));
            println!("SPRINT104_R2_V3_INVALIDATION_POSITION_{position:?}={metrics:?}");
        }
        for seed_index in 0..policy.seed_identities.len() {
            let metrics = aggregate_v3(evidence.events.iter().filter(|event| {
                event.case == ForgettingCaseV3::Invalidation && event.seed_index == seed_index
            }));
            println!(
                "SPRINT104_R2_V3_INVALIDATION_SEED_{}={metrics:?}",
                policy.seed_identities[seed_index]
            );
        }
        assert!(aggregate.base_accuracy >= policy.minimum_invalidation_accuracy);
        assert!((0..policy.seed_identities.len()).all(|seed_index| {
            aggregate_v3(evidence.events.iter().filter(|event| {
                event.case == ForgettingCaseV3::Invalidation && event.seed_index == seed_index
            }))
            .base_accuracy
                >= policy.minimum_per_seed_invalidation_accuracy
        }));
    }

    #[test]
    #[ignore = "explicit capability evidence"]
    fn m3_micro_selective_forgetting_v3_beats_no_forgetting() {
        let evidence = selective_forgetting_evidence_v3();
        let policy = selective_forgetting_evidence_policy_v3();
        let metrics = aggregate_v3(
            evidence
                .events
                .iter()
                .filter(|event| event.case == ForgettingCaseV3::Invalidation),
        );
        assert!(
            metrics.base_accuracy - metrics.no_forgetting_accuracy >= policy.minimum_accuracy_gap
        );
        assert!(
            metrics.base_mean_nll
                <= metrics.no_forgetting_mean_nll - policy.minimum_mean_nll_improvement
        );
        assert!(
            metrics.base_mean_target_margin
                >= metrics.no_forgetting_mean_target_margin
                    + policy.minimum_target_margin_improvement
        );
        assert!(metrics.paired_win_rate >= policy.minimum_paired_win_rate);
    }

    #[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
    enum AttributionTaskV2 {
        Recall,
        Preserve,
        Noise,
        Invalidation,
    }

    #[derive(Clone, Debug, PartialEq, Eq)]
    struct AttributionEventKeyV2 {
        task: AttributionTaskV2,
        sequence_length: usize,
        position: Option<InvalidationPositionV3>,
        seed_index: usize,
        variant_index: usize,
        positive: bool,
    }

