    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    enum AttributionGroupV2 {
        Retention,
        Readout,
        Activation,
        Initialization,
    }

    impl AttributionGroupV2 {
        const ORDERED: [Self; 4] = [
            Self::Retention,
            Self::Readout,
            Self::Activation,
            Self::Initialization,
        ];

        fn comparator(self) -> CoreAttributionProfileV2 {
            match self {
                Self::Retention => CoreAttributionProfileV2::FullWithoutRetention,
                Self::Readout => CoreAttributionProfileV2::FullWithoutReadout,
                Self::Activation => CoreAttributionProfileV2::FullWithoutActivation,
                Self::Initialization => CoreAttributionProfileV2::FullWithoutInitialization,
            }
        }

        fn report_name(self) -> &'static str {
            match self {
                Self::Retention => "G1",
                Self::Readout => "G2",
                Self::Activation => "G3",
                Self::Initialization => "G4",
            }
        }
    }

    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    enum AttributionDecisionV2 {
        RetainRequired,
        RetainSupported,
        RevertUnsupported,
        RevertHarmful,
        BlockedIndeterminate,
    }

    impl AttributionDecisionV2 {
        fn as_str(self) -> &'static str {
            match self {
                Self::RetainRequired => "RETAIN_REQUIRED",
                Self::RetainSupported => "RETAIN_SUPPORTED",
                Self::RevertUnsupported => "REVERT_UNSUPPORTED",
                Self::RevertHarmful => "REVERT_HARMFUL",
                Self::BlockedIndeterminate => "BLOCKED_INDETERMINATE",
            }
        }

        fn retained(self) -> Option<bool> {
            match self {
                Self::RetainRequired | Self::RetainSupported => Some(true),
                Self::RevertUnsupported | Self::RevertHarmful => Some(false),
                Self::BlockedIndeterminate => None,
            }
        }
    }

    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    enum AttributionMetricV2 {
        Recall8,
        Recall16,
        Recall32,
        Preserve,
        Preserve16,
        Preserve32,
        Noise16,
        Noise32,
        Invalidation,
        InvalidationEarly,
        InvalidationMiddle,
        InvalidationLate,
        InvalidationSeed0,
        InvalidationSeed1,
        InvalidationSeed2,
    }

    impl AttributionMetricV2 {
        const ORDERED: [Self; 15] = [
            Self::Recall8,
            Self::Recall16,
            Self::Recall32,
            Self::Preserve,
            Self::Preserve16,
            Self::Preserve32,
            Self::Noise16,
            Self::Noise32,
            Self::Invalidation,
            Self::InvalidationEarly,
            Self::InvalidationMiddle,
            Self::InvalidationLate,
            Self::InvalidationSeed0,
            Self::InvalidationSeed1,
            Self::InvalidationSeed2,
        ];

        fn label(self) -> &'static str {
            match self {
                Self::Recall8 => "Recall8",
                Self::Recall16 => "Recall16",
                Self::Recall32 => "Recall32",
                Self::Preserve => "Preserve",
                Self::Preserve16 => "Preserve16",
                Self::Preserve32 => "Preserve32",
                Self::Noise16 => "Noise16",
                Self::Noise32 => "Noise32",
                Self::Invalidation => "Invalidation",
                Self::InvalidationEarly => "InvalidationEarly",
                Self::InvalidationMiddle => "InvalidationMiddle",
                Self::InvalidationLate => "InvalidationLate",
                Self::InvalidationSeed0 => "InvalidationSeed0",
                Self::InvalidationSeed1 => "InvalidationSeed1",
                Self::InvalidationSeed2 => "InvalidationSeed2",
            }
        }

        fn matches(self, key: &AttributionEventKeyV2) -> bool {
            match self {
                Self::Recall8 => key.task == AttributionTaskV2::Recall && key.sequence_length == 8,
                Self::Recall16 => {
                    key.task == AttributionTaskV2::Recall && key.sequence_length == 16
                }
                Self::Recall32 => {
                    key.task == AttributionTaskV2::Recall && key.sequence_length == 32
                }
                Self::Preserve => key.task == AttributionTaskV2::Preserve,
                Self::Preserve16 => {
                    key.task == AttributionTaskV2::Preserve && key.sequence_length == 16
                }
                Self::Preserve32 => {
                    key.task == AttributionTaskV2::Preserve && key.sequence_length == 32
                }
                Self::Noise16 => key.task == AttributionTaskV2::Noise && key.sequence_length == 16,
                Self::Noise32 => key.task == AttributionTaskV2::Noise && key.sequence_length == 32,
                Self::Invalidation => key.task == AttributionTaskV2::Invalidation,
                Self::InvalidationEarly => {
                    key.task == AttributionTaskV2::Invalidation
                        && key.position == Some(InvalidationPositionV3::Early)
                }
                Self::InvalidationMiddle => {
                    key.task == AttributionTaskV2::Invalidation
                        && key.position == Some(InvalidationPositionV3::Middle)
                }
                Self::InvalidationLate => {
                    key.task == AttributionTaskV2::Invalidation
                        && key.position == Some(InvalidationPositionV3::Late)
                }
                Self::InvalidationSeed0 => {
                    key.task == AttributionTaskV2::Invalidation && key.seed_index == 0
                }
                Self::InvalidationSeed1 => {
                    key.task == AttributionTaskV2::Invalidation && key.seed_index == 1
                }
                Self::InvalidationSeed2 => {
                    key.task == AttributionTaskV2::Invalidation && key.seed_index == 2
                }
            }
        }

        fn hard_gate(self) -> Option<f32> {
            let recall = delayed_recall_evidence_policy_v2();
            let forgetting = selective_forgetting_evidence_policy_v3();
            match self {
                Self::Recall8 | Self::Recall16 | Self::Recall32 => Some(recall.minimum_accuracy),
                Self::Preserve16 | Self::Preserve32 => Some(forgetting.minimum_preserve_accuracy),
                Self::Noise16 | Self::Noise32 => Some(forgetting.minimum_noise_accuracy),
                Self::Invalidation => Some(forgetting.minimum_invalidation_accuracy),
                Self::InvalidationSeed0 | Self::InvalidationSeed1 | Self::InvalidationSeed2 => {
                    Some(forgetting.minimum_per_seed_invalidation_accuracy)
                }
                Self::Preserve
                | Self::InvalidationEarly
                | Self::InvalidationMiddle
                | Self::InvalidationLate => None,
            }
        }
    }

