    fn assert_g4_attribution_comparator_is_valid_v1(evidence: &ReinforcementAttributionEvidenceV2) {
        let comparison = evidence
            .comparisons
            .iter()
            .find(|comparison| comparison.group == AttributionGroupV2::Initialization)
            .unwrap();
        assert_eq!(
            comparison.comparator,
            CoreAttributionProfileV2::FullWithoutInitialization
        );
        assert_eq!(
            comparison.comparator.math(),
            CoreAttributionProfileV2::FullCandidate.math()
        );
        let policy = selective_forgetting_evidence_policy_v3();
        for (seed_index, seed_identity) in policy.seed_identities.iter().enumerate() {
            let seed = seed_from_identity_v3(seed_identity);
            let config = M3MicroConfig::for_agent(AgentId::TrendContinuation, 8);
            let oracle = pre_reinforcement_initialization_oracle_v1(&config, seed)
                .parameters
                .into_iter()
                .map(|parameter| parameter.bits)
                .collect::<Vec<_>>();
            let record = evidence
                .records
                .iter()
                .find(|record| {
                    record.profile == CoreAttributionProfileV2::FullWithoutInitialization
                        && record.seed_index == seed_index
                })
                .unwrap();
            assert_eq!(record.initial_parameter_snapshot, oracle);
            assert!(
                record
                    .initial_parameter_digests
                    .iter()
                    .all(|digest| digest == &record.initial_parameter_digests[0])
            );
        }
    }

