    #[derive(Clone, Debug, PartialEq, Eq)]
    enum GitCheckoutProvenanceV1 {
        Branch { name: String, head: String },
        Detached { head: String },
    }

    const GIT_CHECKOUT_PROVENANCE_POLICY_IDENTITY_V1: &str =
        "m3-r10-git-checkout-provenance-v1:optional-branch-and-head";

    impl GitCheckoutProvenanceV1 {
        fn from_repository_values(branch: &str, head: &str) -> Result<Self, String> {
            let branch = branch.trim();
            let head = head.trim();
            if head.is_empty() {
                return Err("empty repository HEAD".to_string());
            }
            if branch.is_empty() {
                Ok(Self::Detached {
                    head: head.to_string(),
                })
            } else {
                Ok(Self::Branch {
                    name: branch.to_string(),
                    head: head.to_string(),
                })
            }
        }

        fn branch_name(&self) -> Option<&str> {
            match self {
                Self::Branch { name, .. } => Some(name),
                Self::Detached { .. } => None,
            }
        }

        fn head(&self) -> &str {
            match self {
                Self::Branch { head, .. } | Self::Detached { head } => head,
            }
        }

        fn canonical_provenance_preimage_v1(&self) -> Result<String, String> {
            match self {
                Self::Branch { name, head }
                    if name.is_empty()
                        || name.trim() != name
                        || head.is_empty()
                        || head.trim() != head =>
                {
                    Err("invalid attached checkout provenance".to_string())
                }
                Self::Detached { head } if head.is_empty() || head.trim() != head => {
                    Err("invalid detached checkout provenance".to_string())
                }
                _ => serde_json::to_string(&(
                    GIT_CHECKOUT_PROVENANCE_POLICY_IDENTITY_V1,
                    self.branch_name(),
                    self.head(),
                ))
                .map_err(|error| error.to_string()),
            }
        }

        fn canonical_provenance_identity_v1(&self) -> Result<String, String> {
            Ok(stable_hash_string(
                &self.canonical_provenance_preimage_v1()?,
            ))
        }
    }

    fn validate_detached_branch_collision_contract_v1(
        attached: &GitCheckoutProvenanceV1,
        detached: &GitCheckoutProvenanceV1,
    ) -> Result<String, String> {
        let (
            GitCheckoutProvenanceV1::Branch {
                head: attached_head,
                ..
            },
            GitCheckoutProvenanceV1::Detached {
                head: detached_head,
            },
        ) = (attached, detached)
        else {
            return Err("attached and detached provenance evidence is required".to_string());
        };
        if attached_head != detached_head {
            return Err("checkout provenance evidence must use the same HEAD".to_string());
        }
        let attached_preimage = attached.canonical_provenance_preimage_v1()?;
        let detached_preimage = detached.canonical_provenance_preimage_v1()?;
        let attached_identity = attached.canonical_provenance_identity_v1()?;
        let detached_identity = detached.canonical_provenance_identity_v1()?;
        if attached_preimage == detached_preimage || attached_identity == detached_identity {
            return Err(
                "attached and detached canonical provenance identities collide".to_string(),
            );
        }
        serde_json::to_string(&(
            GIT_CHECKOUT_PROVENANCE_POLICY_IDENTITY_V1,
            attached_identity,
            detached_identity,
        ))
        .map(|evidence| stable_hash_string(&evidence))
        .map_err(|error| error.to_string())
    }

    fn current_detached_branch_collision_evidence_v1() -> Result<String, String> {
        let checkout = current_git_checkout_provenance_v1()?;
        let (attached, detached) = match &checkout {
            GitCheckoutProvenanceV1::Branch { head, .. } => (
                checkout.clone(),
                GitCheckoutProvenanceV1::Detached { head: head.clone() },
            ),
            GitCheckoutProvenanceV1::Detached { head } => (
                GitCheckoutProvenanceV1::Branch {
                    name: head.clone(),
                    head: head.clone(),
                },
                checkout.clone(),
            ),
        };
        validate_detached_branch_collision_contract_v1(&attached, &detached)
    }

