    fn lifecycle_after_attribution_v1(
        attribution: GateExecutionStatusV1,
    ) -> M3MicroEvidenceLifecycleV2 {
        M3MicroEvidenceLifecycleV2 {
            initialization_oracle: GateExecutionStatusV1::Passed,
            attribution,
            final_gradient: GateExecutionStatusV1::NotRun,
            metric_semantics: GateExecutionStatusV1::NotRun,
            structural_loss: GateExecutionStatusV1::NotRun,
            event_alignment: GateExecutionStatusV1::NotRun,
            comparator_purity: GateExecutionStatusV1::NotRun,
            suffix_integrity: GateExecutionStatusV1::NotRun,
            protected_interaction: GateExecutionStatusV1::NotRun,
            frozen_v3: GateExecutionStatusV1::NotRun,
            report_integrity: GateExecutionStatusV1::NotRun,
        }
    }

    fn lifecycle_after_gradient_v1(gradient: GateExecutionStatusV1) -> M3MicroEvidenceLifecycleV2 {
        let mut lifecycle = lifecycle_after_attribution_v1(GateExecutionStatusV1::Passed);
        lifecycle.final_gradient = gradient;
        lifecycle
    }

    fn lifecycle_after_interaction_v1(
        interaction: GateExecutionStatusV1,
    ) -> M3MicroEvidenceLifecycleV2 {
        let mut lifecycle = lifecycle_after_gradient_v1(GateExecutionStatusV1::Passed);
        lifecycle.metric_semantics = GateExecutionStatusV1::Passed;
        lifecycle.structural_loss = GateExecutionStatusV1::Passed;
        lifecycle.event_alignment = GateExecutionStatusV1::Passed;
        lifecycle.comparator_purity = GateExecutionStatusV1::Passed;
        lifecycle.suffix_integrity = GateExecutionStatusV1::Passed;
        lifecycle.protected_interaction = interaction;
        lifecycle
    }

    fn root_cause_from_contract_evidence_v2(
        evidence: RootCauseContractEvidenceV2,
    ) -> Length32RootCauseV2 {
        use GateExecutionStatusV1::{Failed, NotRun};
        if evidence.metric_semantics == Failed {
            Length32RootCauseV2::MetricDefinitionMismatch
        } else if evidence.structural_loss == Failed {
            Length32RootCauseV2::StructuralLossImplementationDefect
        } else if evidence.metric_aggregation == Failed {
            Length32RootCauseV2::MetricAggregationDefect
        } else if evidence.accuracy_nll_source == Failed {
            Length32RootCauseV2::AccuracyNllSourceMismatch
        } else if evidence.event_alignment == Failed {
            Length32RootCauseV2::EventAlignmentDefect
        } else if evidence.comparator_purity == Failed {
            Length32RootCauseV2::NoStateComparatorContamination
        } else if evidence.suffix_integrity == Failed {
            Length32RootCauseV2::FinalSuffixLeakage
        } else if evidence.protected_interaction == Failed {
            Length32RootCauseV2::GenuineLength32ConfidenceDeficit
        } else if evidence.protected_interaction == NotRun {
            Length32RootCauseV2::Indeterminate
        } else {
            Length32RootCauseV2::NoDefect
        }
    }

    fn derive_r7_final_status_v1(
        lifecycle: M3MicroEvidenceLifecycleV2,
        root_cause: Length32RootCauseV2,
        report_binding: GateExecutionStatusV1,
    ) -> R7FinalStatusV1 {
        use GateExecutionStatusV1::{Failed, NotRun};
        if lifecycle.attribution == Failed {
            return R7FinalStatusV1::BlockedByReinforcementAttribution;
        }
        if lifecycle.final_gradient == Failed {
            return R7FinalStatusV1::BlockedByGradientConformance;
        }
        if lifecycle.metric_semantics == Failed {
            return R7FinalStatusV1::BlockedByMetricSemantics;
        }
        if lifecycle.event_alignment == Failed {
            return R7FinalStatusV1::BlockedByEventAlignment;
        }
        if lifecycle.comparator_purity == Failed {
            return R7FinalStatusV1::BlockedByNoStateComparator;
        }
        if lifecycle.suffix_integrity == Failed {
            return R7FinalStatusV1::BlockedByFinalSuffixLeakage;
        }
        if lifecycle.protected_interaction == Failed {
            return match root_cause {
                Length32RootCauseV2::GenuineLength32ConfidenceDeficit => {
                    R7FinalStatusV1::BlockedByLength32ConfidenceCapability
                }
                Length32RootCauseV2::EventAlignmentDefect => {
                    R7FinalStatusV1::BlockedByEventAlignment
                }
                Length32RootCauseV2::NoStateComparatorContamination => {
                    R7FinalStatusV1::BlockedByNoStateComparator
                }
                Length32RootCauseV2::FinalSuffixLeakage => {
                    R7FinalStatusV1::BlockedByFinalSuffixLeakage
                }
                Length32RootCauseV2::MetricDefinitionMismatch
                | Length32RootCauseV2::MetricAggregationDefect
                | Length32RootCauseV2::AccuracyNllSourceMismatch
                | Length32RootCauseV2::StructuralLossImplementationDefect => {
                    R7FinalStatusV1::BlockedByMetricSemantics
                }
                Length32RootCauseV2::NoDefect | Length32RootCauseV2::Indeterminate => {
                    R7FinalStatusV1::BlockedByIncompleteEvidence
                }
            };
        }
        if lifecycle.frozen_v3 == Failed {
            return R7FinalStatusV1::BlockedBySelectiveForgettingV3;
        }
        if report_binding == Failed {
            return R7FinalStatusV1::BlockedByReportIntegrity;
        }
        if [
            lifecycle.attribution,
            lifecycle.final_gradient,
            lifecycle.metric_semantics,
            lifecycle.event_alignment,
            lifecycle.comparator_purity,
            lifecycle.suffix_integrity,
            lifecycle.protected_interaction,
            lifecycle.frozen_v3,
            report_binding,
        ]
        .contains(&NotRun)
        {
            return R7FinalStatusV1::BlockedByIncompleteEvidence;
        }
        R7FinalStatusV1::ReadyForReview
    }

    #[test]
    fn m3_micro_gate_lifecycle_has_reachable_states_only() {
        let attribution_failed = lifecycle_after_attribution_v1(GateExecutionStatusV1::Failed);
        assert_eq!(
            attribution_failed.final_gradient,
            GateExecutionStatusV1::NotRun
        );
        assert_eq!(
            attribution_failed.protected_interaction,
            GateExecutionStatusV1::NotRun
        );
        assert_eq!(attribution_failed.frozen_v3, GateExecutionStatusV1::NotRun);

        let gradient_failed = lifecycle_after_gradient_v1(GateExecutionStatusV1::Failed);
        assert_eq!(
            gradient_failed.protected_interaction,
            GateExecutionStatusV1::NotRun
        );
        assert_eq!(gradient_failed.frozen_v3, GateExecutionStatusV1::NotRun);

        let interaction_failed = lifecycle_after_interaction_v1(GateExecutionStatusV1::Failed);
        assert_eq!(interaction_failed.frozen_v3, GateExecutionStatusV1::NotRun);
    }

    fn gradient_path_passed_v1(
        path: &GradientPathEvidenceV1,
        policy: NumericalGradientConformancePolicyV1,
    ) -> bool {
        path.analytical.is_finite()
            && path.numerical_by_step.iter().all(|value| value.is_finite())
            && path.sign_matches
            && path.stable_step_count >= policy.minimum_stable_step_pair
    }

    fn gradient_policy_identity_v2() -> String {
        stable_hash_string(&format!(
            "m3-r6-gradient-receipt:{:?}:{:?}:{:?}",
            numerical_gradient_conformance_policy_v1(),
            REDUCED_CORE_MATH_PROFILE_V1,
            FULL_CANDIDATE_MATH_PROFILE_V2,
        ))
    }

    fn execute_gradient_receipt_v2() -> GradientExecutionReceiptV2 {
        let final_core =
            run_gradient_conformance_with_math_v1(REDUCED_CORE_MATH_PROFILE_V1).unwrap();
        let reinforced =
            run_gradient_conformance_with_math_v1(FULL_CANDIDATE_MATH_PROFILE_V2).unwrap();
        let mut failed_cases = final_core
            .single_step
            .iter()
            .chain(&final_core.multi_step)
            .chain([&final_core.positive_branch, &final_core.negative_branch])
            .filter(|path| !gradient_path_passed_v1(path, final_core.policy))
            .count();
        failed_cases += [
            &reinforced.positive_branch,
            &reinforced.negative_branch,
            &reinforced.dead_zone,
        ]
        .into_iter()
        .filter(|path| !gradient_path_passed_v1(path, reinforced.policy))
        .count();
        failed_cases += usize::from(
            reinforced.dead_zone.analytical.abs() > 1.0e-7
                || reinforced.dead_zone.numerical.abs() > 1.0e-5,
        );
        failed_cases += reinforced
            .boundary_loss_spans
            .iter()
            .filter(|span| {
                !span.is_finite() || **span > reinforced.policy.boundary_output_tolerance
            })
            .count();
        GradientExecutionReceiptV2 {
            status: status_from_bool_v1(failed_cases == 0),
            executed_in_current_lifecycle: true,
            single_step_cases: final_core.single_step.len(),
            multi_step_cases: final_core.multi_step.len(),
            branch_cases: 2 + 3 + reinforced.boundary_loss_spans.len(),
            failed_cases,
            policy_identity: gradient_policy_identity_v2(),
        }
    }

    fn protected_interaction_passed_v1() -> bool {
        let policy = delayed_recall_evidence_policy_v2();
        let delayed_passed = delayed_recall_evidence_v2().iter().all(|evidence| {
            evidence.final_development_loss < evidence.initial_development_loss
                && evidence.final_frozen_composite_role_loss
                    < evidence.initial_frozen_composite_role_loss
                && evidence.frozen_accuracy >= policy.minimum_accuracy
                && evidence.paired_prediction_separation
                    >= policy.minimum_carried_prediction_separation
                && evidence.early_signal_gradient_l1.is_finite()
                && evidence.early_signal_gradient_l1 > 0.0
                && evidence.carried_prediction_separation
                    >= policy.minimum_carried_prediction_separation
                && evidence.reset_prediction_separation
                    <= policy.maximum_reset_prediction_separation
                && evidence.carried_state_l1_separation > 0.0
                && evidence.carried_state_digests[0] != evidence.carried_state_digests[1]
                && evidence.reset_state_digests[0] == evidence.reset_state_digests[1]
                && evidence.base_mean_direction_nll < evidence.no_state_mean_direction_nll
                && evidence.frozen_accuracy > evidence.no_state_accuracy
                && evidence.base_vs_no_state_direction_nll_gap > 0.0
                && evidence.base_vs_no_state_accuracy_gap
                    >= policy.minimum_base_vs_no_state_accuracy_gap
        });
        let roster = test_roster();
        let agent = roster.agent(AgentId::TrendContinuation);
        let width = agent.model.config.input_dim;
        let sequence = (0..11)
            .map(|index| row(width, index as f32 * 0.07 - 0.3, (index as f32 * 0.2).sin()))
            .collect::<Vec<_>>();
        let mut full_state = M3MicroState::zero(&agent.model.config).unwrap();
        let full_output = agent.model.forward(&sequence, &mut full_state).unwrap();
        let mut streaming_state = M3MicroState::zero(&agent.model.config).unwrap();
        let mut streaming_output = Vec::new();
        for input in &sequence {
            streaming_output = agent
                .model
                .stream_step(input, &mut streaming_state)
                .unwrap()
                .0;
        }
        let mut chunked_state = M3MicroState::zero(&agent.model.config).unwrap();
        let mut chunked_output = Vec::new();
        for chunk in sequence.chunks(3) {
            chunked_output = agent.model.forward(chunk, &mut chunked_state).unwrap();
        }
        let streaming_passed = full_output == streaming_output
            && full_output == chunked_output
            && full_state == streaming_state
            && full_state == chunked_state;
        let (_, state, counters) = agent
            .model
            .forward_from_zero_with_work_counters(&sequence)
            .unwrap();
        let counters_passed = counters
            .precise_semantics_v2()
            .zero_state_initialization_count
            == 1
            && counters.sequence_step_count == sequence.len()
            && state.step_index == sequence.len();
        let storage_identities = AgentId::ORDERED
            .into_iter()
            .map(|agent_id| roster.agent(agent_id).model.parameters.storage_identity())
            .collect::<BTreeSet<_>>();
        let isolation_passed = storage_identities.len() == AgentId::ORDERED.len();
        let role_boundaries_passed = AgentId::ORDERED.into_iter().all(|agent_id| {
            let descriptor = role_policy_v1(agent_id).descriptor();
            let roster_agent = roster.agent(agent_id);
            roster_agent.spec.agent_id == descriptor.agent_id
                && roster_agent.spec.target_policy == descriptor.target_policy
                && roster_agent.spec.loss_policy == descriptor.loss_policy
                && roster_agent.model.config.output_dim == descriptor.output_dim
        });
        let finite_stability_passed = [0.0, 0.25, 16.0, -16.0].into_iter().all(|value| {
            let sequence = vec![vec![value; width]; 32];
            let first = agent.model.forward_from_zero_with_work_counters(&sequence);
            let second = agent.model.forward_from_zero_with_work_counters(&sequence);
            matches!((first, second), (Ok(left), Ok(right)) if left == right
                && left.0.iter().all(|output| output.is_finite())
                && left.1.validate(&agent.model.config).is_ok())
        });
        delayed_passed
            && streaming_passed
            && counters_passed
            && isolation_passed
            && role_boundaries_passed
            && finite_stability_passed
    }

    fn frozen_v3_passed_v1() -> bool {
        let evidence = selective_forgetting_evidence_v3();
        let policy = selective_forgetting_evidence_policy_v3();
        let preserve = policy.sequence_lengths.into_iter().all(|length| {
            aggregate_v3(evidence.events.iter().filter(|event| {
                event.case == ForgettingCaseV3::Preserve && event.sequence_length == length
            }))
            .base_accuracy
                >= policy.minimum_preserve_accuracy
        });
        let noise = policy.sequence_lengths.into_iter().all(|length| {
            aggregate_v3(evidence.events.iter().filter(|event| {
                event.case == ForgettingCaseV3::Noise && event.sequence_length == length
            }))
            .base_accuracy
                >= policy.minimum_noise_accuracy
        });
        let invalidation = aggregate_v3(
            evidence
                .events
                .iter()
                .filter(|event| event.case == ForgettingCaseV3::Invalidation),
        );
        preserve
            && noise
            && invalidation.base_accuracy >= policy.minimum_invalidation_accuracy
            && (0..policy.seed_identities.len()).all(|seed_index| {
                aggregate_v3(evidence.events.iter().filter(|event| {
                    event.case == ForgettingCaseV3::Invalidation && event.seed_index == seed_index
                }))
                .base_accuracy
                    >= policy.minimum_per_seed_invalidation_accuracy
            })
            && invalidation.base_accuracy - invalidation.no_forgetting_accuracy
                >= policy.minimum_accuracy_gap
            && invalidation.base_mean_nll
                <= invalidation.no_forgetting_mean_nll - policy.minimum_mean_nll_improvement
            && invalidation.base_mean_target_margin
                >= invalidation.no_forgetting_mean_target_margin
                    + policy.minimum_target_margin_improvement
            && invalidation.paired_win_rate >= policy.minimum_paired_win_rate
    }

    fn metric_semantics_passed_v1(evidence: &[DelayedRecallEvidenceV2]) -> bool {
        evidence.iter().all(|evidence| {
            evidence.composite_loss_semantics == ClassificationLossSemanticsV1::CompositeRoleLoss
                && evidence.direction_nll_semantics
                    == ClassificationLossSemanticsV1::MeanCategoricalNegativeLogLikelihood
                && evidence
                    .base_event_audits
                    .iter()
                    .chain(&evidence.no_state_event_audits)
                    .all(|event| {
                        event.probability_of_true_class.is_finite()
                            && event.probability_of_true_class > 0.0
                            && event.probability_of_true_class <= 1.0
                            && event.event_nll.is_finite()
                            && event.event_nll >= 0.0
                    })
        })
    }

    fn accuracy_nll_source_passed_v1(evidence: &[DelayedRecallEvidenceV2]) -> bool {
        evidence.iter().all(|evidence| {
            [&evidence.base_event_audits, &evidence.no_state_event_audits]
                .into_iter()
                .all(|events| {
                    events.iter().all(|event| {
                        let Ok(prediction) = M3MicroPrediction::from_raw(
                            AgentId::TrendContinuation,
                            &event.raw_output,
                        ) else {
                            return false;
                        };
                        let Some(distribution) = prediction.direction_distribution else {
                            return false;
                        };
                        let score = distribution[2] - distribution[0];
                        let true_probability = if event.target == 1.0 {
                            distribution[2]
                        } else {
                            distribution[0]
                        };
                        score.to_bits() == event.decision_value.to_bits()
                            && true_probability.to_bits()
                                == event.probability_of_true_class.to_bits()
                            && (-true_probability.clamp(PROBABILITY_EPSILON, 1.0).ln()).to_bits()
                                == event.event_nll.to_bits()
                            && ((score > 0.0) == (event.target == 1.0)) == event.correct
                    })
                })
        })
    }

    fn metric_aggregation_passed_v1(evidence: &[DelayedRecallEvidenceV2]) -> bool {
        evidence.iter().all(|evidence| {
            let base = reconstruct_event_metrics_v1(&evidence.base_event_audits);
            let no_state = reconstruct_event_metrics_v1(&evidence.no_state_event_audits);
            base.0.to_bits() == evidence.frozen_accuracy.to_bits()
                && base.1.to_bits() == evidence.base_mean_direction_nll.to_bits()
                && base.2.to_bits() == evidence.base_mean_true_class_probability.to_bits()
                && base.3.to_bits() == evidence.base_mean_target_aligned_margin.to_bits()
                && no_state.0.to_bits() == evidence.no_state_accuracy.to_bits()
                && no_state.1.to_bits() == evidence.no_state_mean_direction_nll.to_bits()
                && no_state.2.to_bits() == evidence.no_state_mean_true_class_probability.to_bits()
                && no_state.3.to_bits() == evidence.no_state_mean_target_aligned_margin.to_bits()
        })
    }

    fn structural_loss_policy_identity_v1() -> String {
        stable_hash_string(&format!(
            "m3-r9-structural-loss-v1:full-delayed-frozen-panel:stable-logsumexp:{R9_EVENT_NLL_TOLERANCE}:{R9_AGGREGATE_NLL_TOLERANCE}:{R9_PROBABILITY_NORMALIZATION_TOLERANCE}"
        ))
    }

    fn within_r9_tolerance(actual: f32, expected: f32, tolerance: f32) -> bool {
        actual.is_finite()
            && expected.is_finite()
            && (actual - expected).abs() <= tolerance * actual.abs().max(expected.abs()).max(1.0)
    }

    fn independently_recomputed_event_nll_v1(
        event: &DelayedMemoryEventAuditV1,
    ) -> Result<(f32, bool, bool), String> {
        if event.raw_output.len() != 5 {
            return Err("raw output shape".to_string());
        }
        let target_index = match event.target {
            0.0 => 0,
            1.0 => 2,
            _ => return Err("target index".to_string()),
        };
        let logits = &event.raw_output[..3];
        if logits.iter().any(|value| !value.is_finite()) {
            return Err("non-finite logits".to_string());
        }
        let maximum = logits
            .iter()
            .map(|value| f64::from(*value))
            .reduce(f64::max)
            .ok_or_else(|| "empty logits".to_string())?;
        let exponentials = logits
            .iter()
            .map(|value| (f64::from(*value) - maximum).exp())
            .collect::<Vec<_>>();
        let total = exponentials.iter().sum::<f64>();
        let probabilities = exponentials
            .iter()
            .map(|value| value / total)
            .collect::<Vec<_>>();
        let probabilities_finite =
            total.is_finite() && total > 0.0 && probabilities.iter().all(|value| value.is_finite());
        let normalization_valid = probabilities_finite
            && (probabilities.iter().sum::<f64>() - 1.0).abs()
                <= R9_PROBABILITY_NORMALIZATION_TOLERANCE;
        let log_sum_exp = maximum + total.ln();
        let nll = (log_sum_exp - f64::from(logits[target_index])) as f32;
        if !nll.is_finite() {
            return Err("non-finite categorical NLL".to_string());
        }
        Ok((nll, probabilities_finite, normalization_valid))
    }

    fn structural_loss_evidence_v1(
        evidence: &[DelayedRecallEvidenceV2],
    ) -> StructuralLossEvidenceV1 {
        let mut populations = Vec::new();
        let mut failed_event_identities = Vec::new();
        let mut event_count = 0;
        let mut recomputed_event_count = 0;
        let mut raw_output_shape_valid = true;
        let mut target_shape_valid = true;
        let mut target_index_valid = true;
        let mut logits_finite = true;
        let mut probability_vectors_finite = true;
        let mut probability_normalization_valid = true;
        let mut recorded_event_nll_matches_recomputed = true;
        let mut recorded_aggregate_nll_matches_recomputed = true;
        let expected_events_per_population =
            delayed_recall_evidence_policy_v2().frozen_evaluation_examples_per_class * 2;
        let population_partition_valid = evidence.len()
            == delayed_recall_evidence_policy_v2().sequence_lengths.len()
            && evidence.iter().all(|delayed| {
                delayed_recall_evidence_policy_v2()
                    .sequence_lengths
                    .contains(&delayed.sequence_length)
                    && delayed.base_event_audits.len() == expected_events_per_population
                    && delayed.no_state_event_audits.len() == expected_events_per_population
            });
        let event_identity_unique = evidence.iter().all(|delayed| {
            [&delayed.base_event_audits, &delayed.no_state_event_audits]
                .into_iter()
                .all(|events| {
                    events
                        .iter()
                        .map(|event| &event.event_identity)
                        .collect::<BTreeSet<_>>()
                        .len()
                        == events.len()
                })
        });

        for delayed in evidence {
            for (population, events, recorded_aggregate) in [
                (
                    "Base",
                    &delayed.base_event_audits,
                    delayed.base_mean_direction_nll,
                ),
                (
                    "No-State",
                    &delayed.no_state_event_audits,
                    delayed.no_state_mean_direction_nll,
                ),
            ] {
                let mut population_failed = 0;
                let mut recomputed = Vec::with_capacity(events.len());
                for event in events {
                    event_count += 1;
                    let shape_valid = event.raw_output.len() == 5;
                    let target_valid = matches!(event.target, 0.0 | 1.0);
                    let index_valid = target_valid;
                    let event_logits_finite =
                        shape_valid && event.raw_output[..3].iter().all(|value| value.is_finite());
                    raw_output_shape_valid &= shape_valid;
                    target_shape_valid &= target_valid;
                    target_index_valid &= index_valid;
                    logits_finite &= event_logits_finite;

                    let mut event_failed =
                        !(shape_valid && target_valid && index_valid && event_logits_finite);
                    match independently_recomputed_event_nll_v1(event) {
                        Ok((nll, probabilities_finite, normalization_valid)) => {
                            recomputed_event_count += 1;
                            recomputed.push(nll);
                            probability_vectors_finite &= probabilities_finite;
                            probability_normalization_valid &= normalization_valid;
                            let matches =
                                within_r9_tolerance(event.event_nll, nll, R9_EVENT_NLL_TOLERANCE);
                            recorded_event_nll_matches_recomputed &= matches;
                            event_failed |=
                                !probabilities_finite || !normalization_valid || !matches;
                        }
                        Err(_) => {
                            probability_vectors_finite = false;
                            probability_normalization_valid = false;
                            recorded_event_nll_matches_recomputed = false;
                            event_failed = true;
                        }
                    }
                    if event_failed {
                        population_failed += 1;
                        failed_event_identities.push(format!(
                            "{}:{}:{}",
                            delayed.sequence_length, population, event.event_identity
                        ));
                    }
                }
                let recomputed_aggregate = if recomputed.len() == events.len() && !events.is_empty()
                {
                    recomputed.iter().sum::<f32>() / recomputed.len() as f32
                } else {
                    0.0
                };
                recorded_aggregate_nll_matches_recomputed &= within_r9_tolerance(
                    recorded_aggregate,
                    recomputed_aggregate,
                    R9_AGGREGATE_NLL_TOLERANCE,
                );
                populations.push(StructuralLossPopulationEvidenceV1 {
                    identity: format!(
                        "length-{}-{}",
                        delayed.sequence_length,
                        population.to_ascii_lowercase()
                    ),
                    sequence_length: delayed.sequence_length,
                    population: population.to_string(),
                    event_count: events.len(),
                    failed_event_count: population_failed,
                    recorded_aggregate_categorical_nll: recorded_aggregate,
                    recomputed_aggregate_categorical_nll: recomputed_aggregate,
                });
            }
        }

        let composite_role_loss_separated = evidence.iter().all(|delayed| {
            delayed.composite_loss_semantics == ClassificationLossSemanticsV1::CompositeRoleLoss
                && delayed.direction_nll_semantics
                    == ClassificationLossSemanticsV1::MeanCategoricalNegativeLogLikelihood
                && delayed.final_frozen_composite_role_loss.is_finite()
                && delayed.no_state_frozen_composite_role_loss.is_finite()
                && delayed.base_mean_direction_nll.is_finite()
                && delayed.no_state_mean_direction_nll.is_finite()
        });
        let categorical_nll_not_aliased_to_role_loss = composite_role_loss_separated
            && evidence.iter().all(|delayed| {
                delayed.final_frozen_composite_role_loss.to_bits()
                    != delayed.base_mean_direction_nll.to_bits()
                    && delayed.no_state_frozen_composite_role_loss.to_bits()
                        != delayed.no_state_mean_direction_nll.to_bits()
            });
        let failed_event_count = failed_event_identities.len();
        let event_categorical_nll_recomputed =
            event_count > 0 && recomputed_event_count == event_count;
        let aggregate_categorical_nll_recomputed = populations.len() == 6
            && populations
                .iter()
                .all(|population| population.event_count > 0);
        let aggregate_denominator_valid = populations
            .iter()
            .all(|population| population.event_count == expected_events_per_population);
        let passed = event_count > 0
            && failed_event_count == 0
            && population_partition_valid
            && event_identity_unique
            && aggregate_denominator_valid
            && raw_output_shape_valid
            && target_shape_valid
            && target_index_valid
            && logits_finite
            && probability_vectors_finite
            && probability_normalization_valid
            && event_categorical_nll_recomputed
            && aggregate_categorical_nll_recomputed
            && recorded_event_nll_matches_recomputed
            && recorded_aggregate_nll_matches_recomputed
            && composite_role_loss_separated
            && categorical_nll_not_aliased_to_role_loss;
        let evaluation_scope_identity = stable_hash_string(
            &serde_json::to_string(&(
                structural_loss_policy_identity_v1(),
                populations
                    .iter()
                    .map(|population| {
                        (
                            &population.identity,
                            population.event_count,
                            population.failed_event_count,
                        )
                    })
                    .collect::<Vec<_>>(),
            ))
            .unwrap(),
        );
        StructuralLossEvidenceV1 {
            status: status_from_bool_v1(passed),
            evaluation_scope_identity,
            populations,
            event_count,
            failed_event_count,
            failed_event_identities,
            population_partition_valid,
            event_identity_unique,
            aggregate_denominator_valid,
            raw_output_shape_valid,
            target_shape_valid,
            target_index_valid,
            logits_finite,
            probability_vectors_finite,
            probability_normalization_valid,
            event_categorical_nll_recomputed,
            aggregate_categorical_nll_recomputed,
            recorded_event_nll_matches_recomputed,
            recorded_aggregate_nll_matches_recomputed,
            composite_role_loss_separated,
            categorical_nll_not_aliased_to_role_loss,
        }
    }

    fn structural_loss_evidence_complete_v1(evidence: &StructuralLossEvidenceV1) -> bool {
        let expected_events =
            delayed_recall_evidence_policy_v2().frozen_evaluation_examples_per_class * 2;
        let expected_populations = [8, 16, 32]
            .into_iter()
            .flat_map(|length| ["Base", "No-State"].map(move |population| (length, population)))
            .collect::<Vec<_>>();
        let passed = evidence.event_count > 0
            && evidence.failed_event_count == 0
            && evidence.populations.len() == 6
            && evidence.population_partition_valid
            && evidence.event_identity_unique
            && evidence.aggregate_denominator_valid
            && evidence.raw_output_shape_valid
            && evidence.target_shape_valid
            && evidence.target_index_valid
            && evidence.logits_finite
            && evidence.probability_vectors_finite
            && evidence.probability_normalization_valid
            && evidence.event_categorical_nll_recomputed
            && evidence.aggregate_categorical_nll_recomputed
            && evidence.recorded_event_nll_matches_recomputed
            && evidence.recorded_aggregate_nll_matches_recomputed
            && evidence.composite_role_loss_separated
            && evidence.categorical_nll_not_aliased_to_role_loss;
        evidence.event_count > 0
            && !evidence.evaluation_scope_identity.is_empty()
            && evidence.populations.len() == 6
            && evidence.event_count
                == evidence
                    .populations
                    .iter()
                    .map(|population| population.event_count)
                    .sum::<usize>()
            && evidence.failed_event_count == evidence.failed_event_identities.len()
            && evidence.failed_event_count
                == evidence
                    .populations
                    .iter()
                    .map(|population| population.failed_event_count)
                    .sum::<usize>()
            && evidence.populations.iter().all(|population| {
                population.event_count == expected_events
                    && population.recorded_aggregate_categorical_nll.is_finite()
                    && population.recomputed_aggregate_categorical_nll.is_finite()
            })
            && evidence
                .populations
                .iter()
                .map(|population| (population.sequence_length, population.population.as_str()))
                .collect::<Vec<_>>()
                == expected_populations
            && status_from_bool_v1(passed) == evidence.status
    }

    fn event_alignment_passed_v1(evidence: &[DelayedRecallEvidenceV2]) -> bool {
        evidence.iter().all(|evidence| {
            evidence.base_event_audits.len() == evidence.no_state_event_audits.len()
                && evidence
                    .base_event_audits
                    .iter()
                    .zip(&evidence.no_state_event_audits)
                    .all(|(base, no_state)| {
                        base.event_identity == no_state.event_identity
                            && base.sequence_length == no_state.sequence_length
                            && base.class_identity == no_state.class_identity
                            && base.target.to_bits() == no_state.target.to_bits()
                    })
                && [&evidence.base_event_audits, &evidence.no_state_event_audits]
                    .into_iter()
                    .all(|events| {
                        events.iter().filter(|event| event.target == 1.0).count()
                            == events.iter().filter(|event| event.target == 0.0).count()
                            && events
                                .iter()
                                .map(|event| &event.event_identity)
                                .collect::<BTreeSet<_>>()
                                .len()
                                == events.len()
                    })
        })
    }

    fn comparator_purity_passed_v1(evidence: &[DelayedRecallEvidenceV2]) -> bool {
        evidence.iter().all(|evidence| {
            let snapshot = &evidence.comparator_snapshot;
            snapshot.parameter_count > 0
                && snapshot.state_capability_path_count == snapshot.differing_path_count
                && snapshot.unexpected_path_count == 0
                && snapshot.missing_path_count == 0
                && snapshot.base_optimizer_digest == snapshot.no_state_optimizer_digest
                && snapshot.base_dataset_identity == snapshot.no_state_dataset_identity
                && snapshot.base_training_policy_identity
                    == snapshot.no_state_training_policy_identity
                && snapshot.normalizer_identity == "STATELESS_FROZEN_HARNESS_NO_NORMALIZER"
        })
    }

    fn no_state_comparator_evidence_v2(
        snapshot: &NoStateComparatorSnapshotV1,
    ) -> NoStateComparatorEvidenceV2 {
        let comparator_pure = snapshot.parameter_count > 0
            && snapshot.state_capability_path_count == snapshot.differing_path_count
            && snapshot.unexpected_path_count == 0
            && snapshot.missing_path_count == 0
            && snapshot.base_optimizer_digest == snapshot.no_state_optimizer_digest
            && snapshot.base_dataset_identity == snapshot.no_state_dataset_identity
            && snapshot.base_training_policy_identity == snapshot.no_state_training_policy_identity
            && snapshot.normalizer_identity == "STATELESS_FROZEN_HARNESS_NO_NORMALIZER";
        NoStateComparatorEvidenceV2 {
            total_parameter_paths: snapshot.parameter_count,
            state_capability_paths: snapshot.state_capability_path_count,
            differing_paths: snapshot.differing_path_count,
            unexpected_paths: snapshot.unexpected_path_count,
            missing_paths: snapshot.missing_path_count,
            comparator_pure,
        }
    }

    fn final_suffix_contract_passed_v1() -> bool {
        let width = M3MicroConfig::for_agent(AgentId::TrendContinuation, 8).input_dim;
        delayed_recall_evidence_policy_v2()
            .sequence_lengths
            .into_iter()
            .all(|length| {
                [false, true].into_iter().all(|frozen| {
                    let examples = delayed_recall_examples_v2(width, length, frozen);
                    let positive = examples
                        .iter()
                        .filter(|example| example.positive)
                        .collect::<Vec<_>>();
                    let negative = examples
                        .iter()
                        .filter(|example| !example.positive)
                        .collect::<Vec<_>>();
                    positive.len() == negative.len()
                        && examples.iter().all(|example| {
                            example.sequence[length - 3..] == examples[0].sequence[length - 3..]
                        })
                        && positive.iter().all(|positive| {
                            negative
                                .iter()
                                .any(|negative| positive.sequence[1..] == negative.sequence[1..])
                        })
                        && negative.iter().all(|negative| {
                            positive
                                .iter()
                                .any(|positive| positive.sequence[1..] == negative.sequence[1..])
                        })
                })
            })
    }

    fn length32_interaction_evidence_v2(
        evidence: &[DelayedRecallEvidenceV2],
    ) -> Length32InteractionEvidenceV2 {
        let evidence = evidence
            .iter()
            .find(|evidence| evidence.sequence_length == 32)
            .unwrap();
        let paired = delayed_memory_paired_metrics_v1(
            &evidence.base_event_audits,
            &evidence.no_state_event_audits,
        );
        Length32InteractionEvidenceV2 {
            event_support: evidence.base_event_audits.len(),
            positive_support: evidence
                .base_event_audits
                .iter()
                .filter(|event| event.class_identity == "positive")
                .count(),
            negative_support: evidence
                .base_event_audits
                .iter()
                .filter(|event| event.class_identity == "negative")
                .count(),
            base_accuracy: evidence.frozen_accuracy,
            no_state_accuracy: evidence.no_state_accuracy,
            accuracy_gap: evidence.base_vs_no_state_accuracy_gap,
            base_categorical_nll: evidence.base_mean_direction_nll,
            no_state_categorical_nll: evidence.no_state_mean_direction_nll,
            nll_gap: evidence.base_vs_no_state_direction_nll_gap,
            base_mean_true_class_probability: evidence.base_mean_true_class_probability,
            no_state_mean_true_class_probability: evidence.no_state_mean_true_class_probability,
            base_target_aligned_margin: evidence.base_mean_target_aligned_margin,
            no_state_target_aligned_margin: evidence.no_state_mean_target_aligned_margin,
            base_only_correct: paired.base_only_correct,
            no_state_only_correct: paired.no_state_only_correct,
            both_correct: paired.both_correct,
            both_wrong: paired.both_wrong,
            paired_nll_win_rate: paired.paired_nll_win_rate,
            paired_margin_win_rate: paired.paired_margin_win_rate,
        }
    }

    fn status_from_bool_v1(passed: bool) -> GateExecutionStatusV1 {
        if passed {
            GateExecutionStatusV1::Passed
        } else {
            GateExecutionStatusV1::Failed
        }
    }

    const CAPABILITY_SOURCE_SCOPE_POLICY_IDENTITY_V2: &str =
        "m3-micro-capability-production-source-scope-v2";
    const CAPABILITY_TEST_MODULE_BOUNDARY_V2: &str = "\n#[cfg(test)]\nmod tests {";
    const CAPABILITY_SOURCE_COMPONENT_IDENTITIES_V2: [&str; 5] = [
        "src/model/m3_micro.rs#production-before-top-level-test-module",
        "src/model/m3_micro_capability.rs",
        "src/model/m3_micro_trend.rs",
        "src/model/m3_micro_volatility.rs",
        "src/model/m3_micro_reversal.rs",
    ];

    #[derive(Clone, Debug, PartialEq, Eq)]
    struct CapabilitySourceComponentV2 {
        logical_identity: &'static str,
        bytes: Vec<u8>,
    }

    #[derive(Clone, Debug, PartialEq, Eq)]
    struct CapabilitySourceScopeV2 {
        policy_identity: &'static str,
        components: Vec<CapabilitySourceComponentV2>,
    }

    fn capability_production_prefix_v2(source: &[u8]) -> Result<&[u8], String> {
        let source = std::str::from_utf8(source).map_err(|error| error.to_string())?;
        let mut boundaries = source.match_indices(CAPABILITY_TEST_MODULE_BOUNDARY_V2);
        let Some((boundary, _)) = boundaries.next() else {
            return Err("missing top-level capability test-module boundary".to_string());
        };
        if boundaries.next().is_some() {
            return Err("ambiguous top-level capability test-module boundary".to_string());
        }
        if source[..boundary].trim().is_empty() {
            return Err("empty capability production source prefix".to_string());
        }
        Ok(source[..boundary].as_bytes())
    }

    fn canonical_pre_boundary_test_only_attributes_v1(prefix: &str) -> Vec<&str> {
        prefix
            .lines()
            .filter(|line| *line == "#[cfg(test)]" || line.starts_with("#[cfg(all(test,"))
            .collect()
    }

    fn capability_source_scope_v2(core_source: &[u8]) -> Result<CapabilitySourceScopeV2, String> {
        Ok(CapabilitySourceScopeV2 {
            policy_identity: CAPABILITY_SOURCE_SCOPE_POLICY_IDENTITY_V2,
            components: vec![
                CapabilitySourceComponentV2 {
                    logical_identity: CAPABILITY_SOURCE_COMPONENT_IDENTITIES_V2[0],
                    bytes: capability_production_prefix_v2(core_source)?.to_vec(),
                },
                CapabilitySourceComponentV2 {
                    logical_identity: CAPABILITY_SOURCE_COMPONENT_IDENTITIES_V2[1],
                    bytes: include_bytes!(concat!(
                        env!("CARGO_MANIFEST_DIR"),
                        "/src/model/m3_micro_capability.rs"
                    ))
                    .to_vec(),
                },
                CapabilitySourceComponentV2 {
                    logical_identity: CAPABILITY_SOURCE_COMPONENT_IDENTITIES_V2[2],
                    bytes: include_bytes!(concat!(
                        env!("CARGO_MANIFEST_DIR"),
                        "/src/model/m3_micro_trend.rs"
                    ))
                    .to_vec(),
                },
                CapabilitySourceComponentV2 {
                    logical_identity: CAPABILITY_SOURCE_COMPONENT_IDENTITIES_V2[3],
                    bytes: include_bytes!(concat!(
                        env!("CARGO_MANIFEST_DIR"),
                        "/src/model/m3_micro_volatility.rs"
                    ))
                    .to_vec(),
                },
                CapabilitySourceComponentV2 {
                    logical_identity: CAPABILITY_SOURCE_COMPONENT_IDENTITIES_V2[4],
                    bytes: include_bytes!(concat!(
                        env!("CARGO_MANIFEST_DIR"),
                        "/src/model/m3_micro_reversal.rs"
                    ))
                    .to_vec(),
                },
            ],
        })
    }

    fn current_capability_source_scope_v2() -> Result<CapabilitySourceScopeV2, String> {
        capability_source_scope_v2(include_bytes!(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/src/model/m3_micro.rs"
        )))
    }

    fn capability_source_component_digests_v2(
        scope: &CapabilitySourceScopeV2,
    ) -> Result<[String; 5], String> {
        if scope.policy_identity != CAPABILITY_SOURCE_SCOPE_POLICY_IDENTITY_V2
            || scope.components.len() != CAPABILITY_SOURCE_COMPONENT_IDENTITIES_V2.len()
        {
            return Err("invalid capability source scope manifest".to_string());
        }
        let digests = scope
            .components
            .iter()
            .zip(CAPABILITY_SOURCE_COMPONENT_IDENTITIES_V2)
            .map(|(component, expected_identity)| {
                if component.logical_identity != expected_identity || component.bytes.is_empty() {
                    return Err("invalid capability source scope component".to_string());
                }
                let source =
                    std::str::from_utf8(&component.bytes).map_err(|error| error.to_string())?;
                let preimage = serde_json::to_string(&(
                    scope.policy_identity,
                    component.logical_identity,
                    source,
                ))
                .map_err(|error| error.to_string())?;
                Ok(stable_hash_string(&preimage))
            })
            .collect::<Result<Vec<_>, String>>()?;
        Ok([
            digests[0].clone(),
            digests[1].clone(),
            digests[2].clone(),
            digests[3].clone(),
            digests[4].clone(),
        ])
    }

    fn repository_output_v1(arguments: &[&str]) -> Result<String, String> {
        let output = Command::new("git")
            .args(arguments)
            .current_dir(env!("CARGO_MANIFEST_DIR"))
            .output()
            .map_err(|error| error.to_string())?;
        if !output.status.success() {
            return Err("repository identity command failed".to_string());
        }
        String::from_utf8(output.stdout)
            .map(|value| value.trim().to_string())
            .map_err(|error| error.to_string())
    }

    fn repository_value_v1(arguments: &[&str]) -> Result<String, String> {
        let value = repository_output_v1(arguments)?;
        if value.is_empty() {
            Err("empty repository identity".to_string())
        } else {
            Ok(value)
        }
    }

    fn current_git_checkout_provenance_v1() -> Result<GitCheckoutProvenanceV1, String> {
        let branch = repository_output_v1(&["branch", "--show-current"])?;
        let head = repository_value_v1(&["rev-parse", "HEAD"])?;
        GitCheckoutProvenanceV1::from_repository_values(&branch, &head)
    }

    fn current_source_binding_v1_for_checkout(
        checkout: &GitCheckoutProvenanceV1,
    ) -> Result<SourceBindingV1, String> {
        let scope = current_capability_source_scope_v2()?;
        let [
            core_source_digest,
            capability_source_digest,
            trend_source_digest,
            volatility_source_digest,
            reversal_source_digest,
        ] = capability_source_component_digests_v2(&scope)?;
        let combined_source_binding_digest = stable_hash_string(
            &serde_json::to_string(&(
                scope.policy_identity,
                &core_source_digest,
                &capability_source_digest,
                &trend_source_digest,
                &volatility_source_digest,
                &reversal_source_digest,
            ))
            .map_err(|error| error.to_string())?,
        );
        Ok(SourceBindingV1 {
            repository_branch: checkout.branch_name().map(str::to_string),
            repository_head: checkout.head().to_string(),
            core_source_digest,
            capability_source_digest,
            trend_source_digest,
            volatility_source_digest,
            reversal_source_digest,
            combined_source_binding_digest,
        })
    }

    fn current_source_binding_v1() -> Result<SourceBindingV1, String> {
        current_source_binding_v1_for_checkout(&current_git_checkout_provenance_v1()?)
    }

    fn source_binding_semantics_match_v1(
        receipt: &SourceBindingV1,
        current: &SourceBindingV1,
    ) -> bool {
        receipt.core_source_digest == current.core_source_digest
            && receipt.capability_source_digest == current.capability_source_digest
            && receipt.trend_source_digest == current.trend_source_digest
            && receipt.volatility_source_digest == current.volatility_source_digest
            && receipt.reversal_source_digest == current.reversal_source_digest
    }

    fn current_support_binding_v1() -> SupportBindingV1 {
        let recall = delayed_recall_evidence_policy_v2();
        let forgetting = selective_forgetting_evidence_policy_v3();
        let recall_support_per_seed =
            recall.sequence_lengths.len() * recall.frozen_evaluation_examples_per_class * 2;
        let forgetting_development_per_seed = ForgettingCaseV3::ORDERED.len()
            * forgetting.sequence_lengths.len()
            * forgetting.invalidation_positions.len()
            * forgetting.development_examples_per_class
            * 2;
        let forgetting_frozen_per_seed = ForgettingCaseV3::ORDERED.len()
            * forgetting.sequence_lengths.len()
            * forgetting.invalidation_positions.len()
            * forgetting.frozen_examples_per_class
            * 2;
        let development_support = (recall.sequence_lengths.len() * 4
            + forgetting_development_per_seed)
            * forgetting.seed_identities.len();
        let frozen_support = (recall_support_per_seed + forgetting_frozen_per_seed)
            * forgetting.seed_identities.len();
        let sequence_lengths = recall.sequence_lengths.to_vec();
        let invalidation_positions = forgetting
            .invalidation_positions
            .iter()
            .map(|position| format!("{position:?}"))
            .collect::<Vec<_>>();
        let seed_identities = forgetting.seed_identities.to_vec();
        let profile_count = CoreAttributionProfileV2::ORDERED.len();
        let support_event_count_per_group = frozen_support;
        let full_support_panel_used =
            reinforcement_attribution_policy_v2().require_full_support_panel;
        let support_binding_digest = stable_hash_string(
            &serde_json::to_string(&(
                &sequence_lengths,
                &invalidation_positions,
                &seed_identities,
                development_support,
                frozen_support,
                profile_count,
                support_event_count_per_group,
                full_support_panel_used,
            ))
            .unwrap(),
        );
        SupportBindingV1 {
            sequence_lengths,
            invalidation_positions,
            seed_identities,
            development_support,
            frozen_support,
            profile_count,
            support_event_count_per_group,
            full_support_panel_used,
            support_binding_digest,
        }
    }

    fn profile_policy_identity_v1() -> String {
        stable_hash_string(&format!(
            "m3-r6-attribution-profiles:{:?}:{:?}",
            CoreAttributionProfileV2::ORDERED,
            AttributionGroupV2::ORDERED.map(AttributionGroupV2::comparator),
        ))
    }

    fn metric_semantics_identity_v1() -> String {
        stable_hash_string(&format!(
            "m3-r7-metric-semantics:{:?}:{:?}:{PROBABILITY_EPSILON}",
            ClassificationLossSemanticsV1::CompositeRoleLoss,
            ClassificationLossSemanticsV1::MeanCategoricalNegativeLogLikelihood,
        ))
    }

    fn current_policy_binding_v1(support: &SupportBindingV1) -> PolicyBindingV1 {
        let attribution_decision_policy_identity = stable_hash_string(&format!(
            "m3-micro-attribution-v2:{:?}",
            reinforcement_attribution_policy_v2()
        ));
        let profile_policy_identity = profile_policy_identity_v1();
        let support_policy_identity = support.support_binding_digest.clone();
        let gradient_policy_identity = gradient_policy_identity_v2();
        let interaction_policy_identity = stable_hash_string(&format!(
            "m3-r7-protected-interaction:{:?}:strict-categorical-nll-and-accuracy",
            delayed_recall_evidence_policy_v2()
        ));
        let metric_semantics_identity = metric_semantics_identity_v1();
        let frozen_v3_policy_identity = stable_hash_string(&format!(
            "m3-r7-frozen-v3:{:?}",
            selective_forgetting_evidence_policy_v3()
        ));
        let combined_policy_binding_digest = stable_hash_string(
            &serde_json::to_string(&(
                &attribution_decision_policy_identity,
                &profile_policy_identity,
                &support_policy_identity,
                &gradient_policy_identity,
                &interaction_policy_identity,
                &metric_semantics_identity,
                &frozen_v3_policy_identity,
            ))
            .unwrap(),
        );
        PolicyBindingV1 {
            attribution_decision_policy_identity,
            profile_policy_identity,
            support_policy_identity,
            gradient_policy_identity,
            interaction_policy_identity,
            metric_semantics_identity,
            frozen_v3_policy_identity,
            combined_policy_binding_digest,
        }
    }

    fn semantic_source_binding_v2_from_scope(
        scope: &CapabilitySourceScopeV2,
    ) -> Result<SemanticSourceBindingV2, String> {
        let [
            core_source_digest,
            capability_source_digest,
            trend_source_digest,
            volatility_source_digest,
            reversal_source_digest,
        ] = capability_source_component_digests_v2(scope)?;
        let model_schema_identity = M3_MICRO_CORE_SCHEMA_V3.to_string();
        let checkpoint_format_identity =
            format!("m3-micro-checkpoint-v{M3_MICRO_CHECKPOINT_FORMAT_VERSION_V4}");
        let runtime_wiring_policy_identity = stable_hash_string(R9_RUNTIME_WIRING_POLICY);
        let combined_source_binding_digest = stable_hash_string(
            &serde_json::to_string(&(
                scope.policy_identity,
                &core_source_digest,
                &capability_source_digest,
                &trend_source_digest,
                &volatility_source_digest,
                &reversal_source_digest,
                &model_schema_identity,
                &checkpoint_format_identity,
                &runtime_wiring_policy_identity,
            ))
            .map_err(|error| error.to_string())?,
        );
        Ok(SemanticSourceBindingV2 {
            core_source_digest,
            capability_source_digest,
            trend_source_digest,
            volatility_source_digest,
            reversal_source_digest,
            model_schema_identity,
            checkpoint_format_identity,
            runtime_wiring_policy_identity,
            combined_source_binding_digest,
        })
    }

    fn current_semantic_source_binding_v2() -> Result<SemanticSourceBindingV2, String> {
        semantic_source_binding_v2_from_scope(&current_capability_source_scope_v2()?)
    }

    fn current_policy_binding_v2(support: &SupportBindingV1) -> PolicyBindingV2 {
        let v1 = current_policy_binding_v1(support);
        let structural_loss_policy_identity = structural_loss_policy_identity_v1();
        let combined_policy_binding_digest = stable_hash_string(
            &serde_json::to_string(&(
                &v1.attribution_decision_policy_identity,
                &v1.profile_policy_identity,
                &v1.support_policy_identity,
                &v1.gradient_policy_identity,
                &v1.metric_semantics_identity,
                &structural_loss_policy_identity,
                &v1.interaction_policy_identity,
                &v1.frozen_v3_policy_identity,
            ))
            .unwrap(),
        );
        PolicyBindingV2 {
            attribution_decision_policy_identity: v1.attribution_decision_policy_identity,
            profile_policy_identity: v1.profile_policy_identity,
            support_policy_identity: v1.support_policy_identity,
            gradient_policy_identity: v1.gradient_policy_identity,
            metric_semantics_identity: v1.metric_semantics_identity,
            structural_loss_policy_identity,
            interaction_policy_identity: v1.interaction_policy_identity,
            frozen_v3_policy_identity: v1.frozen_v3_policy_identity,
            combined_policy_binding_digest,
        }
    }

    fn semantic_binding_v2_from_source_v2(
        source: SemanticSourceBindingV2,
    ) -> Result<SemanticBindingV2, String> {
        let support = current_support_binding_v1();
        let policy = current_policy_binding_v2(&support);
        let combined_semantic_binding_digest = stable_hash_string(
            &serde_json::to_string(&(
                &source.combined_source_binding_digest,
                &policy.combined_policy_binding_digest,
                &support.support_binding_digest,
            ))
            .map_err(|error| error.to_string())?,
        );
        Ok(SemanticBindingV2 {
            source,
            policy,
            support,
            combined_semantic_binding_digest,
        })
    }

    fn current_semantic_binding_v2() -> Result<SemanticBindingV2, String> {
        semantic_binding_v2_from_source_v2(current_semantic_source_binding_v2()?)
    }

    fn current_generation_provenance_v2() -> Result<GenerationProvenanceV2, String> {
        let checkout = current_git_checkout_provenance_v1()?;
        Ok(GenerationProvenanceV2 {
            generation_branch: checkout.branch_name().map(str::to_string),
            generation_head: checkout.head().to_string(),
            generator_label: "m3_micro_r9_generate_commit_safe_authoritative_receipt".to_string(),
        })
    }

    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    enum SemanticCurrentnessErrorV2 {
        Source,
        Policy,
        Support,
    }

    fn validate_semantic_currentness_v2(
        receipt: &SemanticBindingV2,
        current: &SemanticBindingV2,
    ) -> Result<(), SemanticCurrentnessErrorV2> {
        if receipt.source != current.source {
            return Err(SemanticCurrentnessErrorV2::Source);
        }
        if receipt.policy != current.policy {
            return Err(SemanticCurrentnessErrorV2::Policy);
        }
        if receipt.support != current.support {
            return Err(SemanticCurrentnessErrorV2::Support);
        }
        if receipt.combined_semantic_binding_digest != current.combined_semantic_binding_digest {
            return Err(SemanticCurrentnessErrorV2::Source);
        }
        Ok(())
    }

    #[derive(Clone, Debug, Default, PartialEq, Eq)]
    struct ProjectScopeSnapshotV1 {
        tracked_modified: Vec<String>,
        tracked_deleted: Vec<String>,
        untracked: Vec<String>,
        staged: Vec<String>,
    }

    fn r9_allowed_project_path(path: &str) -> bool {
        matches!(
            path,
            "src/model/mod.rs"
                | "src/model/m3_micro.rs"
                | "src/model/m3_micro_metal.rs"
                | "src/model/m3_micro_capability.rs"
                | "src/model/m3_micro_trend.rs"
                | "src/model/m3_micro_volatility.rs"
                | "src/model/m3_micro_reversal.rs"
                | "docs/SPRINT104_R1_M3_MICRO_FUNCTIONAL_CONFORMANCE_REPORT.md"
                | R7_RECEIPT_RELATIVE_PATH
                | R9_RECEIPT_RELATIVE_PATH
                | "docs/evidence/SPRINT104_R1_M3_MICRO_METAL_EXECUTION_RECEIPT_V1.json"
                | R10_DELIVERY_RECEIPT_RELATIVE_PATH
        )
    }

    fn validate_r9_project_scope_v1(snapshot: &ProjectScopeSnapshotV1) -> Result<(), String> {
        if !snapshot.staged.is_empty() {
            return Err("staged project path".to_string());
        }
        if snapshot
            .tracked_modified
            .iter()
            .chain(&snapshot.tracked_deleted)
            .chain(&snapshot.untracked)
            .any(|path| !r9_allowed_project_path(path))
        {
            return Err("unexpected project path".to_string());
        }
        Ok(())
    }

    fn receipt_semantic_bytes_v1(
        receipt: &M3MicroAuthoritativeAttributionReceiptV1,
    ) -> Result<Vec<u8>, String> {
        let mut semantic = receipt.clone();
        semantic.receipt_digest.clear();
        serde_json::to_vec(&semantic).map_err(|error| error.to_string())
    }

    fn receipt_computed_digest_v1(
        receipt: &M3MicroAuthoritativeAttributionReceiptV1,
    ) -> Result<String, String> {
        let bytes = receipt_semantic_bytes_v1(receipt)?;
        let canonical = std::str::from_utf8(&bytes).map_err(|error| error.to_string())?;
        Ok(stable_hash_string(canonical))
    }

    fn canonical_receipt_bytes_v1(
        receipt: &M3MicroAuthoritativeAttributionReceiptV1,
    ) -> Result<Vec<u8>, String> {
        serde_json::to_vec(receipt).map_err(|error| error.to_string())
    }

    fn receipt_groups_v1(
        receipt: &M3MicroAuthoritativeAttributionReceiptV1,
    ) -> [&AttributionGroupReceiptV1; 4] {
        [&receipt.g1, &receipt.g2, &receipt.g3, &receipt.g4]
    }

    fn validate_receipt_self_v1(
        receipt: &M3MicroAuthoritativeAttributionReceiptV1,
    ) -> Result<(), String> {
        if receipt.format_version != R7_RECEIPT_FORMAT_VERSION
            || !receipt.generated_from_fresh_computation
            || receipt.attribution_execution_count != 1
            || receipt.full_attribution_replay_performed
            || receipt.profile_count != receipt.support_binding.profile_count
            || receipt.support_event_count_per_group
                != receipt.support_binding.support_event_count_per_group
            || !receipt.support_binding.full_support_panel_used
            || receipt.policy_binding.gradient_policy_identity != receipt.gradient.policy_identity
            || receipt.policy_binding.metric_semantics_identity
                != receipt.metric_semantics.metric_semantics_identity
            || receipt.gate_lifecycle.report_integrity != GateExecutionStatusV1::NotRun
            || receipt_groups_v1(receipt).iter().any(|group| {
                group.support_event_count != receipt.support_event_count_per_group
                    || group.seed_count != receipt.support_binding.seed_identities.len()
                    || group.sequence_lengths != receipt.support_binding.sequence_lengths
                    || group.invalidation_positions
                        != receipt.support_binding.invalidation_positions
                    || group.metrics.iter().any(|metric| {
                        [
                            metric.full_accuracy,
                            metric.comparator_accuracy,
                            metric.accuracy_delta,
                            metric.full_mean_nll,
                            metric.comparator_mean_nll,
                            metric.mean_nll_gain,
                            metric.full_target_margin,
                            metric.comparator_target_margin,
                            metric.target_margin_gain,
                            metric.paired_win_rate,
                        ]
                        .iter()
                        .any(|value| !value.is_finite())
                    })
            })
            || receipt_computed_digest_v1(receipt)? != receipt.receipt_digest
        {
            return Err("invalid authoritative receipt".to_string());
        }
        let encoded = canonical_receipt_bytes_v1(receipt)?;
        let decoded: M3MicroAuthoritativeAttributionReceiptV1 =
            serde_json::from_slice(&encoded).map_err(|error| error.to_string())?;
        if decoded != *receipt || canonical_receipt_bytes_v1(&decoded)? != encoded {
            return Err("non-canonical receipt roundtrip".to_string());
        }
        Ok(())
    }

    fn receipt_path_v1() -> PathBuf {
        Path::new(env!("CARGO_MANIFEST_DIR")).join(R7_RECEIPT_RELATIVE_PATH)
    }

    fn read_authoritative_receipt_v1() -> Result<M3MicroAuthoritativeAttributionReceiptV1, String> {
        let bytes = fs::read(receipt_path_v1()).map_err(|error| error.to_string())?;
        let receipt: M3MicroAuthoritativeAttributionReceiptV1 =
            serde_json::from_slice(&bytes).map_err(|error| error.to_string())?;
        validate_receipt_self_v1(&receipt)?;
        if canonical_receipt_bytes_v1(&receipt)? != bytes {
            return Err("receipt file is not canonical JSON".to_string());
        }
        Ok(receipt)
    }

    fn validate_receipt_currentness_v1(
        receipt: &M3MicroAuthoritativeAttributionReceiptV1,
    ) -> Result<(), String> {
        validate_receipt_self_v1(receipt)?;
        let support = current_support_binding_v1();
        if !source_binding_semantics_match_v1(
            &receipt.source_binding,
            &current_source_binding_v1()?,
        ) {
            return Err("receipt source binding is stale".to_string());
        }
        if receipt.support_binding != support {
            return Err("receipt support binding is stale".to_string());
        }
        if receipt.policy_binding != current_policy_binding_v1(&support) {
            return Err("receipt policy binding is stale".to_string());
        }
        if !receipt.generated_from_fresh_computation || receipt.attribution_execution_count != 1 {
            return Err("receipt attribution provenance is invalid".to_string());
        }
        Ok(())
    }

    fn attribution_group_receipt_v1(
        evidence: &AttributionGroupEvidenceR6,
    ) -> AttributionGroupReceiptV1 {
        AttributionGroupReceiptV1 {
            group: evidence.group.report_name().to_string(),
            comparator: format!("{:?}", evidence.exact_comparator),
            support_event_count: evidence.support_event_count,
            sequence_lengths: evidence.sequence_lengths.iter().copied().collect(),
            invalidation_positions: evidence
                .positions
                .iter()
                .map(|position| format!("{position:?}"))
                .collect(),
            seed_count: evidence.seed_count,
            metrics: evidence
                .metrics
                .iter()
                .map(|metric| AttributionMetricReceiptV1 {
                    metric: metric.metric.label().to_string(),
                    support_count: metric.full.count,
                    full_accuracy: metric.full.accuracy,
                    comparator_accuracy: metric.comparator.accuracy,
                    accuracy_delta: metric.accuracy_delta,
                    full_mean_nll: metric.full.mean_nll,
                    comparator_mean_nll: metric.comparator.mean_nll,
                    mean_nll_gain: metric.mean_nll_gain,
                    full_target_margin: metric.full.mean_target_margin,
                    comparator_target_margin: metric.comparator.mean_target_margin,
                    target_margin_gain: metric.target_margin_gain,
                    paired_win_rate: metric.paired_win_rate,
                })
                .collect(),
            protected_regressions: evidence.protected_regressions,
            decision: evidence.decision.as_str().to_string(),
            production_action: evidence.production_action.clone(),
        }
    }

    fn build_authoritative_receipt_v1() -> Result<M3MicroAuthoritativeAttributionReceiptV1, String>
    {
        use GateExecutionStatusV1::{NotRun, Passed};

        let source_binding = current_source_binding_v1()?;
        let support_binding = current_support_binding_v1();
        let policy_binding = current_policy_binding_v1(&support_binding);
        let attribution = authoritative_attribution_r7();
        let groups = attribution
            .evidence
            .groups
            .each_ref()
            .map(attribution_group_receipt_v1);
        let attribution_status = status_from_bool_v1(
            attribution.execution_count == 1
                && attribution.raw.full_support_panel_verified
                && attribution.evidence.deterministic_inference_checks_passed
                && attribution.evidence.reduced_candidate.matches_production
                && attribution
                    .evidence
                    .groups
                    .iter()
                    .all(|group| group.decision.retained().is_some())
                && attribution.evidence.policy_identity
                    == policy_binding.attribution_decision_policy_identity
                && attribution.evidence.profile_identity == policy_binding.profile_policy_identity
                && attribution.evidence.groups.iter().all(|group| {
                    group.support_event_count == support_binding.support_event_count_per_group
                        && group.seed_count == support_binding.seed_identities.len()
                        && group.sequence_lengths.iter().copied().collect::<Vec<_>>()
                            == support_binding.sequence_lengths
                        && group
                            .positions
                            .iter()
                            .map(|position| format!("{position:?}"))
                            .collect::<Vec<_>>()
                            == support_binding.invalidation_positions
                }),
        );
        let gradient = execute_gradient_receipt_v2();
        let delayed = delayed_recall_evidence_v2();
        let metric_definition = status_from_bool_v1(metric_semantics_passed_v1(delayed));
        let metric_aggregation = status_from_bool_v1(metric_aggregation_passed_v1(delayed));
        let accuracy_nll_source = status_from_bool_v1(accuracy_nll_source_passed_v1(delayed));
        let metric_semantics = status_from_bool_v1(
            [metric_definition, metric_aggregation, accuracy_nll_source]
                .iter()
                .all(|status| *status == Passed),
        );
        let structural_loss = structural_loss_evidence_v1(delayed);
        let event_alignment = status_from_bool_v1(event_alignment_passed_v1(delayed));
        let comparator_purity = status_from_bool_v1(comparator_purity_passed_v1(delayed));
        let suffix_integrity = status_from_bool_v1(final_suffix_contract_passed_v1());
        let length32_delayed = delayed
            .iter()
            .find(|evidence| evidence.sequence_length == 32)
            .ok_or_else(|| "missing length-32 evidence".to_string())?;
        let comparator = no_state_comparator_evidence_v2(&length32_delayed.comparator_snapshot);
        let length32 = length32_interaction_evidence_v2(delayed);
        let protected_interaction = if attribution_status == Passed
            && gradient.status == Passed
            && [
                metric_semantics,
                structural_loss.status,
                event_alignment,
                comparator_purity,
                suffix_integrity,
            ]
            .iter()
            .all(|status| *status == Passed)
        {
            status_from_bool_v1(protected_interaction_passed_v1())
        } else {
            NotRun
        };
        let root_cause = root_cause_from_contract_evidence_v2(RootCauseContractEvidenceV2 {
            metric_semantics: metric_definition,
            metric_aggregation,
            accuracy_nll_source,
            event_alignment,
            comparator_purity,
            suffix_integrity,
            structural_loss: structural_loss.status,
            protected_interaction,
        });
        let frozen_v3 = if protected_interaction == Passed {
            status_from_bool_v1(frozen_v3_passed_v1())
        } else {
            NotRun
        };
        let gate_lifecycle = M3MicroEvidenceLifecycleV2 {
            initialization_oracle: Passed,
            attribution: attribution_status,
            final_gradient: gradient.status,
            metric_semantics,
            structural_loss: structural_loss.status,
            event_alignment,
            comparator_purity,
            suffix_integrity,
            protected_interaction,
            frozen_v3,
            report_integrity: NotRun,
        };
        let reduced_candidate = ReducedCandidateReceiptV1 {
            retained_groups: attribution
                .evidence
                .reduced_candidate
                .retained_groups
                .iter()
                .map(|group| group.report_name().to_string())
                .collect(),
            reverted_groups: attribution
                .evidence
                .reduced_candidate
                .reverted_groups
                .iter()
                .map(|group| group.report_name().to_string())
                .collect(),
            matches_production: attribution.evidence.reduced_candidate.matches_production,
        };
        let derived_final_status = derive_r7_final_status_v1(gate_lifecycle, root_cause, Passed)
            .as_str()
            .to_string();
        let mut receipt = M3MicroAuthoritativeAttributionReceiptV1 {
            format_version: R7_RECEIPT_FORMAT_VERSION,
            generated_from_fresh_computation: true,
            attribution_execution_count: attribution.execution_count as u32,
            attribution_duration_milliseconds: attribution.duration_milliseconds,
            source_binding,
            policy_binding,
            support_binding: support_binding.clone(),
            profile_count: support_binding.profile_count,
            support_event_count_per_group: support_binding.support_event_count_per_group,
            g1: groups[0].clone(),
            g2: groups[1].clone(),
            g3: groups[2].clone(),
            g4: groups[3].clone(),
            reduced_candidate,
            gradient,
            comparator,
            length32,
            metric_semantics: MetricSemanticsReceiptV1 {
                composite_loss_semantics: "CompositeRoleLoss".to_string(),
                direction_nll_semantics: "MeanCategoricalNegativeLogLikelihood".to_string(),
                metric_semantics_identity: metric_semantics_identity_v1(),
                metric_semantics_status: metric_semantics,
                event_alignment_status: event_alignment,
                suffix_integrity_status: suffix_integrity,
            },
            root_cause,
            gate_lifecycle,
            derived_final_status,
            deterministic_inference_checks_passed: attribution
                .evidence
                .deterministic_inference_checks_passed,
            full_attribution_replay_performed: false,
            receipt_digest: String::new(),
        };
        receipt.receipt_digest = receipt_computed_digest_v1(&receipt)?;
        validate_receipt_self_v1(&receipt)?;
        Ok(receipt)
    }

    fn persist_authoritative_receipt_v1(
        receipt: &M3MicroAuthoritativeAttributionReceiptV1,
    ) -> Result<(), String> {
        validate_receipt_self_v1(receipt)?;
        let path = receipt_path_v1();
        let parent = path
            .parent()
            .ok_or_else(|| "receipt parent is missing".to_string())?;
        fs::create_dir_all(parent).map_err(|error| error.to_string())?;
        if path.exists() {
            read_authoritative_receipt_v1()?;
        }
        let temporary = path.with_extension(format!("json.tmp.{}", receipt.receipt_digest));
        let bytes = canonical_receipt_bytes_v1(receipt)?;
        let mut file = OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(&temporary)
            .map_err(|error| error.to_string())?;
        let write_result = file
            .write_all(&bytes)
            .and_then(|_| file.sync_all())
            .map_err(|error| error.to_string());
        drop(file);
        if let Err(error) = write_result {
            let _ = fs::remove_file(&temporary);
            return Err(error);
        }
        let staged_bytes = fs::read(&temporary).map_err(|error| error.to_string())?;
        let staged: M3MicroAuthoritativeAttributionReceiptV1 =
            serde_json::from_slice(&staged_bytes).map_err(|error| error.to_string())?;
        if staged != *receipt || canonical_receipt_bytes_v1(&staged)? != staged_bytes {
            let _ = fs::remove_file(&temporary);
            return Err("temporary receipt verification failed".to_string());
        }
        validate_receipt_self_v1(&staged)?;
        fs::rename(&temporary, &path).map_err(|error| error.to_string())?;
        let reopened = read_authoritative_receipt_v1()?;
        if reopened != *receipt {
            return Err("persisted receipt verification failed".to_string());
        }
        Ok(())
    }

    #[test]
    #[ignore = "explicit authoritative evidence generation only"]
    fn m3_micro_r7_generate_authoritative_attribution_receipt() {
        assert_eq!(
            std::env::var("SOMA_M3_R7_GENERATE_RECEIPT").as_deref(),
            Ok("1")
        );
        R10_RECEIPT_GENERATIONS.fetch_add(1, Ordering::SeqCst);
        let receipt = build_authoritative_receipt_v1().unwrap();
        persist_authoritative_receipt_v1(&receipt).unwrap();
        println!(
            "SPRINT104_R7_RECEIPT execution_count={} duration_ms={} profile_count={} support_count={} path={} digest={}",
            receipt.attribution_execution_count,
            receipt.attribution_duration_milliseconds,
            receipt.profile_count,
            receipt.support_event_count_per_group,
            R7_RECEIPT_RELATIVE_PATH,
            receipt.receipt_digest,
        );
    }

    fn derive_capability_status_v2(
        lifecycle: M3MicroEvidenceLifecycleV2,
        metric_aggregation: GateExecutionStatusV1,
        accuracy_nll_source: GateExecutionStatusV1,
        root_cause: Length32RootCauseV2,
    ) -> CapabilityStatusV2 {
        use GateExecutionStatusV1::{Failed, NotRun};
        if lifecycle.attribution == Failed {
            return CapabilityStatusV2::BlockedByReinforcementAttribution;
        }
        if lifecycle.final_gradient == Failed {
            return CapabilityStatusV2::BlockedByGradientConformance;
        }
        if lifecycle.metric_semantics == Failed {
            return CapabilityStatusV2::BlockedByMetricSemantics;
        }
        if lifecycle.structural_loss == Failed {
            return CapabilityStatusV2::BlockedByStructuralLossImplementation;
        }
        if metric_aggregation == Failed {
            return CapabilityStatusV2::BlockedByMetricAggregation;
        }
        if accuracy_nll_source == Failed {
            return CapabilityStatusV2::BlockedByMetricSemantics;
        }
        if lifecycle.event_alignment == Failed {
            return CapabilityStatusV2::BlockedByEventAlignment;
        }
        if lifecycle.comparator_purity == Failed {
            return CapabilityStatusV2::BlockedByNoStateComparator;
        }
        if lifecycle.suffix_integrity == Failed {
            return CapabilityStatusV2::BlockedByFinalSuffixLeakage;
        }
        if lifecycle.protected_interaction == Failed {
            return match root_cause {
                Length32RootCauseV2::GenuineLength32ConfidenceDeficit => {
                    CapabilityStatusV2::BlockedByLength32ConfidenceCapability
                }
                Length32RootCauseV2::StructuralLossImplementationDefect => {
                    CapabilityStatusV2::BlockedByStructuralLossImplementation
                }
                Length32RootCauseV2::MetricAggregationDefect => {
                    CapabilityStatusV2::BlockedByMetricAggregation
                }
                Length32RootCauseV2::EventAlignmentDefect => {
                    CapabilityStatusV2::BlockedByEventAlignment
                }
                Length32RootCauseV2::NoStateComparatorContamination => {
                    CapabilityStatusV2::BlockedByNoStateComparator
                }
                Length32RootCauseV2::FinalSuffixLeakage => {
                    CapabilityStatusV2::BlockedByFinalSuffixLeakage
                }
                Length32RootCauseV2::MetricDefinitionMismatch
                | Length32RootCauseV2::AccuracyNllSourceMismatch => {
                    CapabilityStatusV2::BlockedByMetricSemantics
                }
                Length32RootCauseV2::NoDefect | Length32RootCauseV2::Indeterminate => {
                    CapabilityStatusV2::BlockedByIncompleteEvidence
                }
            };
        }
        if lifecycle.frozen_v3 == Failed {
            return CapabilityStatusV2::BlockedBySelectiveForgettingV3;
        }
        if [
            lifecycle.initialization_oracle,
            lifecycle.attribution,
            lifecycle.final_gradient,
            lifecycle.metric_semantics,
            lifecycle.structural_loss,
            metric_aggregation,
            accuracy_nll_source,
            lifecycle.event_alignment,
            lifecycle.comparator_purity,
            lifecycle.suffix_integrity,
            lifecycle.protected_interaction,
            lifecycle.frozen_v3,
        ]
        .contains(&NotRun)
        {
            return CapabilityStatusV2::BlockedByIncompleteEvidence;
        }
        CapabilityStatusV2::ReadyForReview
    }

    fn root_cause_from_receipt_v2(receipt: &M3MicroAuthoritativeReceiptV2) -> Length32RootCauseV2 {
        root_cause_from_contract_evidence_v2(RootCauseContractEvidenceV2 {
            metric_semantics: receipt.metric_semantics.metric_semantics_status,
            metric_aggregation: receipt.metric_semantics.metric_aggregation_status,
            accuracy_nll_source: receipt.metric_semantics.accuracy_nll_source_status,
            event_alignment: receipt.lifecycle.event_alignment,
            comparator_purity: receipt.lifecycle.comparator_purity,
            suffix_integrity: receipt.lifecycle.suffix_integrity,
            structural_loss: receipt.structural_loss.status,
            protected_interaction: receipt.lifecycle.protected_interaction,
        })
    }

    fn receipt_v2_semantic_bytes(
        receipt: &M3MicroAuthoritativeReceiptV2,
    ) -> Result<Vec<u8>, String> {
        let mut semantic = receipt.clone();
        semantic.receipt_digest.clear();
        serde_json::to_vec(&semantic).map_err(|error| error.to_string())
    }

    fn receipt_v2_computed_digest(
        receipt: &M3MicroAuthoritativeReceiptV2,
    ) -> Result<String, String> {
        let bytes = receipt_v2_semantic_bytes(receipt)?;
        let canonical = std::str::from_utf8(&bytes).map_err(|error| error.to_string())?;
        Ok(stable_hash_string(canonical))
    }

    fn canonical_receipt_v2_bytes(
        receipt: &M3MicroAuthoritativeReceiptV2,
    ) -> Result<Vec<u8>, String> {
        serde_json::to_vec(receipt).map_err(|error| error.to_string())
    }

    fn receipt_v2_groups(
        receipt: &M3MicroAuthoritativeReceiptV2,
    ) -> [&AttributionGroupReceiptV1; 4] {
        [
            &receipt.attribution.g1,
            &receipt.attribution.g2,
            &receipt.attribution.g3,
            &receipt.attribution.g4,
        ]
    }

    fn validate_receipt_v2_self(receipt: &M3MicroAuthoritativeReceiptV2) -> Result<(), String> {
        let expected_capability = derive_capability_status_v2(
            receipt.lifecycle,
            receipt.metric_semantics.metric_aggregation_status,
            receipt.metric_semantics.accuracy_nll_source_status,
            receipt.root_cause,
        );
        if receipt.format_version != R9_RECEIPT_FORMAT_VERSION
            || !receipt.computation.generated_from_fresh_computation
            || receipt
                .computation
                .attribution_executions_in_generator_process
                != 1
            || receipt.computation.task_wide_execution_count_claim
                != ExecutionCountClaimV1::NotClaimed
            || receipt.computation.supersedes_receipt_digest.is_none()
            || receipt.attribution.full_attribution_replay_performed
            || receipt.attribution.profile_count != receipt.semantic_binding.support.profile_count
            || receipt.attribution.support_event_count_per_group
                != receipt
                    .semantic_binding
                    .support
                    .support_event_count_per_group
            || !receipt.semantic_binding.support.full_support_panel_used
            || receipt.gradient.policy_identity
                != receipt.semantic_binding.policy.gradient_policy_identity
            || receipt.metric_semantics.metric_semantics_identity
                != receipt.semantic_binding.policy.metric_semantics_identity
            || receipt.lifecycle.structural_loss != receipt.structural_loss.status
            || receipt.lifecycle.report_integrity != GateExecutionStatusV1::NotRun
            || !structural_loss_evidence_complete_v1(&receipt.structural_loss)
            || root_cause_from_receipt_v2(receipt) != receipt.root_cause
            || expected_capability != receipt.capability_status
            || receipt_v2_groups(receipt).iter().any(|group| {
                group.support_event_count != receipt.attribution.support_event_count_per_group
                    || group.seed_count != receipt.semantic_binding.support.seed_identities.len()
                    || group.sequence_lengths != receipt.semantic_binding.support.sequence_lengths
                    || group.invalidation_positions
                        != receipt.semantic_binding.support.invalidation_positions
                    || group.metrics.iter().any(|metric| {
                        [
                            metric.full_accuracy,
                            metric.comparator_accuracy,
                            metric.accuracy_delta,
                            metric.full_mean_nll,
                            metric.comparator_mean_nll,
                            metric.mean_nll_gain,
                            metric.full_target_margin,
                            metric.comparator_target_margin,
                            metric.target_margin_gain,
                            metric.paired_win_rate,
                        ]
                        .iter()
                        .any(|value| !value.is_finite())
                    })
            })
            || receipt_v2_computed_digest(receipt)? != receipt.receipt_digest
        {
            return Err("invalid authoritative receipt V2".to_string());
        }
        let encoded = canonical_receipt_v2_bytes(receipt)?;
        let decoded: M3MicroAuthoritativeReceiptV2 =
            serde_json::from_slice(&encoded).map_err(|error| error.to_string())?;
        if decoded != *receipt || canonical_receipt_v2_bytes(&decoded)? != encoded {
            return Err("non-canonical receipt V2 roundtrip".to_string());
        }
        Ok(())
    }

    fn receipt_v2_path() -> PathBuf {
        Path::new(env!("CARGO_MANIFEST_DIR")).join(R9_RECEIPT_RELATIVE_PATH)
    }

    fn read_authoritative_receipt_v2() -> Result<M3MicroAuthoritativeReceiptV2, String> {
        let bytes = fs::read(receipt_v2_path()).map_err(|error| error.to_string())?;
        let receipt: M3MicroAuthoritativeReceiptV2 =
            serde_json::from_slice(&bytes).map_err(|error| error.to_string())?;
        validate_receipt_v2_self(&receipt)?;
        if canonical_receipt_v2_bytes(&receipt)? != bytes {
            return Err("receipt V2 file is not canonical JSON".to_string());
        }
        Ok(receipt)
    }

    fn validate_receipt_v2_currentness(
        receipt: &M3MicroAuthoritativeReceiptV2,
    ) -> Result<(), String> {
        validate_receipt_v2_self(receipt)?;
        validate_receipt_v2_currentness_typed_v1(receipt)
            .map_err(|error| format!("stale semantic receipt: {error:?}"))
    }

    fn validate_receipt_v2_currentness_typed_v1(
        receipt: &M3MicroAuthoritativeReceiptV2,
    ) -> Result<(), SemanticCurrentnessErrorV2> {
        let current =
            current_semantic_binding_v2().expect("current capability semantic binding must build");
        validate_semantic_currentness_v2(&receipt.semantic_binding, &current)
    }

    fn build_authoritative_receipt_v2() -> Result<M3MicroAuthoritativeReceiptV2, String> {
        use GateExecutionStatusV1::{NotRun, Passed};

        let semantic_binding = current_semantic_binding_v2()?;
        let provenance = current_generation_provenance_v2()?;
        let superseded_v1 = read_authoritative_receipt_v1()?;
        let attribution = authoritative_attribution_r7();
        let groups = attribution
            .evidence
            .groups
            .each_ref()
            .map(attribution_group_receipt_v1);
        let attribution_status = status_from_bool_v1(
            attribution.execution_count == 1
                && attribution.raw.full_support_panel_verified
                && attribution.evidence.deterministic_inference_checks_passed
                && attribution.evidence.reduced_candidate.matches_production
                && attribution
                    .evidence
                    .groups
                    .iter()
                    .all(|group| group.decision.retained().is_some())
                && attribution.evidence.policy_identity
                    == semantic_binding.policy.attribution_decision_policy_identity
                && attribution.evidence.profile_identity
                    == semantic_binding.policy.profile_policy_identity
                && attribution.evidence.groups.iter().all(|group| {
                    group.support_event_count
                        == semantic_binding.support.support_event_count_per_group
                        && group.seed_count == semantic_binding.support.seed_identities.len()
                        && group.sequence_lengths.iter().copied().collect::<Vec<_>>()
                            == semantic_binding.support.sequence_lengths
                        && group
                            .positions
                            .iter()
                            .map(|position| format!("{position:?}"))
                            .collect::<Vec<_>>()
                            == semantic_binding.support.invalidation_positions
                }),
        );
        let gradient = execute_gradient_receipt_v2();
        let delayed = delayed_recall_evidence_v2();
        let metric_definition = status_from_bool_v1(metric_semantics_passed_v1(delayed));
        let metric_aggregation = status_from_bool_v1(metric_aggregation_passed_v1(delayed));
        let accuracy_nll_source = status_from_bool_v1(accuracy_nll_source_passed_v1(delayed));
        let structural_loss = structural_loss_evidence_v1(delayed);
        let event_alignment = status_from_bool_v1(event_alignment_passed_v1(delayed));
        let comparator_purity = status_from_bool_v1(comparator_purity_passed_v1(delayed));
        let suffix_integrity = status_from_bool_v1(final_suffix_contract_passed_v1());
        let length32_delayed = delayed
            .iter()
            .find(|evidence| evidence.sequence_length == 32)
            .ok_or_else(|| "missing length-32 evidence".to_string())?;
        let comparator = no_state_comparator_evidence_v2(&length32_delayed.comparator_snapshot);
        let length32 = length32_interaction_evidence_v2(delayed);
        let protected_interaction = if attribution_status == Passed
            && gradient.status == Passed
            && [
                metric_definition,
                metric_aggregation,
                accuracy_nll_source,
                structural_loss.status,
                event_alignment,
                comparator_purity,
                suffix_integrity,
            ]
            .iter()
            .all(|status| *status == Passed)
        {
            status_from_bool_v1(protected_interaction_passed_v1())
        } else {
            NotRun
        };
        let root_cause = root_cause_from_contract_evidence_v2(RootCauseContractEvidenceV2 {
            metric_semantics: metric_definition,
            metric_aggregation,
            accuracy_nll_source,
            event_alignment,
            comparator_purity,
            suffix_integrity,
            structural_loss: structural_loss.status,
            protected_interaction,
        });
        let frozen_v3 = if protected_interaction == Passed {
            status_from_bool_v1(frozen_v3_passed_v1())
        } else {
            NotRun
        };
        let lifecycle = M3MicroEvidenceLifecycleV2 {
            initialization_oracle: Passed,
            attribution: attribution_status,
            final_gradient: gradient.status,
            metric_semantics: metric_definition,
            structural_loss: structural_loss.status,
            event_alignment,
            comparator_purity,
            suffix_integrity,
            protected_interaction,
            frozen_v3,
            report_integrity: NotRun,
        };
        let capability_status = derive_capability_status_v2(
            lifecycle,
            metric_aggregation,
            accuracy_nll_source,
            root_cause,
        );
        let reduced_candidate = ReducedCandidateReceiptV1 {
            retained_groups: attribution
                .evidence
                .reduced_candidate
                .retained_groups
                .iter()
                .map(|group| group.report_name().to_string())
                .collect(),
            reverted_groups: attribution
                .evidence
                .reduced_candidate
                .reverted_groups
                .iter()
                .map(|group| group.report_name().to_string())
                .collect(),
            matches_production: attribution.evidence.reduced_candidate.matches_production,
        };
        let mut receipt = M3MicroAuthoritativeReceiptV2 {
            format_version: R9_RECEIPT_FORMAT_VERSION,
            computation: ComputationScopeReceiptV2 {
                generated_from_fresh_computation: true,
                attribution_executions_in_generator_process: attribution.execution_count as u32,
                task_wide_execution_count_claim: ExecutionCountClaimV1::NotClaimed,
                supersedes_receipt_digest: Some(superseded_v1.receipt_digest),
                attribution_duration_milliseconds: attribution.duration_milliseconds,
            },
            semantic_binding,
            provenance,
            attribution: AttributionReceiptV2 {
                profile_count: CoreAttributionProfileV2::ORDERED.len(),
                support_event_count_per_group: attribution.evidence.groups[0].support_event_count,
                g1: groups[0].clone(),
                g2: groups[1].clone(),
                g3: groups[2].clone(),
                g4: groups[3].clone(),
                deterministic_inference_checks_passed: attribution
                    .evidence
                    .deterministic_inference_checks_passed,
                full_attribution_replay_performed: false,
            },
            reduced_candidate,
            gradient,
            comparator,
            metric_semantics: MetricSemanticsReceiptV2 {
                composite_loss_semantics: "CompositeRoleLoss".to_string(),
                direction_nll_semantics: "MeanCategoricalNegativeLogLikelihood".to_string(),
                metric_semantics_identity: metric_semantics_identity_v1(),
                metric_semantics_status: metric_definition,
                metric_aggregation_status: metric_aggregation,
                accuracy_nll_source_status: accuracy_nll_source,
                event_alignment_status: event_alignment,
                suffix_integrity_status: suffix_integrity,
            },
            structural_loss,
            length32,
            root_cause,
            lifecycle,
            capability_status,
            receipt_digest: String::new(),
        };
        receipt.receipt_digest = receipt_v2_computed_digest(&receipt)?;
        validate_receipt_v2_self(&receipt)?;
        Ok(receipt)
    }

    fn persist_authoritative_receipt_v2(
        receipt: &M3MicroAuthoritativeReceiptV2,
    ) -> Result<(), String> {
        validate_receipt_v2_self(receipt)?;
        validate_semantic_currentness_v2(
            &receipt.semantic_binding,
            &current_semantic_binding_v2()?,
        )
        .map_err(|error| format!("cannot persist stale V2 receipt: {error:?}"))?;
        let path = receipt_v2_path();
        let parent = path
            .parent()
            .ok_or_else(|| "receipt V2 parent is missing".to_string())?;
        fs::create_dir_all(parent).map_err(|error| error.to_string())?;
        if path.exists() {
            read_authoritative_receipt_v2()?;
        }
        let temporary = path.with_extension(format!("json.tmp.{}", receipt.receipt_digest));
        let bytes = canonical_receipt_v2_bytes(receipt)?;
        let mut file = OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(&temporary)
            .map_err(|error| error.to_string())?;
        let write_result = file
            .write_all(&bytes)
            .and_then(|_| file.sync_all())
            .map_err(|error| error.to_string());
        drop(file);
        if let Err(error) = write_result {
            let _ = fs::remove_file(&temporary);
            return Err(error);
        }
        let staged_bytes = fs::read(&temporary).map_err(|error| error.to_string())?;
        let staged: M3MicroAuthoritativeReceiptV2 =
            serde_json::from_slice(&staged_bytes).map_err(|error| error.to_string())?;
        if staged != *receipt || canonical_receipt_v2_bytes(&staged)? != staged_bytes {
            let _ = fs::remove_file(&temporary);
            return Err("temporary receipt V2 verification failed".to_string());
        }
        validate_receipt_v2_self(&staged)?;
        validate_semantic_currentness_v2(&staged.semantic_binding, &current_semantic_binding_v2()?)
            .map_err(|error| format!("temporary V2 semantic binding failed: {error:?}"))?;
        fs::rename(&temporary, &path).map_err(|error| error.to_string())?;
        let reopened = read_authoritative_receipt_v2()?;
        validate_receipt_v2_currentness(&reopened)?;
        if reopened != *receipt {
            return Err("persisted receipt V2 verification failed".to_string());
        }
        Ok(())
    }

    #[test]
