    #[test]
    fn m3_micro_r7_receipt_canonical_roundtrip_is_byte_identical() {
        let receipt = receipt_codec_fixture_v1();
        let first = canonical_receipt_bytes_v1(&receipt).unwrap();
        let decoded: M3MicroAuthoritativeAttributionReceiptV1 =
            serde_json::from_slice(&first).unwrap();
        let second = canonical_receipt_bytes_v1(&decoded).unwrap();
        assert_eq!(first, second);
        assert_eq!(receipt, decoded);
    }

    #[test]
    fn m3_micro_r7_receipt_digest_excludes_itself() {
        let receipt = receipt_codec_fixture_v1();
        let expected = receipt_computed_digest_v1(&receipt).unwrap();
        let mut changed_digest_only = receipt.clone();
        changed_digest_only.receipt_digest = "ignored-self-field".to_string();
        assert_eq!(
            receipt_computed_digest_v1(&changed_digest_only).unwrap(),
            expected
        );
        assert_eq!(receipt.receipt_digest, expected);
    }

