    #[derive(Clone, Debug, PartialEq)]
    struct ParsedR7ReportV1 {
        receipt_path: String,
        receipt_format_version: u32,
        receipt_digest: String,
        generated_fresh: bool,
        attribution_execution_count: u32,
        deterministic_inference_checks_passed: bool,
        full_attribution_replay_performed: bool,
        source_binding: SourceBindingV1,
        policy_binding: PolicyBindingV1,
        support_binding: SupportBindingV1,
        attribution_decisions: [String; 4],
        reduced_candidate: ReducedCandidateReceiptV1,
        gradient: GradientExecutionReceiptV2,
        comparator: NoStateComparatorEvidenceV2,
        length32: Length32InteractionEvidenceV2,
        root_cause: Length32RootCauseV2,
        lifecycle: M3MicroEvidenceLifecycleV2,
        final_status: R7FinalStatusV1,
        next_step: String,
    }

    fn report_section_r7(report: &str, section: usize) -> Option<&str> {
        let marker = format!("## {section}.");
        let start = report.find(&marker)?;
        let rest = &report[start + marker.len()..];
        let end = if section == 22 {
            rest.len()
        } else {
            rest.find(&format!("## {}.", section + 1))?
        };
        Some(&rest[..end])
    }

    fn report_value_r7<'a>(report: &'a str, key: &str) -> Option<&'a str> {
        let prefix = format!("- {key}: ");
        report
            .lines()
            .find_map(|line| line.strip_prefix(&prefix))
            .map(|value| value.trim().trim_matches('`'))
    }

    fn required_report_value_r7<'a>(report: &'a str, key: &str) -> Result<&'a str, String> {
        report_value_r7(report, key).ok_or_else(|| format!("missing report field: {key}"))
    }

    fn legacy_checkout_branch_report_value_v1(branch: Option<&str>) -> &str {
        branch.unwrap_or("DETACHED")
    }

    fn parse_legacy_checkout_branch_report_value_v1(value: &str) -> Option<String> {
        (value != "DETACHED").then(|| value.to_string())
    }

    fn format_report_float_v1(value: f32) -> String {
        format!("{value:.8}")
    }

    fn parse_report_float_v1(report: &str, key: &str) -> Result<f32, String> {
        let encoded = required_report_value_r7(report, key)?;
        let value = encoded
            .parse::<f32>()
            .map_err(|_| format!("invalid report float: {key}"))?;
        if !value.is_finite() || format_report_float_v1(value) != encoded {
            return Err(format!("non-canonical report float: {key}"));
        }
        Ok(value)
    }

    fn report_length32_matches_receipt_v1(
        report: Length32InteractionEvidenceV2,
        receipt: Length32InteractionEvidenceV2,
    ) -> bool {
        report.event_support == receipt.event_support
            && report.positive_support == receipt.positive_support
            && report.negative_support == receipt.negative_support
            && report.base_only_correct == receipt.base_only_correct
            && report.no_state_only_correct == receipt.no_state_only_correct
            && report.both_correct == receipt.both_correct
            && report.both_wrong == receipt.both_wrong
            && [
                (report.base_accuracy, receipt.base_accuracy),
                (report.no_state_accuracy, receipt.no_state_accuracy),
                (report.accuracy_gap, receipt.accuracy_gap),
                (report.base_categorical_nll, receipt.base_categorical_nll),
                (
                    report.no_state_categorical_nll,
                    receipt.no_state_categorical_nll,
                ),
                (report.nll_gap, receipt.nll_gap),
                (
                    report.base_mean_true_class_probability,
                    receipt.base_mean_true_class_probability,
                ),
                (
                    report.no_state_mean_true_class_probability,
                    receipt.no_state_mean_true_class_probability,
                ),
                (
                    report.base_target_aligned_margin,
                    receipt.base_target_aligned_margin,
                ),
                (
                    report.no_state_target_aligned_margin,
                    receipt.no_state_target_aligned_margin,
                ),
                (report.paired_nll_win_rate, receipt.paired_nll_win_rate),
                (
                    report.paired_margin_win_rate,
                    receipt.paired_margin_win_rate,
                ),
            ]
            .into_iter()
            .all(|(report, receipt)| {
                format_report_float_v1(report) == format_report_float_v1(receipt)
            })
    }

    fn parse_report_usize_v1(report: &str, key: &str) -> Result<usize, String> {
        required_report_value_r7(report, key)?
            .parse::<usize>()
            .map_err(|_| format!("invalid report integer: {key}"))
    }

    fn parse_report_u32_v1(report: &str, key: &str) -> Result<u32, String> {
        required_report_value_r7(report, key)?
            .parse::<u32>()
            .map_err(|_| format!("invalid report integer: {key}"))
    }

    fn parse_report_bool_v1(report: &str, key: &str) -> Result<bool, String> {
        match required_report_value_r7(report, key)? {
            "true" => Ok(true),
            "false" => Ok(false),
            _ => Err(format!("invalid report boolean: {key}")),
        }
    }

    fn parse_gate_status_v1(value: &str) -> Option<GateExecutionStatusV1> {
        match value {
            "NOT_RUN" => Some(GateExecutionStatusV1::NotRun),
            "PASSED" => Some(GateExecutionStatusV1::Passed),
            "FAILED" => Some(GateExecutionStatusV1::Failed),
            _ => None,
        }
    }

    fn parse_report_gate_v1(report: &str, key: &str) -> Result<GateExecutionStatusV1, String> {
        parse_gate_status_v1(required_report_value_r7(report, key)?)
            .ok_or_else(|| format!("invalid report gate: {key}"))
    }

    fn attribution_decision_from_name_v2(value: &str) -> Option<AttributionDecisionV2> {
        [
            AttributionDecisionV2::RetainRequired,
            AttributionDecisionV2::RetainSupported,
            AttributionDecisionV2::RevertUnsupported,
            AttributionDecisionV2::RevertHarmful,
            AttributionDecisionV2::BlockedIndeterminate,
        ]
        .into_iter()
        .find(|decision| decision.as_str() == value)
    }

    fn root_cause_from_name_v1(value: &str) -> Option<Length32RootCauseV2> {
        [
            Length32RootCauseV2::NoDefect,
            Length32RootCauseV2::MetricDefinitionMismatch,
            Length32RootCauseV2::MetricAggregationDefect,
            Length32RootCauseV2::AccuracyNllSourceMismatch,
            Length32RootCauseV2::EventAlignmentDefect,
            Length32RootCauseV2::NoStateComparatorContamination,
            Length32RootCauseV2::FinalSuffixLeakage,
            Length32RootCauseV2::StructuralLossImplementationDefect,
            Length32RootCauseV2::GenuineLength32ConfidenceDeficit,
            Length32RootCauseV2::Indeterminate,
        ]
        .into_iter()
        .find(|root| root.as_str() == value)
    }

    fn r7_final_status_from_name_v1(value: &str) -> Option<R7FinalStatusV1> {
        [
            R7FinalStatusV1::BlockedByReinforcementAttribution,
            R7FinalStatusV1::BlockedByGradientConformance,
            R7FinalStatusV1::BlockedByMetricSemantics,
            R7FinalStatusV1::BlockedByEventAlignment,
            R7FinalStatusV1::BlockedByNoStateComparator,
            R7FinalStatusV1::BlockedByFinalSuffixLeakage,
            R7FinalStatusV1::BlockedByLength32ConfidenceCapability,
            R7FinalStatusV1::BlockedBySelectiveForgettingV3,
            R7FinalStatusV1::BlockedByReceiptGeneration,
            R7FinalStatusV1::BlockedByReceiptSourceBinding,
            R7FinalStatusV1::BlockedByReceiptPolicyBinding,
            R7FinalStatusV1::BlockedByReceiptSupportBinding,
            R7FinalStatusV1::BlockedByReportIntegrity,
            R7FinalStatusV1::BlockedByIncompleteEvidence,
            R7FinalStatusV1::BlockedByVerificationFailure,
            R7FinalStatusV1::ReadyForReview,
        ]
        .into_iter()
        .find(|status| status.as_str() == value)
    }

    fn parse_csv_strings_v1(value: &str) -> Vec<String> {
        if value == "NONE" {
            Vec::new()
        } else {
            value.split(',').map(str::to_string).collect()
        }
    }

    fn parse_csv_usize_v1(value: &str) -> Result<Vec<usize>, String> {
        value
            .split(',')
            .map(|item| {
                item.parse::<usize>()
                    .map_err(|_| "invalid integer list".to_string())
            })
            .collect()
    }

    fn parse_r7_report_v1(report: &str) -> Result<ParsedR7ReportV1, String> {
        const HEADINGS: [&str; 22] = [
            "## 1. Mode and Git State",
            "## 2. Starting Status",
            "## 3. Progress Ledger",
            "## 4. Circular Evidence Removal",
            "## 5. Authoritative Receipt",
            "## 6. Source Binding",
            "## 7. Policy and Support Binding",
            "## 8. Attribution",
            "## 9. Reduced Candidate",
            "## 10. Gradient Receipt",
            "## 11. Comparator Evidence",
            "## 12. Length-32 Evidence",
            "## 13. Root Cause",
            "## 14. Evidence Lifecycle",
            "## 15. Report Binding",
            "## 16. Verification",
            "## 17. Safety",
            "## 18. What This Proves",
            "## 19. What This Does Not Prove",
            "## 20. Remaining Risks",
            "## 21. Final Status",
            "## 22. Exactly One Next Step",
        ];
        let actual_headings = report
            .lines()
            .filter(|line| line.starts_with("## "))
            .collect::<Vec<_>>();
        if actual_headings != HEADINGS
            || (1..=22).any(|section| report_section_r7(report, section).is_none())
        {
            return Err("R7 report section contract mismatch".to_string());
        }
        let source_binding = SourceBindingV1 {
            repository_branch: parse_legacy_checkout_branch_report_value_v1(
                required_report_value_r7(report, "Repository branch")?,
            ),
            repository_head: required_report_value_r7(report, "Repository HEAD")?.to_string(),
            core_source_digest: required_report_value_r7(report, "Core source digest")?.to_string(),
            capability_source_digest: required_report_value_r7(report, "Capability source digest")?
                .to_string(),
            trend_source_digest: required_report_value_r7(report, "Trend source digest")?
                .to_string(),
            volatility_source_digest: required_report_value_r7(report, "Volatility source digest")?
                .to_string(),
            reversal_source_digest: required_report_value_r7(report, "Reversal source digest")?
                .to_string(),
            combined_source_binding_digest: required_report_value_r7(
                report,
                "Source binding digest",
            )?
            .to_string(),
        };
        let policy_binding = PolicyBindingV1 {
            attribution_decision_policy_identity: required_report_value_r7(
                report,
                "Attribution policy identity",
            )?
            .to_string(),
            profile_policy_identity: required_report_value_r7(report, "Profile policy identity")?
                .to_string(),
            support_policy_identity: required_report_value_r7(report, "Support policy identity")?
                .to_string(),
            gradient_policy_identity: required_report_value_r7(report, "Gradient policy identity")?
                .to_string(),
            interaction_policy_identity: required_report_value_r7(
                report,
                "Interaction policy identity",
            )?
            .to_string(),
            metric_semantics_identity: required_report_value_r7(
                report,
                "Metric semantics identity",
            )?
            .to_string(),
            frozen_v3_policy_identity: required_report_value_r7(
                report,
                "Frozen V3 policy identity",
            )?
            .to_string(),
            combined_policy_binding_digest: required_report_value_r7(
                report,
                "Policy binding digest",
            )?
            .to_string(),
        };
        let support_binding = SupportBindingV1 {
            sequence_lengths: parse_csv_usize_v1(required_report_value_r7(
                report,
                "Sequence lengths",
            )?)?,
            invalidation_positions: parse_csv_strings_v1(required_report_value_r7(
                report,
                "Invalidation positions",
            )?),
            seed_identities: parse_csv_strings_v1(required_report_value_r7(
                report,
                "Seed identities",
            )?),
            development_support: parse_report_usize_v1(report, "Development support")?,
            frozen_support: parse_report_usize_v1(report, "Frozen support")?,
            profile_count: parse_report_usize_v1(report, "Profile count")?,
            support_event_count_per_group: parse_report_usize_v1(
                report,
                "Support events per group",
            )?,
            full_support_panel_used: parse_report_bool_v1(report, "Full support panel used")?,
            support_binding_digest: required_report_value_r7(report, "Support binding digest")?
                .to_string(),
        };
        let attribution_decisions = ["G1", "G2", "G3", "G4"].map(|group| {
            required_report_value_r7(report, &format!("{group} decision")).map(str::to_string)
        });
        let attribution_decisions = [
            attribution_decisions[0].clone()?,
            attribution_decisions[1].clone()?,
            attribution_decisions[2].clone()?,
            attribution_decisions[3].clone()?,
        ];
        if attribution_decisions
            .iter()
            .any(|decision| attribution_decision_from_name_v2(decision).is_none())
        {
            return Err("invalid attribution decision".to_string());
        }
        let gradient = GradientExecutionReceiptV2 {
            status: parse_report_gate_v1(report, "Gradient receipt status")?,
            executed_in_current_lifecycle: parse_report_bool_v1(report, "Gradient executed")?,
            single_step_cases: parse_report_usize_v1(report, "Gradient single-step cases")?,
            multi_step_cases: parse_report_usize_v1(report, "Gradient multi-step cases")?,
            branch_cases: parse_report_usize_v1(report, "Gradient branch cases")?,
            failed_cases: parse_report_usize_v1(report, "Gradient failed cases")?,
            policy_identity: required_report_value_r7(report, "Gradient policy identity")?
                .to_string(),
        };
        if required_report_value_r7(report, "Gradient execution provenance")?
            != "EXECUTED_IN_AUTHORITATIVE_LIFECYCLE"
            || !gradient.executed_in_current_lifecycle
        {
            return Err("invalid gradient execution provenance".to_string());
        }
        let comparator = NoStateComparatorEvidenceV2 {
            total_parameter_paths: parse_report_usize_v1(report, "Total parameter paths")?,
            state_capability_paths: parse_report_usize_v1(report, "State capability paths")?,
            differing_paths: parse_report_usize_v1(report, "Differing paths")?,
            unexpected_paths: parse_report_usize_v1(report, "Unexpected paths")?,
            missing_paths: parse_report_usize_v1(report, "Missing paths")?,
            comparator_pure: parse_report_bool_v1(report, "Comparator pure")?,
        };
        let length32 = Length32InteractionEvidenceV2 {
            event_support: parse_report_usize_v1(report, "Length-32 event support")?,
            positive_support: parse_report_usize_v1(report, "Length-32 positive support")?,
            negative_support: parse_report_usize_v1(report, "Length-32 negative support")?,
            base_accuracy: parse_report_float_v1(report, "Length-32 base accuracy")?,
            no_state_accuracy: parse_report_float_v1(report, "Length-32 no-state accuracy")?,
            accuracy_gap: parse_report_float_v1(report, "Length-32 accuracy gap")?,
            base_categorical_nll: parse_report_float_v1(report, "Length-32 base categorical NLL")?,
            no_state_categorical_nll: parse_report_float_v1(
                report,
                "Length-32 no-state categorical NLL",
            )?,
            nll_gap: parse_report_float_v1(report, "Length-32 NLL gap")?,
            base_mean_true_class_probability: parse_report_float_v1(
                report,
                "Length-32 base true-class probability",
            )?,
            no_state_mean_true_class_probability: parse_report_float_v1(
                report,
                "Length-32 no-state true-class probability",
            )?,
            base_target_aligned_margin: parse_report_float_v1(
                report,
                "Length-32 base target-aligned margin",
            )?,
            no_state_target_aligned_margin: parse_report_float_v1(
                report,
                "Length-32 no-state target-aligned margin",
            )?,
            base_only_correct: parse_report_usize_v1(report, "Length-32 base-only correct")?,
            no_state_only_correct: parse_report_usize_v1(
                report,
                "Length-32 no-state-only correct",
            )?,
            both_correct: parse_report_usize_v1(report, "Length-32 both correct")?,
            both_wrong: parse_report_usize_v1(report, "Length-32 both wrong")?,
            paired_nll_win_rate: parse_report_float_v1(report, "Length-32 paired NLL win rate")?,
            paired_margin_win_rate: parse_report_float_v1(
                report,
                "Length-32 paired margin win rate",
            )?,
        };
        let root_cause = root_cause_from_name_v1(required_report_value_r7(
            report,
            "Root-cause classification",
        )?)
        .ok_or_else(|| "invalid root cause".to_string())?;
        let lifecycle = M3MicroEvidenceLifecycleV2 {
            initialization_oracle: parse_report_gate_v1(report, "Initialization status")?,
            attribution: parse_report_gate_v1(report, "Attribution status")?,
            final_gradient: parse_report_gate_v1(report, "Gradient status")?,
            metric_semantics: parse_report_gate_v1(report, "Metric Semantics status")?,
            structural_loss: GateExecutionStatusV1::NotRun,
            event_alignment: parse_report_gate_v1(report, "Event Alignment status")?,
            comparator_purity: parse_report_gate_v1(report, "Comparator Purity status")?,
            suffix_integrity: parse_report_gate_v1(report, "Suffix Integrity status")?,
            protected_interaction: parse_report_gate_v1(report, "Protected Interaction status")?,
            frozen_v3: parse_report_gate_v1(report, "Frozen V3 status")?,
            report_integrity: parse_report_gate_v1(report, "Report Integrity status")?,
        };
        let final_lines = report_section_r7(report, 21)
            .ok_or_else(|| "missing final status section".to_string())?
            .lines()
            .filter_map(|line| line.trim().strip_prefix("- "))
            .collect::<Vec<_>>();
        if final_lines.len() != 1 {
            return Err("report must contain exactly one final status".to_string());
        }
        let final_status = r7_final_status_from_name_v1(final_lines[0])
            .ok_or_else(|| "invalid final status".to_string())?;
        let next_steps = report_section_r7(report, 22)
            .ok_or_else(|| "missing next-step section".to_string())?
            .lines()
            .filter_map(|line| line.trim().strip_prefix("- "))
            .collect::<Vec<_>>();
        if next_steps.len() != 1 {
            return Err("report must contain exactly one next step".to_string());
        }
        Ok(ParsedR7ReportV1 {
            receipt_path: required_report_value_r7(report, "Receipt path")?.to_string(),
            receipt_format_version: parse_report_u32_v1(report, "Receipt format version")?,
            receipt_digest: required_report_value_r7(report, "Receipt digest")?.to_string(),
            generated_fresh: parse_report_bool_v1(report, "Generated fresh")?,
            attribution_execution_count: parse_report_u32_v1(
                report,
                "Attribution execution count",
            )?,
            deterministic_inference_checks_passed: parse_report_bool_v1(
                report,
                "Deterministic inference checks passed",
            )?,
            full_attribution_replay_performed: parse_report_bool_v1(
                report,
                "Full attribution replay performed",
            )?,
            source_binding,
            policy_binding,
            support_binding,
            attribution_decisions,
            reduced_candidate: ReducedCandidateReceiptV1 {
                retained_groups: parse_csv_strings_v1(required_report_value_r7(
                    report,
                    "Retained groups",
                )?),
                reverted_groups: parse_csv_strings_v1(required_report_value_r7(
                    report,
                    "Reverted groups",
                )?),
                matches_production: parse_report_bool_v1(
                    report,
                    "Reduced candidate matches production",
                )?,
            },
            gradient,
            comparator,
            length32,
            root_cause,
            lifecycle,
            final_status,
            next_step: next_steps[0].to_string(),
        })
    }

    fn expected_next_step_r7(status: R7FinalStatusV1) -> &'static str {
        match status {
            R7FinalStatusV1::BlockedByLength32ConfidenceCapability => {
                "Strengthen only the confirmed G4-only Reduced Candidate's length-32 confidence capability in a separate sprint."
            }
            R7FinalStatusV1::BlockedBySelectiveForgettingV3 => {
                "Strengthen only the confirmed Reduced Candidate's selective-forgetting capability in a separate sprint."
            }
            R7FinalStatusV1::ReadyForReview => {
                "Review the full Sprint 104-R1 diff independently in review-only mode."
            }
            _ => {
                "Correct only the first reported evidence contract blocker, then rerun its unchanged lightweight gate."
            }
        }
    }

    fn validate_r7_report_against_receipt_v1(
        report: &str,
        receipt: &M3MicroAuthoritativeAttributionReceiptV1,
    ) -> Result<(), String> {
        validate_receipt_self_v1(receipt)?;
        if report.contains("previous G")
            || report.contains("previous decision")
            || report.contains("deterministic replay")
            || report.contains("/Users/")
        {
            return Err("report contains prohibited evidence claims".to_string());
        }
        let parsed = parse_r7_report_v1(report)?;
        if parsed.receipt_path != R7_RECEIPT_RELATIVE_PATH
            || parsed.receipt_format_version != receipt.format_version
            || parsed.receipt_digest != receipt.receipt_digest
            || parsed.generated_fresh != receipt.generated_from_fresh_computation
            || parsed.attribution_execution_count != receipt.attribution_execution_count
            || parsed.deterministic_inference_checks_passed
                != receipt.deterministic_inference_checks_passed
            || parsed.full_attribution_replay_performed != receipt.full_attribution_replay_performed
            || parsed.source_binding != receipt.source_binding
            || parsed.policy_binding != receipt.policy_binding
            || parsed.support_binding != receipt.support_binding
        {
            return Err("report receipt binding mismatch".to_string());
        }
        let expected_decisions = receipt_groups_v1(receipt).map(|group| group.decision.clone());
        if parsed.attribution_decisions != expected_decisions
            || parsed.reduced_candidate != receipt.reduced_candidate
            || parsed.gradient != receipt.gradient
            || parsed.comparator != receipt.comparator
            || !report_length32_matches_receipt_v1(parsed.length32, receipt.length32)
            || parsed.root_cause != receipt.root_cause
        {
            return Err("report quantitative evidence mismatch".to_string());
        }
        let mut expected_lifecycle = receipt.gate_lifecycle;
        expected_lifecycle.report_integrity = GateExecutionStatusV1::Passed;
        if parsed.lifecycle != expected_lifecycle {
            return Err("report lifecycle mismatch".to_string());
        }
        let derived = derive_r7_final_status_v1(
            receipt.gate_lifecycle,
            receipt.root_cause,
            GateExecutionStatusV1::Passed,
        );
        if receipt.derived_final_status != derived.as_str()
            || parsed.final_status != derived
            || parsed.next_step != expected_next_step_r7(derived)
        {
            return Err("report final status mismatch".to_string());
        }
        Ok(())
    }

    fn report_gate_name_v1(status: GateExecutionStatusV1) -> &'static str {
        match status {
            GateExecutionStatusV1::NotRun => "NOT_RUN",
            GateExecutionStatusV1::Passed => "PASSED",
            GateExecutionStatusV1::Failed => "FAILED",
        }
    }

    fn report_csv_v1(values: &[String]) -> String {
        if values.is_empty() {
            "NONE".to_string()
        } else {
            values.join(",")
        }
    }

