    #[test]
    fn m3_micro_r7_report_fixture_matches_receipt_contract() {
        let receipt = receipt_codec_fixture_v1();
        let report = render_r7_contract_fixture_v1(&receipt);
        validate_r7_report_against_receipt_v1(&report, &receipt).unwrap();
    }

    fn mutate_report_value_r7(report: &str, key: &str, replacement: &str) -> String {
        let current = required_report_value_r7(report, key).unwrap();
        let original_line = format!("- {key}: {current}");
        let replacement_line = format!("- {key}: {replacement}");
        assert_eq!(report.matches(&original_line).count(), 1);
        report.replacen(&original_line, &replacement_line, 1)
    }

    fn read_functional_report_v1() -> String {
        fs::read_to_string(
            Path::new(env!("CARGO_MANIFEST_DIR"))
                .join("docs/SPRINT104_R1_M3_MICRO_FUNCTIONAL_CONFORMANCE_REPORT.md"),
        )
        .unwrap()
    }

    fn authoritative_report_and_receipt_v1() -> (String, M3MicroAuthoritativeAttributionReceiptV1) {
        (
            read_functional_report_v1(),
            read_authoritative_receipt_v1().unwrap(),
        )
    }

