    #[test]
    #[ignore = "superseded by R10 dual-receipt report contract"]
    fn m3_micro_r9_report_rejects_stale_fields_after_valid_original() {
        let (report, receipt) = authoritative_report_and_receipt_v2();
        let report = report.as_str();
        assert_r9_value_mutation(
            report,
            &receipt,
            "Receipt V2 digest",
            "stale-receipt",
            ReportBindingErrorKindV2::Receipt,
        );
        assert_r9_value_mutation(
            report,
            &receipt,
            "Semantic source binding digest",
            "stale-source",
            ReportBindingErrorKindV2::SemanticSource,
        );
        assert_r9_value_mutation(
            report,
            &receipt,
            "Policy binding digest",
            "stale-policy",
            ReportBindingErrorKindV2::Policy,
        );
        assert_r9_value_mutation(
            report,
            &receipt,
            "Support binding digest",
            "stale-support",
            ReportBindingErrorKindV2::Support,
        );
        for (key, expected) in [
            ("G1 decision", receipt.attribution.g1.decision.as_str()),
            ("G4 decision", receipt.attribution.g4.decision.as_str()),
        ] {
            let replacement = if expected == AttributionDecisionV2::RetainSupported.as_str() {
                AttributionDecisionV2::RevertHarmful.as_str()
            } else {
                AttributionDecisionV2::RetainSupported.as_str()
            };
            assert_r9_value_mutation(
                report,
                &receipt,
                key,
                replacement,
                ReportBindingErrorKindV2::Attribution,
            );
        }
        assert_r9_value_mutation(
            report,
            &receipt,
            "Retained groups",
            "NONE",
            ReportBindingErrorKindV2::ReducedCandidate,
        );
        assert_r9_value_mutation(
            report,
            &receipt,
            "Gradient execution scope",
            "NOT_EXECUTED",
            ReportBindingErrorKindV2::Gradient,
        );
        assert_r9_value_mutation(
            report,
            &receipt,
            "Gradient policy identity",
            "stale-gradient-policy",
            ReportBindingErrorKindV2::Policy,
        );
        assert_r9_value_mutation(
            report,
            &receipt,
            "Gradient single-step cases",
            &(receipt.gradient.single_step_cases + 1).to_string(),
            ReportBindingErrorKindV2::Gradient,
        );
        assert_r9_value_mutation(
            report,
            &receipt,
            "State capability paths",
            &(receipt.comparator.state_capability_paths + 1).to_string(),
            ReportBindingErrorKindV2::Comparator,
        );
        assert_r9_value_mutation(
            report,
            &receipt,
            "Differing paths",
            &(receipt.comparator.differing_paths + 1).to_string(),
            ReportBindingErrorKindV2::Comparator,
        );
        for (key, value) in [
            (
                "Length-32 base categorical NLL",
                receipt.length32.base_categorical_nll,
            ),
            (
                "Length-32 no-state categorical NLL",
                receipt.length32.no_state_categorical_nll,
            ),
            ("Length-32 NLL gap", receipt.length32.nll_gap),
            (
                "Length-32 base target-aligned margin",
                receipt.length32.base_target_aligned_margin,
            ),
        ] {
            assert_r9_value_mutation(
                report,
                &receipt,
                key,
                &format_report_float_v1(value + 0.125),
                ReportBindingErrorKindV2::Length32,
            );
        }
        assert_r9_value_mutation(
            report,
            &receipt,
            "Structural Loss status",
            "FAILED",
            ReportBindingErrorKindV2::StructuralLoss,
        );
        assert_r9_value_mutation(
            report,
            &receipt,
            "Structural Loss event count",
            &(receipt.structural_loss.event_count + 1).to_string(),
            ReportBindingErrorKindV2::StructuralLoss,
        );
        assert_r9_value_mutation(
            report,
            &receipt,
            "Structural Loss failed-event count",
            &(receipt.structural_loss.failed_event_count + 1).to_string(),
            ReportBindingErrorKindV2::StructuralLoss,
        );
        let root_replacement = if receipt.root_cause == Length32RootCauseV2::NoDefect {
            Length32RootCauseV2::Indeterminate
        } else {
            Length32RootCauseV2::NoDefect
        };
        assert_r9_value_mutation(
            report,
            &receipt,
            "Root-cause classification",
            root_replacement.as_str(),
            ReportBindingErrorKindV2::RootCause,
        );
        let v3_replacement = if receipt.lifecycle.frozen_v3 == GateExecutionStatusV1::NotRun {
            "FAILED"
        } else {
            "NOT_RUN"
        };
        assert_r9_value_mutation(
            report,
            &receipt,
            "Frozen V3 status",
            v3_replacement,
            ReportBindingErrorKindV2::Lifecycle,
        );
        let capability_replacement =
            if receipt.capability_status == CapabilityStatusV2::ReadyForReview {
                CapabilityStatusV2::BlockedByIncompleteEvidence
            } else {
                CapabilityStatusV2::ReadyForReview
            };
        assert_r9_value_mutation(
            report,
            &receipt,
            "Capability status",
            capability_replacement.as_str(),
            ReportBindingErrorKindV2::CapabilityStatus,
        );
        assert_valid_original_then_reject_mutation_v3(
            report,
            &receipt,
            |report| {
                let current = expected_next_step_r9(derive_r9_overall_status_v2(
                    true,
                    GateExecutionStatusV1::Passed,
                    receipt.capability_status,
                ));
                report.replacen(
                    &format!("- {current}"),
                    "- Correct a different evidence contract.",
                    1,
                )
            },
            ReportBindingErrorKindV2::NextStep,
        );
    }

