    fn delayed_recall_sequence_v2(
        width: usize,
        length: usize,
        positive: bool,
        nuisance_variant: usize,
    ) -> Vec<Vec<f32>> {
        assert!(length >= 8 && width >= 8);
        let mut sequence = vec![vec![0.0; width]; length];
        let sign = if positive { 1.0 } else { -1.0 };
        sequence[0] = row(width, sign, -0.5 * sign);
        for (index, input) in sequence.iter_mut().enumerate().take(length - 3).skip(1) {
            let phase = index as f32 * 0.31 + nuisance_variant as f32 * 0.17;
            input[2] = phase.sin() * 0.04;
            input[3] = phase.cos() * 0.04;
            input[4] = ((index + nuisance_variant) % 3) as f32 * 0.01 - 0.01;
        }
        sequence
    }

    fn delayed_recall_examples_v2(
        width: usize,
        length: usize,
        frozen: bool,
    ) -> Vec<EvidenceExampleV2> {
        let variants = if frozen { [101, 113] } else { [11, 23] };
        let order = if frozen {
            [(false, 0), (true, 1), (true, 0), (false, 1)]
        } else {
            [(true, 0), (false, 1), (false, 0), (true, 1)]
        };
        order
            .into_iter()
            .map(|(positive, variant_index)| EvidenceExampleV2 {
                sequence: delayed_recall_sequence_v2(
                    width,
                    length,
                    positive,
                    variants[variant_index],
                ),
                target: classification_target_v2(positive),
                positive,
            })
            .collect()
    }

    fn average_loss_and_gradients_v2(
        model: &M3MicroModel,
        examples: &[EvidenceExampleV2],
    ) -> Result<(f32, Vec<f32>), M3MicroError> {
        if examples.is_empty() {
            return Err(M3MicroError::InvalidShape);
        }
        let mut mean_loss = 0.0;
        let mut mean_gradients = vec![0.0; model.parameter_count()];
        for example in examples {
            let (loss, gradients) = model_loss_and_gradients(
                model,
                AgentId::TrendContinuation,
                &example.sequence,
                &example.target,
            )?;
            mean_loss += loss / examples.len() as f32;
            for (mean, gradient) in mean_gradients.iter_mut().zip(gradients) {
                *mean += gradient / examples.len() as f32;
            }
        }
        Ok((mean_loss, mean_gradients))
    }

    fn average_loss_v2(
        model: &M3MicroModel,
        examples: &[EvidenceExampleV2],
    ) -> Result<f32, M3MicroError> {
        Ok(average_loss_and_gradients_v2(model, examples)?.0)
    }

    fn ablation_receipt_v2(model: &M3MicroModel, ablation: M3MicroAblationV1) -> String {
        stable_hash_string(&format!(
            "m3-micro-ablation-receipt-v2:{ablation:?}:{}:{}",
            model.parameter_count(),
            model.parameter_digest()
        ))
    }

    fn train_balanced_model_v2(
        initial_model: &M3MicroModel,
        development: &[EvidenceExampleV2],
        fixed_training_budget: usize,
        ablation: Option<M3MicroAblationV1>,
    ) -> Result<TrainedModelEvidenceV2, M3MicroError> {
        let mut model = match ablation {
            Some(ablation) => initial_model.with_ablation(ablation)?,
            None => initial_model.clone(),
        };
        let initial_parameter_digest = model.parameter_digest();
        let ablation_receipt = ablation.map(|ablation| ablation_receipt_v2(&model, ablation));
        let mut optimizer_config = M3MicroOptimizerConfig::default();
        optimizer_config.learning_rate = V2_EVIDENCE_LEARNING_RATE;
        let mut optimizer = M3MicroOptimizerState::new(model.parameter_count(), optimizer_config)?;
        let mut development_loss_vector = Vec::with_capacity(fixed_training_budget);
        for _ in 0..fixed_training_budget {
            let (loss, gradients) = average_loss_and_gradients_v2(&model, development)?;
            development_loss_vector.push(loss);
            optimizer.apply(&mut model, &gradients)?;
            if let Some(ablation) = ablation {
                model = model.with_ablation(ablation)?;
            }
        }
        Ok(TrainedModelEvidenceV2 {
            final_parameter_digest: model.parameter_digest(),
            optimizer_digest: optimizer.digest(),
            model,
            initial_parameter_digest,
            development_loss_vector,
            ablation_receipt,
        })
    }

    fn classification_score_v2(raw_output: &[f32]) -> Result<f32, M3MicroError> {
        let prediction = M3MicroPrediction::from_raw(AgentId::TrendContinuation, raw_output)?;
        let distribution = prediction
            .direction_distribution
            .ok_or(M3MicroError::InvalidShape)?;
        Ok(distribution[2] - distribution[0])
    }

    fn evaluate_classification_v2(
        model: &M3MicroModel,
        examples: &[EvidenceExampleV2],
    ) -> Result<ClassificationMetricsV2, M3MicroError> {
        if examples.is_empty() {
            return Err(M3MicroError::InvalidShape);
        }
        let mut composite_role_loss = 0.0;
        let mut positive_predictions = Vec::new();
        let mut negative_predictions = Vec::new();
        let mut predictions = Vec::with_capacity(examples.len());
        let mut state_digests = Vec::with_capacity(examples.len());
        let mut event_audits = Vec::with_capacity(examples.len());
        let mut final_state_l2_norms = Vec::with_capacity(examples.len());
        let mut final_state_mean_abs = Vec::with_capacity(examples.len());
        let mut max_final_state_abs = 0.0f32;
        let mut final_states_finite = true;
        for example in examples {
            let (raw_output, state, _) =
                model.forward_from_zero_with_work_counters(&example.sequence)?;
            composite_role_loss +=
                loss_and_output_gradient(AgentId::TrendContinuation, &raw_output, &example.target)?
                    .0
                    / examples.len() as f32;
            let prediction = M3MicroPrediction::from_raw(AgentId::TrendContinuation, &raw_output)?;
            let distribution = prediction
                .direction_distribution
                .ok_or(M3MicroError::InvalidShape)?;
            let score = distribution[2] - distribution[0];
            let probability_of_true_class = if example.positive {
                distribution[2]
            } else {
                distribution[0]
            };
            let correct = (score > 0.0) == example.positive;
            let target_aligned_margin = if example.positive { score } else { -score };
            if example.positive {
                positive_predictions.push(score);
            } else {
                negative_predictions.push(score);
            }
            predictions.push(score);
            state_digests.push(state.digest());
            let mut state_l2_sum = 0.0f32;
            let mut state_abs_sum = 0.0f32;
            let mut state_value_count = 0usize;
            for value in state
                .blocks
                .iter()
                .flat_map(|block| block.values.iter().chain(&block.previous_u))
            {
                final_states_finite &= value.is_finite();
                state_l2_sum += value * value;
                let absolute = value.abs();
                state_abs_sum += absolute;
                max_final_state_abs = max_final_state_abs.max(absolute);
                state_value_count += 1;
            }
            if state_value_count == 0 {
                return Err(M3MicroError::InvalidShape);
            }
            final_states_finite &= state.validate(&model.config).is_ok();
            final_state_l2_norms.push(state_l2_sum.sqrt());
            final_state_mean_abs.push(state_abs_sum / state_value_count as f32);
            event_audits.push(DelayedMemoryEventAuditV1 {
                event_identity: stable_hash_string(&format!(
                    "m3-delayed-memory-event-v1:{}:{}:{:?}:{:?}",
                    example.sequence.len(),
                    example.positive,
                    example.sequence,
                    example.target,
                )),
                sequence_length: example.sequence.len(),
                class_identity: if example.positive {
                    "positive".to_string()
                } else {
                    "negative".to_string()
                },
                target: if example.positive { 1.0 } else { 0.0 },
                raw_output,
                decision_value: score,
                probability_of_positive: distribution[2],
                probability_of_true_class,
                predicted_class: if score > 0.0 {
                    "positive".to_string()
                } else {
                    "negative".to_string()
                },
                correct,
                event_nll: -probability_of_true_class
                    .clamp(PROBABILITY_EPSILON, 1.0)
                    .ln(),
                target_aligned_margin,
            });
        }
        if positive_predictions.is_empty() || negative_predictions.is_empty() {
            return Err(M3MicroError::InvalidShape);
        }
        let positive_mean_prediction =
            positive_predictions.iter().sum::<f32>() / positive_predictions.len() as f32;
        let negative_mean_prediction =
            negative_predictions.iter().sum::<f32>() / negative_predictions.len() as f32;
        let mean_direction_nll = event_audits
            .iter()
            .map(|event| event.event_nll)
            .sum::<f32>()
            / event_audits.len() as f32;
        let mut direction_nll = event_audits
            .iter()
            .map(|event| event.event_nll)
            .collect::<Vec<_>>();
        direction_nll.sort_by(f32::total_cmp);
        let median_direction_nll = if direction_nll.len() % 2 == 0 {
            (direction_nll[direction_nll.len() / 2 - 1] + direction_nll[direction_nll.len() / 2])
                * 0.5
        } else {
            direction_nll[direction_nll.len() / 2]
        };
        Ok(ClassificationMetricsV2 {
            loss_semantics: ClassificationLossSemanticsV1::CompositeRoleLoss,
            mean_composite_role_loss: composite_role_loss,
            mean_direction_nll,
            median_direction_nll,
            mean_true_class_probability: event_audits
                .iter()
                .map(|event| event.probability_of_true_class)
                .sum::<f32>()
                / event_audits.len() as f32,
            mean_target_aligned_margin: event_audits
                .iter()
                .map(|event| event.target_aligned_margin)
                .sum::<f32>()
                / event_audits.len() as f32,
            accuracy: event_audits.iter().filter(|event| event.correct).count() as f32
                / event_audits.len() as f32,
            positive_mean_prediction,
            negative_mean_prediction,
            paired_prediction_separation: positive_mean_prediction - negative_mean_prediction,
            predictions,
            state_digests,
            mean_final_state_l2_norm: final_state_l2_norms.iter().sum::<f32>()
                / final_state_l2_norms.len() as f32,
            mean_final_state_abs: final_state_mean_abs.iter().sum::<f32>()
                / final_state_mean_abs.len() as f32,
            max_final_state_abs,
            final_states_finite,
            event_audits,
        })
    }

    fn carried_reset_evidence_v2(
        model: &M3MicroModel,
        width: usize,
        length: usize,
    ) -> Result<(f32, f32, f32, [String; 2], [String; 2]), M3MicroError> {
        let positive = delayed_recall_sequence_v2(width, length, true, 101);
        let negative = delayed_recall_sequence_v2(width, length, false, 101);
        let suffix_start = length - 3;
        let mut carried_scores = Vec::new();
        let mut reset_scores = Vec::new();
        let mut carried_digests = Vec::new();
        let mut reset_digests = Vec::new();
        let mut carried_states = Vec::new();
        for sequence in [&positive, &negative] {
            let (carried_output, carried_state, _) =
                model.forward_from_zero_with_work_counters(sequence)?;
            carried_scores.push(classification_score_v2(&carried_output)?);
            carried_digests.push(carried_state.digest());
            carried_states.push(carried_state);

            let mut reset_state = M3MicroState::zero(&model.config)?;
            model.forward(&sequence[..suffix_start], &mut reset_state)?;
            reset_state = M3MicroState::zero(&model.config)?;
            let reset_output = model.forward(&sequence[suffix_start..], &mut reset_state)?;
            reset_scores.push(classification_score_v2(&reset_output)?);
            reset_digests.push(reset_state.digest());
        }
        let carried_state_l1_separation = carried_states[0]
            .blocks
            .iter()
            .zip(&carried_states[1].blocks)
            .flat_map(|(left, right)| {
                left.values
                    .iter()
                    .chain(&left.previous_u)
                    .zip(right.values.iter().chain(&right.previous_u))
            })
            .map(|(left, right)| (left - right).abs())
            .sum();
        Ok((
            (carried_scores[0] - carried_scores[1]).abs(),
            (reset_scores[0] - reset_scores[1]).abs(),
            carried_state_l1_separation,
            [carried_digests.remove(0), carried_digests.remove(0)],
            [reset_digests.remove(0), reset_digests.remove(0)],
        ))
    }

    fn no_state_capability_parameter_indices_v1(
        config: &M3MicroConfig,
    ) -> Result<BTreeSet<usize>, M3MicroError> {
        let layout = M3MicroLayout::new(config)?;
        let mut indices = BTreeSet::new();
        for block in &layout.blocks {
            indices.extend(block.prev_scale.clone());
            indices.extend(block.curr_scale.clone());
            indices.extend(block.readout_scale.clone());
        }
        Ok(indices)
    }

