    #[test]
    fn m3_micro_delayed_memory_final_suffix_has_no_class_leakage() {
        let width = M3MicroConfig::for_agent(AgentId::TrendContinuation, 8).input_dim;
        for length in delayed_recall_evidence_policy_v2().sequence_lengths {
            for frozen in [false, true] {
                let examples = delayed_recall_examples_v2(width, length, frozen);
                let positive = examples
                    .iter()
                    .filter(|example| example.positive)
                    .collect::<Vec<_>>();
                let negative = examples
                    .iter()
                    .filter(|example| !example.positive)
                    .collect::<Vec<_>>();
                assert_eq!(positive.len(), negative.len());
                assert!(
                    examples.iter().all(|example| example.sequence[length - 3..]
                        == examples[0].sequence[length - 3..])
                );
                assert!(positive.iter().all(|positive| {
                    negative
                        .iter()
                        .any(|negative| positive.sequence[1..] == negative.sequence[1..])
                }));
                assert!(negative.iter().all(|negative| {
                    positive
                        .iter()
                        .any(|positive| positive.sequence[1..] == negative.sequence[1..])
                }));
                assert_eq!(
                    examples.iter().filter(|example| example.positive).count(),
                    examples.iter().filter(|example| !example.positive).count()
                );
            }
            let development = delayed_recall_examples_v2(width, length, false);
            let frozen = delayed_recall_examples_v2(width, length, true);
            assert_ne!(
                development
                    .iter()
                    .map(|example| example.positive)
                    .collect::<Vec<_>>(),
                frozen
                    .iter()
                    .map(|example| example.positive)
                    .collect::<Vec<_>>()
            );
        }
    }

    #[test]
    #[ignore = "explicit capability evidence"]
    fn m3_micro_length32_reports_per_class_and_paired_metrics() {
        let evidence = delayed_evidence_for_length_v2(32);
        let base_positive =
            delayed_memory_class_metrics_v1(&evidence.base_event_audits, "positive");
        let base_negative =
            delayed_memory_class_metrics_v1(&evidence.base_event_audits, "negative");
        let no_state_positive =
            delayed_memory_class_metrics_v1(&evidence.no_state_event_audits, "positive");
        let no_state_negative =
            delayed_memory_class_metrics_v1(&evidence.no_state_event_audits, "negative");
        let paired = delayed_memory_paired_metrics_v1(
            &evidence.base_event_audits,
            &evidence.no_state_event_audits,
        );
        assert_eq!(base_positive.support, 2);
        assert_eq!(base_negative.support, 2);
        assert_eq!(no_state_positive.support, 2);
        assert_eq!(no_state_negative.support, 2);
        assert_eq!(
            paired.base_only_correct
                + paired.no_state_only_correct
                + paired.both_correct
                + paired.both_wrong,
            evidence.base_event_audits.len()
        );
        println!(
            "SPRINT104_R5_LENGTH32 base_accuracy={} no_state_accuracy={} accuracy_gap={} base_direction_nll={} no_state_direction_nll={} direction_nll_gap={} base_median_nll={} no_state_median_nll={} base_true_probability={} no_state_true_probability={} base_margin={} no_state_margin={} base_positive={base_positive:?} base_negative={base_negative:?} no_state_positive={no_state_positive:?} no_state_negative={no_state_negative:?} paired={paired:?}",
            evidence.frozen_accuracy,
            evidence.no_state_accuracy,
            evidence.base_vs_no_state_accuracy_gap,
            evidence.base_mean_direction_nll,
            evidence.no_state_mean_direction_nll,
            evidence.base_vs_no_state_direction_nll_gap,
            evidence.base_median_direction_nll,
            evidence.no_state_median_direction_nll,
            evidence.base_mean_true_class_probability,
            evidence.no_state_mean_true_class_probability,
            evidence.base_mean_target_aligned_margin,
            evidence.no_state_mean_target_aligned_margin,
        );
    }

    #[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
    enum ForgettingCaseV2 {
        Preserve,
        Noise,
        Invalidation,
    }

    impl ForgettingCaseV2 {
        const ORDERED: [Self; 3] = [Self::Preserve, Self::Noise, Self::Invalidation];
    }

    #[derive(Clone, Debug, PartialEq)]
    struct StateTransitionEvidenceV2 {
        retention_before_event: f32,
        retention_at_event: f32,
        state_digest_before_event: String,
        state_digest_after_event: String,
        target_aligned_prediction_before_event: f32,
        target_aligned_prediction_after_sequence: f32,
        old_target_preference_before_event: f32,
        old_target_preference_after_sequence: f32,
    }

    #[derive(Clone, Debug, PartialEq)]
    struct ForgettingCaseEvidenceV2 {
        case: ForgettingCaseV2,
        initial_frozen_loss: f32,
        base_frozen: ClassificationMetricsV2,
        no_forgetting_frozen: ClassificationMetricsV2,
        paired_loss_gap: f32,
        paired_accuracy_gap: f32,
        transition: StateTransitionEvidenceV2,
    }

    #[derive(Clone, Debug, PartialEq)]
    struct SelectiveForgettingEvidenceV2 {
        initial_parameter_digest: String,
        final_parameter_digest: String,
        optimizer_digest: String,
        prediction_vector: Vec<f32>,
        state_digests: Vec<String>,
        development_loss_vector: Vec<f32>,
        no_forgetting_ablation_receipt: String,
        cases: Vec<ForgettingCaseEvidenceV2>,
    }

    fn forgetting_sequence_v2(
        width: usize,
        case: ForgettingCaseV2,
        positive_target: bool,
        nuisance_variant: usize,
    ) -> Vec<Vec<f32>> {
        let policy = selective_forgetting_evidence_policy_v2();
        let invalidation_index = match policy.invalidation_index_policy {
            InvalidationIndexPolicyV2::Fixed(index) => index,
        };
        assert!(width >= 8 && invalidation_index + 2 < policy.sequence_length);
        let mut sequence = vec![vec![0.0; width]; policy.sequence_length];
        let target_sign = if positive_target { 1.0 } else { -1.0 };
        let initial_sign = if case == ForgettingCaseV2::Invalidation {
            if nuisance_variant % 5 < 2 { 1.0 } else { -1.0 }
        } else {
            target_sign
        };
        let initial_scale = if case == ForgettingCaseV2::Invalidation {
            2.0
        } else {
            1.0
        };
        sequence[0] = row(
            width,
            initial_sign * initial_scale,
            -0.5 * initial_sign * initial_scale,
        );
        for (index, input) in sequence
            .iter_mut()
            .enumerate()
            .take(policy.sequence_length - 2)
            .skip(1)
        {
            let phase = index as f32 * 0.23 + nuisance_variant as f32 * 0.11;
            input[4] = phase.sin() * 0.025;
            input[5] = phase.cos() * 0.025;
        }
        if case == ForgettingCaseV2::Noise {
            let noise_sign = if nuisance_variant % 2 == 0 { 1.0 } else { -1.0 };
            sequence[6] = row(width, 6.0 * noise_sign, -3.0 * noise_sign);
            sequence[6][6] = 2.0;
        }
        if case == ForgettingCaseV2::Invalidation {
            for input in sequence.iter_mut().take(3) {
                *input = row(
                    width,
                    initial_sign * initial_scale,
                    -0.5 * initial_sign * initial_scale,
                );
            }
            for input in sequence.iter_mut().skip(invalidation_index).take(3) {
                *input = row(width, 2.0 * target_sign, -target_sign);
            }
            sequence[invalidation_index][2] = 4.0;
            sequence[invalidation_index][3] = -4.0;
        }
        sequence
    }

    fn forgetting_examples_v2(
        width: usize,
        case: ForgettingCaseV2,
        frozen: bool,
    ) -> Vec<EvidenceExampleV2> {
        let variants = if frozen { [131, 149] } else { [31, 47] };
        let order = if frozen {
            [(false, 0), (true, 1), (true, 0), (false, 1)]
        } else {
            [(true, 0), (false, 1), (false, 0), (true, 1)]
        };
        order
            .into_iter()
            .map(|(positive, variant_index)| EvidenceExampleV2 {
                sequence: forgetting_sequence_v2(width, case, positive, variants[variant_index]),
                target: classification_target_v2(positive),
                positive,
            })
            .collect()
    }

    fn state_transition_evidence_v2(
        model: &M3MicroModel,
        example: &EvidenceExampleV2,
        case: ForgettingCaseV2,
    ) -> Result<StateTransitionEvidenceV2, M3MicroError> {
        let policy = selective_forgetting_evidence_policy_v2();
        let event_index = match case {
            ForgettingCaseV2::Preserve => policy.sequence_length / 2,
            ForgettingCaseV2::Noise => 6,
            ForgettingCaseV2::Invalidation => match policy.invalidation_index_policy {
                InvalidationIndexPolicyV2::Fixed(index) => index,
            },
        };
        let mut state = M3MicroState::zero(&model.config)?;
        let before_output = model.forward(&example.sequence[..event_index], &mut state)?;
        let neutral = vec![0.0; model.config.input_dim];
        let before_probe = model.capability_probe_step(&neutral, &state)?;
        let event_probe = model.capability_probe_step(&example.sequence[event_index], &state)?;
        let state_digest_before_event = state.digest();
        model.stream_step(&example.sequence[event_index], &mut state)?;
        let state_digest_after_event = state.digest();
        let final_output = model.forward(&example.sequence[event_index + 1..], &mut state)?;
        let before_score = classification_score_v2(&before_output)?;
        let final_score = classification_score_v2(&final_output)?;
        let target_sign = if example.positive { 1.0 } else { -1.0 };
        let old_target_sign = if case == ForgettingCaseV2::Invalidation {
            example.sequence[0][0].signum()
        } else {
            target_sign
        };
        Ok(StateTransitionEvidenceV2 {
            retention_before_event: before_probe.mean_retention,
            retention_at_event: event_probe.mean_retention,
            state_digest_before_event,
            state_digest_after_event,
            target_aligned_prediction_before_event: target_sign * before_score,
            target_aligned_prediction_after_sequence: target_sign * final_score,
            old_target_preference_before_event: old_target_sign * before_score,
            old_target_preference_after_sequence: old_target_sign * final_score,
        })
    }

    fn run_selective_forgetting_v2() -> Result<SelectiveForgettingEvidenceV2, M3MicroError> {
        let policy = selective_forgetting_evidence_policy_v2();
        let initial_model = M3MicroRoster::new(V2_EVIDENCE_SEED)?
            .agent(AgentId::TrendContinuation)
            .model
            .clone();
        let width = initial_model.config.input_dim;
        let mut cases = Vec::with_capacity(ForgettingCaseV2::ORDERED.len());
        let mut prediction_vector = Vec::new();
        let mut state_digests = Vec::new();
        let mut final_parameter_digests = Vec::new();
        let mut optimizer_digests = Vec::new();
        let mut ablation_receipts = Vec::new();
        let mut development_loss_vector = vec![0.0; policy.fixed_training_budget];
        for case in ForgettingCaseV2::ORDERED {
            let development = forgetting_examples_v2(width, case, false);
            let frozen = forgetting_examples_v2(width, case, true);
            let base = train_balanced_model_v2(
                &initial_model,
                &development,
                policy.fixed_training_budget,
                None,
            )?;
            let no_forgetting = train_balanced_model_v2(
                &initial_model,
                &development,
                policy.fixed_training_budget,
                Some(M3MicroAblationV1::NoSelectiveForgetting),
            )?;
            let initial_frozen_loss =
                evaluate_classification_v2(&initial_model, &frozen)?.mean_composite_role_loss;
            let base_frozen = evaluate_classification_v2(&base.model, &frozen)?;
            let no_forgetting_frozen = evaluate_classification_v2(&no_forgetting.model, &frozen)?;
            for (mean, loss) in development_loss_vector
                .iter_mut()
                .zip(&base.development_loss_vector)
            {
                *mean += loss / ForgettingCaseV2::ORDERED.len() as f32;
            }
            final_parameter_digests.push(base.final_parameter_digest.clone());
            optimizer_digests.push(base.optimizer_digest.clone());
            ablation_receipts.push(no_forgetting.ablation_receipt.clone().unwrap());
            prediction_vector.extend(base_frozen.predictions.iter().copied());
            state_digests.extend(base_frozen.state_digests.iter().cloned());
            cases.push(ForgettingCaseEvidenceV2 {
                case,
                initial_frozen_loss,
                paired_loss_gap: no_forgetting_frozen.mean_composite_role_loss
                    - base_frozen.mean_composite_role_loss,
                paired_accuracy_gap: base_frozen.accuracy - no_forgetting_frozen.accuracy,
                transition: state_transition_evidence_v2(&base.model, &frozen[1], case)?,
                base_frozen,
                no_forgetting_frozen,
            });
        }
        Ok(SelectiveForgettingEvidenceV2 {
            initial_parameter_digest: initial_model.parameter_digest(),
            final_parameter_digest: stable_hash_string(&format!(
                "m3-micro-selective-final-v2:{final_parameter_digests:?}"
            )),
            optimizer_digest: stable_hash_string(&format!(
                "m3-micro-selective-optimizer-v2:{optimizer_digests:?}"
            )),
            prediction_vector,
            state_digests,
            development_loss_vector,
            no_forgetting_ablation_receipt: stable_hash_string(&format!(
                "m3-micro-selective-ablation-v2:{ablation_receipts:?}"
            )),
            cases,
        })
    }

    fn selective_forgetting_evidence_v2() -> &'static SelectiveForgettingEvidenceV2 {
        static EVIDENCE: OnceLock<SelectiveForgettingEvidenceV2> = OnceLock::new();
        EVIDENCE.get_or_init(|| {
            let first = run_selective_forgetting_v2().unwrap();
            let second = run_selective_forgetting_v2().unwrap();
            assert_eq!(first, second);
            first
        })
    }

    fn no_forgetting_changes_only_retention_v2() -> Result<bool, M3MicroError> {
        let base = M3MicroRoster::new(V2_EVIDENCE_SEED)?
            .agent(AgentId::TrendContinuation)
            .model
            .clone();
        let ablated = base.with_ablation(M3MicroAblationV1::NoSelectiveForgetting)?;
        let layout = M3MicroLayout::new(&base.config)?;
        let mut retention_parameter = vec![false; base.parameter_count()];
        for block in &layout.blocks {
            for range in [
                block.w_decay.clone(),
                block.b_decay.clone(),
                block.decay_state_bias.clone(),
            ] {
                retention_parameter[range].fill(true);
            }
        }
        Ok(base
            .parameters
            .values
            .iter()
            .zip(&ablated.parameters.values)
            .enumerate()
            .all(|(index, (base, ablated))| retention_parameter[index] || base == ablated))
    }

    fn historical_input(
        roster: &M3MicroRoster,
        agent_id: AgentId,
        partition: HistoricalPartition,
        sequence_start: usize,
        sequence_end: usize,
        target_index: usize,
        horizon_bars: usize,
        boundary: &HistoricalPartitionBoundary,
        raw_sequence: Vec<Vec<f32>>,
        expected_target: &M3MicroTarget,
    ) -> M3MicroHistoricalInput {
        let agent = roster.agent(agent_id);
        let reference = M3MicroTargetReference::new(
            agent_id,
            partition,
            target_index,
            agent.spec.target_policy,
            format!("{agent_id:?}:{partition:?}:{target_index}"),
            Some(M3MicroTargetReference::commitment_for(expected_target).unwrap()),
        )
        .unwrap();
        M3MicroHistoricalInput::new(
            agent_id,
            partition,
            sequence_start,
            sequence_end,
            target_index,
            horizon_bars,
            boundary.clone(),
            agent.formula_genome.input_schema_digest.clone(),
            raw_sequence,
            reference,
        )
        .unwrap()
    }

    fn historical_dataset(roster: &M3MicroRoster) -> M3MicroHistoricalDataset {
        let development_boundary = HistoricalPartitionBoundary::new(
            HistoricalPartition::Development,
            0,
            2,
            "fixture-development-v2",
        )
        .unwrap();
        let validation_boundary = HistoricalPartitionBoundary::new(
            HistoricalPartition::Validation,
            4,
            6,
            "fixture-validation-v2",
        )
        .unwrap();
        let mut development = BTreeMap::new();
        let mut validation_inputs = BTreeMap::new();
        let mut target_registrations = Vec::new();
        for agent_id in AgentId::ORDERED {
            let width = roster.agent(agent_id).model.config.input_dim;
            let expected_target = target(agent_id);
            let development_input = historical_input(
                roster,
                agent_id,
                HistoricalPartition::Development,
                0,
                1,
                2,
                1,
                &development_boundary,
                vec![row(width, 0.1, 0.2), row(width, 0.2, 0.3)],
                &expected_target,
            );
            let validation_input = historical_input(
                roster,
                agent_id,
                HistoricalPartition::Validation,
                4,
                5,
                6,
                1,
                &validation_boundary,
                vec![row(width, 0.3, 0.4), row(width, 0.4, 0.5)],
                &expected_target,
            );
            target_registrations.push((
                validation_input.target_reference.clone(),
                expected_target.clone(),
            ));
            development.insert(
                agent_id,
                vec![M3MicroDevelopmentExample {
                    input: development_input,
                    target: expected_target,
                }],
            );
            validation_inputs.insert(
                agent_id,
                vec![M3MicroValidationInput {
                    input: validation_input,
                }],
            );
        }
        M3MicroHistoricalDataset {
            boundaries: BTreeMap::from([
                (HistoricalPartition::Development, development_boundary),
                (HistoricalPartition::Validation, validation_boundary),
            ]),
            development,
            validation_inputs,
            validation_targets: M3MicroValidationTargetSource::new(target_registrations).unwrap(),
        }
    }

    fn temp_root(label: &str) -> PathBuf {
        let nonce = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        std::env::temp_dir().join(format!(
            "soma-sprint103-{label}-{}-{nonce}",
            std::process::id()
        ))
    }

    fn candle_series(length: usize, constant: bool) -> CandleSeries {
        let candles = (0..length)
            .map(|index| {
                let drift = if constant {
                    0.0
                } else {
                    index as f64 * 0.15 + (index as f64 * 0.3).sin()
                };
                let close = 100.0 + drift;
                Candle {
                    timestamp_ms: index as u64 * 60_000,
                    open: close - 0.1,
                    high: close + 0.7,
                    low: close - 0.8,
                    close,
                    volume: if constant {
                        10.0
                    } else {
                        10.0 + (index % 7) as f64
                    },
                    trade_value: None,
                    bid: Some(close - 0.02),
                    ask: Some(close + 0.02),
                    spread_bps: Some(4.0),
                }
            })
            .collect();
        CandleSeries {
            symbol: "SYNTH".into(),
            timeframe: Timeframe::OneMinute,
            candles,
        }
    }

