    fn delayed_evidence_for_length_v2(length: usize) -> &'static DelayedRecallEvidenceV2 {
        delayed_recall_evidence_v2()
            .iter()
            .find(|evidence| evidence.sequence_length == length)
            .unwrap()
    }

    fn assert_delayed_recall_dataset_v2(length: usize) {
        let policy = delayed_recall_evidence_policy_v2();
        let width = M3MicroConfig::for_agent(AgentId::TrendContinuation, 8).input_dim;
        let development = delayed_recall_examples_v2(width, length, false);
        let frozen = delayed_recall_examples_v2(width, length, true);
        assert_eq!(development.iter().filter(|item| item.positive).count(), 2);
        assert_eq!(development.iter().filter(|item| !item.positive).count(), 2);
        assert_eq!(frozen.iter().filter(|item| item.positive).count(), 2);
        assert_eq!(frozen.iter().filter(|item| !item.positive).count(), 2);
        assert_eq!(
            policy.frozen_evaluation_examples_per_class,
            frozen.iter().filter(|item| item.positive).count()
        );
        let positive = delayed_recall_sequence_v2(width, length, true, 11);
        let negative = delayed_recall_sequence_v2(width, length, false, 11);
        assert_ne!(positive[0], negative[0]);
        assert_eq!(positive[1..], negative[1..]);
        assert!(
            development.iter().all(|item| {
                item.sequence[length - 3..] == development[0].sequence[length - 3..]
            })
        );
        assert!(
            frozen
                .iter()
                .all(|item| { item.sequence[length - 3..] == frozen[0].sequence[length - 3..] })
        );
        assert_ne!(development[0].sequence, frozen[0].sequence);
    }

    fn assert_delayed_recall_length_v2(length: usize) {
        assert_delayed_recall_dataset_v2(length);
        let policy = delayed_recall_evidence_policy_v2();
        let evidence = delayed_evidence_for_length_v2(length);
        println!("SPRINT104_R1_R1_DELAYED_RECALL_V2={evidence:?}");
        assert!(evidence.final_development_loss < evidence.initial_development_loss);
        assert!(
            evidence.final_frozen_composite_role_loss < evidence.initial_frozen_composite_role_loss
        );
        assert!(evidence.frozen_accuracy >= policy.minimum_accuracy);
        assert!(
            evidence.paired_prediction_separation >= policy.minimum_carried_prediction_separation
        );
        assert!(evidence.early_signal_gradient_l1.is_finite());
        assert!(evidence.early_signal_gradient_l1 > 0.0);
        assert_ne!(
            evidence.initial_parameter_digest,
            evidence.final_parameter_digest
        );
        assert!(!evidence.optimizer_digest.is_empty());
        assert_eq!(
            evidence.development_loss_vector.len(),
            policy.fixed_training_budget
        );
    }

