    fn forgetting_case_evidence_v2(case: ForgettingCaseV2) -> &'static ForgettingCaseEvidenceV2 {
        selective_forgetting_evidence_v2()
            .cases
            .iter()
            .find(|evidence| evidence.case == case)
            .unwrap()
    }

    fn assert_selective_forgetting_dataset_v2(case: ForgettingCaseV2) {
        let policy = selective_forgetting_evidence_policy_v2();
        let width = M3MicroConfig::for_agent(AgentId::TrendContinuation, 8).input_dim;
        let development = forgetting_examples_v2(width, case, false);
        let frozen = forgetting_examples_v2(width, case, true);
        for examples in [&development, &frozen] {
            assert_eq!(examples.iter().filter(|item| item.positive).count(), 2);
            assert_eq!(examples.iter().filter(|item| !item.positive).count(), 2);
            assert_eq!(examples.len(), policy.evaluation_examples_per_case * 2);
            assert!(
                examples
                    .iter()
                    .all(|item| item.sequence.len() == policy.sequence_length)
            );
        }
        assert_ne!(development[0].sequence, frozen[0].sequence);
        if case == ForgettingCaseV2::Invalidation {
            let invalidation_index = match policy.invalidation_index_policy {
                InvalidationIndexPolicyV2::Fixed(index) => index,
            };
            for examples in [&development, &frozen] {
                assert!(examples.iter().any(|item| {
                    item.sequence[0][0].signum() == if item.positive { 1.0 } else { -1.0 }
                }));
                assert!(examples.iter().any(|item| {
                    item.sequence[0][0].signum() != if item.positive { 1.0 } else { -1.0 }
                }));
                assert!(examples.iter().all(|item| {
                    item.sequence[0] == item.sequence[1]
                        && item.sequence[1] == item.sequence[2]
                        && item.sequence[invalidation_index + 1]
                            == item.sequence[invalidation_index + 2]
                        && item.sequence[policy.sequence_length - 2..]
                            == examples[0].sequence[policy.sequence_length - 2..]
                }));
            }
        }
    }

    fn assert_selective_forgetting_case_v2(case: ForgettingCaseV2, minimum_accuracy: f32) {
        assert_selective_forgetting_dataset_v2(case);
        let evidence = forgetting_case_evidence_v2(case);
        println!("SPRINT104_R1_R1_SELECTIVE_FORGETTING_V2={evidence:?}");
        assert!(evidence.base_frozen.mean_composite_role_loss < evidence.initial_frozen_loss);
        assert!(evidence.base_frozen.accuracy >= minimum_accuracy);
        assert!(evidence.base_frozen.paired_prediction_separation > 0.0);
        assert!(evidence.transition.retention_before_event.is_finite());
        assert!(evidence.transition.retention_at_event.is_finite());
        assert_ne!(
            evidence.transition.state_digest_before_event,
            evidence.transition.state_digest_after_event
        );
    }

