    #[derive(Clone, Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
    struct MetalTopologyTraceCountsReceiptV4 {
        command_count: usize,
        encoder_count: usize,
        dispatch_count: usize,
        buffer_binding_count: usize,
    }

    impl MetalTopologyTraceCountsReceiptV4 {
        #[cfg(all(target_os = "macos", feature = "backend-metal"))]
        fn from_trace(trace: &super::metal_execution::MetalSemanticRunTraceV1) -> Self {
            Self {
                command_count: trace.commands.len(),
                encoder_count: trace
                    .commands
                    .iter()
                    .map(|command| command.encoders.len())
                    .sum(),
                dispatch_count: trace
                    .commands
                    .iter()
                    .flat_map(|command| &command.encoders)
                    .map(|encoder| encoder.dispatches.len())
                    .sum(),
                buffer_binding_count: trace
                    .commands
                    .iter()
                    .flat_map(|command| &command.encoders)
                    .map(|encoder| encoder.buffer_bindings.len())
                    .sum(),
            }
        }

        fn merge(&mut self, value: &Self) {
            self.command_count += value.command_count;
            self.encoder_count += value.encoder_count;
            self.dispatch_count += value.dispatch_count;
            self.buffer_binding_count += value.buffer_binding_count;
        }
    }

