    #[cfg(all(target_os = "macos", feature = "backend-metal"))]
    impl From<super::metal_execution::MetalPipelineConstructionEvidenceV1>
        for MetalPipelineConstructionEvidenceReceiptV1
    {
        fn from(value: super::metal_execution::MetalPipelineConstructionEvidenceV1) -> Self {
            use super::metal_execution::{
                MetalPipelineConstructionStatusV1 as SourceStatus,
                MetalPipelineLifecycleEventKindV1 as SourceKind,
            };
            let status = match value.status {
                SourceStatus::Succeeded => MetalPipelineConstructionStatusReceiptV1::Succeeded,
                SourceStatus::Failed => MetalPipelineConstructionStatusReceiptV1::Failed,
            };
            let events = value
                .events
                .into_iter()
                .map(|event| MetalPipelineLifecycleEventReceiptV1 {
                    event_ordinal: event.event_ordinal,
                    executor_construction_ordinal: event.executor_construction_ordinal,
                    kind: match event.kind {
                        SourceKind::LibraryCompileAttempted => {
                            MetalPipelineLifecycleEventKindReceiptV1::LibraryCompileAttempted
                        }
                        SourceKind::LibraryCompileSucceeded => {
                            MetalPipelineLifecycleEventKindReceiptV1::LibraryCompileSucceeded
                        }
                        SourceKind::LibraryCompileFailed => {
                            MetalPipelineLifecycleEventKindReceiptV1::LibraryCompileFailed
                        }
                        SourceKind::FunctionLookupAttempted => {
                            MetalPipelineLifecycleEventKindReceiptV1::FunctionLookupAttempted
                        }
                        SourceKind::FunctionLookupSucceeded => {
                            MetalPipelineLifecycleEventKindReceiptV1::FunctionLookupSucceeded
                        }
                        SourceKind::FunctionLookupFailed => {
                            MetalPipelineLifecycleEventKindReceiptV1::FunctionLookupFailed
                        }
                        SourceKind::PipelineCreationAttempted => {
                            MetalPipelineLifecycleEventKindReceiptV1::PipelineCreationAttempted
                        }
                        SourceKind::PipelineCreationSucceeded => {
                            MetalPipelineLifecycleEventKindReceiptV1::PipelineCreationSucceeded
                        }
                        SourceKind::PipelineCreationFailed => {
                            MetalPipelineLifecycleEventKindReceiptV1::PipelineCreationFailed
                        }
                        SourceKind::PipelineObservationCaptured => {
                            MetalPipelineLifecycleEventKindReceiptV1::PipelineObservationCaptured
                        }
                        SourceKind::PipelineArtifactCreated => {
                            MetalPipelineLifecycleEventKindReceiptV1::PipelineArtifactCreated
                        }
                    },
                    function_name: event.function_name,
                    shader_source_digest: event.shader_source_digest,
                    semantic_pipeline_identity: event.semantic_pipeline_identity,
                    error_kind: event.error_kind.map(|error| format!("{error:?}")),
                })
                .collect();
            Self {
                executor_construction_ordinal: value.executor_construction_ordinal,
                events,
                artifact_semantic_pipeline_identity: value.artifact_semantic_pipeline_identity,
                status,
            }
        }
    }

