    struct MetalPipelineLifecycleSnapshotReceiptV2 {
        event_sequence: u64,
        library_compile_attempted: u64,
        library_compile_succeeded: u64,
        library_compile_failed: u64,
        function_lookup_attempted: u64,
        function_lookup_succeeded: u64,
        function_lookup_failed: u64,
        pipeline_creation_attempted: u64,
        pipeline_creation_succeeded: u64,
        pipeline_creation_failed: u64,
        pipeline_observations_captured: u64,
        pipeline_artifacts_created: u64,
        lifecycle_digest_state: String,
        #[serde(default, skip_serializing_if = "String::is_empty")]
        ordering_digest_state: String,
        #[serde(default, skip_serializing_if = "String::is_empty")]
        function_sequence_digest_state: String,
        #[serde(default, skip_serializing_if = "String::is_empty")]
        shader_sequence_digest_state: String,
        #[serde(default, skip_serializing_if = "String::is_empty")]
        pipeline_identity_sequence_digest_state: String,
    }

    impl MetalPipelineLifecycleSnapshotReceiptV2 {
        fn categorized_event_count(&self) -> Result<u64, String> {
            [
                self.library_compile_attempted,
                self.library_compile_succeeded,
                self.library_compile_failed,
                self.function_lookup_attempted,
                self.function_lookup_succeeded,
                self.function_lookup_failed,
                self.pipeline_creation_attempted,
                self.pipeline_creation_succeeded,
                self.pipeline_creation_failed,
                self.pipeline_observations_captured,
                self.pipeline_artifacts_created,
            ]
            .into_iter()
            .try_fold(0u64, |total, value| {
                total
                    .checked_add(value)
                    .ok_or_else(|| "lifecycle snapshot counter overflow".to_string())
            })
        }

        fn validate(&self) -> Result<(), String> {
            if self.lifecycle_digest_state.is_empty()
                || self.categorized_event_count()? != self.event_sequence
            {
                return Err("inconsistent lifecycle snapshot".to_string());
            }
            Ok(())
        }
    }

