    #[cfg(all(target_os = "macos", feature = "backend-metal"))]
    fn metal_topology_mutation_registry_v1() -> Vec<MetalTopologyMutationSpecV1> {
        use MetalTopologyMutationCategoryV1 as Category;
        let mut specs = Vec::new();
        let mut scalar = |category: Category, template: &str, array_field: bool| {
            specs.push(MetalTopologyMutationSpecV1 {
                identity: format!("scalar:{template}"),
                kind: MetalTopologyMutationKindV1::ScalarField {
                    template: template.to_string(),
                    array_field,
                },
                cardinality: MetalTopologyMutationCardinalityV1::SingleScalarField,
                expected_mismatch_kind: category,
                eligibility: MetalTopologyMutationEligibilityV1::ActualTraceWithScalarField,
                required: true,
            });
        };
        for template in [
            "trace_schema_version",
            "execution_mode",
            "agent_role",
            "sequence_length",
            "chunk_policy_identity",
            "dispatch_argument_provenance.actual_argument_capture_count",
            "dispatch_argument_provenance.trace_record_count",
            "dispatch_argument_provenance.argument_trace_mismatch_count",
            "dispatch_argument_provenance.invalid_dimension_count",
            "dispatch_argument_provenance.conversion_failure_count",
            "dispatch_argument_provenance.geometry_digest",
            "buffer_binding_argument_provenance.actual_buffer_capture_count",
            "buffer_binding_argument_provenance.trace_record_count",
            "buffer_binding_argument_provenance.argument_trace_mismatch_count",
            "buffer_binding_argument_provenance.invalid_offset_count",
            "buffer_binding_argument_provenance.insufficient_span_count",
            "buffer_binding_argument_provenance.duplicate_binding_index_count",
            "buffer_binding_argument_provenance.missing_required_role_count",
            "buffer_binding_argument_provenance.unexpected_role_count",
            "buffer_binding_argument_provenance.binding_sequence_digest",
            "pipeline_binding_argument_provenance.pipeline_artifact_capture_count",
            "pipeline_binding_argument_provenance.trace_record_count",
            "pipeline_binding_argument_provenance.artifact_trace_mismatch_count",
            "pipeline_binding_argument_provenance.incomplete_artifact_count",
            "pipeline_binding_argument_provenance.invalid_pipeline_observation_count",
            "pipeline_binding_argument_provenance.semantic_pipeline_digest",
            "pipeline_binding_argument_provenance.pipeline_observation_digest",
            "pipeline_binding_argument_provenance.pipeline_binding_sequence_digest",
        ] {
            scalar(Category::TraceMetadata, template, false);
        }
        for template in [
            "commands[].command_ordinal",
            "commands[].encoder_count",
            "commands[].committed",
            "commands[].terminal_status",
            "commands[].error_present",
        ] {
            scalar(Category::Command, template, false);
        }
        scalar(
            Category::Encoder,
            "commands[].encoders[].encoder_ordinal",
            false,
        );
        for template in [
            "commands[].encoders[].pipeline_bindings[].pipeline_binding_ordinal",
            "commands[].encoders[].pipeline_bindings[].encoder_ordinal",
            "commands[].encoders[].pipeline_bindings[].artifact_schema_version",
            "commands[].encoders[].pipeline_bindings[].function_name",
            "commands[].encoders[].pipeline_bindings[].shader_source_digest",
            "commands[].encoders[].pipeline_bindings[].library_build_policy_identity",
            "commands[].encoders[].pipeline_bindings[].function_lookup_policy_identity",
            "commands[].encoders[].pipeline_bindings[].function_constant_identity",
            "commands[].encoders[].pipeline_bindings[].kernel_abi_identity",
            "commands[].encoders[].pipeline_bindings[].parameter_buffer_layout_identity",
            "commands[].encoders[].pipeline_bindings[].semantic_pipeline_identity",
            "commands[].encoders[].pipeline_bindings[].thread_execution_width",
            "commands[].encoders[].pipeline_bindings[].max_total_threads_per_threadgroup",
            "commands[].encoders[].pipeline_bindings[].binding_performed",
        ] {
            scalar(Category::Pipeline, template, false);
        }
        for template in [
            "commands[].encoders[].buffer_bindings[].binding_ordinal",
            "commands[].encoders[].buffer_bindings[].binding_index",
            "commands[].encoders[].buffer_bindings[].semantic_role",
            "commands[].encoders[].buffer_bindings[].semantic_access",
            "commands[].encoders[].buffer_bindings[].byte_offset",
            "commands[].encoders[].buffer_bindings[].actual_resource_length_bytes",
            "commands[].encoders[].buffer_bindings[].required_span_bytes",
            "commands[].encoders[].buffer_bindings[].available_span_bytes",
            "commands[].encoders[].buffer_bindings[].binding_performed",
        ] {
            scalar(Category::BufferBinding, template, false);
        }
        for template in [
            "commands[].encoders[].dispatches[].dispatch_ordinal",
            "commands[].encoders[].dispatches[].call_site",
            "commands[].encoders[].dispatches[].sequence_step_ordinal",
            "commands[].encoders[].dispatches[].chunk_ordinal",
            "commands[].encoders[].dispatches[].chunk_start",
            "commands[].encoders[].dispatches[].chunk_length",
            "commands[].encoders[].dispatches[].dispatch_performed",
        ] {
            scalar(Category::Dispatch, template, false);
        }
        scalar(
            Category::Dispatch,
            "commands[].encoders[].dispatches[].grid_threads[]",
            true,
        );
        scalar(
            Category::Dispatch,
            "commands[].encoders[].dispatches[].threads_per_threadgroup[]",
            true,
        );
        for template in [
            "segments[].chunk_ordinal",
            "segments[].chunk_start",
            "segments[].chunk_length",
            "segments[].command_ordinal",
            "segments[].chunk_boundary_state_digest",
        ] {
            scalar(Category::Dispatch, template, false);
        }
        for template in [
            "per_run_witness_delta.command_buffers_created",
            "per_run_witness_delta.command_buffers_committed",
            "per_run_witness_delta.command_buffers_completed",
            "per_run_witness_delta.command_buffer_failures",
            "per_run_witness_delta.compute_encoders_created",
            "per_run_witness_delta.dispatches_attempted",
            "per_run_witness_delta.dispatches_performed",
            "per_run_witness_delta.output_readbacks",
            "per_run_witness_delta.state_readbacks",
            "per_run_witness_delta.output_poison_remaining",
            "per_run_witness_delta.state_poison_remaining",
            "per_run_witness_delta.cpu_fallback_attempts",
            "per_run_witness_delta.cpu_fallback_executions",
        ] {
            scalar(Category::Witness, template, false);
        }
        for template in [
            "output_digest",
            "final_state_digest",
            "semantic_trace_digest",
        ] {
            scalar(Category::Result, template, false);
        }
        drop(scalar);
        for coverage_identity in ["mode-coverage-a", "mode-coverage-b"] {
            specs.push(MetalTopologyMutationSpecV1 {
                identity: format!(
                    "scalar:commands[].encoders[].encoder_ordinal:{coverage_identity}"
                ),
                kind: MetalTopologyMutationKindV1::ScalarField {
                    template: "commands[].encoders[].encoder_ordinal".to_string(),
                    array_field: false,
                },
                cardinality: MetalTopologyMutationCardinalityV1::SingleScalarField,
                expected_mismatch_kind: Category::Encoder,
                eligibility: MetalTopologyMutationEligibilityV1::ActualTraceWithScalarField,
                required: true,
            });
        }
        let mut structural = |category: Category, template: &str, reorder: Option<&str>| {
            let kind = match reorder {
                Some(first_field) => MetalTopologyMutationKindV1::ReorderVector {
                    template: template.to_string(),
                    first_field: first_field.to_string(),
                },
                None => MetalTopologyMutationKindV1::RemoveVector {
                    template: template.to_string(),
                },
            };
            specs.push(MetalTopologyMutationSpecV1 {
                identity: format!(
                    "{}:{template}",
                    if reorder.is_some() {
                        "reorder"
                    } else {
                        "remove"
                    }
                ),
                kind,
                cardinality: MetalTopologyMutationCardinalityV1::SingleStructuralOperation,
                expected_mismatch_kind: category,
                eligibility: if reorder.is_some() {
                    MetalTopologyMutationEligibilityV1::ActualTraceWithMultipleVectorEntries
                } else {
                    MetalTopologyMutationEligibilityV1::ActualTraceWithVectorEntry
                },
                required: true,
            });
        };
        structural(Category::Command, "commands", None);
        structural(Category::Command, "commands", Some("command_ordinal"));
        structural(Category::Encoder, "commands[].encoders", None);
        structural(
            Category::Pipeline,
            "commands[].encoders[].pipeline_bindings",
            None,
        );
        structural(
            Category::BufferBinding,
            "commands[].encoders[].buffer_bindings",
            None,
        );
        structural(
            Category::BufferBinding,
            "commands[].encoders[].buffer_bindings",
            Some("binding_ordinal"),
        );
        structural(Category::Dispatch, "commands[].encoders[].dispatches", None);
        structural(Category::Dispatch, "segments", None);
        structural(Category::TraceMetadata, "call_site_events", None);
        specs
    }

    #[cfg(all(target_os = "macos", feature = "backend-metal"))]
    fn mutation_template_parts_v1(template: &str) -> Vec<(&str, bool)> {
        template
            .split('.')
            .map(|part| match part.strip_suffix("[]") {
                Some(name) => (name, true),
                None => (part, false),
            })
            .collect()
    }

    #[cfg(all(target_os = "macos", feature = "backend-metal"))]
    fn mutation_category_for_field_v1(field: &str) -> MetalTopologyMutationCategoryV1 {
        if field == "commands.len" || field.starts_with("commands[") {
            if field.contains(".pipeline_bindings[") || field.contains(".pipeline_bindings.len") {
                MetalTopologyMutationCategoryV1::Pipeline
            } else if field.contains(".buffer_bindings[") || field.contains(".buffer_bindings.len")
            {
                MetalTopologyMutationCategoryV1::BufferBinding
            } else if field.contains(".dispatches[") || field.contains(".dispatches.len") {
                MetalTopologyMutationCategoryV1::Dispatch
            } else if field.contains(".encoders[") || field.contains(".encoders.len") {
                MetalTopologyMutationCategoryV1::Encoder
            } else {
                MetalTopologyMutationCategoryV1::Command
            }
        } else if field == "segments.len" || field.starts_with("segments[") {
            MetalTopologyMutationCategoryV1::Dispatch
        } else if field.starts_with("per_run_witness_delta.") {
            MetalTopologyMutationCategoryV1::Witness
        } else if matches!(
            field,
            "output_digest" | "final_state_digest" | "semantic_trace_digest"
        ) {
            MetalTopologyMutationCategoryV1::Result
        } else {
            MetalTopologyMutationCategoryV1::TraceMetadata
        }
    }

    #[cfg(all(target_os = "macos", feature = "backend-metal"))]
    fn mutate_scalar_json_value_v1(value: &mut serde_json::Value, path: &str) -> Option<()> {
        match value {
            serde_json::Value::Bool(value) => *value = !*value,
            serde_json::Value::Number(value) => {
                if let Some(number) = value.as_u64() {
                    *value = serde_json::Number::from(number.checked_add(1)?);
                } else if let Some(number) = value.as_i64() {
                    *value = serde_json::Number::from(number.checked_add(1)?);
                } else {
                    let number = value.as_f64()?;
                    *value = serde_json::Number::from_f64(number + 1.0)?;
                }
            }
            serde_json::Value::String(value) => {
                let replacement = match value.as_str() {
                    "Streaming" => "FullSequence".to_string(),
                    "FullSequence" | "Chunked" => "Streaming".to_string(),
                    "M3MicroForward" => "MutationOnly".to_string(),
                    "Completed" => "Error".to_string(),
                    "Error" | "Other" => "Completed".to_string(),
                    "Input" => "Parameters".to_string(),
                    "Parameters" => "Input".to_string(),
                    "ReadOnly" => "WriteOnly".to_string(),
                    "WriteOnly" => "ReadOnly".to_string(),
                    _ if path.ends_with("call_site") => return None,
                    _ => format!("{value}__r5_mutation"),
                };
                *value = replacement;
            }
            _ => return None,
        }
        Some(())
    }

    #[cfg(all(target_os = "macos", feature = "backend-metal"))]
    fn mutate_scalar_at_template_v1(
        value: &mut serde_json::Value,
        parts: &[(&str, bool)],
        display: &str,
    ) -> Option<(String, String, String)> {
        if parts.is_empty() {
            let before = serde_json::to_string(value).ok()?;
            mutate_scalar_json_value_v1(value, display)?;
            let after = serde_json::to_string(value).ok()?;
            return (before != after).then(|| (display.to_string(), before, after));
        }
        let (name, vector) = parts[0];
        let object = value.as_object_mut()?;
        let child = object.get_mut(name)?;
        if vector {
            let values = child.as_array_mut()?;
            for (index, item) in values.iter_mut().enumerate() {
                let next = format!("{display}{name}[{index}].");
                if let Some(result) = mutate_scalar_at_template_v1(item, &parts[1..], &next) {
                    return Some(result);
                }
            }
            None
        } else {
            let separator = if display.is_empty() || display.ends_with('.') {
                ""
            } else {
                "."
            };
            let next = format!("{display}{separator}{name}");
            mutate_scalar_at_template_v1(child, &parts[1..], &next)
        }
    }

    #[cfg(all(target_os = "macos", feature = "backend-metal"))]
    fn mutate_vector_at_template_v1(
        value: &mut serde_json::Value,
        parts: &[(&str, bool)],
        display: &str,
        reorder_field: Option<&str>,
    ) -> Option<(String, String, String)> {
        let (name, vector) = parts.first().copied()?;
        let object = value.as_object_mut()?;
        let child = object.get_mut(name)?;
        if parts.len() == 1 {
            if vector {
                return None;
            }
            let values = child.as_array_mut()?;
            let required_len = if reorder_field.is_some() { 2 } else { 1 };
            if values.len() < required_len {
                return None;
            }
            let target = format!("{display}{name}");
            let before = serde_json::to_string(values).ok()?;
            if let Some(field) = reorder_field {
                let first = values.iter().enumerate().next()?.0;
                let second = values.iter().enumerate().nth(1)?.0;
                values.swap(first, second);
                let after = serde_json::to_string(values).ok()?;
                return (before != after)
                    .then(|| (format!("{target}[{first}].{field}"), before, after));
            }
            values.pop()?;
            let after = serde_json::to_string(values).ok()?;
            let expected = if target == "call_site_events" {
                target
            } else {
                format!("{target}.len")
            };
            return (before != after).then(|| (expected, before, after));
        }
        if vector {
            let values = child.as_array_mut()?;
            for (index, item) in values.iter_mut().enumerate() {
                let next = format!("{display}{name}[{index}].");
                if let Some(result) =
                    mutate_vector_at_template_v1(item, &parts[1..], &next, reorder_field)
                {
                    return Some(result);
                }
            }
            None
        } else {
            let separator = if display.is_empty() || display.ends_with('.') {
                ""
            } else {
                "."
            };
            let next = format!("{display}{separator}{name}.");
            mutate_vector_at_template_v1(child, &parts[1..], &next, reorder_field)
        }
    }

    #[cfg(all(target_os = "macos", feature = "backend-metal"))]
    fn mutate_actual_trace_for_spec_v1(
        trace: &super::metal_execution::MetalSemanticRunTraceV1,
        spec: &MetalTopologyMutationSpecV1,
    ) -> Option<(
        super::metal_execution::MetalSemanticRunTraceV1,
        MetalSingleFieldMutationDeltaV1,
        String,
    )> {
        let mut encoded = serde_json::to_value(trace).ok()?;
        let before_digest = stable_hash_string(&serde_json::to_string(&encoded).ok()?);
        let (mut expected_field, before, after) = match &spec.kind {
            MetalTopologyMutationKindV1::ScalarField {
                template,
                array_field,
            } => {
                let (path, before, after) = mutate_scalar_at_template_v1(
                    &mut encoded,
                    &mutation_template_parts_v1(template),
                    "",
                )?;
                let expected = if *array_field {
                    path.rsplit_once('[')?.0.to_string()
                } else {
                    path
                };
                (expected, before, after)
            }
            MetalTopologyMutationKindV1::RemoveVector { template } => mutate_vector_at_template_v1(
                &mut encoded,
                &mutation_template_parts_v1(template),
                "",
                None,
            )?,
            MetalTopologyMutationKindV1::ReorderVector {
                template,
                first_field,
            } => mutate_vector_at_template_v1(
                &mut encoded,
                &mutation_template_parts_v1(template),
                "",
                Some(first_field),
            )?,
        };
        if expected_field.starts_with('.') {
            expected_field.remove(0);
        }
        let after_digest = stable_hash_string(&serde_json::to_string(&encoded).ok()?);
        let mutated = serde_json::from_value(encoded).ok()?;
        let delta = MetalSingleFieldMutationDeltaV1 {
            mutation_kind: spec.kind.clone(),
            changed_field_paths: vec![expected_field.clone()],
            changed_field_count: 1,
            before_digest: stable_hash_string(&before),
            after_digest: stable_hash_string(&after),
        };
        (delta.before_digest != delta.after_digest && before_digest != after_digest).then_some((
            mutated,
            delta,
            expected_field,
        ))
    }

    #[cfg(all(target_os = "macos", feature = "backend-metal"))]
    fn validate_actual_ab_baseline_v1(
        baseline: &MetalActualABMutationBaselineV1,
    ) -> Result<(), String> {
        use super::metal_execution::compare_metal_semantic_run_traces_v1;
        if baseline.record.origin
            != MetalMutationBaselineOriginV1::ActualIndependentSameExecutorHardwareRuns
            || baseline.record.run_a_identity == baseline.record.run_b_identity
            || !baseline.record.run_a_actual_forward_completed
            || !baseline.record.run_b_actual_forward_completed
            || std::ptr::eq(&baseline.trace_a, &baseline.trace_b)
            || !baseline.trace_a.per_run_witness_delta.successful()
            || !baseline.trace_b.per_run_witness_delta.successful()
            || !compare_metal_semantic_run_traces_v1(
                &baseline.record.scenario_identity,
                "A/B",
                &baseline.trace_a,
                &baseline.trace_b,
            )
            .is_empty()
        {
            return Err("invalid actual independent A/B mutation baseline".to_string());
        }
        Ok(())
    }

    #[cfg(all(target_os = "macos", feature = "backend-metal"))]
    fn build_independent_ab_mutation_baseline_evidence_v1(
        baselines: &[MetalActualABMutationBaselineV1],
    ) -> Result<MetalIndependentABMutationBaselineEvidenceV1, String> {
        use super::metal_execution::compare_metal_semantic_run_traces_v1;
        if baselines.is_empty() {
            return Err("missing actual A/B mutation baselines".to_string());
        }
        for baseline in baselines {
            validate_actual_ab_baseline_v1(baseline)?;
        }
        let registry = metal_topology_mutation_registry_v1();
        let required_mutation_count = registry.iter().filter(|spec| spec.required).count();
        let mut mode_category_counts =
            BTreeMap::<(String, MetalTopologyMutationCategoryV1), usize>::new();
        let mut agent_counts = BTreeMap::<String, usize>::new();
        let mut results = Vec::new();
        for spec in &registry {
            let mut candidates = baselines.iter().enumerate().collect::<Vec<_>>();
            candidates.sort_by_key(|(_, baseline)| {
                (
                    mode_category_counts
                        .get(&(
                            baseline.record.execution_mode.clone(),
                            spec.expected_mismatch_kind,
                        ))
                        .copied()
                        .unwrap_or(0),
                    agent_counts
                        .get(&baseline.record.agent_role)
                        .copied()
                        .unwrap_or(0),
                    baseline.record.scenario_identity.clone(),
                )
            });
            let Some((_, baseline, mutated, delta, expected_field)) =
                candidates.into_iter().find_map(|(index, baseline)| {
                    mutate_actual_trace_for_spec_v1(&baseline.trace_b, spec).map(
                        |(mutated, delta, expected_field)| {
                            (index, baseline, mutated, delta, expected_field)
                        },
                    )
                })
            else {
                return Err(format!(
                    "missing eligible actual mutation baseline for {}",
                    spec.identity
                ));
            };
            if delta.changed_field_count != 1
                || delta.changed_field_paths.len() != 1
                || delta.before_digest == delta.after_digest
            {
                return Err("invalid single-field mutation cardinality".to_string());
            }
            if !compare_metal_semantic_run_traces_v1(
                &baseline.record.scenario_identity,
                "A/B-original",
                &baseline.trace_a,
                &baseline.trace_b,
            )
            .is_empty()
            {
                return Err("actual A/B baseline changed before mutation".to_string());
            }
            let mismatches = compare_metal_semantic_run_traces_v1(
                &baseline.record.scenario_identity,
                "A/B-mutated",
                &baseline.trace_a,
                &mutated,
            );
            let observed = mismatches
                .first()
                .ok_or_else(|| format!("undetected topology mutation: {}", spec.identity))?;
            let observed_kind = mutation_category_for_field_v1(&observed.field);
            if observed.field != expected_field || observed_kind != spec.expected_mismatch_kind {
                return Err(format!(
                    "wrong topology mismatch for {}: expected {} / {}, observed {} / {}",
                    spec.identity,
                    spec.expected_mismatch_kind.as_str(),
                    expected_field,
                    observed_kind.as_str(),
                    observed.field,
                ));
            }
            if !compare_metal_semantic_run_traces_v1(
                &baseline.record.scenario_identity,
                "A/B-original-after-mutation",
                &baseline.trace_a,
                &baseline.trace_b,
            )
            .is_empty()
            {
                return Err("original actual A/B trace was contaminated".to_string());
            }
            *mode_category_counts
                .entry((
                    baseline.record.execution_mode.clone(),
                    spec.expected_mismatch_kind,
                ))
                .or_default() += 1;
            *agent_counts
                .entry(baseline.record.agent_role.clone())
                .or_default() += 1;
            results.push(MetalTopologyMutationResultV1 {
                mutation_identity: spec.identity.clone(),
                selected_baseline_identity: stable_hash_string(
                    &serde_json::to_string(&baseline.record).unwrap(),
                ),
                changed_field_path: expected_field,
                cardinality: spec.cardinality,
                observed_mismatch_kind: observed_kind,
                observed_mismatch_path: observed.field.clone(),
                detected: true,
            });
        }
        let mode_count = |mode: &str| {
            results
                .iter()
                .filter(|result| {
                    baselines.iter().any(|baseline| {
                        stable_hash_string(&serde_json::to_string(&baseline.record).unwrap())
                            == result.selected_baseline_identity
                            && baseline.record.execution_mode == mode
                    })
                })
                .count()
        };
        let agent_count = |agent: &str| {
            results
                .iter()
                .filter(|result| {
                    baselines.iter().any(|baseline| {
                        stable_hash_string(&serde_json::to_string(&baseline.record).unwrap())
                            == result.selected_baseline_identity
                            && baseline.record.agent_role == agent
                    })
                })
                .count()
        };
        let required_modes = ["Streaming", "FullSequence", "Chunked"];
        let required_agents = AgentId::ORDERED.map(|agent| format!("{agent:?}"));
        let major_categories = [
            MetalTopologyMutationCategoryV1::Command,
            MetalTopologyMutationCategoryV1::Encoder,
            MetalTopologyMutationCategoryV1::Pipeline,
            MetalTopologyMutationCategoryV1::BufferBinding,
            MetalTopologyMutationCategoryV1::Dispatch,
        ];
        if required_modes.iter().any(|mode| mode_count(mode) == 0)
            || required_agents.iter().any(|agent| agent_count(agent) == 0)
            || required_modes.iter().any(|mode| {
                major_categories.iter().any(|category| {
                    mode_category_counts
                        .get(&(mode.to_string(), *category))
                        .copied()
                        .unwrap_or(0)
                        == 0
                })
            })
            || !baselines
                .iter()
                .any(|baseline| baseline.record.sequence_length <= 4)
            || !baselines
                .iter()
                .any(|baseline| baseline.record.sequence_length == 32)
            || !baselines
                .iter()
                .any(|baseline| baseline.record.initial_state_policy_identity == "Zero")
            || !baselines.iter().any(|baseline| {
                baseline.record.initial_state_policy_identity == "DeterministicNonZero"
            })
        {
            return Err("actual mutation coverage is incomplete".to_string());
        }
        let baseline_records = baselines
            .iter()
            .map(|baseline| baseline.record.clone())
            .collect::<Vec<_>>();
        let mutation_registry_digest =
            stable_hash_string(&serde_json::to_string(&registry).unwrap());
        let mutation_result_digest = stable_hash_string(&serde_json::to_string(&results).unwrap());
        Ok(MetalIndependentABMutationBaselineEvidenceV1 {
            policy_identity: stable_hash_string(
                "m3-r5-actual-independent-ab:owned-traces:deep-copy:single-field:fail-closed",
            ),
            registry_identity: mutation_registry_digest.clone(),
            actual_ab_pair_count: baselines.len(),
            validated_ab_pair_count: baselines.len(),
            self_comparison_count: 0,
            synthetic_baseline_count: 0,
            unmeasured_baseline_count: 0,
            required_mutation_count,
            executed_mutation_count: results.len(),
            detected_mutation_count: results.iter().filter(|result| result.detected).count(),
            skipped_required_mutation_count: 0,
            missing_eligible_baseline_count: 0,
            unexpected_pass_count: 0,
            wrong_mismatch_kind_count: 0,
            accidental_multi_field_mutation_count: 0,
            streaming_mutation_count: mode_count("Streaming"),
            full_mutation_count: mode_count("FullSequence"),
            chunked_mutation_count: mode_count("Chunked"),
            trend_baseline_count: agent_count("TrendContinuation"),
            volatility_baseline_count: agent_count("VolatilityRegime"),
            reversal_baseline_count: agent_count("ReversalDistortion"),
            baseline_aggregate_digest: stable_hash_string(&serde_json::to_string(&baseline_records).unwrap()),
            mutation_registry_digest,
            mutation_result_digest,
            baseline_records,
            mutation_results: results,
            status: MetalIndependentABMutationBaselineStatusV1::PassedActualIndependentABMutationBaseline,
        })
    }

