    #[cfg(all(target_os = "macos", feature = "backend-metal"))]
    fn execute_actual_m3_micro_topology_mutation_evidence_v1()
    -> Result<MetalTopologyPanelExecutionV8, String> {
        build_metal_topology_determinism_receipt_v4()
    }

    fn metal_v4_topology_failure_surface_v1(
        topology: &MetalTopologyDeterminismReceiptV4,
    ) -> Result<MetalV4TopologyFailureSurfaceV1, String> {
        let mismatch_count = [
            topology.topology_mismatch_count,
            topology.witness_delta_mismatch_count,
            topology.output_digest_mismatch_count,
            topology.state_digest_mismatch_count,
        ]
        .into_iter()
        .try_fold(0usize, |total, count| {
            total
                .checked_add(count)
                .ok_or_else(|| "actual V4 topology mismatch counter overflow".to_string())
        })?;
        let failure_count = [
            topology.normal_command_failure_count,
            topology.cpu_fallback_execution_count,
        ]
        .into_iter()
        .try_fold(0usize, |total, count| {
            total
                .checked_add(count)
                .ok_or_else(|| "actual V4 topology failure counter overflow".to_string())
        })?;
        let unresolved_count = usize::from(
            topology.status != MetalTopologyDeterminismStatusReceiptV4::PassedSemanticTopology,
        );
        let surface_digest = stable_hash_string(
            &serde_json::to_string(&(
                topology.status,
                mismatch_count,
                failure_count,
                unresolved_count,
                &topology.policy_identity,
                &topology.trace_schema_identity,
                &topology.test_vector_policy_identity,
                &topology.ab_comparison_digest,
                &topology.ac_comparison_digest,
                &topology.bc_comparison_digest,
                &topology.aggregate_trace_digest,
                &topology.output_digest,
                &topology.final_state_digest,
            ))
            .map_err(|error| error.to_string())?,
        );
        Ok(MetalV4TopologyFailureSurfaceV1 {
            mismatch_count,
            failure_count,
            unresolved_count,
            surface_digest,
        })
    }

    fn validate_actual_v4_replay_topology_v1(
        topology: &MetalTopologyDeterminismReceiptV4,
    ) -> Result<MetalV4TopologyFailureSurfaceV1, String> {
        let surface = metal_v4_topology_failure_surface_v1(topology)?;
        if topology.status != MetalTopologyDeterminismStatusReceiptV4::PassedSemanticTopology
            || surface.mismatch_count != 0
            || surface.failure_count != 0
            || surface.unresolved_count != 0
        {
            return Err(format!(
                "actual V4 replay topology is not pass-compatible: status={} mismatch={} failure={} unresolved={}",
                topology.status.as_str(),
                surface.mismatch_count,
                surface.failure_count,
                surface.unresolved_count,
            ));
        }
        validate_metal_topology_receipt_v4(topology)?;
        Ok(surface)
    }

    fn validate_persisted_v11_replay_topology_v1(
        receipt: &M3MicroMetalExecutionReceiptV11,
        historical_v4_topology: &MetalTopologyDeterminismReceiptV4,
    ) -> Result<ValidatedActualReplayTopologyV1, String> {
        let surface = validate_actual_v4_replay_topology_v1(historical_v4_topology)?;
        if receipt.topology_status
            != MetalTopologyEvidenceStatusV11::PassedActualSemanticCommandTopology
            || !receipt.unresolved_topology_contracts.is_empty()
            || surface.mismatch_count != 0
            || surface.failure_count != 0
            || surface.unresolved_count != 0
        {
            return Err("persisted V11 replay topology is not pass-compatible".to_string());
        }
        Ok(ValidatedActualReplayTopologyV1 {
            historical_v4_status: historical_v4_topology.status,
            historical_v4_mismatch_count: surface.mismatch_count,
            historical_v4_failure_count: surface.failure_count,
            historical_v4_unresolved_count: surface.unresolved_count,
            historical_v4_surface_digest: surface.surface_digest,
            final_topology_status: receipt.topology_status,
            unresolved_topology_contracts: receipt.unresolved_topology_contracts.clone(),
        })
    }

    #[cfg(all(target_os = "macos", feature = "backend-metal"))]
    fn validate_actual_m3_micro_topology_mutation_execution_v1(
        panel: &MetalTopologyPanelExecutionV8,
    ) -> Result<ValidatedActualReplayTopologyV1, String> {
        let surface = metal_v4_topology_failure_surface_v1(&panel.historical_v4_topology)?;
        let mut unresolved_topology_contracts = Vec::new();
        let mut failures = Vec::new();
        if surface.mismatch_count != 0
            || surface.failure_count != 0
            || surface.unresolved_count != 0
        {
            unresolved_topology_contracts.push(MetalTopologyUnresolvedContractV11::Reserved);
        }
        for validation in [
            validate_actual_v4_replay_topology_v1(&panel.historical_v4_topology).map(|_| ()),
            validate_dispatch_argument_provenance_evidence_v1(&panel.dispatch_argument_provenance),
            validate_buffer_binding_argument_provenance_evidence_v1(
                &panel.buffer_binding_argument_provenance,
            ),
            validate_pipeline_binding_argument_provenance_evidence_v1(
                &panel.pipeline_binding_argument_provenance,
            ),
            validate_metal_pipeline_lifecycle_provenance_v3(
                &panel.pipeline_lifecycle_provenance_v3,
            ),
            validate_independent_ab_mutation_baseline_evidence_v1(
                &panel.independent_ab_mutation_baseline,
            ),
        ] {
            if let Err(error) = validation {
                unresolved_topology_contracts.push(MetalTopologyUnresolvedContractV11::Reserved);
                failures.push(error);
            }
        }
        if !unresolved_topology_contracts.is_empty() {
            return Err(format!(
                "actual replay topology validation failed: v4_mismatch={} v4_failure={} v4_unresolved={} validation_failures={}",
                surface.mismatch_count,
                surface.failure_count,
                surface.unresolved_count,
                failures.join("; "),
            ));
        }
        Ok(ValidatedActualReplayTopologyV1 {
            historical_v4_status: panel.historical_v4_topology.status,
            historical_v4_mismatch_count: surface.mismatch_count,
            historical_v4_failure_count: surface.failure_count,
            historical_v4_unresolved_count: surface.unresolved_count,
            historical_v4_surface_digest: surface.surface_digest,
            final_topology_status:
                MetalTopologyEvidenceStatusV11::PassedActualSemanticCommandTopology,
            unresolved_topology_contracts,
        })
    }

    fn metal_read_only_replay_semantic_projection_v1(
        baseline: &MetalIndependentABMutationBaselineEvidenceV1,
        dispatch: &MetalDispatchArgumentProvenanceEvidenceV1,
        buffer: &MetalBufferBindingArgumentProvenanceEvidenceV1,
        pipeline: &MetalPipelineBindingArgumentProvenanceEvidenceV1,
        lifecycle: &MetalPipelineLifecycleProvenanceEvidenceV3,
        topology: &ValidatedActualReplayTopologyV1,
    ) -> MetalReadOnlyReplaySemanticProjectionV1 {
        MetalReadOnlyReplaySemanticProjectionV1 {
            actual_v4_topology_status: topology.historical_v4_status.as_str().to_string(),
            actual_v4_topology_mismatch_count: topology.historical_v4_mismatch_count,
            actual_v4_topology_failure_count: topology.historical_v4_failure_count,
            actual_v4_topology_unresolved_count: topology.historical_v4_unresolved_count,
            actual_v4_topology_surface_digest: topology.historical_v4_surface_digest.clone(),
            actual_ab_pair_count: baseline.actual_ab_pair_count,
            validated_ab_pair_count: baseline.validated_ab_pair_count,
            self_comparison_count: baseline.self_comparison_count,
            synthetic_baseline_count: baseline.synthetic_baseline_count,
            unmeasured_baseline_count: baseline.unmeasured_baseline_count,
            required_mutation_count: baseline.required_mutation_count,
            executed_mutation_count: baseline.executed_mutation_count,
            detected_mutation_count: baseline.detected_mutation_count,
            skipped_required_mutation_count: baseline.skipped_required_mutation_count,
            missing_eligible_baseline_count: baseline.missing_eligible_baseline_count,
            unexpected_pass_count: baseline.unexpected_pass_count,
            wrong_mismatch_kind_count: baseline.wrong_mismatch_kind_count,
            accidental_multi_field_mutation_count: baseline.accidental_multi_field_mutation_count,
            streaming_mutation_count: baseline.streaming_mutation_count,
            full_mutation_count: baseline.full_mutation_count,
            chunked_mutation_count: baseline.chunked_mutation_count,
            trend_baseline_count: baseline.trend_baseline_count,
            volatility_baseline_count: baseline.volatility_baseline_count,
            reversal_baseline_count: baseline.reversal_baseline_count,
            baseline_aggregate_digest: baseline.baseline_aggregate_digest.clone(),
            mutation_registry_digest: baseline.mutation_registry_digest.clone(),
            mutation_result_digest: baseline.mutation_result_digest.clone(),
            dispatch_provenance_status: dispatch.status.as_str().to_string(),
            buffer_binding_provenance_status: buffer.status.as_str().to_string(),
            pipeline_binding_provenance_status: pipeline.status.as_str().to_string(),
            lifecycle_status: lifecycle.status.as_str().to_string(),
            reuse_status: lifecycle.same_executor_reuse.status.as_str().to_string(),
            fresh_executor_status: lifecycle.fresh_executor.status.as_str().to_string(),
            topology_status: topology.final_topology_status.as_str().to_string(),
            unresolved_topology_contract_count: topology.unresolved_topology_contracts.len(),
        }
    }

