    fn compare_metal_read_only_replay_semantic_projections_v1(
        runtime: &MetalReadOnlyReplaySemanticProjectionV1,
        persisted: &MetalReadOnlyReplaySemanticProjectionV1,
    ) -> Vec<String> {
        let mut mismatches = Vec::new();
        macro_rules! compare_field {
            ($field:ident) => {
                if runtime.$field != persisted.$field {
                    mismatches.push(stringify!($field).to_string());
                }
            };
        }
        compare_field!(actual_v4_topology_status);
        compare_field!(actual_v4_topology_mismatch_count);
        compare_field!(actual_v4_topology_failure_count);
        compare_field!(actual_v4_topology_unresolved_count);
        compare_field!(actual_ab_pair_count);
        compare_field!(validated_ab_pair_count);
        compare_field!(self_comparison_count);
        compare_field!(synthetic_baseline_count);
        compare_field!(unmeasured_baseline_count);
        compare_field!(required_mutation_count);
        compare_field!(executed_mutation_count);
        compare_field!(detected_mutation_count);
        compare_field!(skipped_required_mutation_count);
        compare_field!(missing_eligible_baseline_count);
        compare_field!(unexpected_pass_count);
        compare_field!(wrong_mismatch_kind_count);
        compare_field!(accidental_multi_field_mutation_count);
        compare_field!(streaming_mutation_count);
        compare_field!(full_mutation_count);
        compare_field!(chunked_mutation_count);
        compare_field!(trend_baseline_count);
        compare_field!(volatility_baseline_count);
        compare_field!(reversal_baseline_count);
        compare_field!(baseline_aggregate_digest);
        compare_field!(mutation_registry_digest);
        compare_field!(mutation_result_digest);
        compare_field!(dispatch_provenance_status);
        compare_field!(buffer_binding_provenance_status);
        compare_field!(pipeline_binding_provenance_status);
        compare_field!(lifecycle_status);
        compare_field!(reuse_status);
        compare_field!(fresh_executor_status);
        compare_field!(topology_status);
        compare_field!(unresolved_topology_contract_count);
        mismatches
    }

    fn metal_executor_source_v1() -> &'static str {
        include_str!("m3_micro_metal.rs")
    }

    fn current_metal_dispatch_call_site_inventory_v1() -> Result<(usize, usize, usize), String> {
        let source = metal_executor_source_v1();
        let api_marker = [".dispatch_", "threads("].concat();
        let helper_marker = "fn dispatch_threads_with_semantic_trace_v1(";
        let helper_start = source
            .find(helper_marker)
            .ok_or_else(|| "single traced-dispatch helper is missing".to_string())?;
        let helper = source[helper_start..]
            .split("impl M3MicroMetalExecutorV1")
            .next()
            .ok_or_else(|| "single traced-dispatch helper boundary is missing".to_string())?;
        let normal_dispatch_api_call_sites = source.matches(&api_marker).count();
        let traced_dispatch_api_call_sites = helper.matches(&api_marker).count();
        let untraced_normal_dispatch_api_call_sites =
            normal_dispatch_api_call_sites.saturating_sub(traced_dispatch_api_call_sites);
        Ok((
            normal_dispatch_api_call_sites,
            traced_dispatch_api_call_sites,
            untraced_normal_dispatch_api_call_sites,
        ))
    }

