    #[cfg(all(target_os = "macos", feature = "backend-metal"))]
    fn p2r3_sample_semantic_trace_v1(
        dispatch_count: usize,
    ) -> super::metal_execution::MetalSemanticRunTraceV1 {
        use super::metal_execution::{
            METAL_SEMANTIC_TRACE_SCHEMA_VERSION_V4, MetalActualBufferBindingTraceV1,
            MetalBufferAccessV2, MetalBufferBindingArgumentRunEvidenceV1, MetalBufferRoleV2,
            MetalCommandTerminalStatusV1, MetalDispatchArgumentRunEvidenceV1,
            MetalDispatchCallSiteV1, MetalExecutionModeV1, MetalPerRunWitnessDeltaV1,
            MetalPipelineArtifactMetadataV1, MetalPipelineBindingArgumentRunEvidenceV1,
            MetalSemanticCommandTraceV1, MetalSemanticDispatchTraceV1, MetalSemanticEncoderTraceV1,
            MetalSemanticRunTraceV1, MetalSemanticSegmentTraceV1, MetalSemanticTraceEventV1,
            MetalTraceCallSiteV1, metal_buffer_binding_sequence_digest_v1,
            metal_dispatch_geometry_digest_v1, metal_function_constant_identity_v1,
            metal_function_lookup_policy_identity_v1, metal_kernel_abi_identity_v1,
            metal_library_build_policy_identity_v1, metal_parameter_buffer_layout_identity_v1,
            metal_pipeline_binding_sequence_digest_v1,
            metal_pipeline_binding_trace_from_metadata_for_test_v1,
            metal_pipeline_observation_digest_v1, metal_pipeline_semantic_digest_v1,
            metal_pipeline_semantic_identity_from_metadata_v1, metal_semantic_trace_digest_v1,
        };
        assert!(dispatch_count > 0);
        let roles = [
            (MetalBufferRoleV2::Input, MetalBufferAccessV2::ReadOnly),
            (MetalBufferRoleV2::Parameters, MetalBufferAccessV2::ReadOnly),
            (
                MetalBufferRoleV2::InitialState,
                MetalBufferAccessV2::ReadOnly,
            ),
            (MetalBufferRoleV2::Output, MetalBufferAccessV2::WriteOnly),
            (
                MetalBufferRoleV2::FinalState,
                MetalBufferAccessV2::WriteOnly,
            ),
            (MetalBufferRoleV2::Metadata, MetalBufferAccessV2::ReadOnly),
            (
                MetalBufferRoleV2::ScalarConfiguration,
                MetalBufferAccessV2::ReadOnly,
            ),
            (
                MetalBufferRoleV2::ExecutionWitness,
                MetalBufferAccessV2::WriteOnly,
            ),
        ];
        let buffer_bindings = roles
            .into_iter()
            .enumerate()
            .map(|(binding_index, (semantic_role, semantic_access))| {
                MetalActualBufferBindingTraceV1 {
                    binding_ordinal: binding_index,
                    binding_index,
                    semantic_role,
                    semantic_access,
                    byte_offset: 0,
                    actual_resource_length_bytes: (binding_index + 1) * 16,
                    required_span_bytes: (binding_index + 1) * 16,
                    available_span_bytes: (binding_index + 1) * 16,
                    binding_performed: true,
                }
            })
            .collect::<Vec<_>>();
        let dispatches = (0..dispatch_count)
            .map(|dispatch_ordinal| MetalSemanticDispatchTraceV1 {
                dispatch_ordinal,
                call_site: MetalDispatchCallSiteV1::M3MicroForward,
                grid_threads: [1, 1, 1],
                threads_per_threadgroup: [1, 1, 1],
                sequence_step_ordinal: 0,
                chunk_ordinal: 0,
                chunk_start: 0,
                chunk_length: 1,
                dispatch_performed: true,
            })
            .collect::<Vec<_>>();
        let mut pipeline_metadata = MetalPipelineArtifactMetadataV1 {
            artifact_schema_version: 1,
            function_name: m3_micro_metal_function_identity_v1().to_string(),
            shader_source_digest: m3_micro_metal_shader_digest_v1(),
            library_build_policy_identity: metal_library_build_policy_identity_v1(),
            function_lookup_policy_identity: metal_function_lookup_policy_identity_v1(),
            function_constant_identity: metal_function_constant_identity_v1(),
            kernel_abi_identity: metal_kernel_abi_identity_v1(),
            parameter_buffer_layout_identity: metal_parameter_buffer_layout_identity_v1(),
            semantic_pipeline_identity: String::new(),
            thread_execution_width: 32,
            max_total_threads_per_threadgroup: 1024,
        };
        pipeline_metadata.semantic_pipeline_identity =
            metal_pipeline_semantic_identity_from_metadata_v1(&pipeline_metadata);
        let mut pipeline_binding =
            metal_pipeline_binding_trace_from_metadata_for_test_v1(&pipeline_metadata);
        pipeline_binding.binding_performed = true;
        let mut call_sites = vec![
            MetalTraceCallSiteV1::CommandBufferCreated,
            MetalTraceCallSiteV1::EncoderCreated,
            MetalTraceCallSiteV1::PipelineBound,
        ];
        call_sites.extend([MetalTraceCallSiteV1::BufferBound; 8]);
        call_sites
            .extend(std::iter::repeat(MetalTraceCallSiteV1::DispatchIssued).take(dispatch_count));
        call_sites.extend([
            MetalTraceCallSiteV1::EncoderEnded,
            MetalTraceCallSiteV1::CommandCommitted,
            MetalTraceCallSiteV1::CommandCompleted,
            MetalTraceCallSiteV1::OutputReadback,
            MetalTraceCallSiteV1::StateReadback,
        ]);
        let mut trace = MetalSemanticRunTraceV1 {
            trace_schema_version: METAL_SEMANTIC_TRACE_SCHEMA_VERSION_V4,
            execution_mode: MetalExecutionModeV1::FullSequence,
            agent_role: "TrendContinuation".to_string(),
            sequence_length: 1,
            chunk_policy_identity: "sample-full-policy".to_string(),
            commands: vec![MetalSemanticCommandTraceV1 {
                command_ordinal: 0,
                encoder_count: 1,
                encoders: vec![MetalSemanticEncoderTraceV1 {
                    encoder_ordinal: 0,
                    pipeline_bindings: vec![pipeline_binding],
                    buffer_bindings,
                    dispatches,
                }],
                committed: true,
                terminal_status: MetalCommandTerminalStatusV1::Completed,
                error_present: false,
            }],
            segments: vec![MetalSemanticSegmentTraceV1 {
                chunk_ordinal: 0,
                chunk_start: 0,
                chunk_length: 1,
                command_ordinal: 0,
                chunk_boundary_state_digest: "sample-state".to_string(),
            }],
            call_site_events: call_sites
                .into_iter()
                .enumerate()
                .map(|(event_ordinal, call_site)| MetalSemanticTraceEventV1 {
                    event_ordinal,
                    command_ordinal: 0,
                    encoder_ordinal: matches!(
                        call_site,
                        MetalTraceCallSiteV1::EncoderCreated
                            | MetalTraceCallSiteV1::PipelineBound
                            | MetalTraceCallSiteV1::BufferBound
                            | MetalTraceCallSiteV1::DispatchIssued
                            | MetalTraceCallSiteV1::EncoderEnded
                    )
                    .then_some(0),
                    call_site,
                })
                .collect(),
            dispatch_argument_provenance: MetalDispatchArgumentRunEvidenceV1 {
                actual_argument_capture_count: dispatch_count,
                trace_record_count: dispatch_count,
                argument_trace_mismatch_count: 0,
                invalid_dimension_count: 0,
                conversion_failure_count: 0,
                geometry_digest: String::new(),
            },
            buffer_binding_argument_provenance: MetalBufferBindingArgumentRunEvidenceV1 {
                actual_buffer_capture_count: 8,
                trace_record_count: 8,
                argument_trace_mismatch_count: 0,
                invalid_offset_count: 0,
                insufficient_span_count: 0,
                duplicate_binding_index_count: 0,
                missing_required_role_count: 0,
                unexpected_role_count: 0,
                binding_sequence_digest: String::new(),
            },
            pipeline_binding_argument_provenance: MetalPipelineBindingArgumentRunEvidenceV1 {
                pipeline_artifact_capture_count: 1,
                trace_record_count: 1,
                artifact_trace_mismatch_count: 0,
                incomplete_artifact_count: 0,
                invalid_pipeline_observation_count: 0,
                semantic_pipeline_digest: String::new(),
                pipeline_observation_digest: String::new(),
                pipeline_binding_sequence_digest: String::new(),
            },
            per_run_witness_delta: MetalPerRunWitnessDeltaV1 {
                command_buffers_created: 1,
                command_buffers_committed: 1,
                command_buffers_completed: 1,
                command_buffer_failures: 0,
                compute_encoders_created: 1,
                dispatches_attempted: dispatch_count,
                dispatches_performed: dispatch_count,
                output_readbacks: 1,
                state_readbacks: 1,
                output_poison_remaining: 0,
                state_poison_remaining: 0,
                cpu_fallback_attempts: 0,
                cpu_fallback_executions: 0,
            },
            output_digest: "sample-output".to_string(),
            final_state_digest: "sample-state".to_string(),
            semantic_trace_digest: String::new(),
        };
        trace.dispatch_argument_provenance.geometry_digest =
            metal_dispatch_geometry_digest_v1(&trace);
        trace
            .buffer_binding_argument_provenance
            .binding_sequence_digest = metal_buffer_binding_sequence_digest_v1(&trace);
        trace
            .pipeline_binding_argument_provenance
            .semantic_pipeline_digest = metal_pipeline_semantic_digest_v1(&trace);
        trace
            .pipeline_binding_argument_provenance
            .pipeline_observation_digest = metal_pipeline_observation_digest_v1(&trace);
        trace
            .pipeline_binding_argument_provenance
            .pipeline_binding_sequence_digest = metal_pipeline_binding_sequence_digest_v1(&trace);
        trace.semantic_trace_digest = metal_semantic_trace_digest_v1(&trace).unwrap();
        trace
    }

    #[cfg(all(target_os = "macos", feature = "backend-metal"))]
    fn p2r3_assert_mismatch_field_v1(
        original: &super::metal_execution::MetalSemanticRunTraceV1,
        mutated: &super::metal_execution::MetalSemanticRunTraceV1,
        expected_field: &str,
    ) {
        use super::metal_execution::compare_metal_semantic_run_traces_v1;
        assert!(
            compare_metal_semantic_run_traces_v1("sample", "original/original", original, original)
                .is_empty()
        );
        let mismatches =
            compare_metal_semantic_run_traces_v1("sample", "original/mutated", original, mutated);
        assert!(
            mismatches
                .iter()
                .any(|mismatch| mismatch.field == expected_field),
            "missing {expected_field}: {mismatches:?}"
        );
    }

