    #[cfg(all(target_os = "macos", feature = "backend-metal"))]
    #[test]
    fn m3_micro_p2r3r1_geometry_digest_uses_actual_invocation_sequence() {
        use super::metal_execution::{
            MetalDispatchInvocationV1, metal_dispatch_geometry_digest_v1,
            metal_semantic_dispatch_trace_from_invocation_v1,
        };
        let mut first = p2r3_sample_semantic_trace_v1(2);
        let invocations = [
            MetalDispatchInvocationV1::new(
                metal::MTLSize::new(5, 3, 1),
                metal::MTLSize::new(2, 1, 1),
                0,
                0,
            ),
            MetalDispatchInvocationV1::new(
                metal::MTLSize::new(9, 7, 1),
                metal::MTLSize::new(4, 2, 1),
                1,
                0,
            ),
        ];
        first.commands[0].encoders[0].dispatches = invocations
            .iter()
            .enumerate()
            .map(|(ordinal, invocation)| {
                metal_semantic_dispatch_trace_from_invocation_v1(ordinal, ordinal, 1, invocation)
                    .unwrap()
            })
            .collect();
        let first_digest = metal_dispatch_geometry_digest_v1(&first);
        let mut second = first.clone();
        let changed = MetalDispatchInvocationV1::new(
            metal::MTLSize::new(10, 7, 1),
            metal::MTLSize::new(4, 2, 1),
            1,
            0,
        );
        second.commands[0].encoders[0].dispatches[1] =
            metal_semantic_dispatch_trace_from_invocation_v1(1, 1, 1, &changed).unwrap();
        assert_eq!(first_digest, metal_dispatch_geometry_digest_v1(&first));
        assert_ne!(first_digest, metal_dispatch_geometry_digest_v1(&second));
    }

