    fn m3_micro_p2r3r2_binding_digest_excludes_object_identity() {
        use super::metal_execution::{
            MetalBufferAccessV2, MetalBufferBindingInvocationV1, MetalBufferRoleV2,
            metal_buffer_binding_trace_from_invocation_v1,
        };
        let first_buffer = p2r3r2_test_buffer_v1(64);
        let second_buffer = p2r3r2_test_buffer_v1(64);
        let first = MetalBufferBindingInvocationV1::new(
            &first_buffer,
            0,
            8,
            MetalBufferRoleV2::Input,
            MetalBufferAccessV2::ReadOnly,
            32,
        );
        let second = MetalBufferBindingInvocationV1::new(
            &second_buffer,
            0,
            8,
            MetalBufferRoleV2::Input,
            MetalBufferAccessV2::ReadOnly,
            32,
        );
        assert_eq!(
            metal_buffer_binding_trace_from_invocation_v1(0, &first).unwrap(),
            metal_buffer_binding_trace_from_invocation_v1(0, &second).unwrap()
        );
        let encoded = serde_json::to_string(
            &metal_buffer_binding_trace_from_invocation_v1(0, &first).unwrap(),
        )
        .unwrap();
        for forbidden in ["pointer", "address", "description", "timestamp", "device"] {
            assert!(!encoded.contains(forbidden));
        }
    }

