    #[cfg(all(target_os = "macos", feature = "backend-metal"))]
    #[test]
    fn m3_micro_p2r3_per_run_delta_is_not_cumulative_total() {
        use super::metal_execution::MetalPerRunWitnessDeltaV1;
        let mut before = MetalExecutionWitnessV1::default();
        before.command_buffer_count = 11;
        before.command_buffers_committed = 11;
        before.command_buffers_completed = 11;
        before.compute_encoder_count = 11;
        before.dispatches_attempted = 11;
        before.dispatch_count = 11;
        before.output_readback_count = 11;
        before.state_readback_count = 11;
        let mut after = before.clone();
        after.command_buffer_count += 2;
        after.command_buffers_committed += 2;
        after.command_buffers_completed += 2;
        after.compute_encoder_count += 2;
        after.dispatches_attempted += 2;
        after.dispatch_count += 2;
        after.output_readback_count += 2;
        after.state_readback_count += 2;
        let delta = MetalPerRunWitnessDeltaV1::between(&before, &after).unwrap();
        assert_eq!(delta.command_buffers_created, 2);
        assert_eq!(delta.dispatches_performed, 2);
        assert!(delta.successful());
    }

