    #[cfg(all(target_os = "macos", feature = "backend-metal"))]
    #[test]
    fn m3_micro_p2r3_topology_comparator_rejects_binding_drift() {
        let original = p2r3_sample_semantic_trace_v1(1);
        for (expected, mutate) in [
            (
                "commands[0].encoders[0].buffer_bindings[0].binding_index",
                0usize,
            ),
            (
                "commands[0].encoders[0].buffer_bindings[0].semantic_role",
                1,
            ),
            ("commands[0].encoders[0].buffer_bindings[0].byte_offset", 2),
            (
                "commands[0].encoders[0].buffer_bindings[0].actual_resource_length_bytes",
                3,
            ),
        ] {
            let mut mutated = original.clone();
            let binding = &mut mutated.commands[0].encoders[0].buffer_bindings[0];
            match mutate {
                0 => binding.binding_index = 9,
                1 => binding.semantic_role = super::metal_execution::MetalBufferRoleV2::Parameters,
                2 => binding.byte_offset = 4,
                3 => binding.actual_resource_length_bytes += 4,
                _ => unreachable!(),
            }
            p2r3_assert_mismatch_field_v1(&original, &mutated, expected);
        }
    }

