    #[cfg(all(target_os = "macos", feature = "backend-metal"))]
    #[test]
    fn m3_micro_p2_parameter_layout_is_complete() {
        let roster = test_roster();
        for agent in roster.agents() {
            let mut layout = M3MicroMetalLayoutV1::from_config(&agent.model.config).unwrap();
            layout.validate(&agent.model.config).unwrap();
            assert_eq!(layout.total_parameter_count, agent.model.parameter_count());
            assert_eq!(
                layout.parameter_offsets.len(),
                agent.model.config.block_count
            );
        }
    }

    #[cfg(all(target_os = "macos", feature = "backend-metal"))]
    #[test]
    fn m3_micro_p2r2_fault_policy_separates_required_and_optional() {
        use super::metal_execution::{
            MetalFaultIdentityV2, MetalNegativeEvidencePolicyV2, MetalRequiredFaultInjectionV2,
        };

        let policy = MetalNegativeEvidencePolicyV2::default();
        assert_eq!(policy.entries.len(), MetalFaultIdentityV2::ALL.len());
        assert_eq!(
            policy.required_faults(),
            MetalRequiredFaultInjectionV2::ALL.map(MetalRequiredFaultInjectionV2::identity)
        );
        assert_eq!(
            policy.optional_faults(),
            [MetalFaultIdentityV2::CommandBufferFailure]
        );
        assert!(policy.require_actual_executor_path);
        assert!(policy.require_observed_error_match);
        assert!(policy.require_no_cpu_fallback_execution);
        assert!(!policy.allow_synthetic_enum_only);
        assert!(!policy.identity().is_empty());
    }

    #[cfg(all(target_os = "macos", feature = "backend-metal"))]
    fn p2r1_fault_evidence(
        fault: super::metal_execution::MetalFaultIdentityV2,
    ) -> &'static super::metal_execution::MetalFaultEvidenceV1 {
        cached_metal_negative_evidence_v2()
            .as_ref()
            .unwrap()
            .1
            .iter()
            .find(|evidence| evidence.fault == fault)
            .unwrap()
    }

