    #[test]
    fn m3_micro_p2r1_metal_receipt_rejects_synthetic_negative_evidence() {
        let mut evidence = MetalFaultEvidenceReceiptV2 {
            fault: "MissingKernelFunction".to_string(),
            device_acquired: true,
            queue_created: true,
            library_created: true,
            function_lookup_attempted: true,
            observed_error: Some("MetalFunctionNotFound".to_string()),
            expected_error: "MetalFunctionNotFound".to_string(),
            genuine_fault_path_reached: true,
            passed: true,
            safe_injection_supported: true,
            ..MetalFaultEvidenceReceiptV2::default()
        };
        assert!(validate_fault_evidence_v2(&evidence));
        evidence.synthetic_enum_only = true;
        assert!(!validate_fault_evidence_v2(&evidence));
    }

