    #[cfg(all(target_os = "macos", feature = "backend-metal"))]
    #[test]
    #[ignore = "explicit actual Metal hardware conformance only"]
    fn m3_micro_p2_actual_metal_hardware_conformance() {
        let receipt = cached_metal_conformance_v1().as_ref().unwrap();
        validate_metal_receipt_v3_self(receipt).unwrap();
        let witness = &receipt.normal_execution.execution_witness;
        println!(
            "SPRINT104_P2_METAL device={} function={} command_buffers={} encoders={} dispatches={} completed={} failures={} error_none={} output_readbacks={} state_readbacks={} output_poison={} state_poison={} cpu_fallback={} output_digest={} state_digest={}",
            receipt.provenance.device_name,
            receipt.provenance.kernel_function_identity,
            witness.command_buffer_count,
            witness.compute_encoder_count,
            witness.dispatch_count,
            witness.command_buffers_completed,
            witness.command_buffer_failures,
            witness.command_error_none,
            witness.output_readback_count,
            witness.state_readback_count,
            witness.output_poison_remaining,
            witness.state_poison_remaining,
            witness.cpu_fallback_count,
            witness.output_digest,
            witness.final_state_digest,
        );
        for result in &receipt.parity.agent_results {
            println!(
                "SPRINT104_P2_PARITY agent={} lengths={:?} scenarios={} streaming_output_abs={} streaming_output_rel={} streaming_output_mismatch={} streaming_state_abs={} streaming_state_rel={} streaming_state_mismatch={} full_output_abs={} full_output_rel={} full_output_mismatch={} full_state_abs={} full_state_rel={} full_state_mismatch={} chunk_output_abs={} chunk_output_rel={} chunk_output_mismatch={} chunk_state_abs={} chunk_state_rel={} chunk_state_mismatch={} deterministic={} dispatches={} result_digest={}",
                result.agent_id,
                result.lengths,
                result.scenario_count,
                result.streaming_output.max_absolute_error,
                result.streaming_output.max_relative_error,
                result.streaming_output.mismatch_count,
                result.streaming_state.max_absolute_error,
                result.streaming_state.max_relative_error,
                result.streaming_state.mismatch_count,
                result.full_output.max_absolute_error,
                result.full_output.max_relative_error,
                result.full_output.mismatch_count,
                result.full_state.max_absolute_error,
                result.full_state.max_relative_error,
                result.full_state.mismatch_count,
                result.chunked_output.max_absolute_error,
                result.chunked_output.max_relative_error,
                result.chunked_output.mismatch_count,
                result.chunked_state.max_absolute_error,
                result.chunked_state.max_relative_error,
                result.chunked_state.mismatch_count,
                result.deterministic,
                result.execution_witness.dispatch_count,
                result.result_digest,
            );
        }
    }

