    #[cfg(all(target_os = "macos", feature = "backend-metal"))]
    #[test]
    fn m3_micro_p2r3r5_mutation_registry_covers_comparator_surface() {
        let registry = metal_topology_mutation_registry_v1();
        assert!(!registry.is_empty());
        assert!(registry.iter().all(|spec| spec.required));
        for category in [
            MetalTopologyMutationCategoryV1::TraceMetadata,
            MetalTopologyMutationCategoryV1::Command,
            MetalTopologyMutationCategoryV1::Encoder,
            MetalTopologyMutationCategoryV1::Pipeline,
            MetalTopologyMutationCategoryV1::BufferBinding,
            MetalTopologyMutationCategoryV1::Dispatch,
            MetalTopologyMutationCategoryV1::Witness,
            MetalTopologyMutationCategoryV1::Result,
        ] {
            assert!(
                registry
                    .iter()
                    .any(|spec| spec.expected_mismatch_kind == category)
            );
        }
        assert!(
            registry
                .iter()
                .any(|spec| matches!(spec.kind, MetalTopologyMutationKindV1::RemoveVector { .. }))
        );
        assert!(
            registry
                .iter()
                .any(|spec| matches!(spec.kind, MetalTopologyMutationKindV1::ReorderVector { .. }))
        );
    }

    #[test]
    #[ignore = "post-publication verification contract"]
    fn m3_micro_p2r3r5r2_replay_projection_comparator_rejects_semantic_mutations() {
        let receipt = read_metal_receipt_v11().unwrap();
        let runtime = metal_read_only_replay_persisted_projection_v1(&receipt).unwrap();
        assert!(
            compare_metal_read_only_replay_semantic_projections_v1(&runtime, &runtime).is_empty()
        );
        macro_rules! assert_mutation {
            ($field:ident) => {{
                let mut mutated = runtime.clone();
                mutated.$field += 1;
                assert_eq!(
                    compare_metal_read_only_replay_semantic_projections_v1(&runtime, &mutated),
                    vec![stringify!($field).to_string()]
                );
            }};
        }
        assert_mutation!(actual_ab_pair_count);
        assert_mutation!(executed_mutation_count);
        assert_mutation!(unresolved_topology_contract_count);
        let mut runtime_only_v4_surface = runtime.clone();
        runtime_only_v4_surface
            .actual_v4_topology_surface_digest
            .push_str("-fresh-runtime");
        assert!(
            compare_metal_read_only_replay_semantic_projections_v1(
                &runtime,
                &runtime_only_v4_surface,
            )
            .is_empty(),
            "the raw V4 surface digest is a runtime diagnostic, not a V11 semantic field",
        );

        for field in [
            "mutation_registry_digest",
            "mutation_result_digest",
            "topology_status",
        ] {
            let mut mutated = runtime.clone();
            match field {
                "mutation_registry_digest" => mutated.mutation_registry_digest.push('x'),
                "mutation_result_digest" => mutated.mutation_result_digest.push('x'),
                "topology_status" => mutated.topology_status.push('x'),
                _ => unreachable!(),
            }
            assert_eq!(
                compare_metal_read_only_replay_semantic_projections_v1(&runtime, &mutated),
                vec![field.to_string()]
            );
        }
    }

