    #[test]
    fn m3_micro_p2r3r5r2_replay_uses_shared_core_without_writer_dependencies() {
        let source = include_str!("m3_micro.rs");
        assert_eq!(
            source
                .matches("\n    fn execute_actual_m3_micro_topology_mutation_evidence_v1(")
                .count(),
            1
        );
        let generator = source
            .split("fn build_metal_receipt_v11()")
            .nth(1)
            .unwrap()
            .split("fn persist_metal_receipt_v11")
            .next()
            .unwrap();
        assert!(generator.contains("execute_actual_m3_micro_topology_mutation_evidence_v1()?"));

        let replay = source
            .split("\n    fn run_m3_micro_actual_hardware_read_only_replay_v1()\n")
            .nth(1)
            .unwrap()
            .split("fn build_delivery_receipt_v1()")
            .next()
            .unwrap();
        assert!(replay.contains("execute_actual_m3_micro_topology_mutation_evidence_v1()?"));
        assert!(
            replay.contains("validate_actual_m3_micro_topology_mutation_execution_v1(&panel)?")
        );
        assert!(replay.contains("metal_read_only_replay_runtime_projection_v1(&panel, &topology)"));
        assert!(!replay.contains("PassedActualSemanticCommandTopology.as_str()"));
        for writer_dependency in [
            "persist_metal_receipt_v11",
            "persist_delivery_receipt_v1",
            "OpenOptions",
            "write_all",
            "fs::rename",
            "fs::create_dir_all",
        ] {
            assert!(
                !replay.contains(writer_dependency),
                "read-only replay references writer dependency: {writer_dependency}"
            );
        }
    }

