    fn m3_micro_test_inventory_v1() -> Vec<M3MicroTestInventoryEntryV1> {
        let mut attributes = Vec::new();
        let mut inventory = Vec::new();
        for line in include_str!("m3_micro.rs").lines() {
            let trimmed = line.trim();
            if trimmed.starts_with("#[") {
                attributes.push(trimmed);
                continue;
            }
            if trimmed.is_empty() {
                continue;
            }
            let Some(function) = trimmed.strip_prefix("fn ") else {
                attributes.clear();
                continue;
            };
            if !attributes.contains(&"#[test]") {
                attributes.clear();
                continue;
            }
            let identity = function
                .split(['(', '<'])
                .next()
                .unwrap_or_default()
                .trim()
                .to_string();
            let ignored = attributes
                .iter()
                .any(|attribute| attribute.starts_with("#[ignore"));
            let (intent, heavy_attribution, frozen_v3, reason) =
                if R10_AUTHORITATIVE_GENERATORS.contains(&identity.as_str()) {
                    (
                        M3MicroTestIntentV1::AuthoritativeGenerator,
                        matches!(
                            identity.as_str(),
                            "m3_micro_r7_generate_authoritative_attribution_receipt"
                                | "m3_micro_r9_generate_commit_safe_authoritative_receipt"
                        ),
                        false,
                        "explicit receipt generator",
                    )
                } else if R10_CAPABILITY_TESTS.contains(&identity.as_str()) {
                    (
                        M3MicroTestIntentV1::CapabilityEvidence,
                        identity.contains("attribution")
                            || identity
                                == "m3_micro_reduced_candidate_contains_only_retained_groups_v2",
                        identity.contains("selective_forgetting_v3")
                            || identity == "m3_micro_reduced_candidate_runs_frozen_v3",
                        "explicit research capability evaluator",
                    )
                } else {
                    (
                        M3MicroTestIntentV1::DeliveryRegression,
                        false,
                        false,
                        "delivery contract or lightweight evidence consistency",
                    )
                };
            inventory.push(M3MicroTestInventoryEntryV1 {
                test_identity: identity,
                current_ignore_status: ignored,
                intent,
                heavy_attribution,
                frozen_v3,
                normal_full_library: !ignored,
                reason,
            });
            attributes.clear();
        }
        inventory
    }

    #[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
    struct HeavyEvidenceExecutionCountersV1 {
        attribution_evaluations: usize,
        frozen_v3_evaluations: usize,
        receipt_generations: usize,
    }

    impl HeavyEvidenceExecutionCountersV1 {
        fn snapshot() -> Self {
            Self {
                attribution_evaluations: R10_ATTRIBUTION_EVALUATIONS.load(Ordering::SeqCst),
                frozen_v3_evaluations: R10_FROZEN_V3_EVALUATIONS.load(Ordering::SeqCst),
                receipt_generations: R10_RECEIPT_GENERATIONS.load(Ordering::SeqCst),
            }
        }

        fn delta(self, before: Self) -> Self {
            Self {
                attribution_evaluations: self
                    .attribution_evaluations
                    .saturating_sub(before.attribution_evaluations),
                frozen_v3_evaluations: self
                    .frozen_v3_evaluations
                    .saturating_sub(before.frozen_v3_evaluations),
                receipt_generations: self
                    .receipt_generations
                    .saturating_sub(before.receipt_generations),
            }
        }

        fn is_zero(self) -> bool {
            self == Self::default()
        }
    }

