    fn delivery_candidate_test_module_suffix_v2(source: &[u8]) -> Result<&[u8], String> {
        let source = std::str::from_utf8(source).map_err(|error| error.to_string())?;
        let mut boundaries = source.match_indices(CAPABILITY_TEST_MODULE_BOUNDARY_V2);
        let Some((boundary, _)) = boundaries.next() else {
            return Err("missing top-level candidate test-module boundary".to_string());
        };
        if boundaries.next().is_some() {
            return Err("ambiguous top-level candidate test-module boundary".to_string());
        }
        let suffix = &source.as_bytes()[boundary..];
        if suffix.is_empty() {
            return Err("empty candidate test source".to_string());
        }
        Ok(suffix)
    }

    fn delivery_candidate_content_digest_v2(bytes: &[u8]) -> Result<String, String> {
        const HEX: &[u8; 16] = b"0123456789abcdef";
        let mut encoded = String::with_capacity(bytes.len().saturating_mul(2));
        for byte in bytes {
            encoded.push(HEX[(byte >> 4) as usize] as char);
            encoded.push(HEX[(byte & 0x0f) as usize] as char);
        }
        serde_json::to_string(&(
            DELIVERY_CANDIDATE_MANIFEST_POLICY_IDENTITY_V4,
            "actual-file-bytes-v1",
            bytes.len(),
            encoded,
        ))
        .map(|preimage| stable_hash_string(&preimage))
        .map_err(|error| error.to_string())
    }

    fn candidate_path_without_symlinks_v2(
        candidate_root: &Path,
        logical_repo_relative_path: &str,
    ) -> Result<PathBuf, DeliveryCandidateManifestErrorV2> {
        let relative = Path::new(logical_repo_relative_path);
        if relative.is_absolute()
            || relative
                .components()
                .any(|component| !matches!(component, std::path::Component::Normal(_)))
        {
            return Err(DeliveryCandidateManifestErrorV2::InvalidComponent(
                logical_repo_relative_path.to_string(),
            ));
        }
        let mut current = candidate_root.to_path_buf();
        for component in relative.components() {
            current.push(component.as_os_str());
            let metadata = fs::symlink_metadata(&current).map_err(|error| {
                if error.kind() == std::io::ErrorKind::NotFound {
                    DeliveryCandidateManifestErrorV2::MissingRequiredComponent(
                        logical_repo_relative_path.to_string(),
                    )
                } else {
                    DeliveryCandidateManifestErrorV2::Io(error.to_string())
                }
            })?;
            if metadata.file_type().is_symlink() {
                return Err(DeliveryCandidateManifestErrorV2::SymlinkComponent(
                    logical_repo_relative_path.to_string(),
                ));
            }
        }
        Ok(current)
    }

    fn delivery_candidate_tree_digest_v2(
        candidate_root: &Path,
        policy_entry: &DeliveryCandidateManifestPolicyEntryV2,
        policy: &DeliveryCandidateManifestPolicyV2,
    ) -> Result<String, DeliveryCandidateManifestErrorV2> {
        let tree_root = candidate_path_without_symlinks_v2(
            candidate_root,
            policy_entry.physical_repo_relative_path,
        )?;
        if !fs::symlink_metadata(&tree_root)
            .map_err(|error| DeliveryCandidateManifestErrorV2::Io(error.to_string()))?
            .is_dir()
        {
            return Err(DeliveryCandidateManifestErrorV2::InvalidComponent(
                policy_entry.logical_repo_relative_path.to_string(),
            ));
        }
        let excluded_files = policy
            .entries
            .iter()
            .filter(|entry| {
                !matches!(
                    entry.source,
                    DeliveryCandidateManifestEntrySourceV2::RustSourceTree
                        | DeliveryCandidateManifestEntrySourceV2::FileTree
                )
            })
            .map(|entry| entry.physical_repo_relative_path)
            .collect::<BTreeSet<_>>();
        let mut directories = vec![tree_root];
        let mut tree_entries = Vec::new();
        while let Some(directory) = directories.pop() {
            let mut children = fs::read_dir(&directory)
                .map_err(|error| DeliveryCandidateManifestErrorV2::Io(error.to_string()))?
                .collect::<Result<Vec<_>, _>>()
                .map_err(|error| DeliveryCandidateManifestErrorV2::Io(error.to_string()))?;
            children.sort_by_key(|entry| entry.file_name());
            for child in children {
                let path = child.path();
                let relative = path.strip_prefix(candidate_root).map_err(|_| {
                    DeliveryCandidateManifestErrorV2::InvalidComponent(
                        policy_entry.logical_repo_relative_path.to_string(),
                    )
                })?;
                let relative = relative
                    .components()
                    .map(|component| component.as_os_str().to_str())
                    .collect::<Option<Vec<_>>>()
                    .ok_or_else(|| {
                        DeliveryCandidateManifestErrorV2::InvalidComponent(
                            "non-UTF-8 candidate tree path".to_string(),
                        )
                    })?
                    .join("/");
                let metadata = fs::symlink_metadata(&path)
                    .map_err(|error| DeliveryCandidateManifestErrorV2::Io(error.to_string()))?;
                if metadata.file_type().is_symlink() {
                    return Err(DeliveryCandidateManifestErrorV2::SymlinkComponent(relative));
                }
                if metadata.is_dir() {
                    directories.push(path);
                    continue;
                }
                if !metadata.is_file() {
                    return Err(DeliveryCandidateManifestErrorV2::InvalidComponent(relative));
                }
                if policy_entry.source == DeliveryCandidateManifestEntrySourceV2::RustSourceTree
                    && path.extension().and_then(|extension| extension.to_str()) != Some("rs")
                {
                    continue;
                }
                if excluded_files.contains(relative.as_str()) {
                    continue;
                }
                let bytes = fs::read(&path)
                    .map_err(|error| DeliveryCandidateManifestErrorV2::Io(error.to_string()))?;
                if bytes.is_empty() {
                    return Err(DeliveryCandidateManifestErrorV2::InvalidComponent(relative));
                }
                tree_entries.push((
                    relative,
                    delivery_candidate_content_digest_v2(&bytes)
                        .map_err(DeliveryCandidateManifestErrorV2::Io)?,
                ));
            }
        }
        tree_entries.sort();
        if tree_entries.is_empty() {
            return Err(DeliveryCandidateManifestErrorV2::InvalidComponent(
                policy_entry.logical_repo_relative_path.to_string(),
            ));
        }
        serde_json::to_string(&(
            policy.policy_identity,
            "actual-file-tree-v1",
            policy_entry.logical_repo_relative_path,
            tree_entries.len(),
            tree_entries,
        ))
        .map(|preimage| stable_hash_string(&preimage))
        .map_err(|error| DeliveryCandidateManifestErrorV2::Io(error.to_string()))
    }

    fn audit_unexpected_delivery_candidate_sources_v2(
        candidate_root: &Path,
        policy: &DeliveryCandidateManifestPolicyV2,
    ) -> Result<(), DeliveryCandidateManifestErrorV2> {
        let model_dir = candidate_path_without_symlinks_v2(candidate_root, "src/model")?;
        let expected = policy
            .entries
            .iter()
            .map(|entry| entry.physical_repo_relative_path)
            .collect::<BTreeSet<_>>();
        for entry in fs::read_dir(model_dir)
            .map_err(|error| DeliveryCandidateManifestErrorV2::Io(error.to_string()))?
        {
            let entry =
                entry.map_err(|error| DeliveryCandidateManifestErrorV2::Io(error.to_string()))?;
            let name = entry.file_name().into_string().map_err(|_| {
                DeliveryCandidateManifestErrorV2::InvalidComponent(
                    "non-UTF-8 candidate source name".to_string(),
                )
            })?;
            if !name.starts_with("m3_micro") || !name.ends_with(".rs") {
                continue;
            }
            let logical = format!("src/model/{name}");
            let file_type = entry
                .file_type()
                .map_err(|error| DeliveryCandidateManifestErrorV2::Io(error.to_string()))?;
            if file_type.is_symlink() {
                return Err(DeliveryCandidateManifestErrorV2::SymlinkComponent(logical));
            }
            if !file_type.is_file() || !expected.contains(logical.as_str()) {
                return Err(DeliveryCandidateManifestErrorV2::UnexpectedComponent(
                    logical,
                ));
            }
        }
        Ok(())
    }

    fn canonical_delivery_candidate_manifest_v2(
        mut entries: Vec<DeliveryCandidateManifestEntryV2>,
    ) -> Result<DeliveryCandidateManifestV2, DeliveryCandidateManifestErrorV2> {
        let policy = current_delivery_candidate_manifest_policy_v2();
        let required = policy
            .entries
            .iter()
            .map(|entry| (entry.class, entry.logical_repo_relative_path.to_string()))
            .collect::<BTreeSet<_>>();
        let mut observed = BTreeSet::new();
        for entry in &entries {
            if entry.logical_repo_relative_path.is_empty() || entry.content_digest.is_empty() {
                return Err(DeliveryCandidateManifestErrorV2::InvalidComponent(
                    entry.logical_repo_relative_path.clone(),
                ));
            }
            let key = (entry.class, entry.logical_repo_relative_path.clone());
            if !required.contains(&key) {
                return Err(DeliveryCandidateManifestErrorV2::UnexpectedComponent(
                    entry.logical_repo_relative_path.clone(),
                ));
            }
            if !observed.insert(key) {
                return Err(DeliveryCandidateManifestErrorV2::DuplicateComponent(
                    entry.logical_repo_relative_path.clone(),
                ));
            }
        }
        if let Some((_, missing)) = required.difference(&observed).next() {
            return Err(DeliveryCandidateManifestErrorV2::MissingRequiredComponent(
                missing.clone(),
            ));
        }
        for class in [
            DeliveryCandidateComponentClassV2::ProjectSource,
            DeliveryCandidateComponentClassV2::TestSource,
            DeliveryCandidateComponentClassV2::CandidateVerificationConfig,
        ] {
            if !entries.iter().any(|entry| entry.class == class) {
                return Err(DeliveryCandidateManifestErrorV2::EmptySemanticClass(class));
            }
        }
        entries.sort();
        let manifest_digest =
            serde_json::to_string(&(policy.policy_identity, entries.len(), &entries))
                .map(|preimage| stable_hash_string(&preimage))
                .map_err(|error| DeliveryCandidateManifestErrorV2::Io(error.to_string()))?;
        Ok(DeliveryCandidateManifestV2 {
            policy_identity: policy.policy_identity.to_string(),
            entries,
            manifest_digest,
        })
    }

    fn derive_delivery_candidate_manifest_v2(
        candidate_root: &Path,
    ) -> Result<DeliveryCandidateManifestV2, DeliveryCandidateManifestErrorV2> {
        let root_metadata = fs::symlink_metadata(candidate_root)
            .map_err(|_| DeliveryCandidateManifestErrorV2::InvalidRoot)?;
        if !root_metadata.is_dir() || root_metadata.file_type().is_symlink() {
            return Err(DeliveryCandidateManifestErrorV2::InvalidRoot);
        }
        let policy = current_delivery_candidate_manifest_policy_v2();
        audit_unexpected_delivery_candidate_sources_v2(candidate_root, &policy)?;
        let entries = policy
            .entries
            .iter()
            .map(|policy_entry| {
                if matches!(
                    policy_entry.source,
                    DeliveryCandidateManifestEntrySourceV2::RustSourceTree
                        | DeliveryCandidateManifestEntrySourceV2::FileTree
                ) {
                    return Ok(DeliveryCandidateManifestEntryV2 {
                        class: policy_entry.class,
                        logical_repo_relative_path: policy_entry
                            .logical_repo_relative_path
                            .to_string(),
                        content_digest: delivery_candidate_tree_digest_v2(
                            candidate_root,
                            policy_entry,
                            &policy,
                        )?,
                    });
                }
                let path = candidate_path_without_symlinks_v2(
                    candidate_root,
                    policy_entry.physical_repo_relative_path,
                )?;
                let metadata = fs::symlink_metadata(&path)
                    .map_err(|error| DeliveryCandidateManifestErrorV2::Io(error.to_string()))?;
                if !metadata.is_file() {
                    return Err(DeliveryCandidateManifestErrorV2::InvalidComponent(
                        policy_entry.physical_repo_relative_path.to_string(),
                    ));
                }
                let file_bytes = fs::read(path)
                    .map_err(|error| DeliveryCandidateManifestErrorV2::Io(error.to_string()))?;
                if file_bytes.is_empty() {
                    return Err(DeliveryCandidateManifestErrorV2::InvalidComponent(
                        policy_entry.physical_repo_relative_path.to_string(),
                    ));
                }
                let semantic_bytes = match policy_entry.source {
                    DeliveryCandidateManifestEntrySourceV2::WholeFile => file_bytes.as_slice(),
                    DeliveryCandidateManifestEntrySourceV2::ProductionPrefix => {
                        capability_production_prefix_v2(&file_bytes).map_err(|_| {
                            DeliveryCandidateManifestErrorV2::InvalidComponent(
                                policy_entry.physical_repo_relative_path.to_string(),
                            )
                        })?
                    }
                    DeliveryCandidateManifestEntrySourceV2::TestModuleSuffix => {
                        delivery_candidate_test_module_suffix_v2(&file_bytes).map_err(|_| {
                            DeliveryCandidateManifestErrorV2::InvalidComponent(
                                policy_entry.physical_repo_relative_path.to_string(),
                            )
                        })?
                    }
                    DeliveryCandidateManifestEntrySourceV2::RustSourceTree
                    | DeliveryCandidateManifestEntrySourceV2::FileTree => unreachable!(),
                };
                Ok(DeliveryCandidateManifestEntryV2 {
                    class: policy_entry.class,
                    logical_repo_relative_path: policy_entry.logical_repo_relative_path.to_string(),
                    content_digest: delivery_candidate_content_digest_v2(semantic_bytes)
                        .map_err(DeliveryCandidateManifestErrorV2::Io)?,
                })
            })
            .collect::<Result<Vec<_>, DeliveryCandidateManifestErrorV2>>()?;
        canonical_delivery_candidate_manifest_v2(entries)
    }

    fn delivery_candidate_class_manifest_digest_v2(
        manifest: &DeliveryCandidateManifestV2,
        class: DeliveryCandidateComponentClassV2,
    ) -> Result<Option<String>, DeliveryCandidateManifestErrorV2> {
        let entries = manifest
            .entries
            .iter()
            .filter(|entry| entry.class == class)
            .collect::<Vec<_>>();
        if entries.is_empty() {
            return Ok(None);
        }
        serde_json::to_string(&(
            manifest.policy_identity.as_str(),
            class,
            entries.len(),
            entries,
        ))
        .map(|preimage| Some(stable_hash_string(&preimage)))
        .map_err(|error| DeliveryCandidateManifestErrorV2::Io(error.to_string()))
    }

