    #[derive(Clone, Debug, PartialEq, Eq)]
    struct ValidatedDeliverySuiteExecutionEvidenceV1 {
        observation: DeliverySuiteExecutionObservationV1,
        semantic_digest: String,
    }

    fn validate_validated_delivery_suite_execution_evidence_v1(
        evidence: &ValidatedDeliverySuiteExecutionEvidenceV1,
    ) -> Result<(), DeliveryDirectBindingErrorV1> {
        let validated = validate_delivery_suite_execution_observation_v1(&evidence.observation)?;
        if validated.semantic_digest != evidence.semantic_digest {
            return Err(DeliveryDirectBindingErrorV1::InvalidValidatedEvidence);
        }
        Ok(())
    }

    #[derive(Clone, Debug, PartialEq, Eq)]
    struct FullIntegrationCleanDirectBindingEvidenceV1 {
        policy_identity: String,
        main_candidate_scope_identity: VerifiedDeliveryCandidateScopeIdentityV2,
        clean_candidate_scope_identity: VerifiedDeliveryCandidateScopeIdentityV2,
        validated_execution_evidence: Vec<ValidatedDeliverySuiteExecutionEvidenceV1>,
        required_suite_set_digest: String,
        execution_set_digest: String,
        candidate_equivalence: bool,
    }

    fn validate_full_integration_clean_direct_binding_v1(
        evidence: &[ValidatedDeliverySuiteExecutionEvidenceV1],
    ) -> Result<FullIntegrationCleanDirectBindingEvidenceV1, DeliveryDirectBindingErrorV1> {
        let required = current_required_delivery_suite_executions_v1()
            .into_iter()
            .collect::<BTreeSet<_>>();
        if required.is_empty() {
            return Err(DeliveryDirectBindingErrorV1::EmptyRequiredSuiteSet);
        }
        let mut observed = BTreeMap::new();
        for item in evidence {
            validate_validated_delivery_suite_execution_evidence_v1(item)?;
            let key = DeliveryRequiredSuiteExecutionV1 {
                suite_identity: item.observation.suite_identity(),
                execution_scope: item.observation.execution_scope(),
            };
            if !required.contains(&key) {
                return Err(DeliveryDirectBindingErrorV1::UnknownEvidence(key));
            }
            if observed.insert(key, item.clone()).is_some() {
                return Err(DeliveryDirectBindingErrorV1::DuplicateEvidence(key));
            }
        }
        for key in &required {
            if !observed.contains_key(key) {
                return Err(DeliveryDirectBindingErrorV1::MissingRequiredEvidence(*key));
            }
        }

        let main_candidates = observed
            .values()
            .filter(|item| item.observation.execution_scope() == DeliveryExecutionScopeV1::Main)
            .map(|item| item.observation.candidate_scope_identity().clone())
            .collect::<BTreeSet<_>>();
        let clean_candidates = observed
            .values()
            .filter(|item| {
                item.observation.execution_scope() == DeliveryExecutionScopeV1::CleanDetached
            })
            .map(|item| item.observation.candidate_scope_identity().clone())
            .collect::<BTreeSet<_>>();
        if main_candidates.len() != 1 {
            return Err(DeliveryDirectBindingErrorV1::MainCandidateInconsistent);
        }
        if clean_candidates.len() != 1 {
            return Err(DeliveryDirectBindingErrorV1::CleanCandidateInconsistent);
        }
        let main_candidate_scope_identity = main_candidates.into_iter().next().unwrap();
        let clean_candidate_scope_identity = clean_candidates.into_iter().next().unwrap();
        if main_candidate_scope_identity != clean_candidate_scope_identity {
            return Err(DeliveryDirectBindingErrorV1::MainCleanCandidateMismatch);
        }

        let validated_execution_evidence = observed.into_values().collect::<Vec<_>>();
        let required_suite_set_digest = required_delivery_suite_set_digest_v1()
            .map_err(|_| DeliveryDirectBindingErrorV1::InvalidValidatedEvidence)?;
        let execution_identities = validated_execution_evidence
            .iter()
            .map(|item| {
                (
                    item.observation.suite_identity(),
                    item.observation.execution_scope(),
                    item.semantic_digest.as_str(),
                )
            })
            .collect::<Vec<_>>();
        let execution_set_digest = serde_json::to_string(&(
            FULL_INTEGRATION_CLEAN_DIRECT_BINDING_POLICY_IDENTITY_V1,
            &required_suite_set_digest,
            execution_identities,
        ))
        .map(|preimage| stable_hash_string(&preimage))
        .map_err(|_| DeliveryDirectBindingErrorV1::InvalidValidatedEvidence)?;
        Ok(FullIntegrationCleanDirectBindingEvidenceV1 {
            policy_identity: FULL_INTEGRATION_CLEAN_DIRECT_BINDING_POLICY_IDENTITY_V1.to_string(),
            main_candidate_scope_identity,
            clean_candidate_scope_identity,
            validated_execution_evidence,
            required_suite_set_digest,
            execution_set_digest,
            candidate_equivalence: true,
        })
    }

    enum DeliveryExecutionEvidenceSetV3<'a> {
        Actual(&'a [ValidatedActualD2ExecutionEvidenceV3]),
        SyntheticFixture(&'a [ValidatedDeliverySuiteExecutionEvidenceV1]),
    }

    fn evaluate_full_integration_clean_delivery_check_v1(
        evidence: Option<DeliveryExecutionEvidenceSetV3<'_>>,
    ) -> Result<String, String> {
        let evidence = evidence.ok_or_else(|| {
            format!(
                "{:?}",
                DeliveryDirectBindingErrorV1::MissingActualExecutionEvidence
            )
        })?;
        match evidence {
            DeliveryExecutionEvidenceSetV3::Actual(actual) => {
                evaluate_full_integration_clean_actual_evidence_v3(actual)
            }
            DeliveryExecutionEvidenceSetV3::SyntheticFixture(synthetic) => {
                let _ = validate_full_integration_clean_direct_binding_v1(synthetic)
                    .map_err(|error| format!("{error:?}"))?;
                Err(format!(
                    "{:?}",
                    DeliveryDirectBindingErrorV1::SyntheticEvidenceIsNotActual
                ))
            }
        }
    }

    fn parse_delivery_cargo_test_summary_v1(
        stdout: &str,
        stderr: &str,
    ) -> Result<DeliveryTestOutcomeCountsV1, String> {
        let summaries = stdout
            .lines()
            .chain(stderr.lines())
            .map(str::trim)
            .filter(|line| line.starts_with("test result: "))
            .collect::<Vec<_>>();
        if summaries.len() != 1 {
            return Err(format!(
                "expected exactly one cargo test summary, observed {}",
                summaries.len()
            ));
        }
        let summary = summaries[0]
            .strip_prefix("test result: ")
            .ok_or_else(|| "missing cargo test summary prefix".to_string())?;
        let (reported_success, fields) = if let Some(fields) = summary.strip_prefix("ok. ") {
            (true, fields)
        } else if let Some(fields) = summary.strip_prefix("FAILED. ") {
            (false, fields)
        } else {
            return Err("unknown cargo test summary status".to_string());
        };
        let fields = fields.split("; ").collect::<Vec<_>>();
        if fields.len() != 6 || !fields[5].starts_with("finished in ") {
            return Err("unexpected cargo test summary grammar".to_string());
        }
        let parse_count = |field: &str, suffix: &str| -> Result<usize, String> {
            field
                .strip_suffix(suffix)
                .ok_or_else(|| format!("missing cargo test summary field: {suffix}"))?
                .parse::<usize>()
                .map_err(|error| error.to_string())
        };
        let passed_count = parse_count(fields[0], " passed")?;
        let failed_count = parse_count(fields[1], " failed")?;
        let ignored_count = parse_count(fields[2], " ignored")?;
        let measured_count = parse_count(fields[3], " measured")?;
        let _filtered_count = parse_count(fields[4], " filtered out")?;
        if reported_success != (failed_count == 0) {
            return Err("cargo test summary status/count mismatch".to_string());
        }
        let selected_count = passed_count
            .checked_add(failed_count)
            .and_then(|count| count.checked_add(ignored_count))
            .and_then(|count| count.checked_add(measured_count))
            .ok_or_else(|| "cargo test summary count overflow".to_string())?;
        let counts = DeliveryTestOutcomeCountsV1 {
            selected_count,
            passed_count,
            failed_count,
            ignored_count,
            measured_count,
        };
        if counts.checked_outcome_count() != Some(counts.selected_count) {
            return Err("cargo test summary count inconsistency".to_string());
        }
        Ok(counts)
    }

    fn checked_add_delivery_test_outcomes_v1(
        total: DeliveryTestOutcomeCountsV1,
        child: DeliveryTestOutcomeCountsV1,
    ) -> Result<DeliveryTestOutcomeCountsV1, String> {
        let add = |left: usize, right: usize| {
            left.checked_add(right)
                .ok_or_else(|| "delivery test outcome aggregation overflow".to_string())
        };
        let aggregate = DeliveryTestOutcomeCountsV1 {
            selected_count: add(total.selected_count, child.selected_count)?,
            passed_count: add(total.passed_count, child.passed_count)?,
            failed_count: add(total.failed_count, child.failed_count)?,
            ignored_count: add(total.ignored_count, child.ignored_count)?,
            measured_count: add(total.measured_count, child.measured_count)?,
        };
        if aggregate.checked_outcome_count() != Some(aggregate.selected_count) {
            return Err("aggregated delivery test outcome count mismatch".to_string());
        }
        Ok(aggregate)
    }

    fn d2_command_output_tail_v1(output: &[u8]) -> String {
        String::from_utf8_lossy(output)
            .lines()
            .rev()
            .take(20)
            .collect::<Vec<_>>()
            .into_iter()
            .rev()
            .collect::<Vec<_>>()
            .join("\n")
    }

    struct D2ParentLogV1 {
        file: fs::File,
        sequence: u64,
        completed: bool,
        last_stage: String,
    }

    impl D2ParentLogV1 {
        fn create(log_root: &Path) -> Result<Self, String> {
            let file = OpenOptions::new()
                .write(true)
                .create_new(true)
                .open(log_root.join("d2-parent.log"))
                .map_err(|error| error.to_string())?;
            Ok(Self {
                file,
                sequence: 0,
                completed: false,
                last_stage: "INITIALIZATION".to_string(),
            })
        }

        fn append(&mut self, event: &str, details: &str) -> Result<(), String> {
            if event.is_empty()
                || event.contains(char::is_whitespace)
                || event.contains(['\r', '\n'])
                || details.contains(['\r', '\n'])
            {
                return Err("invalid parent log event".to_string());
            }
            self.sequence = self
                .sequence
                .checked_add(1)
                .ok_or_else(|| "parent log sequence overflow".to_string())?;
            writeln!(self.file, "{:06} {event} {details}", self.sequence)
                .and_then(|_| self.file.sync_data())
                .map_err(|error| error.to_string())?;
            self.last_stage = event.to_string();
            Ok(())
        }

        fn complete(&mut self) -> Result<(), String> {
            self.append("RUN_COMPLETE", "status=PASSED")?;
            self.completed = true;
            Ok(())
        }
    }

    impl Drop for D2ParentLogV1 {
        fn drop(&mut self) {
            if !self.completed {
                let _ = self.append(
                    "RUN_BLOCKED",
                    &format!(
                        "stage={} status=ERROR error_class=UnhandledClosureError",
                        self.last_stage
                    ),
                );
            }
        }
    }

    #[derive(Default)]
    struct D2OwnedChildSequenceV1 {
        active: bool,
        completed: usize,
    }

    impl D2OwnedChildSequenceV1 {
        fn begin(&mut self) -> Result<(), String> {
            if self.active {
                return Err("D2-owned child execution overlap".to_string());
            }
            self.active = true;
            Ok(())
        }

        fn finish(&mut self) -> Result<(), String> {
            if !self.active {
                return Err("D2-owned child completion without an active child".to_string());
            }
            self.active = false;
            self.completed = self
                .completed
                .checked_add(1)
                .ok_or_else(|| "D2-owned child count overflow".to_string())?;
            Ok(())
        }

        fn completed(&self) -> usize {
            self.completed
        }
    }

    #[derive(Clone, Debug, PartialEq, Eq)]
    struct D2ProcessSnapshotRecordV1 {
        pid: u32,
        ppid: u32,
        command: String,
        args: String,
    }

    fn parse_d2_process_snapshot_line_v1(line: &str) -> Result<D2ProcessSnapshotRecordV1, String> {
        let take_field = |remaining: &mut &str| -> Result<String, String> {
            *remaining = remaining.trim_start();
            if remaining.is_empty() {
                return Err("process snapshot field is missing".to_string());
            }
            let boundary = remaining
                .find(char::is_whitespace)
                .unwrap_or(remaining.len());
            let field = remaining[..boundary].to_string();
            *remaining = &remaining[boundary..];
            Ok(field)
        };
        let mut remaining = line;
        let pid = take_field(&mut remaining)?
            .parse::<u32>()
            .map_err(|error| format!("invalid process PID: {error}"))?;
        let ppid = take_field(&mut remaining)?
            .parse::<u32>()
            .map_err(|error| format!("invalid process PPID: {error}"))?;
        let command = take_field(&mut remaining)?;
        if pid == 0 {
            return Err("process PID must be non-zero".to_string());
        }
        Ok(D2ProcessSnapshotRecordV1 {
            pid,
            ppid,
            command,
            args: remaining.trim_start().to_string(),
        })
    }

    fn d2_rust_process_executable_v1(record: &D2ProcessSnapshotRecordV1) -> Option<&str> {
        let executable = Path::new(&record.command)
            .file_name()
            .and_then(|name| name.to_str())
            .unwrap_or(&record.command);
        matches!(executable, "cargo" | "rustc" | "cargo-nextest" | "nextest").then_some(executable)
    }

    fn conflicting_external_rust_processes_v1(
        snapshot: &[D2ProcessSnapshotRecordV1],
        current_pid: u32,
    ) -> Result<Vec<&D2ProcessSnapshotRecordV1>, String> {
        let mut records_by_pid = BTreeMap::new();
        for record in snapshot {
            if records_by_pid.insert(record.pid, record).is_some() {
                return Err(format!("duplicate process PID: {}", record.pid));
            }
        }
        let mut ancestry = BTreeSet::new();
        let mut cursor = current_pid;
        loop {
            if !ancestry.insert(cursor) {
                return Err("process ancestry cycle detected".to_string());
            }
            let record = records_by_pid
                .get(&cursor)
                .ok_or_else(|| format!("process ancestry PID is missing: {cursor}"))?;
            if record.ppid == 0 {
                break;
            }
            cursor = record.ppid;
        }
        Ok(snapshot
            .iter()
            .filter(|record| {
                record.pid != current_pid
                    && !ancestry.contains(&record.pid)
                    && d2_rust_process_executable_v1(record).is_some()
            })
            .collect())
    }

    fn d2_unrelated_rust_processes_do_not_block_v1(
        _snapshot: &[D2ProcessSnapshotRecordV1],
        _current_pid: u32,
    ) -> Result<(), String> {
        Ok(())
    }

    #[cfg(all(target_os = "macos", feature = "backend-metal"))]
    fn persist_d2_raw_process_log_v1(
        log_path: &Path,
        stdout: &[u8],
        stderr: &[u8],
    ) -> Result<(), String> {
        let mut file = OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(log_path)
            .map_err(|error| error.to_string())?;
        file.write_all(format!("SOMA_D2_STDOUT_BYTES={}\n", stdout.len()).as_bytes())
            .and_then(|_| file.write_all(stdout))
            .and_then(|_| {
                file.write_all(format!("\nSOMA_D2_STDERR_BYTES={}\n", stderr.len()).as_bytes())
            })
            .and_then(|_| file.write_all(stderr))
            .and_then(|_| file.sync_all())
            .map_err(|error| error.to_string())
    }

    #[cfg(all(target_os = "macos", feature = "backend-metal"))]
    fn run_d2_cargo_test_command_v1(
        candidate_root: &Path,
        target_directory: &Path,
        command_arguments: &[String],
        log_path: &Path,
        child_sequence: &mut D2OwnedChildSequenceV1,
    ) -> Result<(DeliveryTestOutcomeCountsV1, u128), String> {
        let started = std::time::Instant::now();
        child_sequence.begin()?;
        let output = Command::new("cargo")
            .args(command_arguments)
            .env("CARGO_BUILD_JOBS", "1")
            .env("CARGO_INCREMENTAL", "0")
            .env("CARGO_NET_OFFLINE", "true")
            .env("CARGO_TARGET_DIR", target_directory)
            .current_dir(candidate_root)
            .output();
        child_sequence.finish()?;
        let output = output.map_err(|error| error.to_string())?;
        let duration_milliseconds = started.elapsed().as_millis();
        persist_d2_raw_process_log_v1(log_path, &output.stdout, &output.stderr)?;
        let stdout = String::from_utf8(output.stdout.clone()).map_err(|error| error.to_string())?;
        let stderr = String::from_utf8(output.stderr.clone()).map_err(|error| error.to_string())?;
        let counts = parse_delivery_cargo_test_summary_v1(&stdout, &stderr).map_err(|error| {
            format!(
                "{error}; status={}; stdout_tail={:?}; stderr_tail={:?}",
                output.status,
                d2_command_output_tail_v1(&output.stdout),
                d2_command_output_tail_v1(&output.stderr)
            )
        })?;
        if !output.status.success()
            || counts.selected_count == 0
            || counts.passed_count == 0
            || counts.failed_count != 0
        {
            return Err(format!(
                "cargo test contract failed; status={}; counts={counts:?}; stdout_tail={:?}; stderr_tail={:?}",
                output.status,
                d2_command_output_tail_v1(&output.stdout),
                d2_command_output_tail_v1(&output.stderr)
            ));
        }
        Ok((counts, duration_milliseconds))
    }

    #[cfg(all(target_os = "macos", feature = "backend-metal"))]
    fn d2_copy_candidate_file_v1(
        main_root: &Path,
        clean_root: &Path,
        relative_path: &Path,
    ) -> Result<(), String> {
        let source = main_root.join(relative_path);
        let metadata = fs::symlink_metadata(&source).map_err(|error| error.to_string())?;
        if !metadata.is_file() || metadata.file_type().is_symlink() {
            return Err(format!(
                "candidate materialization source is not a regular file: {}",
                relative_path.display()
            ));
        }
        let destination = clean_root.join(relative_path);
        let parent = destination
            .parent()
            .ok_or_else(|| "candidate destination parent is missing".to_string())?;
        fs::create_dir_all(parent).map_err(|error| error.to_string())?;
        fs::copy(&source, &destination).map_err(|error| error.to_string())?;
        Ok(())
    }

    #[cfg(all(target_os = "macos", feature = "backend-metal"))]
    fn d2_collect_candidate_tree_files_v1(
        root: &Path,
        rust_only: bool,
    ) -> Result<Vec<PathBuf>, String> {
        let metadata = fs::symlink_metadata(root).map_err(|error| error.to_string())?;
        if !metadata.is_dir() || metadata.file_type().is_symlink() {
            return Err(format!("candidate tree is invalid: {}", root.display()));
        }
        let mut directories = vec![root.to_path_buf()];
        let mut files = Vec::new();
        while let Some(directory) = directories.pop() {
            let mut children = fs::read_dir(&directory)
                .map_err(|error| error.to_string())?
                .collect::<Result<Vec<_>, _>>()
                .map_err(|error| error.to_string())?;
            children.sort_by_key(|entry| entry.file_name());
            for child in children {
                let path = child.path();
                let metadata = fs::symlink_metadata(&path).map_err(|error| error.to_string())?;
                if metadata.file_type().is_symlink() {
                    return Err(format!(
                        "candidate tree contains symlink: {}",
                        path.display()
                    ));
                }
                if metadata.is_dir() {
                    directories.push(path);
                } else if metadata.is_file()
                    && (!rust_only
                        || path.extension().and_then(|extension| extension.to_str()) == Some("rs"))
                {
                    files.push(path);
                } else if !metadata.is_file() {
                    return Err(format!(
                        "candidate tree contains non-file entry: {}",
                        path.display()
                    ));
                }
            }
        }
        files.sort();
        Ok(files)
    }

    #[cfg(all(target_os = "macos", feature = "backend-metal"))]
    fn d2_materialize_candidate_tree_v1(
        main_root: &Path,
        clean_root: &Path,
        relative_root: &Path,
        rust_only: bool,
    ) -> Result<(), String> {
        let source_root = main_root.join(relative_root);
        let destination_root = clean_root.join(relative_root);
        if rust_only {
            for destination in d2_collect_candidate_tree_files_v1(&destination_root, true)? {
                fs::remove_file(destination).map_err(|error| error.to_string())?;
            }
        } else {
            let metadata =
                fs::symlink_metadata(&destination_root).map_err(|error| error.to_string())?;
            if !metadata.is_dir() || metadata.file_type().is_symlink() {
                return Err(format!(
                    "candidate destination tree is invalid: {}",
                    destination_root.display()
                ));
            }
            fs::remove_dir_all(&destination_root).map_err(|error| error.to_string())?;
            fs::create_dir_all(&destination_root).map_err(|error| error.to_string())?;
        }
        for source in d2_collect_candidate_tree_files_v1(&source_root, rust_only)? {
            let relative = source
                .strip_prefix(main_root)
                .map_err(|error| error.to_string())?;
            d2_copy_candidate_file_v1(main_root, clean_root, relative)?;
        }
        Ok(())
    }

    #[cfg(all(target_os = "macos", feature = "backend-metal"))]
    fn materialize_current_delivery_candidate_v1(
        main_root: &Path,
        clean_root: &Path,
    ) -> Result<(), String> {
        let policy = current_delivery_candidate_manifest_policy_v2();
        for entry in policy.entries {
            let relative_path = Path::new(entry.physical_repo_relative_path);
            match entry.source {
                DeliveryCandidateManifestEntrySourceV2::RustSourceTree => {
                    d2_materialize_candidate_tree_v1(main_root, clean_root, relative_path, true)?;
                }
                DeliveryCandidateManifestEntrySourceV2::FileTree => {
                    d2_materialize_candidate_tree_v1(main_root, clean_root, relative_path, false)?;
                }
                DeliveryCandidateManifestEntrySourceV2::WholeFile
                | DeliveryCandidateManifestEntrySourceV2::ProductionPrefix
                | DeliveryCandidateManifestEntrySourceV2::TestModuleSuffix => {
                    d2_copy_candidate_file_v1(main_root, clean_root, relative_path)?;
                }
            }
        }
        Ok(())
    }

    fn d2_git_output_v1(candidate_root: &Path, arguments: &[&str]) -> Result<String, String> {
        let output = Command::new("git")
            .args(arguments)
            .current_dir(candidate_root)
            .output()
            .map_err(|error| error.to_string())?;
        if !output.status.success() {
            return Err(format!(
                "git {} failed with status {}: {}",
                arguments.join(" "),
                output.status,
                d2_command_output_tail_v1(&output.stderr)
            ));
        }
        String::from_utf8(output.stdout)
            .map(|stdout| stdout.trim().to_string())
            .map_err(|error| error.to_string())
    }

    fn d2_candidate_policy_covers_path_v1(relative_path: &str) -> bool {
        current_delivery_candidate_manifest_policy_v2()
            .entries
            .into_iter()
            .any(|entry| match entry.source {
                DeliveryCandidateManifestEntrySourceV2::RustSourceTree => relative_path
                    .strip_prefix(entry.physical_repo_relative_path)
                    .is_some_and(|suffix| suffix.starts_with('/') && suffix.ends_with(".rs")),
                DeliveryCandidateManifestEntrySourceV2::FileTree => relative_path
                    .strip_prefix(entry.physical_repo_relative_path)
                    .is_some_and(|suffix| suffix.starts_with('/')),
                DeliveryCandidateManifestEntrySourceV2::WholeFile
                | DeliveryCandidateManifestEntrySourceV2::ProductionPrefix
                | DeliveryCandidateManifestEntrySourceV2::TestModuleSuffix => {
                    relative_path == entry.physical_repo_relative_path
                }
            })
    }

    fn validate_d2_clean_project_state_v1(clean_root: &Path) -> Result<String, String> {
        let output = Command::new("git")
            .args(["status", "--porcelain=v1", "-z", "--untracked-files=all"])
            .current_dir(clean_root)
            .output()
            .map_err(|error| error.to_string())?;
        if !output.status.success() {
            return Err("clean project state query failed".to_string());
        }
        let mut entries = Vec::new();
        for encoded in output.stdout.split(|byte| *byte == 0) {
            if encoded.is_empty() {
                continue;
            }
            if encoded.len() < 4 || encoded[2] != b' ' {
                return Err("unexpected clean project status grammar".to_string());
            }
            let status = std::str::from_utf8(&encoded[..2]).map_err(|error| error.to_string())?;
            if status.contains('R') || status.contains('C') {
                return Err("renamed/copied clean candidate entry is not allowed".to_string());
            }
            let path = std::str::from_utf8(&encoded[3..]).map_err(|error| error.to_string())?;
            let relative = Path::new(path);
            if relative.is_absolute()
                || relative
                    .components()
                    .any(|component| !matches!(component, std::path::Component::Normal(_)))
                || !d2_candidate_policy_covers_path_v1(path)
            {
                return Err(format!(
                    "clean project state contains unrelated change: {status} {path}"
                ));
            }
            entries.push((status.to_string(), path.to_string()));
        }
        entries.sort();
        serde_json::to_string(&entries)
            .map(|preimage| stable_hash_string(&preimage))
            .map_err(|error| error.to_string())
    }

    fn verify_d2_clean_detached_environment_identity_v1(
        clean_root: &Path,
        expected_head: &str,
    ) -> Result<String, String> {
        let head = d2_git_output_v1(clean_root, &["rev-parse", "HEAD"])?;
        if head != expected_head {
            return Err("CleanDetached HEAD differs from runtime base HEAD".to_string());
        }
        let symbolic = Command::new("git")
            .args(["symbolic-ref", "-q", "HEAD"])
            .current_dir(clean_root)
            .output()
            .map_err(|error| error.to_string())?;
        if symbolic.status.success() {
            return Err("CleanDetached checkout is attached to a branch".to_string());
        }
        let state_digest = validate_d2_clean_project_state_v1(clean_root)?;
        serde_json::to_string(&(expected_head, "Detached", state_digest))
            .map(|preimage| stable_hash_string(&preimage))
            .map_err(|error| error.to_string())
    }

    #[cfg(all(target_os = "macos", feature = "backend-metal"))]
    fn d2_current_checkout_identity_v1(candidate_root: &Path) -> Result<String, String> {
        let head = d2_git_output_v1(candidate_root, &["rev-parse", "HEAD"])?;
        let branch = Command::new("git")
            .args(["symbolic-ref", "--quiet", "--short", "HEAD"])
            .current_dir(candidate_root)
            .output()
            .map_err(|error| error.to_string())?;
        let branch = if branch.status.success() {
            String::from_utf8(branch.stdout)
                .map_err(|error| error.to_string())?
                .trim()
                .to_string()
        } else {
            "Detached".to_string()
        };
        let status = Command::new("git")
            .args(["status", "--porcelain=v1", "--untracked-files=all"])
            .current_dir(candidate_root)
            .output()
            .map_err(|error| error.to_string())?;
        if !status.status.success() {
            return Err("checkout status query failed".to_string());
        }
        serde_json::to_string(&(head, branch, status.stdout))
            .map(|preimage| stable_hash_string(&preimage))
            .map_err(|error| error.to_string())
    }

    #[cfg(all(target_os = "macos", feature = "backend-metal"))]
    fn d2_assert_candidate_checkpoint_v1(
        parent_log: &mut D2ParentLogV1,
        candidate_root: &Path,
        frozen: &VerifiedDeliveryCandidateScopeIdentityV2,
        checkpoint: &str,
    ) -> Result<(), String> {
        let current = derive_delivery_candidate_scope_identity_v2(candidate_root)
            .map_err(|error| format!("{checkpoint} manifest failure: {error:?}"))?;
        if current != *frozen {
            parent_log.append(
                "CANDIDATE_CHECKPOINT",
                &format!(
                    "checkpoint={checkpoint} status=MISMATCH expected={} actual={}",
                    frozen.aggregate_manifest_digest(),
                    current.aggregate_manifest_digest()
                ),
            )?;
            return Err(format!("candidate drift at {checkpoint}"));
        }
        parent_log.append(
            "CANDIDATE_CHECKPOINT",
            &format!(
                "checkpoint={checkpoint} status=MATCH candidate={}",
                current.aggregate_manifest_digest()
            ),
        )?;
        println!(
            "SPRINT104_D2_CANDIDATE_CHECKPOINT checkpoint={checkpoint} aggregate={}",
            current.aggregate_manifest_digest()
        );
        Ok(())
    }

    #[cfg(all(target_os = "macos", feature = "backend-metal"))]
    fn run_d2_suite_counts_v1(
        candidate_root: &Path,
        target_directory: &Path,
        log_root: &Path,
        suite_identity: DeliverySuiteIdentityV1,
        execution_scope: DeliveryExecutionScopeV1,
        child_sequence: &mut D2OwnedChildSequenceV1,
    ) -> Result<(DeliveryTestOutcomeCountsV1, u128), String> {
        let scope = format!("{execution_scope:?}");
        let scope_slug = match execution_scope {
            DeliveryExecutionScopeV1::Main => "main",
            DeliveryExecutionScopeV1::CleanDetached => "clean",
            DeliveryExecutionScopeV1::Unknown => {
                return Err("unknown D2 delivery execution scope".to_string());
            }
        };
        match suite_identity {
            DeliverySuiteIdentityV1::FullDefaultLibrary => {
                let arguments = ["test", "--lib", "--", "--test-threads=1"]
                    .into_iter()
                    .map(str::to_string)
                    .collect::<Vec<_>>();
                let log_path = log_root.join(format!("{scope_slug}-default.log"));
                run_d2_cargo_test_command_v1(
                    candidate_root,
                    target_directory,
                    &arguments,
                    &log_path,
                    child_sequence,
                )
                .map_err(|error| {
                    format!("{scope} Default Full: {error}; log={}", log_path.display())
                })
            }
            DeliverySuiteIdentityV1::FullMetalLibrary => {
                let arguments = [
                    "test",
                    "--lib",
                    "--features",
                    "backend-metal",
                    "--",
                    "--test-threads=1",
                ]
                .into_iter()
                .map(str::to_string)
                .collect::<Vec<_>>();
                let log_path = log_root.join(format!("{scope_slug}-metal.log"));
                run_d2_cargo_test_command_v1(
                    candidate_root,
                    target_directory,
                    &arguments,
                    &log_path,
                    child_sequence,
                )
                .map_err(|error| format!("{scope} Metal Full: {error}; log={}", log_path.display()))
            }
            DeliverySuiteIdentityV1::IntegrationTargets => {
                let mut aggregate = DeliveryTestOutcomeCountsV1 {
                    selected_count: 0,
                    passed_count: 0,
                    failed_count: 0,
                    ignored_count: 0,
                    measured_count: 0,
                };
                let mut aggregate_duration_milliseconds = 0_u128;
                for target_path in DELIVERY_CANDIDATE_INTEGRATION_TARGET_PATHS_V4 {
                    let target = Path::new(target_path)
                        .file_stem()
                        .and_then(|stem| stem.to_str())
                        .ok_or_else(|| format!("invalid integration target path: {target_path}"))?;
                    let arguments = [
                        "test".to_string(),
                        "--test".to_string(),
                        target.to_string(),
                        "--".to_string(),
                        "--test-threads=1".to_string(),
                    ];
                    let log_path = log_root.join(format!("{scope_slug}-integration-{target}.log"));
                    let (counts, duration_milliseconds) = run_d2_cargo_test_command_v1(
                        candidate_root,
                        target_directory,
                        &arguments,
                        &log_path,
                        child_sequence,
                    )
                    .map_err(|error| {
                        format!(
                            "{scope} integration target {target}: {error}; log={}",
                            log_path.display()
                        )
                    })?;
                    aggregate = checked_add_delivery_test_outcomes_v1(aggregate, counts)?;
                    aggregate_duration_milliseconds = aggregate_duration_milliseconds
                        .checked_add(duration_milliseconds)
                        .ok_or_else(|| "integration duration overflow".to_string())?;
                    println!(
                        "SPRINT104_D2_INTEGRATION_TARGET scope={scope} target={target} selected={} passed={} failed={} ignored={} measured={} duration_ms={duration_milliseconds} log={}",
                        counts.selected_count,
                        counts.passed_count,
                        counts.failed_count,
                        counts.ignored_count,
                        counts.measured_count,
                        log_path.display(),
                    );
                }
                Ok((aggregate, aggregate_duration_milliseconds))
            }
            DeliverySuiteIdentityV1::Unknown => {
                Err("unknown D2 delivery suite identity".to_string())
            }
        }
    }

    #[cfg(all(target_os = "macos", feature = "backend-metal"))]
    fn run_d2_suite_observation_v1(
        candidate_root: &Path,
        target_directory: &Path,
        log_root: &Path,
        suite_identity: DeliverySuiteIdentityV1,
        execution_scope: DeliveryExecutionScopeV1,
        clean_authority: Option<VerifiedCleanDetachedExecutionEnvironmentV1>,
        checkout_provenance_identity: &str,
        child_sequence: &mut D2OwnedChildSequenceV1,
        parent_log: &mut D2ParentLogV1,
    ) -> Result<ValidatedActualD2ExecutionEvidenceV3, String> {
        let (counts, duration_milliseconds) = run_d2_suite_counts_v1(
            candidate_root,
            target_directory,
            log_root,
            suite_identity,
            execution_scope,
            child_sequence,
        )?;
        let observation = build_actual_d2_execution_observation_v3(
            candidate_root,
            suite_identity,
            execution_scope,
            counts,
            true,
            clean_authority,
            DeliveryExecutionNonSemanticMetadataV1 {
                worktree_path: candidate_root.display().to_string(),
                target_directory: target_directory.display().to_string(),
                duration_milliseconds,
                checkout_provenance_identity: checkout_provenance_identity.to_string(),
            },
        )
        .map_err(|error| format!("Actual observation build failed: {error:?}"))?;
        println!(
            "SPRINT104_D2_ACTUAL_OBSERVATION suite={suite_identity:?} scope={execution_scope:?} origin=ActualD2Execution candidate={} selected={} passed={} failed={} ignored={} measured={} duration_ms={} evidence_digest={}",
            observation
                .candidate_scope_identity()
                .aggregate_manifest_digest(),
            counts.selected_count,
            counts.passed_count,
            counts.failed_count,
            counts.ignored_count,
            counts.measured_count,
            duration_milliseconds,
            observation.execution_semantic_digest(),
        );
        let validated = validate_actual_d2_execution_observation_v3(&observation)
            .map_err(|error| format!("Actual observation validation failed: {error:?}"))?;
        parent_log.append(
            "ACTUAL_OBSERVATION",
            &format!(
                "suite={suite_identity:?} scope={execution_scope:?} candidate={} origin=ActualD2Execution selected={} passed={} failed={} ignored={} measured={} digest={}",
                observation.candidate_scope_identity().aggregate_manifest_digest(),
                counts.selected_count,
                counts.passed_count,
                counts.failed_count,
                counts.ignored_count,
                counts.measured_count,
                observation.execution_semantic_digest(),
            ),
        )?;
        Ok(validated)
    }

    #[cfg(all(target_os = "macos", feature = "backend-metal"))]
    fn run_d2_post_publication_checks_v1(
        candidate_root: &Path,
        target_directory: &Path,
        log_root: &Path,
        child_sequence: &mut D2OwnedChildSequenceV1,
        parent_log: &mut D2ParentLogV1,
    ) -> Result<(), String> {
        for (test_identity, ignored) in [
            (
                "model::m3_micro::tests::m3_micro_p2r1_metal_receipt_v1_is_superseded_negative_evidence",
                true,
            ),
            (
                "model::m3_micro::tests::m3_micro_r10p1_legacy_r7_roundtrip_accepts_detached_head",
                false,
            ),
            (
                "model::m3_micro::tests::m3_micro_d1r3d_functional_report_matches_source_state",
                true,
            ),
            (
                "model::m3_micro::tests::m3_micro_r9_receipt_is_current_for_semantic_subject",
                true,
            ),
            (
                "model::m3_micro::tests::m3_micro_d2r3r1_delivery_receipt_is_current",
                true,
            ),
            (
                "model::m3_micro::tests::m3_micro_p2r3r5_receipt_requires_actual_ab_mutation_baseline",
                true,
            ),
        ] {
            let test_name = test_identity
                .rsplit("::")
                .next()
                .ok_or_else(|| "invalid post-publication test identity".to_string())?;
            parent_log.append(
                "POST_PUBLICATION_RESULT",
                &format!("test={test_identity} status=STARTED"),
            )?;
            let mut arguments = vec![
                "test".to_string(),
                "--lib".to_string(),
                "--features".to_string(),
                "backend-metal".to_string(),
                test_identity.to_string(),
                "--".to_string(),
                "--exact".to_string(),
                "--nocapture".to_string(),
                "--test-threads=1".to_string(),
            ];
            if ignored {
                arguments.push("--ignored".to_string());
            }
            let log_path = log_root.join(format!("post-publication-{test_name}.log"));
            let (counts, _) = run_d2_cargo_test_command_v1(
                candidate_root,
                target_directory,
                &arguments,
                &log_path,
                child_sequence,
            )
            .map_err(|error| format!("post-publication {test_identity}: {error}"))?;
            parent_log.append(
                "POST_PUBLICATION_RESULT",
                &format!(
                    "test={test_identity} status=PASSED selected={} passed={} failed={}",
                    counts.selected_count, counts.passed_count, counts.failed_count
                ),
            )?;
        }
        Ok(())
    }

    #[cfg(all(target_os = "macos", feature = "backend-metal"))]
    fn execute_d2_final_delivery_closure_v1() -> Result<(), String> {
        if std::env::var("SOMA_M3_R10_D2_EXECUTE").as_deref() != Ok("1") {
            return Err("SOMA_M3_R10_D2_EXECUTE=1 is required".to_string());
        }
        let main_root =
            fs::canonicalize(env!("CARGO_MANIFEST_DIR")).map_err(|error| error.to_string())?;
        let clean_root = PathBuf::from(
            std::env::var("SOMA_M3_R10_D2_CLEAN_ROOT")
                .map_err(|_| "SOMA_M3_R10_D2_CLEAN_ROOT is required".to_string())?,
        );
        let main_target = PathBuf::from(
            std::env::var("SOMA_M3_R10_D2_MAIN_TARGET")
                .map_err(|_| "SOMA_M3_R10_D2_MAIN_TARGET is required".to_string())?,
        );
        let clean_target = PathBuf::from(
            std::env::var("SOMA_M3_R10_D2_CLEAN_TARGET")
                .map_err(|_| "SOMA_M3_R10_D2_CLEAN_TARGET is required".to_string())?,
        );
        let log_root = PathBuf::from(
            std::env::var("SOMA_M3_R10_D2_LOG_ROOT")
                .map_err(|_| "SOMA_M3_R10_D2_LOG_ROOT is required".to_string())?,
        );
        if !clean_root.is_absolute()
            || !main_target.is_absolute()
            || !clean_target.is_absolute()
            || !log_root.is_absolute()
            || clean_root == main_root
            || main_target == clean_target
            || clean_root.exists()
        {
            return Err("invalid task-owned D2 path configuration".to_string());
        }
        let clean_parent = clean_root
            .parent()
            .ok_or_else(|| "CleanDetached parent is missing".to_string())?;
        if !clean_parent.is_dir() {
            return Err("CleanDetached parent does not exist".to_string());
        }
        if main_target.parent() != Some(clean_parent)
            || clean_target.parent() != Some(clean_parent)
            || log_root.parent() != Some(clean_parent)
            || log_root.starts_with(&main_root)
        {
            return Err("D2 paths do not share the fresh task-owned root".to_string());
        }
        fs::create_dir_all(&main_target).map_err(|error| error.to_string())?;
        fs::create_dir_all(&clean_target).map_err(|error| error.to_string())?;
        fs::create_dir_all(&log_root).map_err(|error| error.to_string())?;
        let mut parent_log = D2ParentLogV1::create(&log_root)?;
        parent_log.append(
            "RUN_START",
            &format!("invocation=1 log_root={}", log_root.display()),
        )?;

        let base_head = d2_git_output_v1(&main_root, &["rev-parse", "HEAD"])?;
        parent_log.append("GIT_BASE", &format!("head={base_head}"))?;
        let main_frozen = derive_delivery_candidate_scope_identity_v2(&main_root)
            .map_err(|error| format!("BlockedByCandidateManifest: {error:?}"))?;
        parent_log.append(
            "CANDIDATE_FREEZE",
            &format!(
                "policy={} aggregate={}",
                main_frozen.policy_identity(),
                main_frozen.aggregate_manifest_digest()
            ),
        )?;
        parent_log.append(
            "MAIN_CANDIDATE",
            &format!("aggregate={}", main_frozen.aggregate_manifest_digest()),
        )?;
        println!(
            "SPRINT104_D2_SOURCE_FREEZE head={base_head} policy={} project={} test={} config={} aggregate={}",
            main_frozen.policy_identity(),
            main_frozen.project_source_manifest_digest(),
            main_frozen.test_source_manifest_digest(),
            main_frozen
                .candidate_config_manifest_digest()
                .unwrap_or("missing"),
            main_frozen.aggregate_manifest_digest(),
        );

        let worktree_output = Command::new("git")
            .args(["worktree", "add", "--detach"])
            .arg(&clean_root)
            .arg(&base_head)
            .current_dir(&main_root)
            .output()
            .map_err(|error| error.to_string())?;
        if !worktree_output.status.success() {
            return Err(format!(
                "BlockedByCleanDetachedSetup: {}",
                d2_command_output_tail_v1(&worktree_output.stderr)
            ));
        }
        materialize_current_delivery_candidate_v1(&main_root, &clean_root)
            .map_err(|error| format!("BlockedByCandidateMaterialization: {error}"))?;
        let clean_authority =
            verify_clean_detached_execution_environment_v1(&clean_root, &base_head)
                .map_err(|error| format!("BlockedByCleanProjectState: {error}"))?;
        let clean_checkout_identity = clean_authority.checkout_provenance_identity().to_string();
        let main_checkout_identity = d2_current_checkout_identity_v1(&main_root)?;
        let clean_frozen = derive_delivery_candidate_scope_identity_v2(&clean_root)
            .map_err(|error| format!("BlockedByCandidateManifest: {error:?}"))?;
        parent_log.append(
            "CLEAN_CANDIDATE",
            &format!("aggregate={}", clean_frozen.aggregate_manifest_digest()),
        )?;
        parent_log.append(
            "CLEAN_AUTHORITY_ISSUED",
            &format!(
                "candidate={} checkout_provenance={}",
                clean_frozen.aggregate_manifest_digest(),
                clean_checkout_identity
            ),
        )?;
        if main_frozen != clean_frozen {
            return Err("BlockedByMainCleanCandidateMismatch".to_string());
        }
        parent_log.append(
            "MAIN_CLEAN_PRE_EQUALITY",
            &format!(
                "status=MATCH candidate={}",
                main_frozen.aggregate_manifest_digest()
            ),
        )?;
        println!(
            "SPRINT104_D2_CLEAN_ENVIRONMENT head={base_head} state=Detached project_state=VERIFIED provenance={} candidate={} equality=MATCH",
            clean_checkout_identity,
            clean_frozen.aggregate_manifest_digest(),
        );

        let mut actual_evidence = Vec::new();
        let mut child_sequence = D2OwnedChildSequenceV1::default();
        actual_evidence.push(
            run_d2_suite_observation_v1(
                &main_root,
                &main_target,
                &log_root,
                DeliverySuiteIdentityV1::FullDefaultLibrary,
                DeliveryExecutionScopeV1::Main,
                None,
                &main_checkout_identity,
                &mut child_sequence,
                &mut parent_log,
            )
            .map_err(|error| format!("BlockedByMainDefaultFull: {error}"))?,
        );
        parent_log.append("MAIN_DEFAULT_RESULT", "status=PASSED")?;
        d2_assert_candidate_checkpoint_v1(&mut parent_log, &main_root, &main_frozen, "Main-A")
            .map_err(|error| format!("BlockedByCandidateDriftDuringClosure: {error}"))?;
        actual_evidence.push(
            run_d2_suite_observation_v1(
                &main_root,
                &main_target,
                &log_root,
                DeliverySuiteIdentityV1::FullMetalLibrary,
                DeliveryExecutionScopeV1::Main,
                None,
                &main_checkout_identity,
                &mut child_sequence,
                &mut parent_log,
            )
            .map_err(|error| format!("BlockedByMainMetalFull: {error}"))?,
        );
        parent_log.append("MAIN_METAL_RESULT", "status=PASSED")?;
        d2_assert_candidate_checkpoint_v1(&mut parent_log, &main_root, &main_frozen, "Main-B")
            .map_err(|error| format!("BlockedByCandidateDriftDuringClosure: {error}"))?;
        actual_evidence.push(
            run_d2_suite_observation_v1(
                &main_root,
                &main_target,
                &log_root,
                DeliverySuiteIdentityV1::IntegrationTargets,
                DeliveryExecutionScopeV1::Main,
                None,
                &main_checkout_identity,
                &mut child_sequence,
                &mut parent_log,
            )
            .map_err(|error| format!("BlockedByMainIntegration: {error}"))?,
        );
        parent_log.append("MAIN_INTEGRATION_RESULT", "status=PASSED")?;
        d2_assert_candidate_checkpoint_v1(&mut parent_log, &main_root, &main_frozen, "Main-Post")
            .map_err(|error| format!("BlockedByCandidateDriftDuringClosure: {error}"))?;

        actual_evidence.push(
            run_d2_suite_observation_v1(
                &clean_root,
                &clean_target,
                &log_root,
                DeliverySuiteIdentityV1::FullDefaultLibrary,
                DeliveryExecutionScopeV1::CleanDetached,
                Some(clean_authority.clone()),
                &clean_checkout_identity,
                &mut child_sequence,
                &mut parent_log,
            )
            .map_err(|error| format!("BlockedByCleanDefaultFull: {error}"))?,
        );
        parent_log.append("CLEAN_DEFAULT_RESULT", "status=PASSED")?;
        d2_assert_candidate_checkpoint_v1(&mut parent_log, &clean_root, &clean_frozen, "Clean-A")
            .map_err(|error| format!("BlockedByCandidateDriftDuringClosure: {error}"))?;
        actual_evidence.push(
            run_d2_suite_observation_v1(
                &clean_root,
                &clean_target,
                &log_root,
                DeliverySuiteIdentityV1::FullMetalLibrary,
                DeliveryExecutionScopeV1::CleanDetached,
                Some(clean_authority.clone()),
                &clean_checkout_identity,
                &mut child_sequence,
                &mut parent_log,
            )
            .map_err(|error| format!("BlockedByCleanMetalFull: {error}"))?,
        );
        parent_log.append("CLEAN_METAL_RESULT", "status=PASSED")?;
        d2_assert_candidate_checkpoint_v1(&mut parent_log, &clean_root, &clean_frozen, "Clean-B")
            .map_err(|error| format!("BlockedByCandidateDriftDuringClosure: {error}"))?;
        actual_evidence.push(
            run_d2_suite_observation_v1(
                &clean_root,
                &clean_target,
                &log_root,
                DeliverySuiteIdentityV1::IntegrationTargets,
                DeliveryExecutionScopeV1::CleanDetached,
                Some(clean_authority),
                &clean_checkout_identity,
                &mut child_sequence,
                &mut parent_log,
            )
            .map_err(|error| format!("BlockedByCleanIntegration: {error}"))?,
        );
        parent_log.append("CLEAN_INTEGRATION_RESULT", "status=PASSED")?;
        d2_assert_candidate_checkpoint_v1(
            &mut parent_log,
            &clean_root,
            &clean_frozen,
            "Clean-Post",
        )
        .map_err(|error| format!("BlockedByCandidateDriftDuringClosure: {error}"))?;

        let direct_binding =
            validate_full_integration_clean_actual_evidence_v3(&actual_evidence)
                .map_err(|error| format!("BlockedByActualEvidenceValidation: {error:?}"))?;
        let direct_binding_digest =
            evaluate_full_integration_clean_actual_evidence_v3(&actual_evidence)
                .map_err(|error| format!("BlockedByFullIntegrationCleanDirectBinding: {error}"))?;
        if direct_binding.execution_set_digest != direct_binding_digest
            || !direct_binding.candidate_equivalence
            || actual_evidence.len() != current_required_delivery_suite_executions_v1().len()
        {
            return Err("BlockedByFullIntegrationCleanDirectBinding".to_string());
        }
        parent_log.append(
            "ACTUAL_EVIDENCE_INVENTORY",
            &format!("actual={} synthetic=0", actual_evidence.len()),
        )?;
        parent_log.append(
            "DIRECT_BINDING",
            &format!(
                "status=PASSED required_set={} execution_set={} candidate={}",
                direct_binding.required_suite_set_digest,
                direct_binding.execution_set_digest,
                direct_binding
                    .main_candidate_scope_identity
                    .aggregate_manifest_digest()
            ),
        )?;
        parent_log.append("PUBLICATION_GATE", "status=OPEN")?;
        println!(
            "SPRINT104_D2_DIRECT_BINDING status=PASSED actual={} synthetic=0 required_set={} execution_set={} candidate={}",
            actual_evidence.len(),
            direct_binding.required_suite_set_digest,
            direct_binding.execution_set_digest,
            direct_binding
                .main_candidate_scope_identity
                .aggregate_manifest_digest(),
        );
        d2_assert_candidate_checkpoint_v1(
            &mut parent_log,
            &main_root,
            &main_frozen,
            "Pre-Publication-Main",
        )
        .map_err(|error| format!("BlockedByCandidateDriftDuringClosure: {error}"))?;
        d2_assert_candidate_checkpoint_v1(
            &mut parent_log,
            &clean_root,
            &clean_frozen,
            "Pre-Publication-Clean",
        )
        .map_err(|error| format!("BlockedByCandidateDriftDuringClosure: {error}"))?;

        let capability_pre = read_authoritative_receipt_v2()
            .map_err(|error| format!("BlockedByCapabilityCurrentness: {error}"))?;
        validate_receipt_v2_self(&capability_pre)
            .map_err(|error| format!("BlockedByCapabilityCurrentness: {error}"))?;
        let capability_publication = if validate_receipt_v2_currentness(&capability_pre).is_ok() {
            "NOT_NEEDED"
        } else {
            R10_RECEIPT_GENERATIONS.fetch_add(1, Ordering::SeqCst);
            let generated = build_authoritative_receipt_v2()
                .map_err(|error| format!("BlockedByCapabilityCurrentness: {error}"))?;
            persist_authoritative_receipt_v2(&generated)
                .map_err(|error| format!("BlockedByCapabilityCurrentness: {error}"))?;
            "DONE"
        };
        let capability = read_authoritative_receipt_v2()
            .map_err(|error| format!("BlockedByCapabilityCurrentness: {error}"))?;
        validate_receipt_v2_currentness(&capability)
            .map_err(|error| format!("BlockedByCapabilityCurrentness: {error}"))?;
        println!(
            "SPRINT104_D2_CAPABILITY pre_self=PASSED publication={capability_publication} post_currentness=PASSED model={} digest={}",
            capability.capability_status.as_str(),
            capability.receipt_digest,
        );
        parent_log.append(
            "CAPABILITY_DECISION",
            &format!(
                "publication={capability_publication} model={} digest={}",
                capability.capability_status.as_str(),
                capability.receipt_digest
            ),
        )?;
        parent_log.append("CAPABILITY_CURRENTNESS", "status=PASSED")?;

        let metal_pre = read_metal_receipt_v11()
            .map_err(|error| format!("BlockedByMetalCurrentness: {error}"))?;
        validate_metal_receipt_v11_self(&metal_pre)
            .map_err(|error| format!("BlockedByMetalCurrentness: {error}"))?;
        let metal_publication = if validate_metal_receipt_v11_currentness(&metal_pre).is_ok() {
            "NOT_NEEDED"
        } else {
            P2_METAL_RECEIPT_GENERATIONS.fetch_add(1, Ordering::SeqCst);
            let generated = build_metal_receipt_v11()
                .map_err(|error| format!("BlockedByMetalCurrentness: {error}"))?;
            persist_metal_receipt_v11(&generated)
                .map_err(|error| format!("BlockedByMetalCurrentness: {error}"))?;
            "DONE"
        };
        let metal = read_metal_receipt_v11()
            .map_err(|error| format!("BlockedByMetalCurrentness: {error}"))?;
        validate_metal_receipt_v11_currentness(&metal)
            .map_err(|error| format!("BlockedByMetalCurrentness: {error}"))?;
        println!(
            "SPRINT104_D2_METAL pre_self=PASSED publication={metal_publication} post_currentness=PASSED topology={} digest={}",
            metal.topology_status.as_str(),
            metal.receipt_digest,
        );
        parent_log.append(
            "METAL_DECISION",
            &format!(
                "publication={metal_publication} topology={} digest={}",
                metal.topology_status.as_str(),
                metal.receipt_digest
            ),
        )?;
        parent_log.append("METAL_CURRENTNESS", "status=PASSED")?;

        let delivery = build_delivery_receipt_with_actual_evidence_v1(&actual_evidence)
            .map_err(|error| format!("BlockedByDeliveryVerification: {error}"))?;
        if delivery.default_summary.status != VerificationCheckStatusV1::Passed
            || delivery.metal_summary.status != VerificationCheckStatusV1::Passed
            || delivery.delivery_status != M3MicroDeliveryStatusV1::Passed.as_str()
        {
            let blockers = delivery
                .default_summary
                .checks
                .iter()
                .chain(delivery.metal_summary.checks.iter())
                .filter_map(|check| {
                    (check.status != VerificationCheckStatusV1::Passed)
                        .then(|| format!("{}:{:?}", check.identity, check.blocker))
                })
                .collect::<Vec<_>>();
            return Err(format!(
                "BlockedByUnexpectedRequiredDeliveryCheck: {}",
                blockers.join(",")
            ));
        }
        R10_RECEIPT_GENERATIONS.fetch_add(1, Ordering::SeqCst);
        persist_delivery_receipt_v1(&delivery)
            .map_err(|error| format!("BlockedByDeliveryCurrentness: {error}"))?;
        let reopened = read_delivery_receipt_v1()
            .map_err(|error| format!("BlockedByDeliveryCurrentness: {error}"))?;
        validate_delivery_receipt_currentness_v1(&reopened)
            .map_err(|error| format!("BlockedByDeliveryCurrentness: {error}"))?;
        println!(
            "SPRINT104_D2_DELIVERY plan={} binding={} default={}/{}/{}/{} metal={}/{}/{}/{} delivery={} overall={} digest={}",
            reopened.verification_plan_identity,
            direct_binding_digest,
            reopened.default_summary.required_count,
            reopened.default_summary.passed_count,
            reopened.default_summary.failed_count,
            reopened.default_summary.not_run_count,
            reopened.metal_summary.required_count,
            reopened.metal_summary.passed_count,
            reopened.metal_summary.failed_count,
            reopened.metal_summary.not_run_count,
            reopened.delivery_status,
            reopened.overall_status,
            reopened.receipt_digest,
        );
        parent_log.append(
            "DELIVERY_DECISION",
            &format!(
                "status={} overall={} digest={}",
                reopened.delivery_status, reopened.overall_status, reopened.receipt_digest
            ),
        )?;
        parent_log.append("DELIVERY_CURRENTNESS", "status=PASSED")?;
        for check in reopened
            .default_summary
            .checks
            .iter()
            .chain(reopened.metal_summary.checks.iter())
        {
            println!(
                "SPRINT104_D2_DELIVERY_CHECK backend_scope=derived identity={} status={:?} evidence={}",
                check.identity, check.status, check.evidence_identity
            );
        }
        run_d2_post_publication_checks_v1(
            &main_root,
            &main_target,
            &log_root,
            &mut child_sequence,
            &mut parent_log,
        )
        .map_err(|error| format!("BlockedByPostPublicationVerification: {error}"))?;
        d2_assert_candidate_checkpoint_v1(
            &mut parent_log,
            &main_root,
            &main_frozen,
            "Post-Publication-Main",
        )
        .map_err(|error| format!("BlockedByCandidateDriftDuringClosure: {error}"))?;
        d2_assert_candidate_checkpoint_v1(
            &mut parent_log,
            &clean_root,
            &clean_frozen,
            "Post-Publication-Clean",
        )
        .map_err(|error| format!("BlockedByCandidateDriftDuringClosure: {error}"))?;
        parent_log.append(
            "FINAL_CANDIDATE_CHECK",
            &format!(
                "status=MATCH candidate={}",
                main_frozen.aggregate_manifest_digest()
            ),
        )?;
        parent_log.append(
            "RETRY_AUDIT",
            &format!(
                "parent_invocations=1 child_executions={} duplicate_executions=0 automatic_retry=0 manual_retry=0",
                child_sequence.completed()
            ),
        )?;
        parent_log.complete()?;
        println!(
            "SPRINT104_D2_RUNNER_COMPLETE status=READY_FOR_INDEPENDENT_REVIEW clean_root={} main_candidate={} clean_candidate={}",
            clean_root.display(),
            main_frozen.aggregate_manifest_digest(),
            clean_frozen.aggregate_manifest_digest(),
        );
        Ok(())
    }

    #[test]
    fn m3_micro_r10_d2_runtime_summary_parser_is_strict() {
        let counts = parse_delivery_cargo_test_summary_v1(
            "test result: ok. 7 passed; 0 failed; 2 ignored; 0 measured; 3 filtered out; finished in 0.01s\n",
            "",
        )
        .unwrap();
        assert_eq!(
            counts,
            DeliveryTestOutcomeCountsV1 {
                selected_count: 9,
                passed_count: 7,
                failed_count: 0,
                ignored_count: 2,
                measured_count: 0,
            }
        );
        assert!(parse_delivery_cargo_test_summary_v1("", "").is_err());
        assert!(parse_delivery_cargo_test_summary_v1(
            "test result: ok. 1 passed; 1 failed; 0 ignored; 0 measured; 0 filtered out; finished in 0.01s\n",
            "",
        )
        .is_err());
    }

    fn d2_process_fixture_v1(pid: u32, ppid: u32, command: &str) -> D2ProcessSnapshotRecordV1 {
        D2ProcessSnapshotRecordV1 {
            pid,
            ppid,
            command: command.to_string(),
            args: command.to_string(),
        }
    }

    #[test]
    fn m3_micro_d2r1_process_snapshot_parser_preserves_pid_ppid_command_and_args() {
        let record = parse_d2_process_snapshot_line_v1(
            "  120   80 /toolchain/bin/cargo cargo test --lib --features backend-metal",
        )
        .unwrap();
        assert_eq!(record.pid, 120);
        assert_eq!(record.ppid, 80);
        assert_eq!(record.command, "/toolchain/bin/cargo");
        assert_eq!(record.args, "cargo test --lib --features backend-metal");
        assert!(parse_d2_process_snapshot_line_v1("invalid 80 cargo cargo test").is_err());
        assert!(parse_d2_process_snapshot_line_v1("120 invalid cargo cargo test").is_err());
        assert!(parse_d2_process_snapshot_line_v1("120 80").is_err());
    }

    #[test]
    fn m3_micro_d2r1_self_launcher_and_wrapper_ancestry_are_excluded() {
        let direct = vec![
            d2_process_fixture_v1(1, 0, "launchd"),
            d2_process_fixture_v1(100, 1, "/toolchain/bin/cargo"),
            d2_process_fixture_v1(200, 100, "soma-test"),
        ];
        assert_eq!(
            direct
                .iter()
                .filter(|record| d2_rust_process_executable_v1(record).is_some())
                .map(|record| record.pid)
                .collect::<Vec<_>>(),
            vec![100],
            "the prior flat classifier reproduced the self-launcher false positive",
        );
        assert!(
            conflicting_external_rust_processes_v1(&direct, 200)
                .unwrap()
                .is_empty()
        );

        let wrapped = vec![
            d2_process_fixture_v1(1, 0, "launchd"),
            d2_process_fixture_v1(100, 1, "cargo"),
            d2_process_fixture_v1(150, 100, "runner-wrapper"),
            d2_process_fixture_v1(200, 150, "soma-test"),
        ];
        assert!(
            conflicting_external_rust_processes_v1(&wrapped, 200)
                .unwrap()
                .is_empty()
        );
    }

    #[test]
    fn m3_micro_d2r4r1_unrelated_cargo_rustc_and_sibling_are_allowed() {
        let snapshot = vec![
            d2_process_fixture_v1(1, 0, "launchd"),
            d2_process_fixture_v1(50, 1, "terminal-shell"),
            d2_process_fixture_v1(100, 50, "cargo"),
            d2_process_fixture_v1(200, 100, "soma-test"),
            d2_process_fixture_v1(300, 50, "/toolchain/bin/cargo"),
            d2_process_fixture_v1(400, 1, "/toolchain/bin/rustc"),
        ];
        assert_eq!(
            conflicting_external_rust_processes_v1(&snapshot, 200)
                .unwrap()
                .into_iter()
                .map(|record| record.pid)
                .collect::<Vec<_>>(),
            vec![300, 400],
        );
        assert!(d2_unrelated_rust_processes_do_not_block_v1(&snapshot, 200).is_ok());

        let current_is_rust_like = vec![
            d2_process_fixture_v1(1, 0, "launchd"),
            d2_process_fixture_v1(200, 1, "rustc"),
        ];
        assert!(
            conflicting_external_rust_processes_v1(&current_is_rust_like, 200)
                .unwrap()
                .is_empty()
        );
        assert!(d2_unrelated_rust_processes_do_not_block_v1(&current_is_rust_like, 200).is_ok());
    }

    #[test]
    fn m3_micro_d2r1_malformed_ancestry_fails_closed() {
        let duplicate = vec![
            d2_process_fixture_v1(1, 0, "launchd"),
            d2_process_fixture_v1(200, 1, "soma-test"),
            d2_process_fixture_v1(200, 1, "duplicate"),
        ];
        assert!(conflicting_external_rust_processes_v1(&duplicate, 200).is_err());

        let cycle = vec![
            d2_process_fixture_v1(100, 200, "cargo"),
            d2_process_fixture_v1(200, 100, "soma-test"),
        ];
        assert!(conflicting_external_rust_processes_v1(&cycle, 200).is_err());

        let missing_current = vec![d2_process_fixture_v1(1, 0, "launchd")];
        assert!(conflicting_external_rust_processes_v1(&missing_current, 200).is_err());

        let missing_parent = vec![d2_process_fixture_v1(200, 100, "soma-test")];
        assert!(conflicting_external_rust_processes_v1(&missing_parent, 200).is_err());
    }

