    #[test]
    fn m3_micro_p2r2_delivery_requires_all_required_genuine_faults() {
        assert!(
            metal_required_negative_delivery_gate_v3(
                "PASSED_ALL_REQUIRED_GENUINE_FAULTS",
                5,
                0,
                0,
                5,
            )
            .is_ok()
        );
        assert!(
            metal_required_negative_delivery_gate_v3("FAILED_REQUIRED_GENUINE_FAULT", 4, 0, 0, 5,)
                .is_err()
        );
        assert!(
            metal_required_negative_delivery_gate_v3(
                "PASSED_ALL_REQUIRED_GENUINE_FAULTS",
                5,
                1,
                0,
                5,
            )
            .is_err()
        );
    }

