    #[cfg(all(target_os = "macos", feature = "backend-metal"))]
    fn p2r3r3r1r1_actual_measured_pair_v2(
        sabotage_between_runs: bool,
    ) -> MetalPipelineLifecycleMeasuredPairV2 {
        let roster = test_roster();
        let agent = roster.agent(AgentId::ORDERED[0]);
        let (mut executor, _) = M3MicroMetalExecutorV1::try_new_with_lifecycle_for_test(1).unwrap();
        executor.upload_model(&agent.model).unwrap();
        let initial_state = M3MicroState::zero(&agent.model.config).unwrap();
        let sequence = vec![vec![0.0; agent.model.config.input_dim]];
        executor.upload_state(&initial_state).unwrap();
        let run_a_before = executor.pipeline_lifecycle_snapshot_for_test().unwrap();
        executor.forward_sequence(&sequence).unwrap();
        let run_a_after = executor.pipeline_lifecycle_snapshot_for_test().unwrap();
        if sabotage_between_runs {
            executor.record_pipeline_reconstruction_for_test().unwrap();
        }
        let run_b_before = executor.pipeline_lifecycle_snapshot_for_test().unwrap();
        executor.upload_state(&initial_state).unwrap();
        executor.forward_sequence(&sequence).unwrap();
        let run_b_after = executor.pipeline_lifecycle_snapshot_for_test().unwrap();
        MetalPipelineLifecycleMeasuredPairV2 {
            scenario_identity: "actual-forward-pair".to_string(),
            execution_mode_identity: "FullSequence".to_string(),
            agent_role: format!("{:?}", agent.agent_id()),
            executor_evidence_identity: stable_hash_string("actual-forward-executor-1"),
            run_a: MetalPipelineLifecycleForwardMeasurementV2 {
                actual_forward_completed: true,
                before: Some(run_a_before.clone().into()),
                after: Some(run_a_after.clone().into()),
                delta: Some(
                    super::metal_execution::MetalPipelineLifecycleDeltaV2::checked_between(
                        &run_a_before,
                        &run_a_after,
                    )
                    .unwrap()
                    .into(),
                ),
            },
            run_b: MetalPipelineLifecycleForwardMeasurementV2 {
                actual_forward_completed: true,
                before: Some(run_b_before.clone().into()),
                after: Some(run_b_after.clone().into()),
                delta: Some(
                    super::metal_execution::MetalPipelineLifecycleDeltaV2::checked_between(
                        &run_b_before,
                        &run_b_after,
                    )
                    .unwrap()
                    .into(),
                ),
            },
            between_a_b_delta: Some(
                super::metal_execution::MetalPipelineLifecycleDeltaV2::checked_between(
                    &run_a_after,
                    &run_b_before,
                )
                .unwrap()
                .into(),
            ),
        }
    }

    #[cfg(all(target_os = "macos", feature = "backend-metal"))]
    fn p2r3r3r1r1_lifecycle_fixture_v2() -> MetalPipelineLifecycleProvenanceEvidenceV2 {
        let mut constructions = Vec::new();
        let mut monitor_matches = Vec::new();
        for (ordinal, mode) in [
            (1, "SharedExecutor"),
            (2, "Streaming"),
            (3, "FullSequence"),
            (4, "Chunked"),
        ] {
            let (executor, evidence) =
                M3MicroMetalExecutorV1::try_new_with_lifecycle_for_test(ordinal).unwrap();
            let snapshot = executor.pipeline_lifecycle_snapshot_for_test().unwrap();
            monitor_matches.push(MetalPipelineConstructionMonitorMatchV2 {
                execution_mode_identity: mode.to_string(),
                executor_construction_ordinal: ordinal,
                construction_trace_event_count: evidence.events.len(),
                monitor_snapshot: snapshot.into(),
                event_count_matches: true,
            });
            constructions.push(MetalPipelineLifecycleConstructionReceiptV1 {
                execution_mode_identity: mode.to_string(),
                evidence: evidence.into(),
            });
        }
        let pairs = ["Streaming", "FullSequence", "Chunked"]
            .map(|mode| p2r3r3r1r1_measured_pair_fixture_v2(mode, mode))
            .to_vec();
        let fresh_measurements = monitor_matches
            .iter()
            .filter(|measurement| measurement.execution_mode_identity != "SharedExecutor")
            .map(|construction| MetalPipelineFreshExecutorMeasurementV2 {
                scenario_identity: construction.execution_mode_identity.clone(),
                execution_mode_identity: construction.execution_mode_identity.clone(),
                agent_role: "Trend".to_string(),
                executor_evidence_identity: stable_hash_string(&format!(
                    "fresh:{}",
                    construction.executor_construction_ordinal
                )),
                construction: construction.clone(),
                forward: p2r3r3r1r1_zero_forward_measurement_v2(&construction.monitor_snapshot),
            })
            .collect::<Vec<_>>();
        build_metal_pipeline_lifecycle_provenance_v2(
            &constructions,
            &monitor_matches,
            build_metal_pipeline_lifecycle_reuse_evidence_v2(pairs).unwrap(),
            build_metal_pipeline_fresh_executor_evidence_v2(fresh_measurements).unwrap(),
            current_metal_pipeline_lifecycle_call_site_inventory_v2().unwrap(),
        )
        .unwrap()
    }

    fn p2r3r3r1r1r1_construction_fixture_v3() -> (
        MetalPipelineLifecycleConstructionReceiptV1,
        MetalPipelineLifecycleSnapshotReceiptV2,
    ) {
        use MetalPipelineLifecycleEventKindReceiptV1 as Kind;

        let kinds = [
            Kind::LibraryCompileAttempted,
            Kind::LibraryCompileSucceeded,
            Kind::FunctionLookupAttempted,
            Kind::FunctionLookupSucceeded,
            Kind::PipelineCreationAttempted,
            Kind::PipelineCreationSucceeded,
            Kind::PipelineObservationCaptured,
            Kind::PipelineArtifactCreated,
        ];
        let events = kinds
            .into_iter()
            .enumerate()
            .map(|(index, kind)| MetalPipelineLifecycleEventReceiptV1 {
                event_ordinal: index + 1,
                executor_construction_ordinal: 41,
                kind,
                function_name: (!matches!(
                    kind,
                    Kind::LibraryCompileAttempted | Kind::LibraryCompileSucceeded
                ))
                .then_some("m3_micro_step_v1".to_string()),
                shader_source_digest: Some("fixture-shader".to_string()),
                semantic_pipeline_identity: matches!(
                    kind,
                    Kind::PipelineCreationSucceeded
                        | Kind::PipelineObservationCaptured
                        | Kind::PipelineArtifactCreated
                )
                .then_some("fixture-pipeline".to_string()),
                error_kind: None,
            })
            .collect::<Vec<_>>();
        let replay = MetalConstructionLifecycleReplayV3::from_event_vector(&events).unwrap();
        let snapshot = MetalPipelineLifecycleSnapshotReceiptV2 {
            event_sequence: replay.event_count,
            library_compile_attempted: replay.kind_counts.library_compile_attempted,
            library_compile_succeeded: replay.kind_counts.library_compile_succeeded,
            library_compile_failed: replay.kind_counts.library_compile_failed,
            function_lookup_attempted: replay.kind_counts.function_lookup_attempted,
            function_lookup_succeeded: replay.kind_counts.function_lookup_succeeded,
            function_lookup_failed: replay.kind_counts.function_lookup_failed,
            pipeline_creation_attempted: replay.kind_counts.pipeline_creation_attempted,
            pipeline_creation_succeeded: replay.kind_counts.pipeline_creation_succeeded,
            pipeline_creation_failed: replay.kind_counts.pipeline_creation_failed,
            pipeline_observations_captured: replay.kind_counts.pipeline_observation_captured,
            pipeline_artifacts_created: replay.kind_counts.pipeline_artifact_created,
            lifecycle_digest_state: "fixture-monitor".to_string(),
            ordering_digest_state: replay.ordering_digest.clone(),
            function_sequence_digest_state: replay.function_sequence_digest.clone(),
            shader_sequence_digest_state: replay.shader_sequence_digest.clone(),
            pipeline_identity_sequence_digest_state: replay
                .pipeline_identity_sequence_digest
                .clone(),
        };
        (
            MetalPipelineLifecycleConstructionReceiptV1 {
                execution_mode_identity: "Streaming".to_string(),
                evidence: MetalPipelineConstructionEvidenceReceiptV1 {
                    executor_construction_ordinal: 41,
                    events,
                    artifact_semantic_pipeline_identity: Some("fixture-pipeline".to_string()),
                    status: MetalPipelineConstructionStatusReceiptV1::Succeeded,
                },
            },
            snapshot,
        )
    }

