    fn run_delivery_check_with_actual_evidence_v1(
        identity: &str,
        actual_evidence: Option<&[ValidatedActualD2ExecutionEvidenceV3]>,
    ) -> Result<String, String> {
        let receipt = || read_authoritative_receipt_v2();
        match identity {
            "capability-receipt-self" => {
                let receipt = receipt()?;
                validate_receipt_v2_self(&receipt)?;
                Ok(receipt.receipt_digest)
            }
            "capability-receipt-currentness" => {
                let receipt = receipt()?;
                validate_receipt_v2_currentness(&receipt)?;
                Ok(receipt.semantic_binding.combined_semantic_binding_digest)
            }
            "capability-status-derivation" => {
                let receipt = receipt()?;
                let derived = derive_capability_status_v2(
                    receipt.lifecycle,
                    receipt.metric_semantics.metric_aggregation_status,
                    receipt.metric_semantics.accuracy_nll_source_status,
                    receipt.root_cause,
                );
                if derived != receipt.capability_status {
                    return Err("capability status derivation mismatch".to_string());
                }
                Ok(stable_hash_string(derived.as_str()))
            }
            "structural-loss-completeness" => {
                let receipt = receipt()?;
                if !structural_loss_evidence_complete_v1(&receipt.structural_loss)
                    || receipt.lifecycle.structural_loss != receipt.structural_loss.status
                {
                    return Err("Structural Loss evidence is incomplete".to_string());
                }
                Ok(receipt.structural_loss.evaluation_scope_identity)
            }
            "gradient-receipt-integrity" => {
                let receipt = receipt()?;
                if receipt.gradient.status
                    != status_from_bool_v1(receipt.gradient.failed_cases == 0)
                    || receipt.gradient.policy_identity
                        != receipt.semantic_binding.policy.gradient_policy_identity
                {
                    return Err("gradient receipt mismatch".to_string());
                }
                Ok(receipt.gradient.policy_identity)
            }
            "comparator-purity" => {
                let receipt = receipt()?;
                if receipt.comparator.comparator_pure
                    != (receipt.comparator.unexpected_paths == 0
                        && receipt.comparator.missing_paths == 0
                        && receipt.comparator.differing_paths
                            == receipt.comparator.state_capability_paths)
                {
                    return Err("comparator purity mismatch".to_string());
                }
                Ok(stable_hash_string(&format!("{:?}", receipt.comparator)))
            }
            "metric-semantics" => {
                let receipt = receipt()?;
                if [
                    receipt.metric_semantics.metric_semantics_status,
                    receipt.metric_semantics.metric_aggregation_status,
                    receipt.metric_semantics.accuracy_nll_source_status,
                    receipt.metric_semantics.event_alignment_status,
                    receipt.metric_semantics.suffix_integrity_status,
                ]
                .contains(&GateExecutionStatusV1::NotRun)
                {
                    return Err("metric semantics evidence is incomplete".to_string());
                }
                Ok(receipt.metric_semantics.metric_semantics_identity)
            }
            "test-taxonomy" => {
                let inventory = m3_micro_test_inventory_v1();
                if inventory.is_empty()
                    || inventory.iter().any(|entry| {
                        entry.test_identity.is_empty()
                            || entry.reason.is_empty()
                            || (entry.normal_full_library
                                && (entry.heavy_attribution || entry.frozen_v3))
                    })
                {
                    return Err("test taxonomy is incomplete".to_string());
                }
                Ok(stable_hash_string(&format!("{inventory:?}")))
            }
            "default-runtime-contract" => {
                delivery_runtime_contract_v1(VerificationBackendV1::Default)
            }
            "metal-execution-receipt" => {
                let receipt = current_metal_delivery_receipt_v11()?;
                Ok(receipt.receipt_digest)
            }
            "metal-runtime-contract" => delivery_runtime_contract_v1(VerificationBackendV1::Metal),
            "metal-cpu-parity" => {
                let receipt = current_metal_delivery_receipt_v11()?;
                if receipt.parity.status != "PASSED" {
                    return Err("CPU/Metal parity is not passed".to_string());
                }
                Ok(receipt
                    .semantic_binding
                    .normal_semantic_binding
                    .parity_policy_identity)
            }
            "metal-required-genuine-negative-evidence" => {
                let receipt = current_metal_delivery_receipt_v11()?;
                metal_required_negative_delivery_gate_v3(
                    &receipt.required_negative.status,
                    receipt.required_negative.genuine_required_fault_count,
                    receipt.required_negative.synthetic_required_evidence_count,
                    receipt.required_negative.required_cpu_fallback_executions,
                    5,
                )
            }
            "metal-optional-command-failure-status" => {
                let receipt = current_metal_delivery_receipt_v11()?;
                optional_command_failure_delivery_gate_v2(
                    &receipt.optional_command_failure.status,
                    receipt.optional_command_failure.unsafe_injection_attempts,
                    receipt.optional_command_failure.cpu_fallback_executions,
                )
            }
            "metal-command-error-observer" => {
                let receipt = current_metal_delivery_receipt_v11()?;
                metal_command_error_observer_delivery_gate_v1(&receipt.command_observation.status)
            }
            "metal-dispatch-argument-provenance" => {
                let receipt = current_metal_delivery_receipt_v11()?;
                metal_dispatch_provenance_delivery_gate_v1(&receipt.dispatch_argument_provenance)
            }
            "metal-buffer-binding-argument-provenance" => {
                let receipt = current_metal_delivery_receipt_v11()?;
                metal_buffer_binding_provenance_delivery_gate_v1(
                    &receipt.buffer_binding_argument_provenance,
                )
            }
            "metal-pipeline-binding-argument-provenance" => {
                let receipt = current_metal_delivery_receipt_v11()?;
                metal_pipeline_binding_provenance_delivery_gate_v1(
                    &receipt.pipeline_binding_argument_provenance,
                )
            }
            "metal-pipeline-lifecycle-provenance" => {
                let receipt = current_metal_delivery_receipt_v11()?;
                metal_pipeline_lifecycle_delivery_gate_v3(&receipt.pipeline_lifecycle_provenance)
            }
            "full-integration-clean-direct-binding" => {
                evaluate_full_integration_clean_delivery_check_v1(
                    actual_evidence.map(DeliveryExecutionEvidenceSetV3::Actual),
                )
            }
            "verification-mutation-coverage" => {
                Err("verification mutation coverage is incomplete".to_string())
            }
            "detached-branch-name-collision" => current_detached_branch_collision_evidence_v1(),
            _ => Err(format!("unknown delivery check: {identity}")),
        }
    }

    fn run_delivery_check_v1(identity: &str) -> Result<String, String> {
        run_delivery_check_with_actual_evidence_v1(identity, None)
    }

    fn run_m3_micro_delivery_verification_with_actual_evidence_v1(
        backend: VerificationBackendV1,
        actual_evidence: Option<&[ValidatedActualD2ExecutionEvidenceV3]>,
    ) -> BackendDeliverySummaryV1 {
        let plan = current_validated_delivery_plan_v2()
            .expect("canonical delivery plan must pass identity validation");
        let before = HeavyEvidenceExecutionCountersV1::snapshot();
        let checks = plan
            .entries()
            .iter()
            .filter(|check| delivery_check_applies_v1(check, backend))
            .map(|check| {
                let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                    run_delivery_check_with_actual_evidence_v1(&check.identity, actual_evidence)
                }));
                match result {
                    Ok(Ok(evidence_identity)) => DeliveryCheckResultV1 {
                        identity: check.identity.clone(),
                        status: VerificationCheckStatusV1::Passed,
                        evidence_identity,
                        blocker: None,
                        failure_evidence_entries: Vec::new(),
                        blocker_group_identity: None,
                    },
                    Ok(Err(blocker)) => DeliveryCheckResultV1 {
                        identity: check.identity.clone(),
                        status: VerificationCheckStatusV1::Failed,
                        evidence_identity: stable_hash_string(&format!(
                            "{}:{blocker}",
                            check.identity
                        )),
                        blocker: Some(blocker.clone()),
                        failure_evidence_entries: vec![blocker],
                        blocker_group_identity: Some(delivery_blocker_group_identity_v1(
                            &check.identity,
                        )),
                    },
                    Err(_) => DeliveryCheckResultV1 {
                        identity: check.identity.clone(),
                        status: VerificationCheckStatusV1::Failed,
                        evidence_identity: stable_hash_string(&format!("{}:panic", check.identity)),
                        blocker: Some("delivery check panicked".to_string()),
                        failure_evidence_entries: vec!["delivery check panicked".to_string()],
                        blocker_group_identity: Some(delivery_blocker_group_identity_v1(
                            &check.identity,
                        )),
                    },
                }
            })
            .collect::<Vec<_>>();
        let counters = HeavyEvidenceExecutionCountersV1::snapshot().delta(before);
        let derived = derive_delivery_check_summary_v2(&plan, backend, &checks)
            .expect("delivery checks must satisfy their canonical plan");
        let status = if derived.failed_check_count == 0
            && derived.not_run_check_count == 0
            && counters.is_zero()
        {
            VerificationCheckStatusV1::Passed
        } else {
            VerificationCheckStatusV1::Failed
        };
        let mut summary = BackendDeliverySummaryV1 {
            backend: backend.as_str().to_string(),
            plan_identity: plan.plan_digest().to_string(),
            required_count: derived.required_check_count,
            passed_count: derived.passed_check_count,
            failed_count: derived.failed_check_count,
            not_run_count: derived.not_run_check_count,
            checks,
            heavy_execution_counters: counters,
            status,
            summary_digest: String::new(),
        };
        summary.summary_digest = backend_summary_digest_v1(&summary);
        summary
    }

    fn run_m3_micro_delivery_verification_v1(
        backend: VerificationBackendV1,
    ) -> BackendDeliverySummaryV1 {
        run_m3_micro_delivery_verification_with_actual_evidence_v1(backend, None)
    }

    #[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
    enum M3MicroDeliveryStatusV1 {
        NotRun,
        Passed,
        Failed,
        Incomplete,
    }

    impl M3MicroDeliveryStatusV1 {
        fn as_str(self) -> &'static str {
            match self {
                Self::NotRun => "NOT_RUN",
                Self::Passed => "PASSED",
                Self::Failed => "FAILED",
                Self::Incomplete => "INCOMPLETE",
            }
        }
    }

    fn delivery_status_from_summaries_v1(
        default: &BackendDeliverySummaryV1,
        metal: &BackendDeliverySummaryV1,
    ) -> M3MicroDeliveryStatusV1 {
        if [default.status, metal.status].contains(&VerificationCheckStatusV1::Failed) {
            M3MicroDeliveryStatusV1::Failed
        } else if [default.status, metal.status].contains(&VerificationCheckStatusV1::NotRun) {
            M3MicroDeliveryStatusV1::Incomplete
        } else {
            M3MicroDeliveryStatusV1::Passed
        }
    }

    fn derive_r10_overall_status_v1(
        report_integrity: bool,
        delivery_status: M3MicroDeliveryStatusV1,
        capability_status: CapabilityStatusV2,
    ) -> String {
        if !report_integrity {
            "BlockedByReportIntegrity".to_string()
        } else {
            match delivery_status {
                M3MicroDeliveryStatusV1::Failed => "BlockedByVerificationFailure".to_string(),
                M3MicroDeliveryStatusV1::NotRun | M3MicroDeliveryStatusV1::Incomplete => {
                    "BlockedByIncompleteVerification".to_string()
                }
                M3MicroDeliveryStatusV1::Passed => capability_status.as_str().to_string(),
            }
        }
    }

