    fn clean_summary_digest_v1(
        default: &BackendDeliverySummaryV1,
        metal: &BackendDeliverySummaryV1,
    ) -> String {
        stable_hash_string(&format!(
            "m3-r10-clean-summary-v1:{}:{}",
            default.summary_digest, metal.summary_digest
        ))
    }

    fn delivery_receipt_computed_digest_v1(
        receipt: &M3MicroDeliveryVerificationReceiptV1,
    ) -> String {
        let mut semantic = receipt.clone();
        semantic.receipt_digest.clear();
        stable_hash_string(&serde_json::to_string(&semantic).unwrap())
    }

    fn canonical_delivery_receipt_bytes_v1(
        receipt: &M3MicroDeliveryVerificationReceiptV1,
    ) -> Result<Vec<u8>, String> {
        serde_json::to_vec(receipt).map_err(|error| error.to_string())
    }

    fn validate_delivery_receipt_self_v1(
        receipt: &M3MicroDeliveryVerificationReceiptV1,
    ) -> Result<(), String> {
        validate_backend_summary_v1(&receipt.default_summary)?;
        validate_backend_summary_v1(&receipt.metal_summary)?;
        let capability = read_authoritative_receipt_v2()?;
        let metal = read_metal_receipt_v11()?;
        let plan = validated_delivery_plan_for_identity_v1(&receipt.verification_plan_identity)?;
        let expected_binding = delivery_semantic_binding_for_plan_v1(&capability, &metal, &plan);
        let delivery_status =
            delivery_status_from_summaries_v1(&receipt.default_summary, &receipt.metal_summary);
        if receipt.format_version != R10_DELIVERY_RECEIPT_FORMAT_VERSION
            || receipt.capability_receipt_digest != capability.receipt_digest
            || receipt.semantic_binding.capability_receipt_digest != capability.receipt_digest
            || receipt.semantic_binding != expected_binding
            || receipt.metal_execution_receipt_digest != metal.receipt_digest
            || receipt.semantic_binding.metal_execution_receipt_digest != metal.receipt_digest
            || receipt.actual_metal_status != metal.normal_execution.status
            || receipt.cpu_metal_parity_status != metal.parity.status
            || receipt.required_genuine_negative_status != metal.required_negative.status
            || receipt.optional_command_failure_status != metal.optional_command_failure.status
            || receipt.command_error_observation_handler_status != metal.command_observation.status
            || receipt.required_negative_policy_identity != metal.required_negative.policy_identity
            || receipt.required_negative_evidence_digest
                != stable_hash_string(
                    &serde_json::to_string(&metal.required_negative.faults).unwrap(),
                )
            || receipt.synthetic_required_evidence_count
                != metal.required_negative.synthetic_required_evidence_count
            || receipt.genuine_required_fault_count
                != metal.required_negative.genuine_required_fault_count
            || receipt.required_cpu_fallback_executions
                != metal.required_negative.required_cpu_fallback_executions
            || receipt.unsafe_command_failure_injection_attempts
                != metal.optional_command_failure.unsafe_injection_attempts
            || receipt.dispatch_argument_provenance_status
                != metal.dispatch_argument_provenance.status.as_str()
            || receipt.buffer_binding_provenance_status
                != metal.buffer_binding_argument_provenance.status.as_str()
            || receipt.buffer_binding_provenance_status != "PASSED_ACTUAL_BOUND_BUFFER_ARGUMENTS"
            || receipt.buffer_binding_sequence_digest
                != metal
                    .buffer_binding_argument_provenance
                    .binding_sequence_digest
            || receipt.pipeline_binding_provenance_status
                != metal.pipeline_binding_argument_provenance.status.as_str()
            || receipt.pipeline_binding_provenance_status
                != "PASSED_ACTUAL_BOUND_PIPELINE_ARGUMENTS"
            || receipt.pipeline_semantic_digest
                != metal
                    .pipeline_binding_argument_provenance
                    .semantic_pipeline_digest
            || receipt.pipeline_observation_digest
                != metal
                    .pipeline_binding_argument_provenance
                    .pipeline_observation_digest
            || receipt.pipeline_binding_sequence_digest
                != metal
                    .pipeline_binding_argument_provenance
                    .pipeline_binding_sequence_digest
            || receipt.pipeline_lifecycle_provenance_status
                != metal.pipeline_lifecycle_provenance.status.as_str()
            || receipt.pipeline_lifecycle_provenance_status
                != "PASSED_ACTUAL_EVENTS_AND_EXACT_MONITOR_CROSS_VALIDATION"
            || receipt.pipeline_lifecycle_digest
                != metal.pipeline_lifecycle_provenance.lifecycle_digest
            || receipt.pipeline_lifecycle_v2 != expected_binding.pipeline_lifecycle_v2
            || receipt.pipeline_lifecycle_v2.constructor_lifecycle_status
                != "PASSED_ACTUAL_EVENTS_AND_EXACT_MONITOR_CROSS_VALIDATION"
            || receipt
                .pipeline_lifecycle_v2
                .construction_monitor_cross_validation_status
                != "PASSED_ACTUAL_EVENTS_AND_EXACT_MONITOR_CROSS_VALIDATION"
            || receipt.pipeline_lifecycle_v2.construction_count == 0
            || receipt.pipeline_lifecycle_v2.validated_construction_count
                != receipt.pipeline_lifecycle_v2.construction_count
            || receipt
                .pipeline_lifecycle_v2
                .construction_monitor_comparison_count
                != receipt.pipeline_lifecycle_v2.construction_count
            || receipt.pipeline_lifecycle_v2.event_count_mismatch_count != 0
            || receipt.pipeline_lifecycle_v2.kind_count_mismatch_count != 0
            || receipt.pipeline_lifecycle_v2.ordering_digest_mismatch_count != 0
            || receipt
                .pipeline_lifecycle_v2
                .semantic_sequence_mismatch_count
                != 0
            || receipt.pipeline_lifecycle_v2.comparison_digest.is_empty()
            || receipt.pipeline_lifecycle_v2.same_executor_reuse_status
                != "PASSED_MEASURED_NO_RECONSTRUCTION"
            || receipt
                .pipeline_lifecycle_v2
                .fresh_executor_lifecycle_status
                != "PASSED_ACTUAL_FRESH_CONSTRUCTION"
            || receipt.topology_mutation_baseline_status
                != "PASSED_ACTUAL_INDEPENDENT_AB_MUTATION_BASELINE"
            || receipt.metal_topology_status
                != delivery_metal_topology_status_v1(metal.topology_status)
            || receipt.dispatch_geometry_digest
                != metal.dispatch_argument_provenance.geometry_digest
            || metal_dispatch_provenance_delivery_gate_v1(&metal.dispatch_argument_provenance)
                .is_err()
            || metal_buffer_binding_provenance_delivery_gate_v1(
                &metal.buffer_binding_argument_provenance,
            )
            .is_err()
            || metal_pipeline_binding_provenance_delivery_gate_v1(
                &metal.pipeline_binding_argument_provenance,
            )
            .is_err()
            || metal_pipeline_lifecycle_delivery_gate_v3(&metal.pipeline_lifecycle_provenance)
                .is_err()
            || receipt.metal_witness_summary_digest
                != receipt.semantic_binding.metal_witness_summary_digest
            || receipt.required_genuine_negative_status
                != receipt.semantic_binding.required_genuine_negative_status
            || receipt.optional_command_failure_status
                != receipt.semantic_binding.optional_command_failure_status
            || receipt.command_error_observation_handler_status
                != receipt
                    .semantic_binding
                    .command_error_observation_handler_status
            || receipt.required_negative_policy_identity
                != receipt.semantic_binding.required_negative_policy_identity
            || receipt.required_negative_evidence_digest
                != receipt.semantic_binding.required_negative_evidence_digest
            || receipt.dispatch_argument_provenance_status
                != receipt.semantic_binding.dispatch_argument_provenance_status
            || receipt.buffer_binding_provenance_status
                != receipt.semantic_binding.buffer_binding_provenance_status
            || receipt.buffer_binding_sequence_digest
                != receipt.semantic_binding.buffer_binding_sequence_digest
            || receipt.pipeline_binding_provenance_status
                != receipt.semantic_binding.pipeline_binding_provenance_status
            || receipt.pipeline_semantic_digest != receipt.semantic_binding.pipeline_semantic_digest
            || receipt.pipeline_observation_digest
                != receipt.semantic_binding.pipeline_observation_digest
            || receipt.pipeline_binding_sequence_digest
                != receipt.semantic_binding.pipeline_binding_sequence_digest
            || receipt.pipeline_lifecycle_provenance_status
                != receipt
                    .semantic_binding
                    .pipeline_lifecycle_provenance_status
            || receipt.pipeline_lifecycle_digest
                != receipt.semantic_binding.pipeline_lifecycle_digest
            || receipt.pipeline_lifecycle_v2 != receipt.semantic_binding.pipeline_lifecycle_v2
            || receipt.topology_mutation_baseline_status
                != receipt.semantic_binding.topology_mutation_baseline_status
            || receipt.metal_topology_status != receipt.semantic_binding.metal_topology_status
            || receipt.dispatch_geometry_digest != receipt.semantic_binding.dispatch_geometry_digest
            || receipt.verification_plan_identity
                != receipt.semantic_binding.verification_plan_identity
            || receipt.default_summary.plan_identity != receipt.verification_plan_identity
            || receipt.metal_summary.plan_identity != receipt.verification_plan_identity
            || receipt.default_summary.backend != VerificationBackendV1::Default.as_str()
            || receipt.metal_summary.backend != VerificationBackendV1::Metal.as_str()
            || receipt.clean_summary_digest
                != clean_summary_digest_v1(&receipt.default_summary, &receipt.metal_summary)
            || receipt.capability_status != capability.capability_status.as_str()
            || receipt.delivery_status != delivery_status.as_str()
            || receipt.overall_status
                != derive_r10_overall_status_v1(true, delivery_status, capability.capability_status)
            || receipt.receipt_digest != delivery_receipt_computed_digest_v1(receipt)
        {
            return Err("invalid delivery verification receipt".to_string());
        }
        let encoded = canonical_delivery_receipt_bytes_v1(receipt)?;
        let decoded: M3MicroDeliveryVerificationReceiptV1 =
            serde_json::from_slice(&encoded).map_err(|error| error.to_string())?;
        if decoded != *receipt || canonical_delivery_receipt_bytes_v1(&decoded)? != encoded {
            return Err("non-canonical delivery receipt roundtrip".to_string());
        }
        Ok(())
    }

    fn delivery_receipt_path_v1() -> PathBuf {
        Path::new(env!("CARGO_MANIFEST_DIR")).join(R10_DELIVERY_RECEIPT_RELATIVE_PATH)
    }

    fn read_delivery_receipt_v1() -> Result<M3MicroDeliveryVerificationReceiptV1, String> {
        let bytes = fs::read(delivery_receipt_path_v1()).map_err(|error| error.to_string())?;
        let receipt = serde_json::from_slice(&bytes).map_err(|error| error.to_string())?;
        if canonical_delivery_receipt_bytes_v1(&receipt)? != bytes {
            return Err("delivery receipt is not canonical".to_string());
        }
        validate_delivery_receipt_self_v1(&receipt)?;
        Ok(receipt)
    }

    #[derive(Clone, Debug, PartialEq, Eq)]
    enum DeliveryOwnCurrentnessErrorV1 {
        CurrentPlanIdentityMismatch { expected: String, observed: String },
        SemanticBindingMismatch,
    }

    #[derive(Clone, Debug, PartialEq, Eq)]
    enum DeliveryReceiptCurrentnessErrorV2 {
        CapabilityDependency(SemanticCurrentnessErrorV2),
        MetalDependency(String),
        DeliveryBinding(DeliveryOwnCurrentnessErrorV1),
    }

    fn validate_delivery_receipt_own_current_binding_v1(
        receipt: &M3MicroDeliveryVerificationReceiptV1,
        current_plan: &ValidatedDeliveryPlanV2,
        current_binding: &DeliverySemanticBindingV1,
    ) -> Result<(), DeliveryOwnCurrentnessErrorV1> {
        if receipt.verification_plan_identity != current_plan.plan_digest() {
            return Err(DeliveryOwnCurrentnessErrorV1::CurrentPlanIdentityMismatch {
                expected: current_plan.plan_digest().to_string(),
                observed: receipt.verification_plan_identity.clone(),
            });
        }
        if receipt.semantic_binding != *current_binding {
            return Err(DeliveryOwnCurrentnessErrorV1::SemanticBindingMismatch);
        }
        Ok(())
    }

    fn assess_delivery_receipt_currentness_v2(
        receipt: &M3MicroDeliveryVerificationReceiptV1,
        capability: &M3MicroAuthoritativeReceiptV2,
        metal: &M3MicroMetalExecutionReceiptV11,
    ) -> Result<(), DeliveryReceiptCurrentnessErrorV2> {
        validate_receipt_v2_currentness_typed_v1(capability)
            .map_err(DeliveryReceiptCurrentnessErrorV2::CapabilityDependency)?;
        validate_metal_receipt_v11_currentness(metal)
            .map_err(DeliveryReceiptCurrentnessErrorV2::MetalDependency)?;
        let current_plan = current_validated_delivery_plan_v2()
            .expect("current canonical delivery plan must validate");
        let current_binding =
            delivery_semantic_binding_for_plan_v1(capability, metal, &current_plan);
        validate_delivery_receipt_own_current_binding_v1(receipt, &current_plan, &current_binding)
            .map_err(DeliveryReceiptCurrentnessErrorV2::DeliveryBinding)
    }

    fn delivery_receipt_currentness_error_message_v1(
        error: DeliveryReceiptCurrentnessErrorV2,
    ) -> String {
        match error {
            DeliveryReceiptCurrentnessErrorV2::CapabilityDependency(source) => {
                format!("stale semantic receipt: {source:?}")
            }
            DeliveryReceiptCurrentnessErrorV2::MetalDependency(error) => error,
            DeliveryReceiptCurrentnessErrorV2::DeliveryBinding(_) => {
                "delivery receipt semantic binding is stale".to_string()
            }
        }
    }

    fn validate_delivery_receipt_currentness_v1(
        receipt: &M3MicroDeliveryVerificationReceiptV1,
    ) -> Result<(), String> {
        validate_delivery_receipt_self_v1(receipt)?;
        let capability = read_authoritative_receipt_v2()?;
        if let Err(source) = validate_receipt_v2_currentness_typed_v1(&capability) {
            return Err(delivery_receipt_currentness_error_message_v1(
                DeliveryReceiptCurrentnessErrorV2::CapabilityDependency(source),
            ));
        }
        let metal = read_metal_receipt_v11()?;
        assess_delivery_receipt_currentness_v2(receipt, &capability, &metal)
            .map_err(delivery_receipt_currentness_error_message_v1)
    }

    #[cfg(all(target_os = "macos", feature = "backend-metal"))]
    fn read_only_replay_git_output_v1(arguments: &[&str]) -> Result<String, String> {
        let output = Command::new("git")
            .args(arguments)
            .current_dir(env!("CARGO_MANIFEST_DIR"))
            .output()
            .map_err(|error| error.to_string())?;
        if !output.status.success() {
            return Err(format!(
                "git {} failed with status {}",
                arguments.join(" "),
                output.status
            ));
        }
        String::from_utf8(output.stdout).map_err(|error| error.to_string())
    }

    #[cfg(all(target_os = "macos", feature = "backend-metal"))]
    fn capture_metal_read_only_replay_project_snapshot_v1()
    -> Result<MetalReadOnlyReplayProjectSnapshotV1, String> {
        let root = Path::new(env!("CARGO_MANIFEST_DIR"));
        Ok(MetalReadOnlyReplayProjectSnapshotV1 {
            capability_receipt: fs::read(receipt_v2_path()).map_err(|error| error.to_string())?,
            metal_receipt_v11: fs::read(metal_receipt_v11_path())
                .map_err(|error| error.to_string())?,
            delivery_receipt: fs::read(delivery_receipt_path_v1())
                .map_err(|error| error.to_string())?,
            functional_conformance_report: fs::read(
                root.join("docs/SPRINT104_R1_M3_MICRO_FUNCTIONAL_CONFORMANCE_REPORT.md"),
            )
            .map_err(|error| error.to_string())?,
            git_status: read_only_replay_git_output_v1(&["status", "--short"])?,
            git_diff: read_only_replay_git_output_v1(&["diff", "--no-ext-diff"])?,
            git_cached_diff: read_only_replay_git_output_v1(&[
                "diff",
                "--cached",
                "--no-ext-diff",
            ])?,
        })
    }

    #[cfg(all(target_os = "macos", feature = "backend-metal"))]
    fn run_m3_micro_actual_hardware_read_only_replay_v1()
    -> Result<MetalReadOnlyReplayExecutionEvidenceV1, String> {
        let metal = read_metal_receipt_v11()?;
        validate_metal_receipt_v11_currentness(&metal)?;
        let before = capture_metal_read_only_replay_project_snapshot_v1()?;
        let panel = execute_actual_m3_micro_topology_mutation_evidence_v1()?;
        let topology = validate_actual_m3_micro_topology_mutation_execution_v1(&panel)?;
        let runtime = metal_read_only_replay_runtime_projection_v1(&panel, &topology);
        let persisted = metal_read_only_replay_persisted_projection_v1(&metal)?;
        let semantic_mismatches =
            compare_metal_read_only_replay_semantic_projections_v1(&runtime, &persisted);
        if !semantic_mismatches.is_empty() {
            return Err(format!(
                "read-only replay semantic mismatch: {}",
                semantic_mismatches.join(", ")
            ));
        }
        let after = capture_metal_read_only_replay_project_snapshot_v1()?;
        if before != after {
            return Err("read-only replay changed project files or git state".to_string());
        }
        Ok(MetalReadOnlyReplayExecutionEvidenceV1 {
            runtime,
            persisted,
            semantic_mismatches,
            project_write_count: 0,
        })
    }

    #[cfg(all(target_os = "macos", feature = "backend-metal"))]
    fn build_delivery_receipt_from_summaries_v1(
        default_summary: BackendDeliverySummaryV1,
        metal_summary: BackendDeliverySummaryV1,
    ) -> Result<M3MicroDeliveryVerificationReceiptV1, String> {
        let capability = read_authoritative_receipt_v2()?;
        validate_receipt_v2_currentness(&capability)?;
        let metal = read_metal_receipt_v11()?;
        validate_metal_receipt_v11_currentness(&metal)?;
        validate_backend_summary_v1(&default_summary)?;
        validate_backend_summary_v1(&metal_summary)?;
        let delivery_status = delivery_status_from_summaries_v1(&default_summary, &metal_summary);
        let plan = current_validated_delivery_plan_v2()?;
        let checkout = current_git_checkout_provenance_v1()?;
        let semantic_binding = delivery_semantic_binding_v1(&capability, &metal);
        let mut receipt = M3MicroDeliveryVerificationReceiptV1 {
            format_version: R10_DELIVERY_RECEIPT_FORMAT_VERSION,
            semantic_binding: semantic_binding.clone(),
            provenance: DeliveryProvenanceV1 {
                generation_branch: checkout.branch_name().map(str::to_string),
                generation_head: checkout.head().to_string(),
                generator_label: "m3_micro_r10_generate_delivery_verification_receipt".to_string(),
            },
            capability_receipt_digest: capability.receipt_digest.clone(),
            metal_execution_receipt_digest: metal.receipt_digest.clone(),
            actual_metal_status: metal.normal_execution.status.clone(),
            cpu_metal_parity_status: metal.parity.status.clone(),
            required_genuine_negative_status: metal.required_negative.status.clone(),
            optional_command_failure_status: metal.optional_command_failure.status.clone(),
            command_error_observation_handler_status: metal.command_observation.status.clone(),
            required_negative_policy_identity: metal.required_negative.policy_identity.clone(),
            required_negative_evidence_digest: stable_hash_string(
                &serde_json::to_string(&metal.required_negative.faults).unwrap(),
            ),
            synthetic_required_evidence_count: metal
                .required_negative
                .synthetic_required_evidence_count,
            genuine_required_fault_count: metal.required_negative.genuine_required_fault_count,
            required_cpu_fallback_executions: metal
                .required_negative
                .required_cpu_fallback_executions,
            unsafe_command_failure_injection_attempts: metal
                .optional_command_failure
                .unsafe_injection_attempts,
            dispatch_argument_provenance_status: semantic_binding
                .dispatch_argument_provenance_status,
            buffer_binding_provenance_status: semantic_binding.buffer_binding_provenance_status,
            buffer_binding_sequence_digest: semantic_binding.buffer_binding_sequence_digest,
            pipeline_binding_provenance_status: semantic_binding.pipeline_binding_provenance_status,
            pipeline_semantic_digest: semantic_binding.pipeline_semantic_digest,
            pipeline_observation_digest: semantic_binding.pipeline_observation_digest,
            pipeline_binding_sequence_digest: semantic_binding.pipeline_binding_sequence_digest,
            pipeline_lifecycle_provenance_status: semantic_binding
                .pipeline_lifecycle_provenance_status,
            pipeline_lifecycle_digest: semantic_binding.pipeline_lifecycle_digest,
            pipeline_lifecycle_v2: semantic_binding.pipeline_lifecycle_v2,
            topology_mutation_baseline_status: semantic_binding.topology_mutation_baseline_status,
            metal_topology_status: semantic_binding.metal_topology_status,
            dispatch_geometry_digest: semantic_binding.dispatch_geometry_digest,
            metal_witness_summary_digest: stable_hash_string(
                &serde_json::to_string(&metal.normal_execution.execution_witness).unwrap(),
            ),
            verification_plan_identity: plan.plan_digest().to_string(),
            clean_summary_digest: clean_summary_digest_v1(&default_summary, &metal_summary),
            default_summary,
            metal_summary,
            capability_status: capability.capability_status.as_str().to_string(),
            delivery_status: delivery_status.as_str().to_string(),
            overall_status: derive_r10_overall_status_v1(
                true,
                delivery_status,
                capability.capability_status,
            ),
            receipt_digest: String::new(),
        };
        receipt.receipt_digest = delivery_receipt_computed_digest_v1(&receipt);
        validate_delivery_receipt_self_v1(&receipt)?;
        Ok(receipt)
    }

    #[cfg(all(target_os = "macos", feature = "backend-metal"))]
    fn build_delivery_receipt_with_actual_evidence_v1(
        actual_evidence: &[ValidatedActualD2ExecutionEvidenceV3],
    ) -> Result<M3MicroDeliveryVerificationReceiptV1, String> {
        let default_summary = run_m3_micro_delivery_verification_with_actual_evidence_v1(
            VerificationBackendV1::Default,
            Some(actual_evidence),
        );
        let metal_summary = run_m3_micro_delivery_verification_with_actual_evidence_v1(
            VerificationBackendV1::Metal,
            Some(actual_evidence),
        );
        build_delivery_receipt_from_summaries_v1(default_summary, metal_summary)
    }

    #[cfg(all(target_os = "macos", feature = "backend-metal"))]
    fn build_delivery_receipt_v1() -> Result<M3MicroDeliveryVerificationReceiptV1, String> {
        let default_summary = run_m3_micro_delivery_verification_v1(VerificationBackendV1::Default);
        let metal_summary = run_m3_micro_delivery_verification_v1(VerificationBackendV1::Metal);
        build_delivery_receipt_from_summaries_v1(default_summary, metal_summary)
    }

    #[cfg(all(target_os = "macos", feature = "backend-metal"))]
    fn persist_delivery_receipt_v1(
        receipt: &M3MicroDeliveryVerificationReceiptV1,
    ) -> Result<(), String> {
        validate_delivery_receipt_self_v1(receipt)?;
        let path = delivery_receipt_path_v1();
        let parent = path
            .parent()
            .ok_or_else(|| "delivery receipt parent is missing".to_string())?;
        fs::create_dir_all(parent).map_err(|error| error.to_string())?;
        let temporary = path.with_extension(format!("json.tmp.{}", receipt.receipt_digest));
        let bytes = canonical_delivery_receipt_bytes_v1(receipt)?;
        let mut file = OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(&temporary)
            .map_err(|error| error.to_string())?;
        let write_result = file
            .write_all(&bytes)
            .and_then(|_| file.sync_all())
            .map_err(|error| error.to_string());
        drop(file);
        if let Err(error) = write_result {
            let _ = fs::remove_file(&temporary);
            return Err(error);
        }
        let staged_bytes = fs::read(&temporary).map_err(|error| error.to_string())?;
        let staged: M3MicroDeliveryVerificationReceiptV1 =
            serde_json::from_slice(&staged_bytes).map_err(|error| error.to_string())?;
        if staged != *receipt || canonical_delivery_receipt_bytes_v1(&staged)? != staged_bytes {
            let _ = fs::remove_file(&temporary);
            return Err("temporary delivery receipt verification failed".to_string());
        }
        validate_delivery_receipt_self_v1(&staged)?;
        fs::rename(&temporary, &path).map_err(|error| error.to_string())?;
        let reopened = read_delivery_receipt_v1()?;
        validate_delivery_receipt_currentness_v1(&reopened)?;
        if reopened != *receipt {
            return Err("persisted delivery receipt verification failed".to_string());
        }
        Ok(())
    }

    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    enum R10ReportBindingErrorKindV1 {
        Format,
        Receipt,
        DefaultDelivery,
        MetalDelivery,
        HeavyExecution,
        CapabilityStatus,
        DeliveryStatus,
        OverallStatus,
        CleanWorktree,
        NextStep,
    }

    #[derive(Clone, Debug, PartialEq, Eq)]
    struct R10ReportBindingErrorV1 {
        kind: R10ReportBindingErrorKindV1,
        message: String,
    }

    impl R10ReportBindingErrorV1 {
        fn new(kind: R10ReportBindingErrorKindV1, message: impl Into<String>) -> Self {
            Self {
                kind,
                message: message.into(),
            }
        }
    }

    #[derive(Clone, Debug, PartialEq, Eq)]
    struct ParsedR10VerificationReportV1 {
        capability_receipt_digest: String,
        delivery_receipt_digest: String,
        capability_status: String,
        default_delivery_status: VerificationCheckStatusV1,
        metal_delivery_status: VerificationCheckStatusV1,
        full_default_status: VerificationCheckStatusV1,
        full_metal_status: VerificationCheckStatusV1,
        integration_status: VerificationCheckStatusV1,
        clean_worktree_status: VerificationCheckStatusV1,
        delivery_status: M3MicroDeliveryStatusV1,
        overall_status: String,
        final_status: String,
        default_required: usize,
        default_passed: usize,
        default_failed: usize,
        default_not_run: usize,
        metal_required: usize,
        metal_passed: usize,
        metal_failed: usize,
        metal_not_run: usize,
        default_heavy: HeavyEvidenceExecutionCountersV1,
        metal_heavy: HeavyEvidenceExecutionCountersV1,
        default_summary_digest: String,
        metal_summary_digest: String,
        clean_summary_digest: String,
        report_binding_status: VerificationCheckStatusV1,
        next_step: String,
    }

    fn report_section_r10(report: &str, section: usize) -> Option<&str> {
        let marker = format!("## {section}.");
        let start = report.find(&marker)?;
        let rest = &report[start + marker.len()..];
        let end = if section == 23 {
            rest.len()
        } else {
            rest.find(&format!("## {}.", section + 1))?
        };
        Some(&rest[..end])
    }

    fn parse_r10_string(report: &str, key: &str) -> Result<String, R10ReportBindingErrorV1> {
        required_report_value_r7(report, key)
            .map(str::to_string)
            .map_err(|error| {
                R10ReportBindingErrorV1::new(R10ReportBindingErrorKindV1::Format, error)
            })
    }

    fn parse_r10_usize(report: &str, key: &str) -> Result<usize, R10ReportBindingErrorV1> {
        parse_r10_string(report, key)?
            .parse::<usize>()
            .map_err(|_| {
                R10ReportBindingErrorV1::new(
                    R10ReportBindingErrorKindV1::Format,
                    format!("invalid report integer: {key}"),
                )
            })
    }

    fn parse_r10_check_status(
        report: &str,
        key: &str,
    ) -> Result<VerificationCheckStatusV1, R10ReportBindingErrorV1> {
        match parse_r10_string(report, key)?.as_str() {
            "NOT_RUN" => Ok(VerificationCheckStatusV1::NotRun),
            "PASSED" => Ok(VerificationCheckStatusV1::Passed),
            "FAILED" => Ok(VerificationCheckStatusV1::Failed),
            _ => Err(R10ReportBindingErrorV1::new(
                R10ReportBindingErrorKindV1::Format,
                format!("invalid verification status: {key}"),
            )),
        }
    }

    fn parse_r10_delivery_status(
        report: &str,
        key: &str,
    ) -> Result<M3MicroDeliveryStatusV1, R10ReportBindingErrorV1> {
        match parse_r10_string(report, key)?.as_str() {
            "NOT_RUN" => Ok(M3MicroDeliveryStatusV1::NotRun),
            "PASSED" => Ok(M3MicroDeliveryStatusV1::Passed),
            "FAILED" => Ok(M3MicroDeliveryStatusV1::Failed),
            "INCOMPLETE" => Ok(M3MicroDeliveryStatusV1::Incomplete),
            _ => Err(R10ReportBindingErrorV1::new(
                R10ReportBindingErrorKindV1::Format,
                format!("invalid delivery status: {key}"),
            )),
        }
    }

    fn derive_final_delivery_status_v1(
        statuses: [VerificationCheckStatusV1; 7],
    ) -> M3MicroDeliveryStatusV1 {
        if statuses.contains(&VerificationCheckStatusV1::Failed) {
            M3MicroDeliveryStatusV1::Failed
        } else if statuses
            .iter()
            .all(|status| *status == VerificationCheckStatusV1::NotRun)
        {
            M3MicroDeliveryStatusV1::NotRun
        } else if statuses.contains(&VerificationCheckStatusV1::NotRun) {
            M3MicroDeliveryStatusV1::Incomplete
        } else {
            M3MicroDeliveryStatusV1::Passed
        }
    }

    fn expected_r10_next_step(delivery: M3MicroDeliveryStatusV1) -> &'static str {
        if delivery == M3MicroDeliveryStatusV1::Passed {
            "Review the full Sprint 104-R1-R10 change set independently in review-only mode."
        } else {
            "Correct only the first failed delivery verification contract, then rerun its unchanged gate."
        }
    }

    fn single_report_bullet_r10p1(report: &str, section: usize) -> Result<String, String> {
        let bullets = report_section_r10(report, section)
            .ok_or_else(|| format!("missing R10-P1 report section: {section}"))?
            .lines()
            .filter_map(|line| line.trim().strip_prefix("- "))
            .collect::<Vec<_>>();
        if bullets.len() != 1 {
            return Err(format!(
                "R10-P1 report section {section} requires exactly one bullet"
            ));
        }
        Ok(bullets[0].to_string())
    }

    fn validate_r10p1_report_against_receipts_v1(
        report: &str,
        capability: &M3MicroAuthoritativeReceiptV2,
        delivery: &M3MicroDeliveryVerificationReceiptV1,
    ) -> Result<(), String> {
        const HEADINGS: [&str; 23] = [
            "## 1. Mode and Git State",
            "## 2. Starting Status",
            "## 3. Progress Ledger",
            "## 4. Detached-HEAD Root Cause",
            "## 5. Checkout Provenance Contract",
            "## 6. Semantic Binding",
            "## 7. Legacy R7 Regression",
            "## 8. Source Freeze",
            "## 9. Capability Receipt",
            "## 10. Delivery Receipt",
            "## 11. Main Worktree Verification",
            "## 12. Detached Clean Verification",
            "## 13. Known Unresolved Delivery Blockers",
            "## 14. Status Separation",
            "## 15. Safety",
            "## 16. What This Proves",
            "## 17. What This Does Not Prove",
            "## 18. Remaining Risks",
            "## 19. Task Repair Final Status",
            "## 20. Project Capability Status",
            "## 21. Project Delivery Status",
            "## 22. Project Overall Status",
            "## 23. Exactly One Next Step",
        ];
        let actual = report
            .lines()
            .filter(|line| line.starts_with("## "))
            .collect::<Vec<_>>();
        if actual != HEADINGS
            || (1..=23).any(|section| report_section_r10(report, section).is_none())
            || report.contains("/Users/")
        {
            return Err("R10-P1 report section or isolation contract mismatch".to_string());
        }
        let expected_capability = capability.capability_status.as_str();
        let fields = [
            (
                "Capability Receipt digest",
                capability.receipt_digest.as_str(),
            ),
            ("Delivery Receipt digest", delivery.receipt_digest.as_str()),
            ("Capability Receipt currentness", "PASSED"),
            ("Delivery Receipt currentness", "PASSED"),
            (
                "Default summary digest",
                delivery.default_summary.summary_digest.as_str(),
            ),
            (
                "Metal summary digest",
                delivery.metal_summary.summary_digest.as_str(),
            ),
            ("Main Full Default Status", "PASSED"),
            ("Main Full Metal Status", "PASSED"),
            ("Main Integration Status", "PASSED"),
            ("Detached checkout state", "DETACHED"),
            ("Detached Full Default Status", "PASSED"),
            ("Detached Full Metal Status", "PASSED"),
            ("Detached Integration Status", "PASSED"),
            ("Detached Clean Status", "PASSED"),
            ("Known Metal compute blocker", "UNRESOLVED"),
            ("Known Delivery Receipt coverage blocker", "UNRESOLVED"),
            ("Known Verification mutation coverage blocker", "UNRESOLVED"),
            ("Detached Repair Status", "READY_FOR_INDEPENDENT_REVIEW"),
            ("Capability Status", expected_capability),
            ("Delivery Status", "FAILED"),
            ("Overall Status", "BlockedByVerificationFailure"),
            ("Report binding status", "PASSED"),
        ];
        for (key, expected) in fields {
            if required_report_value_r7(report, key)? != expected {
                return Err(format!("R10-P1 report field mismatch: {key}"));
            }
        }
        if single_report_bullet_r10p1(report, 19)? != "READY_FOR_INDEPENDENT_REVIEW"
            || single_report_bullet_r10p1(report, 20)? != expected_capability
            || single_report_bullet_r10p1(report, 21)? != "FAILED"
            || single_report_bullet_r10p1(report, 22)? != "BlockedByVerificationFailure"
            || single_report_bullet_r10p1(report, 23)?
                != "R10-P1 변경을 독립 review-only로 검토한다."
        {
            return Err("R10-P1 final status separation mismatch".to_string());
        }
        Ok(())
    }

