    fn d1r3a_candidate_root_fixture_v2(
        root_label: &str,
        project_source: &str,
        test_source: &str,
    ) -> PathBuf {
        let root = temp_root(root_label);
        let model = root.join("src/model");
        fs::create_dir_all(&model).unwrap();
        let core = format!(
            "pub const CANDIDATE_PROJECT_SOURCE: &str = {project_source:?};\n\n#[cfg(test)]\nmod tests {{\n    const CANDIDATE_TEST_SOURCE: &str = {test_source:?};\n}}\n"
        );
        fs::write(model.join("m3_micro.rs"), core).unwrap();
        for (name, bytes) in [
            (
                "m3_micro_capability.rs",
                b"pub const CAPABILITY_SOURCE: &str = \"shared\";\n".as_slice(),
            ),
            (
                "m3_micro_trend.rs",
                b"pub const TREND_SOURCE: &str = \"shared\";\n".as_slice(),
            ),
            (
                "m3_micro_volatility.rs",
                b"pub const VOLATILITY_SOURCE: &str = \"shared\";\n".as_slice(),
            ),
            (
                "m3_micro_reversal.rs",
                b"pub const REVERSAL_SOURCE: &str = \"shared\";\n".as_slice(),
            ),
            (
                "m3_micro_metal.rs",
                b"pub const METAL_SOURCE: &str = \"shared\";\n".as_slice(),
            ),
        ] {
            fs::write(model.join(name), bytes).unwrap();
        }
        for entry in current_delivery_candidate_manifest_policy_v2().entries {
            let path = root.join(entry.physical_repo_relative_path);
            if matches!(
                entry.source,
                DeliveryCandidateManifestEntrySourceV2::RustSourceTree
                    | DeliveryCandidateManifestEntrySourceV2::FileTree
            ) {
                fs::create_dir_all(path).unwrap();
                continue;
            }
            if path.exists() {
                continue;
            }
            fs::create_dir_all(path.parent().unwrap()).unwrap();
            fs::write(
                path,
                format!("fixture bytes for {}\n", entry.logical_repo_relative_path),
            )
            .unwrap();
        }
        fs::write(
            root.join("src/candidate_fixture_project.rs"),
            "pub const CANDIDATE_TREE_SOURCE: bool = true;\n",
        )
        .unwrap();
        fs::write(
            root.join("tests/support/candidate_fixture_support.rs"),
            "pub const CANDIDATE_TEST_SUPPORT: bool = true;\n",
        )
        .unwrap();
        fs::write(
            root.join("fixtures/historical/sample_ohlcv.csv"),
            "timestamp,open,high,low,close,volume\n1,1,1,1,1,1\n",
        )
        .unwrap();
        fs::write(
            root.join("examples/candidate_fixture.json"),
            "{\"candidate_fixture\":true}\n",
        )
        .unwrap();
        root
    }

    fn d1r3_candidate_scope_fixture_v1(label: &str) -> VerifiedDeliveryCandidateScopeIdentityV2 {
        let root = d1r3a_candidate_root_fixture_v2(label, label, label);
        let identity = derive_delivery_candidate_scope_identity_v2(&root).unwrap();
        fs::remove_dir_all(root).unwrap();
        identity
    }

    fn mutate_d1r3c_candidate_file_v3(root: &Path, relative_path: &str, marker: &str) {
        let path = root.join(relative_path);
        let mut bytes = fs::read(&path).unwrap();
        bytes.extend_from_slice(marker.as_bytes());
        fs::write(path, bytes).unwrap();
    }

    fn d2r3r2_git_command_v1(root: &Path, arguments: &[&str]) {
        let output = Command::new("git")
            .args(arguments)
            .current_dir(root)
            .output()
            .unwrap();
        assert!(
            output.status.success(),
            "git {} failed: {}",
            arguments.join(" "),
            String::from_utf8_lossy(&output.stderr),
        );
    }

    fn d2r3r2_verified_clean_authority_fixture_v1(
        root: &Path,
        provenance_marker: &str,
    ) -> VerifiedCleanDetachedExecutionEnvironmentV1 {
        fs::write(root.join("README.md"), provenance_marker).unwrap();
        d2r3r2_git_command_v1(root, &["init"]);
        d2r3r2_git_command_v1(root, &["add", "--all"]);
        d2r3r2_git_command_v1(
            root,
            &[
                "-c",
                "user.name=SOMA focused fixture",
                "-c",
                "user.email=soma-focused-fixture@example.invalid",
                "commit",
                "--quiet",
                "-m",
                "focused clean authority fixture",
            ],
        );
        let head = d2_git_output_v1(root, &["rev-parse", "HEAD"]).unwrap();
        d2r3r2_git_command_v1(root, &["checkout", "--detach", "--quiet"]);
        verify_clean_detached_execution_environment_v1(root, &head).unwrap()
    }

    fn d2r3r2r1_clean_worktree_fixture_v1(
        source_root: &Path,
        root_label: &str,
    ) -> (PathBuf, VerifiedCleanDetachedExecutionEnvironmentV1) {
        let worktree_root = temp_root(root_label);
        let worktree_path = worktree_root.to_string_lossy().into_owned();
        let head = d2_git_output_v1(source_root, &["rev-parse", "HEAD"]).unwrap();
        d2r3r2_git_command_v1(
            source_root,
            &[
                "worktree",
                "add",
                "--detach",
                worktree_path.as_str(),
                head.as_str(),
            ],
        );
        let authority =
            verify_clean_detached_execution_environment_v1(&worktree_root, &head).unwrap();
        (worktree_root, authority)
    }

    fn d2r3r2r1_remove_clean_worktree_fixture_v1(source_root: &Path, worktree_root: &Path) {
        let worktree_path = worktree_root.to_string_lossy().into_owned();
        d2r3r2_git_command_v1(
            source_root,
            &["worktree", "remove", "--force", worktree_path.as_str()],
        );
    }

