    #[test]
    fn m3_micro_d1r3d_publication_dependent_tests_are_classified() {
        let source = include_str!("m3_micro.rs");
        let ignore = "#[ignore = \"post-publication verification contract\"]";
        let mut unique = BTreeSet::new();
        for name in D1R3D_RECLASSIFIED_PUBLICATION_TESTS_V1 {
            assert!(unique.insert(name), "duplicate publication test: {name}");
            let needle = format!("fn {name}(");
            assert_eq!(source.matches(&needle).count(), 1, "{name}");
            let function_offset = source.find(&needle).unwrap();
            let attributes = &source[..function_offset];
            let attributes = attributes
                .rsplit_once("    #[test]")
                .map(|(_, attributes)| attributes)
                .unwrap_or_default();
            assert!(attributes.contains(ignore), "unclassified test: {name}");
        }
    }

    fn d1r3_non_semantic_metadata_fixture_v1(
        label: &str,
    ) -> DeliveryExecutionNonSemanticMetadataV1 {
        DeliveryExecutionNonSemanticMetadataV1 {
            worktree_path: format!("/temporary/worktree/{label}"),
            target_directory: format!("/temporary/target/{label}"),
            duration_milliseconds: label.len() as u128,
            checkout_provenance_identity: format!("checkout-provenance-{label}"),
        }
    }

    fn d1r3_observation_fixture_v1(
        required: DeliveryRequiredSuiteExecutionV1,
        candidate_scope_identity: VerifiedDeliveryCandidateScopeIdentityV2,
    ) -> DeliverySuiteExecutionObservationV1 {
        build_synthetic_delivery_suite_execution_fixture_v3(
            required.suite_identity,
            required.execution_scope,
            candidate_scope_identity,
            DeliveryTestOutcomeCountsV1 {
                selected_count: 3,
                passed_count: 2,
                failed_count: 0,
                ignored_count: 1,
                measured_count: 0,
            },
            true,
            d1r3_non_semantic_metadata_fixture_v1(&format!("{required:?}")),
        )
        .unwrap()
    }

    fn d1r3_complete_evidence_fixture_v1(
        main_candidate: &VerifiedDeliveryCandidateScopeIdentityV2,
        clean_candidate: &VerifiedDeliveryCandidateScopeIdentityV2,
    ) -> Vec<ValidatedDeliverySuiteExecutionEvidenceV1> {
        current_required_delivery_suite_executions_v1()
            .into_iter()
            .map(|required| {
                let candidate = match required.execution_scope {
                    DeliveryExecutionScopeV1::Main => main_candidate.clone(),
                    DeliveryExecutionScopeV1::CleanDetached => clean_candidate.clone(),
                    DeliveryExecutionScopeV1::Unknown => unreachable!(),
                };
                validate_delivery_suite_execution_observation_v1(&d1r3_observation_fixture_v1(
                    required, candidate,
                ))
                .unwrap()
            })
            .collect()
    }

    fn d1r3a_complete_actual_evidence_fixture_v2(
        main_root: &Path,
        clean_root: &Path,
    ) -> Vec<ValidatedActualD2ExecutionEvidenceV3> {
        let clean_authority =
            d2r3r2_verified_clean_authority_fixture_v1(clean_root, "complete-actual-evidence");
        d1r3a_complete_actual_evidence_with_clean_authority_fixture_v2(
            main_root,
            clean_root,
            &clean_authority,
        )
    }

    fn d1r3a_complete_actual_evidence_with_clean_authority_fixture_v2(
        main_root: &Path,
        clean_root: &Path,
        clean_authority: &VerifiedCleanDetachedExecutionEnvironmentV1,
    ) -> Vec<ValidatedActualD2ExecutionEvidenceV3> {
        current_required_delivery_suite_executions_v1()
            .into_iter()
            .map(|required| {
                let candidate_root = match required.execution_scope {
                    DeliveryExecutionScopeV1::Main => main_root,
                    DeliveryExecutionScopeV1::CleanDetached => clean_root,
                    DeliveryExecutionScopeV1::Unknown => unreachable!(),
                };
                let authority = (required.execution_scope
                    == DeliveryExecutionScopeV1::CleanDetached)
                    .then(|| clean_authority.clone());
                let observation = build_actual_d2_execution_observation_v3(
                    candidate_root,
                    required.suite_identity,
                    required.execution_scope,
                    DeliveryTestOutcomeCountsV1 {
                        selected_count: 3,
                        passed_count: 2,
                        failed_count: 0,
                        ignored_count: 1,
                        measured_count: 0,
                    },
                    true,
                    authority,
                    d1r3_non_semantic_metadata_fixture_v1(&format!("actual-{required:?}")),
                )
                .unwrap();
                validate_actual_d2_execution_observation_v3(&observation).unwrap()
            })
            .collect()
    }

