    #[test]
    fn m3_micro_d2r3r2_raw_boolean_and_synthetic_promotion_paths_are_absent() {
        let source = include_str!("m3_micro.rs");
        let module_marker = "    mod delivery_candidate_authority_v3 {";
        let use_marker = "\n    use self::delivery_candidate_authority_v3::{";
        let (_, after_module_marker) = source.split_once(module_marker).unwrap();
        let (authority, _) = after_module_marker.split_once(use_marker).unwrap();
        let (_, synthetic_and_after) = authority
            .split_once("pub(super) fn build_synthetic_delivery_suite_execution_fixture_v3(")
            .unwrap();
        let (synthetic, _) = synthetic_and_after
            .split_once("#[derive(Debug, PartialEq, Eq)]")
            .unwrap();
        let detached_boolean = ["detached_checkout_", "verified"].concat();
        let clean_state_boolean = ["clean_project_state_", "verified"].concat();
        let synthetic_promotion = ["From<SyntheticDeliverySuite", "Execution"].concat();
        let clean_default = [
            "Default for VerifiedCleanDetachedExecution",
            "EnvironmentV1",
        ]
        .concat();
        let clean_deserialize = [
            "Deserialize for VerifiedCleanDetachedExecution",
            "EnvironmentV1",
        ]
        .concat();
        assert!(!source.contains(&detached_boolean));
        assert!(!source.contains(&clean_state_boolean));
        assert!(!authority.contains("VerifiedCleanDetachedExecutionEnvironmentV1::new"));
        assert!(!authority.contains(&clean_default));
        assert!(!authority.contains(&clean_deserialize));
        assert!(!authority.contains("From<(bool, bool)>"));
        assert!(!synthetic.contains("VerifiedCleanDetachedExecutionEnvironmentV1"));
        assert!(!source.contains(&synthetic_promotion));
    }

    #[test]
    fn m3_micro_d1r3_complete_direct_binding_fixture_passes() {
        let candidate = d1r3_candidate_scope_fixture_v1("same-candidate");
        let evidence = d1r3_complete_evidence_fixture_v1(&candidate, &candidate);
        let binding = validate_full_integration_clean_direct_binding_v1(&evidence).unwrap();
        assert_eq!(
            binding.policy_identity,
            FULL_INTEGRATION_CLEAN_DIRECT_BINDING_POLICY_IDENTITY_V1
        );
        assert_eq!(binding.main_candidate_scope_identity, candidate);
        assert_eq!(binding.clean_candidate_scope_identity, candidate);
        assert_eq!(
            binding.validated_execution_evidence.len(),
            current_required_delivery_suite_executions_v1().len()
        );
        assert_eq!(
            binding.required_suite_set_digest,
            required_delivery_suite_set_digest_v1().unwrap()
        );
        assert!(!binding.execution_set_digest.is_empty());
        assert!(binding.candidate_equivalence);
    }

    #[test]
    fn m3_micro_d1r3_missing_full_integration_and_clean_evidence_fail() {
        let candidate = d1r3_candidate_scope_fixture_v1("same-candidate");
        let complete = d1r3_complete_evidence_fixture_v1(&candidate, &candidate);
        for missing in [
            DeliveryRequiredSuiteExecutionV1 {
                suite_identity: DeliverySuiteIdentityV1::FullDefaultLibrary,
                execution_scope: DeliveryExecutionScopeV1::Main,
            },
            DeliveryRequiredSuiteExecutionV1 {
                suite_identity: DeliverySuiteIdentityV1::IntegrationTargets,
                execution_scope: DeliveryExecutionScopeV1::Main,
            },
            DeliveryRequiredSuiteExecutionV1 {
                suite_identity: DeliverySuiteIdentityV1::FullMetalLibrary,
                execution_scope: DeliveryExecutionScopeV1::CleanDetached,
            },
        ] {
            let evidence = complete
                .iter()
                .filter(|item| {
                    (
                        item.observation.suite_identity(),
                        item.observation.execution_scope(),
                    ) != (missing.suite_identity, missing.execution_scope)
                })
                .cloned()
                .collect::<Vec<_>>();
            assert_eq!(
                validate_full_integration_clean_direct_binding_v1(&evidence),
                Err(DeliveryDirectBindingErrorV1::MissingRequiredEvidence(
                    missing
                ))
            );
        }
    }

