    #[test]
    fn m3_micro_d1r3_path_timing_and_checkout_provenance_are_non_semantic() {
        let candidate = d1r3_candidate_scope_fixture_v1("candidate");
        let branch =
            GitCheckoutProvenanceV1::from_repository_values("feature/one", "shared-head").unwrap();
        let detached = GitCheckoutProvenanceV1::from_repository_values("", "shared-head").unwrap();
        let required = DeliveryRequiredSuiteExecutionV1 {
            suite_identity: DeliverySuiteIdentityV1::FullDefaultLibrary,
            execution_scope: DeliveryExecutionScopeV1::Main,
        };
        let build = |metadata| {
            build_synthetic_delivery_suite_execution_fixture_v3(
                required.suite_identity,
                required.execution_scope,
                candidate.clone(),
                DeliveryTestOutcomeCountsV1 {
                    selected_count: 1,
                    passed_count: 1,
                    failed_count: 0,
                    ignored_count: 0,
                    measured_count: 0,
                },
                true,
                metadata,
            )
            .unwrap()
        };
        let first = build(DeliveryExecutionNonSemanticMetadataV1 {
            worktree_path: "/first/worktree".to_string(),
            target_directory: "/first/target".to_string(),
            duration_milliseconds: 1,
            checkout_provenance_identity: branch.canonical_provenance_identity_v1().unwrap(),
        });
        let second = build(DeliveryExecutionNonSemanticMetadataV1 {
            worktree_path: "/second/worktree".to_string(),
            target_directory: "/second/target".to_string(),
            duration_milliseconds: 999,
            checkout_provenance_identity: detached.canonical_provenance_identity_v1().unwrap(),
        });
        assert_ne!(
            first.non_semantic_metadata().worktree_path,
            second.non_semantic_metadata().worktree_path
        );
        assert_ne!(
            first.non_semantic_metadata().target_directory,
            second.non_semantic_metadata().target_directory
        );
        assert_ne!(
            first.non_semantic_metadata().duration_milliseconds,
            second.non_semantic_metadata().duration_milliseconds
        );
        assert_ne!(
            first.non_semantic_metadata().checkout_provenance_identity,
            second.non_semantic_metadata().checkout_provenance_identity
        );
        assert_eq!(
            first.candidate_scope_identity(),
            second.candidate_scope_identity()
        );
        assert_eq!(
            first.execution_semantic_digest(),
            second.execution_semantic_digest()
        );
        assert_eq!(
            validate_delivery_suite_execution_observation_v1(&first)
                .unwrap()
                .semantic_digest,
            validate_delivery_suite_execution_observation_v1(&second)
                .unwrap()
                .semantic_digest
        );
    }

