    fn m3_micro_d1r3a_manifest_policy_is_actual_byte_bound_and_deterministic() {
        let root = d1r3a_candidate_root_fixture_v2("manifest", "project", "test");
        let first = derive_delivery_candidate_manifest_v2(&root).unwrap();
        let second = derive_delivery_candidate_manifest_v2(&root).unwrap();
        assert_eq!(first, second);
        assert_eq!(
            first.policy_identity,
            DELIVERY_CANDIDATE_MANIFEST_POLICY_IDENTITY_V4
        );
        let policy = current_delivery_candidate_manifest_policy_v2();
        let expected = policy
            .entries
            .iter()
            .map(|entry| (entry.class, entry.logical_repo_relative_path.to_string()))
            .collect::<BTreeSet<_>>();
        let actual = first
            .entries
            .iter()
            .map(|entry| (entry.class, entry.logical_repo_relative_path.clone()))
            .collect::<BTreeSet<_>>();
        assert_eq!(actual, expected);
        assert!(first.entries.iter().all(|entry| {
            !entry.logical_repo_relative_path.starts_with('/') && !entry.content_digest.is_empty()
        }));
        assert!(first.entries.iter().any(|entry| {
            entry.class == DeliveryCandidateComponentClassV2::ProjectSource
                && entry.logical_repo_relative_path
                    == "src/model/m3_micro.rs#production-before-top-level-test-module"
        }));
        assert!(first.entries.iter().any(|entry| {
            entry.class == DeliveryCandidateComponentClassV2::ProjectSource
                && entry.logical_repo_relative_path == "src/model/m3_micro_metal.rs"
        }));
        assert!(first.entries.iter().any(|entry| {
            entry.class == DeliveryCandidateComponentClassV2::TestSource
                && entry.logical_repo_relative_path == "src/model/m3_micro.rs#top-level-test-module"
        }));
        assert!(policy.entries.iter().any(|entry| {
            entry.class == DeliveryCandidateComponentClassV2::CandidateVerificationConfig
        }));
        fs::remove_dir_all(root).unwrap();
    }

