    #[test]
    fn m3_micro_d1r3d_execution_input_envelope_is_manifest_bound() {
        let policy = current_delivery_candidate_manifest_policy_v2();
        for (class, path) in DELIVERY_CANDIDATE_GLOBAL_CONFIG_PATHS_V4
            .into_iter()
            .map(|path| {
                (
                    DeliveryCandidateComponentClassV2::CandidateVerificationConfig,
                    path,
                )
            })
            .chain(
                DELIVERY_CANDIDATE_CRATE_ROUTING_PATHS_V4
                    .into_iter()
                    .map(|path| (DeliveryCandidateComponentClassV2::ProjectSource, path)),
            )
            .chain(
                DELIVERY_CANDIDATE_INTEGRATION_TARGET_PATHS_V4
                    .into_iter()
                    .map(|path| (DeliveryCandidateComponentClassV2::TestSource, path)),
            )
            .chain(
                DELIVERY_CANDIDATE_VERIFICATION_INPUT_PATHS_V4
                    .into_iter()
                    .map(|path| {
                        (
                            DeliveryCandidateComponentClassV2::CandidateVerificationConfig,
                            path,
                        )
                    }),
            )
        {
            assert!(policy.entries.iter().any(|entry| {
                entry.class == class
                    && entry.physical_repo_relative_path == path
                    && entry.logical_repo_relative_path == path
                    && entry.source == DeliveryCandidateManifestEntrySourceV2::WholeFile
            }));
        }
        for (class, physical_path, logical_path, source) in [
            (
                DeliveryCandidateComponentClassV2::ProjectSource,
                "src",
                "src#remaining-rust-source-tree",
                DeliveryCandidateManifestEntrySourceV2::RustSourceTree,
            ),
            (
                DeliveryCandidateComponentClassV2::TestSource,
                "tests/support",
                "tests/support#rust-source-tree",
                DeliveryCandidateManifestEntrySourceV2::RustSourceTree,
            ),
            (
                DeliveryCandidateComponentClassV2::CandidateVerificationConfig,
                "fixtures/historical",
                "fixtures/historical#verification-input-tree",
                DeliveryCandidateManifestEntrySourceV2::FileTree,
            ),
        ] {
            assert!(policy.entries.iter().any(|entry| {
                entry.class == class
                    && entry.physical_repo_relative_path == physical_path
                    && entry.logical_repo_relative_path == logical_path
                    && entry.source == source
            }));
        }
        assert!(policy.entries.iter().all(|entry| {
            entry.physical_repo_relative_path
                != "docs/SPRINT104_R1_M3_MICRO_FUNCTIONAL_CONFORMANCE_REPORT.md"
                && !entry
                    .physical_repo_relative_path
                    .starts_with("docs/evidence/")
                && !entry.physical_repo_relative_path.starts_with("target/")
                && !entry.physical_repo_relative_path.starts_with(".git/")
        }));
        assert!(!policy.entries.iter().any(|entry| {
            entry.physical_repo_relative_path == "examples"
                && entry.source == DeliveryCandidateManifestEntrySourceV2::FileTree
        }));
        let root = Path::new(env!("CARGO_MANIFEST_DIR"));
        let manifest = derive_delivery_candidate_manifest_v2(root).unwrap();
        assert_eq!(manifest.policy_identity, policy.policy_identity);
        assert_eq!(manifest.entries.len(), policy.entries.len());
    }

