    #[test]
    fn m3_micro_d1r3b_authority_surfaces_are_confined_to_private_child_module() {
        let source = include_str!("m3_micro.rs");
        let module_marker = "    mod delivery_candidate_authority_v3 {";
        let use_marker = "\n    use self::delivery_candidate_authority_v3::{";
        let (before_authority, after_module_marker) = source.split_once(module_marker).unwrap();
        let (authority, after_authority) = after_module_marker.split_once(use_marker).unwrap();
        let outside_authority = format!("{before_authority}{after_authority}");

        let verified_literal = ["VerifiedDeliveryCandidateScopeIdentityV2", " {"].concat();
        let actual_origin = ["DeliveryExecutionEvidenceOriginV1::", "ActualD2Execution"].concat();
        let generic_assembler = ["assemble_delivery_suite_execution_", "observation_v3("].concat();
        let outside_identity_literals = outside_authority
            .lines()
            .filter(|line| {
                let line = line.trim();
                line.contains(verified_literal.as_str())
                    && !line.starts_with("fn ")
                    && !line.starts_with(") ->")
                    && !line.starts_with("impl ")
                    && !line.starts_with("struct ")
                    && !line.starts_with("pub(super) struct ")
            })
            .count();
        assert_eq!(outside_identity_literals, 0);
        assert_eq!(outside_authority.matches(actual_origin.as_str()).count(), 0);
        assert_eq!(
            outside_authority
                .matches(generic_assembler.as_str())
                .count(),
            0
        );
        assert!(authority.matches(verified_literal.as_str()).count() >= 2);
        assert!(authority.contains(actual_origin.as_str()));
        assert!(authority.contains(generic_assembler.as_str()));

        let (_, actual_builder_and_after) = authority
            .split_once("pub(super) fn build_actual_d2_execution_observation_v3(")
            .unwrap();
        let (actual_builder_parameters, _) =
            actual_builder_and_after.split_once(") -> Result").unwrap();
        assert!(actual_builder_parameters.contains("candidate_root: &Path"));
        assert!(
            actual_builder_parameters
                .contains("clean_authority: Option<VerifiedCleanDetachedExecutionEnvironmentV1>")
        );
        assert!(!actual_builder_parameters.contains("candidate_scope_identity"));
        assert!(!actual_builder_parameters.contains("origin"));
        assert!(!actual_builder_parameters.contains("clean_authority: bool"));
        let verified_default = [
            "impl Default for VerifiedDeliveryCandidate",
            "ScopeIdentityV2",
        ]
        .concat();
        let verified_deserialize = [
            "Deserialize for VerifiedDeliveryCandidate",
            "ScopeIdentityV2",
        ]
        .concat();
        let clean_default = [
            "Default for VerifiedCleanDetachedExecution",
            "EnvironmentV1",
        ]
        .concat();
        let clean_deserialize = [
            "Deserialize for VerifiedCleanDetachedExecution",
            "EnvironmentV1",
        ]
        .concat();
        let synthetic_to_actual = ["From<SyntheticDeliverySuite", "Execution"].concat();
        assert!(!source.contains(verified_default.as_str()));
        assert!(!source.contains(verified_deserialize.as_str()));
        assert!(!source.contains(clean_default.as_str()));
        assert!(!source.contains(clean_deserialize.as_str()));
        assert!(!source.contains(synthetic_to_actual.as_str()));
    }

