    #[test]
    fn m3_micro_r10_test_inventory_is_complete() {
        let inventory = m3_micro_test_inventory_v1();
        assert!(!inventory.is_empty());
        let identities = inventory
            .iter()
            .map(|entry| entry.test_identity.as_str())
            .collect::<BTreeSet<_>>();
        assert_eq!(identities.len(), inventory.len());
        for identity in R10_CAPABILITY_TESTS {
            let entry = inventory
                .iter()
                .find(|entry| entry.test_identity == *identity)
                .unwrap_or_else(|| panic!("missing capability test inventory: {identity}"));
            assert_eq!(entry.intent, M3MicroTestIntentV1::CapabilityEvidence);
            assert!(entry.current_ignore_status, "{identity}");
            assert!(!entry.normal_full_library, "{identity}");
        }
        for identity in R10_AUTHORITATIVE_GENERATORS {
            let entry = inventory
                .iter()
                .find(|entry| entry.test_identity == *identity)
                .unwrap_or_else(|| panic!("missing generator inventory: {identity}"));
            assert_eq!(entry.intent, M3MicroTestIntentV1::AuthoritativeGenerator);
            assert!(entry.current_ignore_status, "{identity}");
        }
        assert!(inventory.iter().all(|entry| {
            !(entry.normal_full_library && (entry.heavy_attribution || entry.frozen_v3))
        }));
    }

