    #[test]
    fn m3_micro_d1r3d_r3_r10_parser_has_minimal_pure_in_memory_coverage() {
        let capability_digest = stable_hash_string("r10-parser-fixture-capability");
        let delivery_digest = stable_hash_string("r10-parser-fixture-delivery");
        let default_summary_digest = stable_hash_string("r10-parser-fixture-default-summary");
        let metal_summary_digest = stable_hash_string("r10-parser-fixture-metal-summary");
        let clean_summary_digest = stable_hash_string("r10-parser-fixture-clean-summary");
        let capability_status = "SYNTHETIC_CAPABILITY_STATUS";
        let overall_status = "SYNTHETIC_OVERALL_STATUS";
        let final_status = "SYNTHETIC_FINAL_STATUS";
        let next_step = "Review only the synthetic R10 parser fixture.";
        let default_required = 7;
        let default_passed = 5;
        let default_failed = 1;
        let default_not_run = 1;
        let metal_required = 11;
        let metal_passed = 8;
        let metal_failed = 2;
        let metal_not_run = 1;
        let default_heavy = HeavyEvidenceExecutionCountersV1 {
            attribution_evaluations: 2,
            frozen_v3_evaluations: 3,
            receipt_generations: 5,
        };
        let metal_heavy = HeavyEvidenceExecutionCountersV1 {
            attribution_evaluations: 7,
            frozen_v3_evaluations: 11,
            receipt_generations: 13,
        };
        let body_headings = [
            "## 1. Mode and Git State",
            "## 2. Starting Status",
            "## 3. Progress Ledger",
            "## 4. Test Taxonomy",
            "## 5. Heavy Execution Isolation",
            "## 6. Reclassified Tests",
            "## 7. Capability Receipt",
            "## 8. Delivery Verification Plan",
            "## 9. Delivery Verification Receipt",
            "## 10. Default Delivery",
            "## 11. Metal Delivery",
            "## 12. Full Library",
            "## 13. Integration",
            "## 14. Clean-worktree",
            "## 15. Capability and Delivery Status",
            "## 16. Report Binding",
            "## 17. Verification",
            "## 18. Safety",
            "## 19. What This Proves",
            "## 20. What This Does Not Prove",
            "## 21. Remaining Risks",
        ];
        let mut report = String::from("# Synthetic R10 Parser Fixture\n");
        for heading in body_headings {
            report.push_str(&format!("\n{heading}\n"));
        }
        report.push_str(&format!(
            "- Capability Receipt digest: {capability_digest}\n- Delivery Verification Receipt digest: {delivery_digest}\n- Capability Status: {capability_status}\n- Default Delivery Status: FAILED\n- Metal Delivery Status: NOT_RUN\n- Full Default Status: PASSED\n- Full Metal Status: FAILED\n- Integration Status: NOT_RUN\n- Clean-worktree Status: PASSED\n- Delivery Status: INCOMPLETE\n- Overall Status: {overall_status}\n- Default required: {default_required}\n- Default passed: {default_passed}\n- Default failed: {default_failed}\n- Default not-run: {default_not_run}\n- Metal required: {metal_required}\n- Metal passed: {metal_passed}\n- Metal failed: {metal_failed}\n- Metal not-run: {metal_not_run}\n- Default heavy attribution count: {}\n- Default Frozen V3 count: {}\n- Default generator count: {}\n- Metal heavy attribution count: {}\n- Metal Frozen V3 count: {}\n- Metal generator count: {}\n- Default summary digest: {default_summary_digest}\n- Metal summary digest: {metal_summary_digest}\n- Clean summary digest: {clean_summary_digest}\n- Report binding status: PASSED\n",
            default_heavy.attribution_evaluations,
            default_heavy.frozen_v3_evaluations,
            default_heavy.receipt_generations,
            metal_heavy.attribution_evaluations,
            metal_heavy.frozen_v3_evaluations,
            metal_heavy.receipt_generations,
        ));
        let final_heading = "## 22. Final Status";
        let next_step_heading = "## 23. Exactly One Next Step";
        report.push_str(&format!(
            "\n{final_heading}\n- {final_status}\n\n{next_step_heading}\n- {next_step}\n"
        ));

        let expected_headings = body_headings
            .into_iter()
            .chain([final_heading, next_step_heading])
            .collect::<Vec<_>>();
        let actual_headings = report
            .lines()
            .filter(|line| line.starts_with("## "))
            .collect::<Vec<_>>();
        assert_eq!(actual_headings, expected_headings);

        let parsed = parse_r10_verification_report_v1(&report).unwrap();
        assert_eq!(parsed.capability_receipt_digest, capability_digest);
        assert_eq!(parsed.delivery_receipt_digest, delivery_digest);
        assert_eq!(parsed.capability_status, capability_status);
        assert_eq!(
            (
                parsed.default_delivery_status,
                parsed.metal_delivery_status,
                parsed.full_default_status,
                parsed.full_metal_status,
                parsed.integration_status,
                parsed.clean_worktree_status,
                parsed.delivery_status,
                parsed.report_binding_status,
            ),
            (
                VerificationCheckStatusV1::Failed,
                VerificationCheckStatusV1::NotRun,
                VerificationCheckStatusV1::Passed,
                VerificationCheckStatusV1::Failed,
                VerificationCheckStatusV1::NotRun,
                VerificationCheckStatusV1::Passed,
                M3MicroDeliveryStatusV1::Incomplete,
                VerificationCheckStatusV1::Passed,
            )
        );
        assert_eq!(
            (
                parsed.default_required,
                parsed.default_passed,
                parsed.default_failed,
                parsed.default_not_run,
            ),
            (
                default_required,
                default_passed,
                default_failed,
                default_not_run,
            )
        );
        assert_eq!(
            (
                parsed.metal_required,
                parsed.metal_passed,
                parsed.metal_failed,
                parsed.metal_not_run,
            ),
            (metal_required, metal_passed, metal_failed, metal_not_run,)
        );
        assert_eq!(parsed.default_heavy, default_heavy);
        assert_eq!(parsed.metal_heavy, metal_heavy);
        assert_eq!(parsed.default_summary_digest, default_summary_digest);
        assert_eq!(parsed.metal_summary_digest, metal_summary_digest);
        assert_eq!(parsed.clean_summary_digest, clean_summary_digest);
        assert_eq!(parsed.overall_status, overall_status);
        assert_eq!(parsed.final_status, final_status);
        assert_eq!(parsed.next_step, next_step);

        let invalid_heading = report.replacen(
            "## 11. Metal Delivery",
            "## 11. Invalid Synthetic Metal Section",
            1,
        );
        assert_eq!(
            parse_r10_verification_report_v1(&invalid_heading)
                .unwrap_err()
                .kind,
            R10ReportBindingErrorKindV1::Format
        );
        let duplicate_next_step = report.replacen(
            &format!("- {next_step}\n"),
            &format!("- {next_step}\n- Duplicate synthetic next step.\n"),
            1,
        );
        assert_eq!(
            parse_r10_verification_report_v1(&duplicate_next_step)
                .unwrap_err()
                .kind,
            R10ReportBindingErrorKindV1::Format
        );
    }

