    #[derive(Clone, Debug, PartialEq, Eq)]
    struct SyntheticCurrentCapabilityBindingV2 {
        semantic_binding: SemanticBindingV2,
    }

    fn synthetic_capability_source_v2(production: &str, test_only: &str) -> String {
        format!("{production}{CAPABILITY_TEST_MODULE_BOUNDARY_V2}\n{test_only}\n}}\n")
    }

    fn synthetic_pre_boundary_test_helper_source_v1(helper_value: u8) -> String {
        format!(
            "pub const CAPABILITY_CORE: u8 = 1;\n#[cfg(test)]\nconst TEST_HELPER: u8 = {helper_value};\npub const CAPABILITY_POLICY: u8 = 2;{CAPABILITY_TEST_MODULE_BOUNDARY_V2}\nfn fixture() {{}}\n}}\n"
        )
    }

    fn synthetic_canonicalized_test_helper_source_v1(helper_value: u8) -> String {
        synthetic_capability_source_v2(
            "pub const CAPABILITY_CORE: u8 = 1;\npub const CAPABILITY_POLICY: u8 = 2;",
            &format!("const TEST_HELPER: u8 = {helper_value};\nfn fixture() {{}}"),
        )
    }

    fn synthetic_current_capability_binding_v2(
        source: &[u8],
    ) -> Result<SyntheticCurrentCapabilityBindingV2, String> {
        let scope = capability_source_scope_v2(source)?;
        Ok(SyntheticCurrentCapabilityBindingV2 {
            semantic_binding: semantic_binding_v2_from_source_v2(
                semantic_source_binding_v2_from_scope(&scope)?,
            )?,
        })
    }

